var QUESTOES_CONHECIMENTOS_BANCARIOS_GERAL = [{"id":28343,"enunciado":"O SFN tem como órgão executivo central o BACEN, que estabelece normas a serem observadas pelo CMN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28352,"enunciado":"é o órgão do SFN que se responsabiliza pela fiscalização das operações de câmbio e dos consórcios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28354,"enunciado":"É atribuição do CRSFN adaptar o volume dos meios de pagamento às reais necessidades da economia, bem como regular os valores interno e externo da moeda e o equilíbrio do balanço de pagamentos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28355,"enunciado":"De decisão em processo administrativo oriundo do BACEN, da CVM, da Secretaria de Comércio Exterior ou da Secretaria da Receita Federal, cabe recurso ao CRSFN, no prazo estipulado na intimação, devendo o interessado entregá-lo mediante recibo ao respectivo órgão instaurador.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28356,"enunciado":"É atribuição do CRSFN julgar, em segunda e última instância administrativa, os recursos interpostos das decisões relativas às penalidades administrativas aplicadas pelo BACEN quanto a matérias relativas à aplicação de penalidades por infração à legislação de consórcios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28357,"enunciado":"Todo banco comercial deve ser constituído sob a forma de sociedade anônima e, na sua denominação social, deve constar a palavra Banco, exceto no caso da Caixa Econômica Federal (CAIXA), que é um banco múltiplo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28358,"enunciado":"Os bancos comerciais podem captar depósitos à vista, mas não podem captar depósitos a prazo, o que está facultado apenas aos bancos de investimento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28359,"enunciado":"As cooperativas de crédito estão autorizadas a realizar operações de captação por meio de depósitos à vista e a prazo somente vindos de associados, de empréstimos, repasses e refinanciamentos oriundos de outras entidades financeiras e de doações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28360,"enunciado":"As cooperativas de crédito podem conceder crédito somente a brasileiros maiores de 21 anos de idade, por meio de desconto de títulos, empréstimos e financiamentos, e realizar aplicação de recursos no mercado financeiro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28362,"enunciado":"Após ter incorporado o Banco Nacional de Habitação (BNH) e o papel de agente operador do Fundo de Garantia do Tempo de Serviço (FGTS), a CAIXA passou a centralizar todas as contas recolhedoras do FGTS existentes na rede bancária e a administrar a arrecadação desse fundo e o pagamento dos valores aos trabalhadores.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28366,"enunciado":"As SCTVMs podem emitir certificados de depósito de ações e cédulas pignoratícias de debêntures; intermediar operações de câmbio; praticar operações no mercado de câmbio de taxas flutuantes; praticar operações de conta margem; e realizar operações compromissadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28367,"enunciado":"São objetivos das SCTVMs: praticar operações de compra e venda de metais preciosos no mercado físico, por conta própria e de terceiros; operar em bolsas de mercadorias e de futuros por conta própria e de terceiros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28368,"enunciado":"A normatização, a concessão de autorização, o registro e a supervisão dos fundos de investimento são de competência do BACEN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28370,"enunciado":"As sociedades de arrendamento mercantil são constituídas sob a forma de sociedade por cotas limitadas, devendo constar obrigatoriamente na sua denominação social a palavra leasing.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28371,"enunciado":"As sociedades corretoras de câmbio têm por objeto social exclusivamente a intermediação em operações de câmbio, não contemplando, portanto, a prática de operações no mercado de câmbio de taxas flutuantes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":28373,"enunciado":"Atualmente, o valor máximo de garantia proporcionada pelo FGC é de R$ 120.000,00 contra a mesma instituição associada ou contra todas as instituições associadas do mesmo conglomerado financeiro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30327,"enunciado":"Uma empresa que capte ou administre seguros não se caracteriza, de acordo com a Lei n.º 4.595/1964, como instituição financeira, embora possa a esta ser equiparada, para fins específicos, em outras leis especiais como, por exemplo, na lei que dispõe acerca dos crimes contra o SFN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30328,"enunciado":"As instituições financeiras que recebem depósitos do público podem emitir debêntures, desde que previamente autorizadas pelo BACEN.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30329,"enunciado":"Embora o BACEN não seja responsável por fiscalizar e autorizar o funcionamento das administradoras de cartões de crédito, o Superior Tribunal de Justiça (STJ) entende que essas administradoras configuram instituições financeiras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30330,"enunciado":"É permitida a fixação de preços diferenciados para pagamentos de bens e serviços efetuados em dinheiro ou em cartão de crédito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30331,"enunciado":"Eventual penalidade aplicada pela Comissão de Valores Mobiliários a uma sociedade anônima administradora de cartões de crédito por descumprimento da lei de sociedade por ações é passível de revisão pelo Conselho de Recursos do Sistema Financeiro Nacional (CRSFN).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30332,"enunciado":"Para facilitar a comparação entre as taxas oferecidas no mercado, as instituições financeiras e as sociedades de arrendamento mercantil são obrigadas, previamente à contratação de operações de crédito, a informar o custo efetivo total (CET), que corresponde ao custo total da operação, expresso na forma de taxa percentual anual.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30333,"enunciado":"Em todos os informes publicitários das operações de crédito destinadas à aquisição de bens e serviços, deve ser informado o CET correspondente às condições contratadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30334,"enunciado":"O CMN regulamentou, por resolução, a cobrança de tarifas pelas instituições financeiras, vedando a cobrança de tarifas pelos serviços considerados prioritários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30335,"enunciado":"A taxa de renovação de cadastro pode ser cobrada ao cliente, desde que previamente informada e adequadamente identificada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30336,"enunciado":"Na hipótese das chamadas contas-salário, utilizadas exclusivamente para recebimento de salários e similares, é vedado à instituição financeira cobrar dos beneficiários, a qualquer título, tarifas destinadas ao ressarcimento dos serviços prestados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30337,"enunciado":"Nas instituições financeiras, é obrigatório o funcionamento de ouvidorias, necessariamente segregadas da unidade executora da atividade de auditoria interna.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30338,"enunciado":"Os contratos de arrendamento mercantil (leasing), assim como todos os contratos celebrados no país, não podem conter cláusula de correção das parcelas pela variação cambial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30339,"enunciado":"Para o ressarcimento das suas despesas, as instituições financeiras estão autorizadas a cobrar taxas por emissão de boletos de cobrança.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30340,"enunciado":"As operações de hot money constituem empréstimos de curtíssimo prazo que utilizam como referencial de custo a taxa do certificado de depósito interbancário (CDI) diária, acrescida de tributos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30341,"enunciado":"Uma das fontes de recursos para o crédito rural consiste nas multas impostas aos bancos que deixam de aplicar nessa atividade o percentual exigido pelo CMN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30342,"enunciado":"Na operação de vendor finance ou financiamento de vendas, o risco de crédito recai sobre a empresa compradora dos bens, contra quem o banco financiador detém direito de regresso em caso de inadimplemento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30343,"enunciado":"Segundo o STJ, nos contratos de arrendamento mercantil (leasing) com cláusula resolutiva expressa, não é necessária a notificação prévia do arrendatário para configurar seu inadimplemento por atraso (mora).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30344,"enunciado":"Tanto o documento de crédito (DOC) quanto a transferência eletrônica disponível (TED) constituem instrumentos de transferência de fundos que transitam pelos serviços da centralizadora da compensação de cheques.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30345,"enunciado":"A edição de atos regulamentares é função privativa do Conselho Nacional de Seguros Privados (CNSP), competindo à Superintendência de Seguros Privados (SUSEP) atribuições exclusivamente executivas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30346,"enunciado":"A aplicação das reservas técnicas das seguradoras deve seguir diretrizes estabelecidas pelo CMN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30347,"enunciado":"Admite-se que um ressegurador sediado no exterior opere no Brasil, desde que atenda às exigências legais e esteja cadastrado no órgão competente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30348,"enunciado":"De acordo com seu estatuto, o Instituto de Resseguros do Brasil pode exercer outras atividades empresariais além das operações de resseguro e retrocessão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30349,"enunciado":"Embora a contratação de seguros seja geralmente facultativa, há casos em que o seguro é obrigatório, como na hipótese de bens dados em garantia de financiamento de instituição financeira pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30350,"enunciado":"O principal elemento que caracteriza os bancos comerciais é a vedação de captar recursos junto ao público, em suas operações passivas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30351,"enunciado":"Os bancos de investimento, as financeiras (sociedades de crédito, financiamento e investimento) e os bancos de desenvolvimento são exemplos de instituições financeiras não bancárias.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30352,"enunciado":"Para a constituição de um banco cooperativo, exige-se, como requisito, que a totalidade das ações com direito a voto pertença a cooperativas centrais de crédito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30354,"enunciado":"Considere que, em determinado momento, uma onça-troy - 31,1035 gramas - esteja avaliada em US$ 1.104,00, que o dólar esteja cotado em R$ 1,75 e que a Bolsa de Mercadorias e Futuros e Bolsa de Valores de São Paulo (BMF&BOVESPA) esteja oferecendo um grama de ouro a R$ 65,00. Com base nessas informações, é correto afirmar que é momento de comprar ouro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30358,"enunciado":"Os corretores de câmbio, na função de intermediários nas operações de câmbio, buscam os melhores negócios com as melhores taxas para seus clientes fecharem o câmbio. Esses corretores podem trabalhar livremente no mercado de taxas livres (dólar comercial) e no mercado de taxas flutuantes (dólar turismo).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30359,"enunciado":"O mercado de câmbio de taxas livres é destinado a operações de empréstimos/financiamentos, investimentos externos, assim como a remuneração dessas operações no exterior, e às operações de importação e exportação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30360,"enunciado":"Considere que um exportador fature uma mercadoria que vale US$ 200,00 por US$ 150,00 e que um importador estrangeiro pague por essa mercadoria, oficialmente, US$ 150,00 mais US$ 50,00 de forma ilegal. Nessa situação, o subfaturamento de exportação caracteriza evasão de divisas e alimenta o mercado de câmbio paralelo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30361,"enunciado":"Quando o BACEN realiza uma operação de compra ou venda de moeda estrangeira, todos os bancos comerciais, múltiplos e de investimentos são instituições habilitadas para participar do leilão de compra ou de venda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30362,"enunciado":"Considere hipoteticamente que José, um investidor brasileiro, use R$ 100.000,00 para comprar dólares e remetê-los para Nova York, autorize um operador a comprar euros com esses dólares e a remetê-los para Frankfurt, autorize outro operador a comprar reais com esses euros e a remetê-los de volta para o Brasil. Considere também que as cotações entre as moedas sejam US$ 1,00 = R$ 1,75;  1,00 = R$ 2,60; e US$ 1,00 =  0,70. Com base nessas informações e sem considerar outras despesas como custos de remessas e comissões dos operadores, conclui-se que o ganho de José com a arbitragem de moedas é de R$ 4.000,00.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30363,"enunciado":"Uma empresa brasileira que tem dívida em dólar pode comprar uma put option (opção de venda) com prazo de vencimento igual ao da dívida para se proteger de desvalorização do real.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30364,"enunciado":"Uma empresa brasileira que tem empréstimo bancário em dólar, para se proteger contra variações da moeda, pode fazer uma operação de swap com a própria instituição financeira, mudando a dívida de dólar para real, indexada ao certificado de depósito interbancário (CDI) mais juros.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30365,"enunciado":"Para assegurar o preço de seu produto a ser entregue em data futura, é correto que um agricultor faça um contrato a termo com um comerciante, especificando o produto a ser entregue, a data da entrega, a quantidade e o preço do produto a ser entregue.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30366,"enunciado":"Com expectativa de alta do preço de um produto, é correto que um investidor que deseja comprar o produto no futuro, para se proteger contra o aumento do preço, compre uma put option.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30367,"enunciado":"Um investidor que vende uma call option (opção de compra) está fazendo uma operação para obter ganhos financeiros pelo recebimento do prêmio, e o risco dessa operação é equivalente ao valor do prêmio recebido pela venda da opção.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30368,"enunciado":"O valor do prêmio de uma opção de compra, assim como o de uma opção de venda, é apurado somente em função das expectativas das seguintes variáveis: preço de mercado, preço de exercício, taxa de juros e tempo de vencimento da opção.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30369,"enunciado":"Na concessão de um aval, garantia pessoal, o avalista assume a mesma condição jurídica do avalizado, sendo solidário pela liquidação da dívida. Nesse caso, o credor poderá cobrar a dívida de qualquer avalista sem cobrar do devedor principal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30370,"enunciado":"Em uma garantia por meio de fiança, há a condição de benefício da ordem, o que significa que o credor deverá acionar primeiro o devedor e depois o fiador, exceto se o fiador renunciar ao benefício.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30371,"enunciado":"Um imóvel pode ser hipotecado junto a vários credores simultaneamente e, em todas as situações, a preferência do credor será pela ordem do registro no cartório de imóveis de circunscrição de localização do bem. Para assegurar o pagamento, o credor da hipoteca de segundo grau poderá executar a garantia, promovendo venda judicial, antes do vencimento da hipoteca do primeiro grau.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30372,"enunciado":"Os seguintes bens podem ser oferecidos como garantia na modalidade de hipoteca: imóveis, aeronaves e navios. A hipoteca se extingue quando do vencimento do contrato principal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30373,"enunciado":"A propriedade fiduciária é uma forma especial de garantia, próxima da garantia real, que transfere a posse direta do bem para o credor, enquanto o devedor fica apenas com a posse indireta, isto é, o devedor alienante é proprietário do bem alienado, podendo fazer uso dele.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30444,"enunciado":"Em uma garantia formalizada por meio de aval, o avalista assume a mesma posição jurídica do avaliado, isto é, o avalista é solidário com o avalizado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30445,"enunciado":"A ausência da assinatura do cônjuge em garantias formalizadas por meio de fiança e(ou) de aval não invalida a garantia outorgada, em qualquer regime de bens do casal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30446,"enunciado":"Um contrato de empréstimo pode ter vários avalistas, caso o devedor principal fique inadimplente. O credor deve exigir a liquidação do empréstimo primeiro do devedor principal e depois, proporcionalmente, de cada um dos avalistas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30447,"enunciado":"Na garantia oferecida para o credor mediante fiança, em caso de inadimplência, o credor deve executar simultaneamente o devedor e o fiador, mesmo que o fiador não tenha renunciado tacitamente ao benefício da ordem.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30448,"enunciado":"Quando oferecer garantia ao credor por meio de penhor mercantil, o devedor fica como depositário dos bens oferecidos em garantia, sem transferência da posse ao credor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30449,"enunciado":"Uma fiança bancária é normalmente aprovada pela área de crédito do banco, que pode exigir garantias do cliente e definir um custo para a operação, sem restrições para o prazo de vencimento, que pode ser desde o prazo do vencimento da obrigação para a qual a fiança se destina até prazo indeterminado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30450,"enunciado":"Fiança bancária é um contrato firmado por um banco e seu cliente, no qual o banco assegura o pagamento de uma obrigação de seu cliente junto a um credor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30451,"enunciado":"O valor total de fianças em vigor por instituição financeira não pode, em momento algum, exceder 5% do valor do patrimônio líquido da instituição financeira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30452,"enunciado":"Um bem imóvel pode ser hipotecado a vários credores simultaneamente. Na situação em que um imóvel que seja oferecido em garantia para dois credores e o valor obtido pela sua venda não seja suficiente para liquidar a dívida da hipoteca de segundo grau, o credor da segunda passará para a condição de quirografário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30453,"enunciado":"O credor da hipoteca de segundo grau, em caso de venda judicial do imóvel hipotecado, tem direito, no mínimo, a 50% do valor obtido pela venda do imóvel.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30454,"enunciado":"Na alienação fiduciária de um bem móvel perfeitamente identificável, o devedor alienante não é proprietário do bem alienado, embora tenha a sua posse diretamente. Ele torna-se titular pleno do domínio do bem somente após a liquidação do financiamento no qual o bem tenha sido oferecido como garantia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30455,"enunciado":"Se uma empresa de construção civil, proprietária de um prédio, vender para um adquirente um apartamento financiado diretamente pelo construtor, mediante assinatura de um contrato de alienação fiduciária de bem imóvel, então, no registro imobiliário, o credor constará como proprietário fiduciário e o devedor, como proprietário fiduciante. Nesse caso, o fiduciante terá a posse direta e o fiduciário será o possuidor indireto da coisa imóvel.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30456,"enunciado":"No mercado de câmbio de taxas flutuantes, são realizadas operações de importação e exportação, operações de empréstimos e investimentos externos, assim como as remessas para remuneração dessas operações.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30457,"enunciado":"Operações de câmbio consistem basicamente na conversão da moeda de um país na moeda de outro país. Essas operações podem ser de compra de moeda estrangeira, de venda de moeda estrangeira ou de arbitragem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30458,"enunciado":"Se um turista trocar dólares por reais, estará trocando moedas, o que é denominado câmbio manual.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30462,"enunciado":"Se um banco faz um contrato de venda de moeda estrangeira para um importador de mercadorias com prazo de entrega de cinco dias, essa operação não altera a posição do sistema bancário, mas aumenta a posição vendida do banco operador ou diminui a sua posição comprada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30463,"enunciado":"Um exportador de commodities, ao fazer adiantamento sobre contratos de câmbio (ACC) com um banco que opera no mercado de câmbio, antecipa recursos para o período do processo produtivo e da comercialização da mercadoria a seu exportador.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30464,"enunciado":"Considere que um importador tenha oferecido ao exportador uma carta de crédito emitida por um banco do país do importador como garantia de pagamento e que esse banco transferiu os termos do crédito para um correspondente do país exportador. Nesse caso, se o importador não pagar, o compromisso de pagamento passará a ser do banco que instituiu a carta de crédito e do banco correspondente do país exportador.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30465,"enunciado":"O exportador pode contratar o câmbio antes de embarcar a mercadoria, travando o câmbio. Nessa operação, o exportador fixa a taxa de conversão da moeda estrangeira, fecha o câmbio com um banco e recebe o valor equivalente em reais no momento do fechamento do câmbio.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30466,"enunciado":"Se um banco autorizado a operar no mercado de câmbio tiver comprado divisas de um exportador de commodities, necessariamente deverá vendê-las para outro banco ou recolher o excesso da posição comprada para o BACEN.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30467,"enunciado":"Considere que o dólar e o euro tenham apresentado, em um dado momento, as seguintes cotações: Nova Iorque: US$ 1 =  0,70; Viena:  1 = US$ 1,50. Considere ainda que, de posse dessas informações, um investidor norte-americano invista US$ 50.000 na compra de euros em Nova Iorque e autorize seu operador de Viena, na Áustria, a vender os euros e comprar dólares. Nessa operação, o investidor obterá um ganho superior a US$ 2.000, sem considerar os efeitos dos custos operacionais e impostos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30468,"enunciado":"Se o cliente de um banco no Brasil deseja remeter  1.000 para um residente em Madri, essa operação pode ser efetuada com o banco no Brasil, que recebe o equivalente em reais ou debita o valor correspondente na conta-corrente do cliente, cobrando uma comissão pela remessa, e credita em moeda estrangeira para um banqueiro no exterior. Então, o banqueiro avisa o favorecido e entrega a ele o valor na moeda local.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30470,"enunciado":"Um contrato de câmbio pactuado entre comprador e vendedor de moeda estrangeira estabelece as características e as condições em que a operação está sendo realizada e deve ser registrado no Sistema de Informações do BACEN (SISBACEN), por uma instituição autorizada pelo BACEN até as 19 h do dia em que a operação for realizada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30471,"enunciado":"Podem operar em câmbio, nas posições compradas e vendidas, bancos múltiplos; bancos de investimento; bancos comerciais; sociedades de crédito, financiamento e investimento, corretoras de títulos e valores mobiliários; distribuidoras de títulos e valores mobiliários e corretoras de câmbio.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30472,"enunciado":"Se, em determinado dia, uma instituição financeira comprar mais moedas estrangeiras do que vender, ela deverá ter, no final do dia, uma posição comprada e, para zerar a sua posição, deverá recolher para o BACEN toda a posição comprada, até as 16 h 30 min do mesmo dia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30473,"enunciado":"Se, em determinado dia, uma instituição financeira vender mais moedas estrangeiras do que comprar, ela deverá ter, no final do dia, uma posição vendida, que deverá ser adicionada à posição do dia anterior. Esse saldo não deverá exceder o limite definido pelo BACEN.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30475,"enunciado":"O Banco da Amazônia S.A. é supervisionado, no que se refere às operações de crédito que realiza, exclusivamente pela Comissão de Valores Mobiliários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30477,"enunciado":"As cooperativas de crédito não são classificadas como instituições financeiras e não estão autorizadas a realizar operações de captação por meio de depósitos à vista e a prazo de associados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30479,"enunciado":"Os bancos comerciais podem manter contas de depósitos à vista.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30480,"enunciado":"O certificado de depósito bancário (CDB) é uma modalidade de depósito à vista.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30481,"enunciado":"Contas de depósito à vista são popularmente denominadas contas correntes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30482,"enunciado":"A transferência eletrônica disponível (TED) é uma modalidade ágil de transferência de fundos entre contas de depósitos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30484,"enunciado":"Em uma transação de compra e venda de determinado título realizada pela CETIP, o preço do título é definido por ela, sendo as partes obrigadas a aceitar as condições estipuladas por essa empresa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30485,"enunciado":"Um sistema de liquidação e custódia é aquele no qual se dá a liquidação física e financeira das compras e vendas de títulos e outros papéis.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30486,"enunciado":"Liquidação física em uma transação de compra e venda de títulos é a entrega de numerário em espécie do vendedor para o comprador.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30487,"enunciado":"Liquidação financeira é a entrega, do comprador para o vendedor, de determinado montante de recursos previamente acertado entre as partes quando elas realizam transação de compra e venda de títulos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30488,"enunciado":"A cobrança bancária possibilita que o vendedor receba do comprador os valores devidos por este último, na data acertada entre as partes, mesmo que elas residam em cidades diferentes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30489,"enunciado":"As taxas de condomínio e mensalidades escolares não podem ser recebidas por meio de cobrança bancária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30490,"enunciado":"Sacado é obrigatoriamente o cliente do banco que tem valores a receber por meio de um boleto de cobrança enviado ao cedente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30491,"enunciado":"Uma duplicata pode ser liquidada por meio do serviço de cobrança bancária e as principais informações desse título de crédito podem constar do boleto bancário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30492,"enunciado":"As operações de crédito, sob o ponto de vista do banco, são denominadas operações ativas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30493,"enunciado":"As operações denominadas hot money são aquelas de longo prazo, normalmente realizadas com recursos providos pelo Banco Nacional de Desenvolvimento Econômico e Social.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30494,"enunciado":"As contas garantidas assemelham-se em funcionamento ao cheque especial e destinam-se, prioritariamente, às empresas (pessoas jurídicas).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30495,"enunciado":"O desconto de títulos é uma modalidade de empréstimo bancário em que é feita uma antecipação de recursos aos quais o cliente do banco apenas iria ter acesso em data futura, recursos esses provenientes da liquidação de títulos de crédito cujo credor/beneficiário é esse cliente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30496,"enunciado":"No desconto de duplicatas, se o sacado não pagar, o banco não pode requerer de volta o dinheiro antecipado ao seu clientes, isto é, não há direito de regresso.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30497,"enunciado":"A principal atividade das empresas de fomento mercantil (factoring) é atuar provendo operações de arrendamento mercantil (leasing) diretamente a seus clientes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30498,"enunciado":"O crédito direto ao consumidor é uma modalidade destinada exclusivamente à compra de bens imóveis comerciais e residenciais, e seus principais clientes são as pessoas físicas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30499,"enunciado":"Ao aplicar em um fundo de investimentos, assim como em um CDB, o cliente tem seus recursos garantidos pelo Fundo Garantidor de Créditos (FGC).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30500,"enunciado":"As letras de crédito imobiliário são lastreadas por créditos imobiliários garantidos por hipoteca ou por alienação fiduciária de coisa imóvel.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30501,"enunciado":"O plano de previdência privada aberta denominado plano gerador de benefício livre (PGBL) destina-se a captar recursos de curto prazo dos clientes, de preferência inferior a sessenta dias.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30502,"enunciado":"Os seguros do tipo vida gerador de benefício livre (VGBL) possibilitam o desconto integral dos prêmios mensais para aqueles contribuintes que utilizam o formulário de declaração simplificada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30503,"enunciado":"Os títulos de capitalização são adequados para os recursos de curtíssimo prazo, considerando a alta liquidez, sendo vedada a distribuição de prêmios aos detentores desses títulos por meio da realização de sorteios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30511,"enunciado":"Um fundo referenciado DI deve manter uma carteira de investimentos que apresente retorno compatível com o referencial determinado (as taxas de juros equivalentes aos depósitos interfinanceiros de um dia).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30512,"enunciado":"A taxa de administração é a principal remuneração obtida pela instituição financeira quando oferece um fundo de investimentos aos clientes. Ela é devida mesmo quando o fundo em questão apresenta retorno negativo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30513,"enunciado":"A alavancagem é uma técnica que provê total garantia quanto a possíveis perdas, por estar baseada na manutenção de operações restritas a um único mercado e indexador.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30934,"enunciado":"Considerando as características das operações de empréstimos bancários, marque a alternativa CORRETA:","opcoes":["os bancos devem assegurar o direito de liquidação antecipada do débito, total ou parcialmente, mediante redução proporcional dos juros.","nas operações de empréstimos os bancos não podem cobrar tarifas porque já cobram juros.","a utilização do limite do cheque especial está sujeita à cobrança de juros previamente definidos pelo Banco Central.","o crédito direto ao consumidor é uma linha de empréstimo destinada exclusivamente ao consumo de bens alimentícios.","os bancos estão sujeitos, na atualidade, a controles dos valores que podem emprestar aos usuários."],"correta":0,"explicacao":"Gabarito: <strong>os bancos devem assegurar o direito de liquidação antecipada do débito, total ou parcialmente, mediante redução proporcional dos juros.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30935,"enunciado":"A operação de Leasing é uma operação de crédito, considerada um aluguel de equipamentos por um período estabelecido, com algumas características especiais. Em relação a essa operação, analise as afirmações de I a IV: I. o Leasing, ou arrendamento mercantil, é uma operação em que o cliente pode fazer uso de um bem sem necessariamente tê-lo comprado; II. a operação de Leasing é destinada apenas para pessoas jurídicas do setor industrial; III. caso o cliente deseje adquirir o bem definitivamente deverá pagar o valor residual definido entre as partes no início do contrato; IV. os contratos de Leasing são feitos por tempo indeterminado. Marque a alternativa CORRETA:","opcoes":["são verdadeiros os itens I e II.","são verdadeiros os itens I, III e IV.","são verdadeiros os itens I e III.","são verdadeiros os itens III e IV.","apenas o item III é verdadeiro."],"correta":2,"explicacao":"Gabarito: <strong>são verdadeiros os itens I e III.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30936,"enunciado":"O Programa de Geração de Emprego e Renda (PROGER) é um conjunto de linhas de crédito para financiar quem quer se iniciar ou investir no crescimento de seu próprio negócio, tanto na área urbana como na rural. A respeito desse Programa, considere as afirmativas abaixo como V se verdadeira e F se falsa : I. os recursos do PROGER rural se destinam exclusivamente às cooperativas localizadas na região Nordeste; II. os principais agentes financeiros do PROGER são exclusivamente bancos privados, que dispõem de recursos livres destinados a essa finalidade; III. o PROGER rural é destinado exclusivamente para a finalidade de investimento, por seu caráter empreendedor. Marque a alternativa com a sequência CORRETA:","opcoes":["F-F-F","F-V-F","F-F-V","V-F-F","V-V-F"],"correta":0,"explicacao":"Gabarito: <strong>F-F-F</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30937,"enunciado":"O cheque é um documento que proporciona grande facilidade aos usuários como meio de pagamento de compras e serviços. Analise as afirmações abaixo sobre suas principais características legais: I. a aceitação de cheques é um ato de confiança entre a pessoa que emite o cheque (emitente) e aquele que recebe, o beneficiário; II. por lei, somente cheques de valor até R$ 100,00 (cem reais) podem ser emitidos ao portador; III. a pessoa física ou jurídica que for incluída no Cadastro de Emitentes de Cheques sem Fundos (CCF) não pode movimentar, sob hipótese alguma, sua conta corrente; IV. após cinco anos da inclusão, a ocorrência é retirada do CCF automaticamente, conforme determina o Código de Defesa do Consumidor. Marque a alternativa CORRETA:","opcoes":["são verdadeiros os itens I, II e III.","são verdadeiros os itens I, II e IV.","são verdadeiros os itens II e III.","são verdadeiros os itens II, III e IV.","são verdadeiros os itens III e IV."],"correta":1,"explicacao":"Gabarito: <strong>são verdadeiros os itens I, II e IV.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30939,"enunciado":"Marque a alternativa CORRETA sobre as características e atribuições legais das instituições financeiras pertencentes ao Sistema Financeiro Nacional:","opcoes":["consideram-se instituições financeiras, as pessoas jurídicas públicas e privadas que tenham como atividade principal a intermediação de recursos financeiros próprios.","as instituições financeiras somente poderão funcionar no país mediante prévia autorização do Banco Central do Brasil ou de decreto do Poder Executivo, quando forem estrangeiras.","as instituições financeiras públicas federais, por sua personalidade jurídica, não estão sujeitas às mesmas disposições relativas às instituições financeiras privadas.","é permitido às instituições financeiras conceder empréstimos e adiantamentos a seus diretores e membros do conselho de administração, na condição dos mesmos possuírem, pelo menos, 20% do capital da instituição.","as instituições financeiras podem manter aplicações ilimitadas em bens imóveis."],"correta":1,"explicacao":"Gabarito: <strong>as instituições financeiras somente poderão funcionar no país mediante prévia autorização do Banco Central do Brasil ou de decreto do Poder Executivo, quando forem estrangeiras.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30940,"enunciado":"Objetivando fortalecer a solidez do sistema financeiro, o Banco Central do Brasil estabeleceu diversas normas relativas ao risco das operações de crédito. Sobre esses riscos analise as afirmações abaixo: I. o risco de crédito está associado à necessidade de se avaliar a capacidade de endividamento dos tomadores; II. o movimento nos preços de mercado dos ativos financeiros nacionais e internacionais expõe os bancos ao risco de mercado; III. o risco de liquidez em um banco decorre da sua incapacidade de promover reduções em seu passivo ou financiar acréscimos em seus ativos; IV. as modalidades mais relevantes de risco operacional envolvem o colapso de controles internos e do domínio corporativo. Marque a alternativa CORRETA:","opcoes":["são verdadeiros os itens I e III.","são verdadeiros os itens II e IV.","são verdadeiros os itens I, II e III.","apenas o item I é verdadeiro.","todos os itens são verdadeiros."],"correta":4,"explicacao":"Gabarito: <strong>todos os itens são verdadeiros.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30941,"enunciado":"Para evitar problemas de risco de crédito, existem normas concernentes ao comportamento que os bancos devem cumprir em relação aos clientes e à própria operação. A respeito desse assunto, considere as afirmativas abaixo como V se verdadeira e F se falsa: I. as instituições financeiras só precisam lançar em suas demonstrações contábeis, os créditos em atraso por mais de noventa dias, quando são considerados de liquidação duvidosa; II. a classificação das operações de crédito é exigida apenas para as pessoas jurídicas, principalmente pelo risco inerente à atividade econômica do tomador; III. as operações de adiantamento sobre contratos de câmbio e de financiamento à importação não são classificadas por ordem de risco, por estarem amparadas por recursos internacionais; IV. as operações objeto de renegociação devem ser retiradas do nível de risco anterior e classificadas como normal. Marque a alternativa com a sequência CORRETA:","opcoes":["V-F-F-F","F-F-F-F","V-V-F-F","V-F-V-F","F-F-F-V"],"correta":1,"explicacao":"Gabarito: <strong>F-F-F-F</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30942,"enunciado":"As operações de crédito bancário apresentam diversas modalidades de linhas de créditos, em função do direcionamento dos recursos e do tipo de instituição que está concedendo o recurso. Sobre este assunto, marque a alternativa CORRETA:","opcoes":["o Hot Money é uma linha de crédito destinada ao financiamento das exportações, sendo operacionalizada exclusivamente por bancos estrangeiros atuando no país.","os empréstimos para capital de giro são operações típicas de bancos de investimento, com abertura de linhas específicas sem limites de crédito e garantias.","o crédito direto ao consumidor é um financiamento destinado para aquisição de bens e serviços, operação típica das financeiras e de bancos comerciais, com carteira de crédito, financiamento e investimento.","o desconto de duplicatas ou notas promissórias é uma operação de empréstimo exclusivo de bancos comerciais.","a conta garantida é uma linha especial de financiamento de capital de giro que deve ser quitada integralmente no vencimento estabelecido no prazo concedido no contrato."],"correta":2,"explicacao":"Gabarito: <strong>o crédito direto ao consumidor é um financiamento destinado para aquisição de bens e serviços, operação típica das financeiras e de bancos comerciais, com carteira de crédito, financiamento e investimento.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30943,"enunciado":"As instituições financeiras devem observar certas condições sobre as normas relativas a abertura, manutenção, movimentação e encerramentos de contas de depósito. A respeito deste assunto considere as afirmações abaixo: I. quando a conta for titulada por menor ou pessoa incapaz, além de sua qualificação, também deverá ser identificado o responsável que o assistir ou o representar; II. se o correntista emitir um cheque sem provisão de fundos, a instituição financeira deverá encerrar sua conta, sem necessidade de aviso ao correntista; III.as instituições financeiras estão autorizadas pelo Banco Central a cobrar tarifas sobre todos os serviços relativos à conta de depósitos; IV. é vedada a estipulação de cláusulas na ficha-proposta que, em qualquer hipótese, impeçam ou criem limitações a sustação de pagamentos de cheque. Marque a alternativa CORRETA:","opcoes":["as afirmativas I e IV são verdadeiras.","as afirmativas I e II são verdadeiras.","as afirmativas II e III são verdadeiras.","as afirmativas II e IV são verdadeiras.","todas as afirmativas são verdadeiras."],"correta":0,"explicacao":"Gabarito: <strong>as afirmativas I e IV são verdadeiras.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30944,"enunciado":"Objetivando expandir o acesso aos serviços bancários por parte da população de baixa renda e para facilitar recebimentos de proventos e de microcrédito, foram criadas contas especiais. Considerando as características dessas contas, marque a alternativa CORRETA:","opcoes":["a conta especial de depósito a vista, denominada de conta simplificada, somente pode ser aberta por pessoas físicas e mantida na modalidade de conta individual, vedado o fornecimento de talonários de cheque para respectiva movimentação.","a conta especial de depósito a vista, denominada de conta simplificada, pode ser livremente movimentada, sem limites de recursos.","por ser uma conta simplificada, é permitida a abertura de conta de depósitos sob nome abreviado ou de qualquer forma alterado, inclusive mediante supressão de parte ou partes do nome do depositante.","a \"conta salário\" foi criada para prestação de serviços relativos ao pagamento de salários, vencimentos, aposentadorias, pensões e similares, contas essas que podem ser movimentadas por cheques.","a \"conta salário\" pode ser aberta livremente pelo interessado para receber seus salários, vencimentos, aposentadorias ou pensões, mas essas contas estão sujeitas a cobrança de tarifas por parte das instituições financeiras."],"correta":0,"explicacao":"Gabarito: <strong>a conta especial de depósito a vista, denominada de conta simplificada, somente pode ser aberta por pessoas físicas e mantida na modalidade de conta individual, vedado o fornecimento de talonários de cheque para respectiva movimentação.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30945,"enunciado":"Foram instituídos alguns procedimentos a serem observados pelas instituições financeiras autorizadas a funcionar pelo Banco Central na contratação e na prestação de serviços aos clientes e ao público em geral. Esses procedimentos são conhecidos no mercado como \"Código de Defesa do Consumidor Bancário\". Sobre esses procedimentos, marque a alternativa CORRETA:","opcoes":["as instituições financeiras podem se recusar a receber cheques, bloquetos de cobrança, fichas de compensação e outros, sem necessidade de informação prévia aos clientes.","não há, na norma, nenhum dispositivo relativo à propaganda enganosa ou abusiva.","a liquidação antecipada de débito, total ou parcial, mediante redução proporcional dos juros nas operações de crédito pessoal e de crédito direto ao consumidor, é uma opção das instituições financeiras.","as instituições devem estabelecer em suas dependências alternativas técnicas, físicas e especiais que garantam o atendimento prioritário para pessoas portadoras de deficiência física ou com mobilidade reduzida.","os saques em espécie, realizados em contas de depósitos a vista, devem ser assegurados, independente de valor, não podendo as instituições postergar o saque para o expediente seguinte, alegando falta de recursos em caixa."],"correta":3,"explicacao":"Gabarito: <strong>as instituições devem estabelecer em suas dependências alternativas técnicas, físicas e especiais que garantam o atendimento prioritário para pessoas portadoras de deficiência física ou com mobilidade reduzida.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30946,"enunciado":"Objetivando possibilitar a concessão de crédito para a população de baixa renda e para micro-empreendedores, o governo vem incentivando as operações de microfinanças. Para isso foram criadas instituições e linhas de crédito específicas para esse setor da economia. Em relação a esse assunto, considere as afirmações abaixo, indicando V se verdadeira e F se falsa: I. as instituições financeiras destinam, no mínimo, 2% dos saldos dos depósitos a vista para realização de operações de microfinanças direcionadas à população de baixa renda e a microempreendedores; II. as taxas de juros efetivas da linha de crédito para microfinanças não podem exceder a 2% a.m., e os limites máximos dos valores são definidos pela instituição financeira, de acordo com a capacidade de financiamento do tomador; III. as operações de crédito destinadas ao programa de microfinanças somente podem ser realizadas com pessoas físicas detentoras de contas especiais de depósitos a vista (conta simplificada); IV. dado o caráter social, as instituições financeiras não podem cobrar taxa de abertura de crédito e para valores inferiores a R$ 1.000,00 o prazo máximo da operação permitido é de 90 dias. Marque a alternativa com a seqüência CORRETA:","opcoes":["V-V-F-V","V-F-F-F","V-F-V-F","V-V-V-V","F-F-V-V"],"correta":2,"explicacao":"Gabarito: <strong>V-F-V-F</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30947,"enunciado":"Existem, no mercado, diversos instrumentos de captação de recurso, que se diferenciam pelo prazo de captação, destinação e rentabilidade. Marque a alternativa CORRETA que caracteriza um desses instrumentos:","opcoes":["as cadernetas de poupança representam o mais popular instrumento de captação, proporcionando uma rentabilidade de 12 % a.a.","o prazo mínimo para aplicações em Certificado de Depósito Bancário (CDB) é de 90 dias.","os recursos da caderneta de poupança são destinados exclusivamente para financiar casas para população de baixa renda.","o Certificado de Depósito Bancário pode oferecer rendimento diferenciado, em função do valor e do prazo da aplicação.","a Instituição Financeira pode remunerar o depósito a vista, desde que o cliente permaneça com o recurso depositado na conta corrente por mais de trinta dias."],"correta":3,"explicacao":"Gabarito: <strong>o Certificado de Depósito Bancário pode oferecer rendimento diferenciado, em função do valor e do prazo da aplicação.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30949,"enunciado":"Dentre as operações de crédito especializado, o crédito rural tem como objetivo estimular e fortalecer o setor rural, destinando financiamentos aos produtores e suas associações. Sobre as características dessa modalidade de crédito, considere as afirmações abaixo: I. podem ser financiadas pelo crédito rural as atividades de custeio, investimento, comercialização e industrialização de produtos agropecuários; II. todos os recursos para financiamento do crédito rural são provenientes das instituições financeiras oficiais federais; III. o Programa Nacional de Fortalecimento da Agricultura Familiar (PRONAF) tem por finalidade apoiar as atividades agrícolas e nãoagrícolas desenvolvidas por agricultores familiares no estabelecimento ou aglomerado rural urbano; IV. o financiamento do PRONAF está limitado a R$ 3.000,00 (três mil reais), por produtor, em cada ano. Marque a alternativa CORRETA:","opcoes":["são verdadeiros os itens I e IV.","são verdadeiros os itens I e II.","são verdadeiros os itens II e III.","são verdadeiros os itens III e IV","apenas o item III é verdadeiro."],"correta":2,"explicacao":"Gabarito: <strong>são verdadeiros os itens II e III.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30951,"enunciado":"O crédito industrial, agro-industrial e para o comércio são atendidos principalmente por linhas operacionalizadas por instituições oficiais de crédito, como o Banco Nacional de Desenvolvimento Econômico e Social (BNDES). Com relação às finalidades e beneficiários dessas linhas, marque a alternativa CORRETA:","opcoes":["o FINAME é uma linha de financiamento do BNDES exclusivamente para pequenas e médias empresas para aquisição isolada de máquinas e equipamentos novos, com custo de apenas 12% ao ano.","o custo dos financiamentos realizados diretamente pelo BNDES é composto por: custo financeiro mais remuneração do BNDES mais outros encargos, se for o caso.","o BNDES financia a aquisição de veículos (automóveis e utilitários) desde que façam parte de um financiamento industrial.","o BNDES não dispõe de linhas de crédito para exportações de bens produzidos no País.","o BNDES não financia a capacitação tecnológica nem a formação e qualificação profissional."],"correta":2,"explicacao":"Gabarito: <strong>o BNDES financia a aquisição de veículos (automóveis e utilitários) desde que façam parte de um financiamento industrial.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30952,"enunciado":"O Fundo Constitucional de Financiamento do Nordeste (FNE), regulamentado pela Lei n° 7827/89, tem por objetivo contribuir para o desenvolvimento da região Nordeste, mediante execução de programas de financiamento aos setores produtivos, em consonância com os respectivos planos regionais de desenvolvimento. Considere as afirmações abaixo como V se verdadeira e F se falsa: I. o Banco do Nordeste do Brasil S.A., como instituição financeira federal de caráter regional, é administradora do FNE; II.os encargos financeiros dos financiamentos concedidos com recursos do FNE, são definidos pelo Banco do Nordeste do Brasil S.A , em função dos projetos específicos e da localização do projeto a ser financiado; III.as principais atividades beneficiadas com financiamentos do FNE são a indústria, a agropecuária e o turismo, por intermédio de diversos programas definidos no plano regional de desenvolvimento; IV. O Banco do Nordeste do Brasil S.A. financia, com recursos provenientes do FNE, o Programa de Apoio ao Turismo Regional, que tem por objetivo a implantação, expansão, modernização e reforma de empreendimentos do setor turístico. Marque a alternativa com a seqüência CORRETA:","opcoes":["V-F-V-F","V-F-V-V","F-V-V-F","V-V-V-V","V-F-F-F"],"correta":1,"explicacao":"Gabarito: <strong>V-F-V-V</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30953,"enunciado":"O Fundo de Amparo ao Trabalhador (FAT) constitui-se em uma importante fonte de financiamento para os programas sociais do Governo, o qual apresenta certas características. Marque a alternativa CORRETA:","opcoes":["o FAT financia o Programa de Geração de Emprego e Renda (PROGER), que é uma iniciativa do Governo Federal voltada para quem deseja iniciar ou expandir seu próprio negócio, tanto na área urbana quanto na área rural.","os recursos do FAT são oriundos do Orçamento Geral da União e de recursos próprios do Banco do Brasil S.A., que é a instituição financeira responsável pelo Fundo.","os agentes financeiros do PROGER, programa financiado pelo FAT, são apenas o Banco do Brasil S.A. e o Banco do Nordeste do Brasil S.A.","o FAT financia o Plano Nacional de Qualificação, que é um programa para trabalhadores das áreas de alta tecnologia.","os recursos do FAT não financiam unidades habitacionais."],"correta":1,"explicacao":"Gabarito: <strong>os recursos do FAT são oriundos do Orçamento Geral da União e de recursos próprios do Banco do Brasil S.A., que é a instituição financeira responsável pelo Fundo.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30954,"enunciado":"Segundo a Constituição Federal, a Seguridade Social no Brasil compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade destinadas a assegurar os direitos relativos à saúde, à previdência social e à assistência social. Com relação ao tema, marque a alternativa CORRETA:","opcoes":["compete privativamente aos Estados legislar sobre seguridade social no âmbito de suas respectivas jurisdições, sem qualquer subordinação à União","cabe exclusivamente à sociedade civil organizar e administrar a seguridade social tendo como principais objetivos a universalidade da cobertura e do atendimento e o caráter democrático e descentralizado de sua administração.","nenhum benefício ou serviço da seguridade social poderá ser criado, majorado ou estendido sem a correspondente fonte de custeio total.","as contribuições sociais para a seguridade social somente poderão ser exigidas no exercício financeiro subseqüente àquele em que tenha sido publicada a lei que as instituiu ou aumentou.","são isentas de contribuição para a seguridade social, as sociedades cooperativas, as micro e pequenas empresas e as entidades religiosas beneficentes de assistência social, atendidas as exigências estabelecidas em lei."],"correta":0,"explicacao":"Gabarito: <strong>compete privativamente aos Estados legislar sobre seguridade social no âmbito de suas respectivas jurisdições, sem qualquer subordinação à União</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30955,"enunciado":"Consoante a Constituição Federal, a Previdência Social no Brasil é organizada sobretudo sob a forma do Regime Geral de Previdência Social, de caráter contributivo e de filiação obrigatória, observados critérios que lhe preservem o equilíbrio financeiro e atuarial. Sobre as principais características desse tema, marque a alternativa CORRETA:","opcoes":["cobertura dos eventos de doença, invalidez, morte e idade avançada; proteção à maternidade, especialmente à gestante, e ao trabalhador em situação de desemprego involuntário; concessão de salário-família e auxílio-reclusão para os dependentes dos segurados de baixa renda e de pensão por morte do segurado, homem ou mulher, ao cônjuge ou companheiro e dependentes.","a cobertura do risco de acidente do trabalho é atendida exclusivamente por companhias de seguro do setor privado.","os benefícios da previdência social são acessíveis somente àqueles que tiveram relação formal de emprego, com carteira de trabalho assinada por seu(s) empregador(es).","nenhum benefício que substitua o salário de contribuição ou o rendimento do trabalho do segurado é concedido com valor mensal inferior à media dos 3 (três) salários mínimos mensais pertinentes aos 3 (três) anos imediatamente anteriores à sua concessão.","a gratificação natalina dos aposentados e pensionistas é igual ao provento do mês de dezembro de cada ano, mas somente é devida se tiverem sido trabalhados todos os meses do ano civil correspondente."],"correta":2,"explicacao":"Gabarito: <strong>os benefícios da previdência social são acessíveis somente àqueles que tiveram relação formal de emprego, com carteira de trabalho assinada por seu(s) empregador(es).</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30956,"enunciado":"Segundo mandamento constitucional, o regime da Previdência Privada tem caráter complementar e está organizado de forma autônoma em relação ao Regime Geral de Previdência Social. Quanto a este segundo regime de previdência, marque a alternativa CORRETA:","opcoes":["as instituições e empresas privadas, a União, os Estados, o Distrito Federal e os Municípios, suas autarquias, fundações, empresas públicas, sociedades de economia mista e outras entidades públicas, podem instituir entidades de previdência privada e patrocinar seus planos de benefícios de natureza complementar, situação na qual, o custo normal total é sempre dividido entre o empregador e o empregado de forma a nunca resultar em uma proporção nula para uma das partes.","é facultativa para o empregador a instituição de entidade de previdência privada de plano de benefícios complementares, mas, uma vez instituída, torna-se obrigatória a filiação dos correspondentes empregados.","as contribuições do empregador, os benefícios e as condições contratuais previstas no estatuto da entidade de previdência privada e no regulamento do plano de benefícios integram, para todos os fins de direito, o contrato de trabalho dos empregados participantes.","o regime de previdência privada complementar é regulado por lei ordinária e por normas editadas pelo Ministério do Trabalho e Emprego.","o regime de previdência privada complementar adota sempre o regime financeiro de capitalização, constituindo reservas que garantam o benefício contratado."],"correta":0,"explicacao":"Gabarito: <strong>as instituições e empresas privadas, a União, os Estados, o Distrito Federal e os Municípios, suas autarquias, fundações, empresas públicas, sociedades de economia mista e outras entidades públicas, podem instituir entidades de previdência privada e patrocinar seus planos de benefícios de natureza complementar, situação na qual, o custo normal total é sempre dividido entre o empregador e o empregado de forma a nunca resultar em uma proporção nula para uma das partes.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30957,"enunciado":"A Lei Complementar nº 108, de 29 de maio de 2001, dispõe sobre as entidades fechadas de previdência complementar do Setor Público e suas relações com a União, os Estados, o Distrito Federal e os Municípios, suas autarquias, fundações, sociedades de economia mista e outras entidades públicas, que lhes seriam patrocinadores. Sobre o tema em foco, marque a alternativa CORRETA:","opcoes":["as entidades em questão organizam-se sob a forma de autarquia, fundação ou sociedade civil, com fins lucrativos","a elegibilidade a um benefício de prestação programada e continuada requer uma carência mínima de 120 (cento e vinte) contribuições mensais ao plano de benefícios, permitindo-se a manutenção do vínculo empregatício com o patrocinador após a concessão do benefício.","os reajustes dos benefícios em manutenção são efetuados de acordo com os critérios do regulamento do plano, permitidos os repasses de ganhos de produtividade, de abonos e de vantagens concedidas ao cargo ou função em que o participante se aposentou.","o custeio do plano de benefícios e a despesa administrativa da entidade de previdência complementar são de responsabilidade do patrocinador, dos participantes e, também, dos assistidos (participante ou seus beneficiários em gozo de benefício de prestação continuada).","além das contribuições normais, os planos poderão prever o aporte de recursos adicionais pelos participantes, a título de contribuição laboral facultativa, aporte esse acompanhado do correspondente aporte patronal do patrocinador."],"correta":4,"explicacao":"Gabarito: <strong>além das contribuições normais, os planos poderão prever o aporte de recursos adicionais pelos participantes, a título de contribuição laboral facultativa, aporte esse acompanhado do correspondente aporte patronal do patrocinador.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":30963,"enunciado":"Assinale a afirmação CORRETA que trata de empréstimo:","opcoes":["o comodato é o empréstimo gratuito de coisa fungível.","o mútuo transfere o domínio da coisa emprestada ao mutuário, por cuja conta correm todos os riscos dela desde a tradição.","o contrato de comodato é a mesma coisa que contrato de mútuo.","o comodato sempre será celebrado por prazo certo.","o comodatário poderá recobrar do comodante as despesas feitas com o uso e gozo da coisa emprestada."],"correta":2,"explicacao":"Gabarito: <strong>o contrato de comodato é a mesma coisa que contrato de mútuo.</strong>.","banca":"ACEP","ano":2004,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36446,"enunciado":"A citada lei extinguiu a Superintendência da Moeda e do Crédito e deu origem ao Banco Central da República do Brasil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36447,"enunciado":"O Conselho Monetário Nacional (CMN) foi criado pela mencionada lei em substituição à Casa da Moeda do Brasil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36448,"enunciado":"Segundo a referida lei, são instituições financeiras as pessoas jurídicas públicas ou privadas que tenham como atividade principal ou acessória a coleta, a intermediação ou a aplicação de recursos financeiros próprios ou de terceiros, em moeda nacional ou estrangeira, e a custódia de valor de propriedade de terceiros.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36449,"enunciado":"De acordo com a lei considerada, as instituições financeiras somente poderão funcionar no país mediante prévia autorização do CMN ou por força de decreto do Poder Executivo, quando forem estrangeiras.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36457,"enunciado":"Bancos de investimento são especializados em operações financeiras de curtíssimo prazo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36458,"enunciado":"Os bancos comerciais, cuja denominação social deve conter a expressão BANCO, captam principalmente depósitos à vista, livremente negociáveis, e depósitos de poupança. Esses bancos são tradicionais fornecedores de crédito para pessoas físicas e jurídicas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36459,"enunciado":"Caixas econômicas captam depósitos à vista e depósitos de poupança e atuam mais fortemente no crédito habitacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36460,"enunciado":"Empresas corretoras e distribuidoras atuam especialmente nos mercados de câmbio, de títulos públicos e privados, de valores mobiliários e de mercadorias e futuros.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36467,"enunciado":"Agência é a dependência da instituição financeira que está autorizada a funcionar pelo BACEN e é destinada à prática das atividades para as quais a instituição esteja regularmente habilitada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36468,"enunciado":"Título de crédito é um documento representativo de uma obrigação de pagar o valor nele indicado, tal como o cheque, a nota promissória e a letra de câmbio.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36470,"enunciado":"Back office é a área responsável pela liquidação, compensação, contabilização, registro e custódia das operações realizadas por uma instituição financeira.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36471,"enunciado":"A Contribuição Provisória sobre Movimentação ou Transferência de Valores e de Crédito e de Direitos de Natureza Financeira (CPMF) é um tributo e, como tal, é de responsabilidade da Receita Federal, aplicando-se a ela os regulamentos das tarifas bancárias.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36472,"enunciado":"O CDB é um título de débito, físico ou escritural, emitido por banco comercial e representativo de depósitos a prazo feitos pelo cliente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36473,"enunciado":"Tanto o CDB quanto o RDB podem ser resgatados antes do prazo contratado, independentemente do prazo mínimo da aplicação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36474,"enunciado":"Fundo de investimento é um tipo de aplicação financeira em que o aplicador adquire cotas do patrimônio de um fundo administrado por instituição financeira para o qual o valor da cota é recalculado mensalmente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36475,"enunciado":"Tarifa é a remuneração do banco por serviço prestado ao cliente. Todo serviço prestado pelo banco a seus clientes está sujeito a tarifações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36476,"enunciado":"O quadro demonstrativo de tarifas deve estar obrigatoriamente fixado na agência bancária em local visível ao público, a partir da data de início da cobrança ou da alteração de valores.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36477,"enunciado":"Os depósitos em poupança realizados por meio de cheque, desde que este não seja devolvido, devem ser considerados a partir do dia do depósito, independentemente do prazo de liberação do cheque.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36478,"enunciado":"O banco pode cobrar pela manutenção de conta de poupança desde que o saldo da conta seja igual ou inferior a R$ 50,00 e não apresente registros de depósitos ou saques pelo período de 6 meses.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36479,"enunciado":"Cabe à administradora do cartão de crédito emitir e apresentar ao usuário do cartão fatura que contenha a relação e o valor das compras efetuadas para que seja realizado o pagamento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36480,"enunciado":"Compete ao BACEN autorizar e fiscalizar o funcionamento das empresas administradoras de cartão de crédito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36481,"enunciado":"Para atuarem como agentes no mercado de câmbio, os bancos, as corretoras, as distribuidoras, as agências de turismo e os meios de hospedagem devem estar autorizados pelo Banco do Brasil S.A.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36482,"enunciado":"Denomina-se mercado de câmbio o espaço onde se realizam as operações de câmbio entre os agentes de câmbio e entre estes e seus clientes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36485,"enunciado":"O FGC é uma entidade pública, sem fins lucrativos, que administra um mecanismo de proteção aos correntistas, poupadores e investidores do mercado financeiro. Esse mecanismo permite recuperar os depósitos ou créditos mantidos em instituição financeira, em caso de sua falência ou liquidação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36486,"enunciado":"As instituições financeiras contribuem para a manutenção do FGC com a totalidade dos depósitos que recebem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36487,"enunciado":"Um contrato futuro nada mais é do que um contrato a termo padronizado, no qual são determinados o bem, seu volume e a data da liquidação e da entrega. Essas especificações são estabelecidas pelas bolsas de futuros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36488,"enunciado":"O objetivo da padronização é conferir ao contrato futuro liquidez maior que a do contrato a termo, dando-lhe negociabilidade e facilitando a sua transferência entre diferentes participantes do mercado, o que permite ampliar ou encerrar antecipadamente os compromissos assumidos mediante operações da mesma natureza ou de natureza inversa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36489,"enunciado":"Parte das operações com contratos futuros é liquidada por diferença. Na prática, o que se negociam não são produtos, mas sim riscos de preços.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36490,"enunciado":"Os swaps são acordos públicos entre duas empresas para a troca futura de fluxos de caixa, respeitada uma fórmula preestabelecida, e podem ser considerados carteiras de contratos a termo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36491,"enunciado":"Opção é o direito de uma parte comprar ou vender a outra parte, até determinada data, uma quantidade do ativo-objeto a preço preestabelecido.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36497,"enunciado":"O objetivo desse contrato é proporcionar recursos antecipados ao importador, de sorte a incrementar o comércio internacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36498,"enunciado":"O ACC pode ser utilizado como um instrumento de ganho financeiro pelo importador.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36499,"enunciado":"O ACC consiste sempre na antecipação total dos reais equivalentes à quantia em moeda estrangeira comprada a termo de exportadores pelo banco.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36501,"enunciado":"A primeira fase do ACC ocorre quando a mercadoria já está pronta e embarcada, aproveitando o máximo possível a variação cambial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36502,"enunciado":"Inexiste captação de recursos nesse tipo de operação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36503,"enunciado":"A natureza mercantil constitui uma das características dessas operações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36504,"enunciado":"Nas operações de fomento comercial, pode-se efetuar financiamentos mediante o desconto de títulos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36505,"enunciado":"Esse tipo de operação tem por devedor a empresa sacada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36977,"enunciado":"O lucro do banco comercial, conhecido como spread bancário, é obtido entre a diferença da remuneração que paga às pessoas que lhe emprestam e a remuneração que cobra das pessoas que lhe tomam os recursos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36978,"enunciado":"As operações bancárias passivas, conhecidas como funding, são usadas pelo banco na busca de recursos para lastrear as suas operações ativas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36979,"enunciado":"Entre as operações bancárias ativas relacionadas à aplicação dos recursos captados, incluem-se o desconto bancário, o cheque especial, os empréstimos a pessoas físicas e a cobrança simples.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36980,"enunciado":"Adiantamento a depositante é uma operação passiva, na qual o cliente utilizará recurso acima do valor do saldo de sua conta-corrente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36981,"enunciado":"Empréstimos tomados pelos bancos de outras instituições financeiras, do país ou do exterior, é uma modalidade em que o banco cria moeda para suas aplicações em operações ativas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36992,"enunciado":"Para fins de ajuste de operações ativas e passivas contratadas com cláusula de variação monetária, entende-se como dia do aniversário aquele correspondente ao dia do vencimento, em qualquer mês, do título ou obrigação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36997,"enunciado":"As contas interdepartamentais funcionam como um conjunto de contas de compensação entre agências do mesmo banco.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36998,"enunciado":"As contas interbancárias funcionam como uma conta-corrente entre bancos diferentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":36999,"enunciado":"As contas interdepartamentais, quando debitadas em uma agência, são creditadas em outra agência do mesmo banco, o que resulta em saldo zero, quando é feito o balanço.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37000,"enunciado":"O resultado da contabilização das contas interbancárias redunda em direitos a receber ou em obrigações a pagar, consoante o resultado do saldo devedor ou credor, respectivamente, pelas diversas relações entre os bancos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37001,"enunciado":"No encerramento do balanço, as contas interdepartamentais são encerradas em contrapartida às contas interbancárias.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37017,"enunciado":"É vedada a abertura de conta em moeda estrangeira, exceto para estrangeiros que estejam transitoriamente no país.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37018,"enunciado":"Segundo normas do BACEN, os documentos necessários e obrigatórios para a abertura de conta de depósitos, no caso de pessoa física, são o documento de identificação, a inscrição no cadastro de pessoa física, o comprovante de residência e o comprovante de renda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37019,"enunciado":"O analfabeto poderá ser titular de conta bancária, desde que apresente procurador, nomeado por meio de procuração simples, com poderes específicos para abrir e movimentar a conta em seu nome.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37020,"enunciado":"A conta-salário é um tipo especial de conta de depósito à vista, destinada a receber salários, vencimentos, aposentadorias, pensões e similares. Não é movimentável por cheques, é isenta da cobrança de tarifas e está sujeita aos regulamentos aplicáveis às demais contas de depósitos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37021,"enunciado":"Para abrir uma conta-corrente, o jovem menor de 16 anos de idade (menor impúbere) precisa ser assistido pelo pai ou responsável legal. O maior de 16 anos e menor de 18 anos de idade (menor púbere) deve ser representado pelo pai ou responsável legal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37038,"enunciado":"A oposição ao pagamento, que é uma forma de sustação, poderá ser solicitada ao Banco Alfa por João de Sousa, por Pedro da Silva ou por Antônio Pereira, desde que seja efetuada dentro do prazo de trinta dias.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37042,"enunciado":"Nas operações de desconto bancário, alguns fraudadores, no ímpeto de obter dinheiro facilmente, emitem duplicata que não corresponde à mercadoria realmente vendida. Essa espécie de fraude é conhecida como duplicata simulada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37044,"enunciado":"O ato de frustrar desmotivadamente o pagamento de um cheque emitido também é considerado uma fraude no pagamento por meio de cheque.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37045,"enunciado":"Como uma das formas de barrar as fraudes financeiras, entre as competências do Conselho Monetário Nacional (CMN), está a determinação de percentagem máxima dos recursos que as instituições financeiras poderão emprestar a um mesmo cliente ou grupo de empresas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37046,"enunciado":"O BACEN criou o Cadastro de Emitentes de Cheques sem Fundos (CCF). Dessa forma, pode-se obstar que clientes estelionatários continuem emitindo cheques sem fundos. Os motivos que geram a inclusão automática do correntista no CCF são a prática espúria, a emissão de cheque de conta encerrada e a devolução de dois cheques sem a devida provisão de fundos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37047,"enunciado":"Para dar maior segurança ao sistema financeiro, o CMN criou a Central de Risco de Crédito (CRC), gerida pelo BACEN, com a função de facilitar a troca de informações entre as instituições financeiras. Hoje, é obrigatória a identificação dos clientes, com a inclusão do nome da pessoa física ou da pessoa jurídica na CRC, toda vez que operarem com somas iguais ou superiores a R$ 5.000,00.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37048,"enunciado":"As instituições financeiras e as demais instituições autorizadas a funcionar pelo BACEN devem classificar as operações de crédito em ordem crescente de risco.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37049,"enunciado":"No Brasil, foi implantado o Sistema de Pagamentos Brasileiro (SPB), com a função de, entre outras, dar mais agilidade e segurança às transações bancárias. Com o SPB, os recursos ficam disponíveis no dia da transferência, e há redução do risco de crédito nos pagamentos, que são irreversíveis, ou seja, não podem ser sustados ou devolvidos por falta de fundos, como pode ocorrer com os cheques.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37050,"enunciado":"Quando a iniciativa do encerramento de conta-corrente for do próprio cliente, para sua segurança, ele deve ser orientado a entregar ao banco correspondência em que solicita o encerramento de sua conta, a verificar se todos os cheques emitidos foram compensados e a entregar ao banco os cheques ainda em seu poder.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":37051,"enunciado":"As senhas e as assinaturas eletrônicas, na medida do possível, devem corresponder a dados pessoais referentes ao próprio cliente ou a seus familiares, como data de aniversário, número de telefone, parte do CPF, para não se correr risco de esquecimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":48610,"enunciado":"Segundo estatísticas do BACEN, entre 2003 e 2007, o número de cartões com função de crédito passou de 44 milhões para 117,7 milhões. No mesmo período, o número de transações com cheques processados em sistema de liquidação interbancária caiu de 2,13 bilhões para 1,99 bilhões. Quanto ao SPB, assinale a opção incorreta.","opcoes":["Além da compensação de cheques e outros papéis, o SPB admite sistema próprio para compensação e liquidação de operações realizadas em bolsas de mercadorias.","Não se admite o compartilhamento de perdas entre os participantes dos sistemas de compensação e liquidação, razão pela qual tais sistemas devem adotar mecanismos de controle de riscos.","Advertência e cassação da autorização de funcionamento das instituições financeiras privadas ou públicas, exceto as federais, são penas aplicáveis pelo BACEN nos casos de infração à lei que rege o SPB.","A liquidação extrajudicial de instituição participante do SPB não afeta o adimplemento de suas obrigações, assumidas no âmbito das câmaras ou dos prestadores de serviços de compensação e de liquidação.","Operações com derivativos estão submetidas ao sistema de compensação e liquidação."],"correta":1,"explicacao":"Gabarito: <strong>Não se admite o compartilhamento de perdas entre os participantes dos sistemas de compensação e liquidação, razão pela qual tais sistemas devem adotar mecanismos de controle de riscos.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":48614,"enunciado":"Segundo a exposição de motivos da Medida Provisória n.º 443/2008, convertida na Lei n.º 11.908/2009, a forte retração internacional do crédito observada nas últimas semanas levou o governo federal a adotar algumas medidas para ampliar a oferta de divisas, expandir a liquidez no mercado interbancário e incentivar a compra de carteiras de crédito de instituições bancárias de pequeno e médio porte. Acerca da aquisição de participação em instituições financeiras, nos termos da lei citada, assinale a opção incorreta.","opcoes":["O Banco Nacional de Desenvolvimento Econômico e Social (BNDES) não está autorizado a adquirir participações em instituições financeiras sediadas no Brasil.","As aquisições de participação acionária em instituições públicas pelo Banco do Brasil são dispensadas de licitação.","Para aquisição de participações, devem ser contratadas empresas especializadas em avaliação financeira, admitindose, nessa contratação, em certos casos, a dispensa de processo licitatório.","É vedada a aquisição de participações em empresas dos ramos de seguro, previdência e capitalização.","A compra de carteira de crédito de instituição financeira por banco autorizado pode ser feita diretamente."],"correta":3,"explicacao":"Gabarito: <strong>É vedada a aquisição de participações em empresas dos ramos de seguro, previdência e capitalização.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":48621,"enunciado":"Suponha que, até 30/6/2009, o BACEN tenha obtido resultado positivo de 3 bilhões de reais e que, no segundo semestre deste mesmo ano, o resultado tenha sido negativo de 5 bilhões de reais, compondo resultado anual negativo de 2 bilhões de reais. A partir dessa situação hipotética, assinale a opção correta.","opcoes":["O resultado é apurado anualmente e considera-se obrigação de 2 bilhões de reais do BACEN para com a União.","O resultado é apurado anualmente e considera-se que haja obrigação de 2 bilhões de reais da União para com o BACEN.","O resultado é apurado semestralmente e considera-se que o do segundo semestre seja obrigação de 5 bilhões de reais do BACEN para com a União.","O resultado é apurado semestralmente e considera-se que o do primeiro semestre seja obrigação de 3 bilhões de reais do BACEN para com a União.","O resultado é apurado semestralmente e considera-se que o do primeiro semestre seja obrigação de 3 bilhões de reais da União para com o BACEN."],"correta":3,"explicacao":"Gabarito: <strong>O resultado é apurado semestralmente e considera-se que o do primeiro semestre seja obrigação de 3 bilhões de reais do BACEN para com a União.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54714,"enunciado":"Compete à Comissão de Valores Mobiliários - CVM disciplinar as seguintes matérias: I. registro de companhias abertas. II. execução da política monetária. III. registro e fiscalização de fundos de investimento. IV. registro de distribuições de valores mobiliários. V. custódia de títulos públicos. Está correto o que se afirma APENAS em","opcoes":["II, III e V.","III, IV e V.","I, II e III.","I, II e IV.","I, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, III e IV.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54715,"enunciado":"De acordo com as normas do Conselho Monetário Nacional - CMN, os bancos múltiplos devem ser constituídos com, no mínimo, duas carteiras, sendo uma delas obrigatoriamente de","opcoes":["câmbio.","arrendamento mercantil.","investimento.","crédito, financiamento e investimento.","crédito imobiliário."],"correta":2,"explicacao":"Gabarito: <strong>investimento.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54716,"enunciado":"A CETIP S.A. tem por finalidade","opcoes":["assegurar que as operações somente sejam finalizadas caso os títulos estejam efetivamente disponíveis na posição do vendedor e os recursos relativos a seu pagamento disponibilizados integralmente pelo comprador.","dispensar a supervisão e normatização da Comissão de Valores Mobiliários para os casos de administração de carteiras e custódia de valores mobiliários.","garantir a liquidação financeira de transações de títulos privados entre instituições bancárias no Mercado de Balcão.","operar como substituta no caso de interrupção das operações diárias do Sistema de Pagamentos Brasileiro - SPB.","atuar internacionalmente, em tempo real, tendo como participantes bancos, corretoras, distribuidoras, fundos de investimento, seguradoras e fundos de pensão."],"correta":0,"explicacao":"Gabarito: <strong>assegurar que as operações somente sejam finalizadas caso os títulos estejam efetivamente disponíveis na posição do vendedor e os recursos relativos a seu pagamento disponibilizados integralmente pelo comprador.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54717,"enunciado":"A fiança bancária é uma obrigação escrita prestada à empresa que necessita de garantia para contratação de operação que envolva responsabilidade na sua execução e","opcoes":["está sujeita à incidência de Imposto sobre Operações Financeiras ? IOF.","não apresenta risco de crédito para a instituição financeira.","comprova que os recursos financeiros necessários estão depositados pela empresa na instituição financeira fiadora.","pode ser concedida somente em operações relacionadas ao comércio internacional.","substitui total ou parcialmente os adiantamentos em dinheiro ao credor por parte da empresa."],"correta":4,"explicacao":"Gabarito: <strong>substitui total ou parcialmente os adiantamentos em dinheiro ao credor por parte da empresa.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54718,"enunciado":"As entidades fechadas de previdência complementar, também conhecidas como fundos de pensão, são organizadas sob a forma de","opcoes":["planos que devem ser oferecidos a todos os colaboradores e que também podem ser adquiridos por pessoas que não tenham vínculo empregatício com a empresa patrocinadora.","fundação ou sociedade civil, sem fins lucrativos e acessíveis, exclusivamente, aos empregados de uma empresa ou grupo de empresas.","fundos PGBL ? Plano Gerador de Benefício Livre.","fundos VGBL ? Vida Gerador de Benefício Livre.","empresas vinculadas ao Ministério da Fazenda e fiscalizadas pela SUSEP - Superintendência de Seguros Privados."],"correta":1,"explicacao":"Gabarito: <strong>fundação ou sociedade civil, sem fins lucrativos e acessíveis, exclusivamente, aos empregados de uma empresa ou grupo de empresas.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54719,"enunciado":"Os depósitos a prazo feitos pelo cliente em bancos comerciais e representados por RDB","opcoes":["são aplicações financeiras isentas de risco de crédito.","oferecem liquidez diária após carência de 30 dias.","são títulos de crédito.","são recibos inegociáveis e intransferíveis.","contam com garantia do Fundo Garantidor de Crédito  - FGC até R$ 20.000,00."],"correta":3,"explicacao":"Gabarito: <strong>são recibos inegociáveis e intransferíveis.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54721,"enunciado":"Sobre os Fundos de Investimento em Direitos Creditórios - FIDC é correto afirmar:","opcoes":["A aplicação mínima é de R$ 25 mil por investidor.","Não há incidência de imposto de renda na fonte.","É requerida a existência de uma Sociedade de Propósito Específico.","Suas cotas podem ser adquiridas por todos os tipos de investidores.","É facultativa a contratação e divulgação de relatório elaborado por agência de classificação de risco."],"correta":0,"explicacao":"Gabarito: <strong>A aplicação mínima é de R$ 25 mil por investidor.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54723,"enunciado":"As cadernetas de poupança remuneram o investidor à taxa de juros de 6% ao ano com capitalização","opcoes":["mensal e atualização pela Taxa Referencial ? TR.","diária e atualização pelo Índice Geral de Preços do Mercado ? IGP-M.","mensal e atualização pelo Índice Nacional de Preços ao Consumidor Amplo ? IPCA.","trimestral e atualização pela Taxa Referencial ? TR.","semestral e atualização pelo Índice Geral de Preços ? IGP."],"correta":0,"explicacao":"Gabarito: <strong>mensal e atualização pela Taxa Referencial ? TR.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54724,"enunciado":"O arrendamento mercantil (leasing) é uma operação com características legais próprias, como","opcoes":["destinação exclusivamente à pessoa jurídica.","cobrança de Imposto sobre Operações Financeiras ? IOF.","cessão do uso de um bem, por determinado prazo, mediante condições contratadas entre arrendador e arrendatário.","prazo mínimo de arrendamento de três anos para bens com vida útil de até cinco anos.","aquisição obrigatória do bem pelo arrendatário ao final do prazo do contrato."],"correta":2,"explicacao":"Gabarito: <strong>cessão do uso de um bem, por determinado prazo, mediante condições contratadas entre arrendador e arrendatário.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54725,"enunciado":"Os contratos negociados nos mercados futuros são caracterizados","opcoes":["pela dispensa da prestação de garantias pelas partes.","pelas diferenças de preços ajustadas no vencimento.","pelas diferenças de preços ajustadas diariamente.","pelas cláusulas redigidas de acordo com a conveniência das partes.","pela padronização quando as partes são instituições financeiras."],"correta":2,"explicacao":"Gabarito: <strong>pelas diferenças de preços ajustadas diariamente.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54726,"enunciado":"No mercado de câmbio no Brasil são realizadas operações","opcoes":["no segmento flutuante, relativas a importação e exportação de mercadorias e serviços.","de troca de moeda nacional exclusivamente pelo dólar norte-americano ou vice-versa.","no mercado à vista apenas por pessoa jurídica.","pelos agentes autorizados pelo Banco Central do Brasil.","dispensadas da regulamentação e fiscalização pelo Banco Central do Brasil."],"correta":3,"explicacao":"Gabarito: <strong>pelos agentes autorizados pelo Banco Central do Brasil.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54727,"enunciado":"As operações para financiamento do capital de giro das empresas vêm sendo preferencialmente formalizadas por meio de Cédula de Crédito Bancário ? CCB, que proporciona","opcoes":["a dispensa de custódia do título na respectiva instituição financeira.","a negociabilidade do certificado no mercado secundário.","a promessa de pagamento mediante conferência de bens.","a efetividade processual de um título executivo judicial.","a garantia do Fundo Garantidor de Crédito − FGC."],"correta":1,"explicacao":"Gabarito: <strong>a negociabilidade do certificado no mercado secundário.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54728,"enunciado":"Sobre o mercado de seguros no Brasil, considere: I. O Instituto de Resseguros do Brasil (hoje IRB-Brasil Re) tem seu capital controlado integralmente pela União. II. A Lei Complementar no 126/2007 abriu o mercado brasileiro de resseguros e possibilitou a instalação e funcionamento de outras companhias no setor. III. A Superintendência de Seguros Privados − SUSEP é responsável pelo controle e fiscalização dos mercados de seguro, previdência privada aberta, capitalização e resseguro. IV. As seguradoras são organizadas sob a forma de sociedades anônimas, não estando sujeitas a falência nem podendo impetrar concordata, embora possam ser liquidadas, voluntária ou compulsoriamente. V. O seguro garantia é destinado exclusivamente aos órgãos públicos da administração direta e indireta federais, estaduais e municipais. São características do mercado de seguros no Brasil o que se afirma APENAS em","opcoes":["II, III e IV.","II, IV e V.","I, II e III.","I, II e IV.","I, III, IV e V."],"correta":0,"explicacao":"Gabarito: <strong>II, III e IV.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54729,"enunciado":"A Lei nº 9.613/98, que dispõe sobre os crimes de lavagem ou ocultação de bens, direitos e valores, determina que","opcoes":["a obtenção de proveito específico é exigida para caracterizar o crime.","é facultado à instituição financeira fornecer talonário de cheque ao depositante enquanto são verificadas as informações constantes da ficha proposta.","os crimes são afiançáveis e permitem liberdade provisória.","a simples ocultação de valores é suficiente para cumprir exigência punitiva.","o agente pode ser punido, ainda que a posse ou o uso dos bens não lhe tenha trazido nenhum proveito."],"correta":4,"explicacao":"Gabarito: <strong>o agente pode ser punido, ainda que a posse ou o uso dos bens não lhe tenha trazido nenhum proveito.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":54732,"enunciado":"O Fundo Garantidor de Crédito ? FGC é uma entidade privada, sem fins lucrativos, que administra o mecanismo de proteção aos correntistas, poupadores e investidores, contra instituições financeiras em caso de intervenção, liquidação ou falência. São cobertos limitadamente pela garantia","opcoes":["Letras Financeiras do Tesouro.","Fundos de Investimentos Financeiros.","Notas Promissórias Comerciais.","Letras Hipotecárias.","Depósitos Judiciais."],"correta":3,"explicacao":"Gabarito: <strong>Letras Hipotecárias.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204475,"enunciado":"Por constituírem exemplo típico de sociedade de capitalização, os fundos de pensão devem seguir as diretrizes estabelecidas pelo CMN no que se refere à aplicação dos recursos dos planos de benefícios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204476,"enunciado":"Compete ao Conselho Nacional de Seguros Privados fixar as diretrizes e as normas dos seguros privados bem como prescrever critérios de constituição das sociedades seguradoras, de capitalização, entidades de previdência privada aberta e resseguradores e determinar limites legais e técnicos das respectivas operações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204477,"enunciado":"A fiscalização das seguradoras e corretoras e a regulamentação das operações de seguros são de competência do Instituto de Resseguros do Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204478,"enunciado":"A remuneração de garantia cobrada pelas administradoras de cartões de crédito corresponde à comissão paga pelos estabelecimentos a determinada bandeira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204479,"enunciado":"No cálculo do deságio sobre o valor de face do ativo, as empresas de factoring consideram, além do custo dos recursos por elas obtidos, o spread representativo da taxa de risco envolvida na transação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204482,"enunciado":"É possível a transferência de certificado de depósito bancário mediante endosso nominativo. Nesse caso, o endosso acarretará, para o endossante, a responsabilidade tanto pela existência do crédito quanto pelo seu pagamento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204483,"enunciado":"As letras de câmbio são instrumentos de captação das sociedades de crédito emitidos unicamente a taxas prefixadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204484,"enunciado":"As notas promissórias comerciais (commercial papers), além de serem isentas do imposto sobre operações financeiras, permitem a captação de recursos fora do sistema financeiro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204485,"enunciado":"São vantagens da cobrança bancária para o cedente do título a garantia do processo de cobrança e o crédito imediato dos títulos bancários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204486,"enunciado":"Desde que consigam replicar o retorno de um índice de referência, os fundos de renda fixa referenciados têm liberdade para decidir como investir seus recursos, já que até 49% do patrimônio desses fundos pode ser investido em ações e derivativos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204487,"enunciado":"Se o fornecedor da matéria-prima para a empresa em questão prestar garantias para que o BRB ofereça crédito à empresa para aquisição dessa matéria-prima, então não haverá como caracterizar esta operação como Vendor Finance.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204488,"enunciado":"A referida empresa poderá oferecer aos seus clientes pessoas naturais o crédito direto ao consumidor com interveniência, provido pelo BRB, para que eles adquiram os seus produtos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204489,"enunciado":"A conta garantida é modalidade de linha de crédito adequada para cobrir eventuais deficiências do fluxo de caixa dessa empresa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204491,"enunciado":"Uma conta de depósitos de poupança que renda juros de 0,5% ao mês mais a variação da TR já garante ao seu correntista, sem levar em conta a variação da taxa referencial, mais de 6% de juros ao ano.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204492,"enunciado":"Embora todos os bancos possam cobrar tarifas sobre as contas de poupança, os correntistas dessas contas terão direito, em qualquer banco e sem custo algum, a extratos ilimitados nos terminais de autoatendimento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204493,"enunciado":"O saldo na conta de poupança só pode ser resgatado no dia do aniversário; caso precise do dinheiro antes desse dia, o titular dessa conta não poderá sacá-lo, ainda que abra mão dos rendimentos daquele mês.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204494,"enunciado":"É permitida a cobrança da tarifa de anuidade ainda que o cartão de crédito seja o básico.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204495,"enunciado":"Conforme as novas regras do Conselho Monetário Nacional, os cartões de crédito básicos podem ser tanto nacionais quanto internacionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204496,"enunciado":"O percentual para pagamento mínimo é superior a 10% do valor da fatura do cartão de crédito.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204500,"enunciado":"Se houver um saldo de R$ 120.000,00 na conta de depósitos à vista de um único titular, o montante desse saldo que não estará coberto pelo FGC será de R$ 80.000,00.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204501,"enunciado":"Os fundos de investimento e os fundos de ações não têm cobertura do FGC.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204502,"enunciado":"O FGC é uma associação civil sem fins lucrativos e não exerce nenhuma função pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204503,"enunciado":"O FGC foi criado para garantir os recursos mantidos, principalmente, em contas de depósito à vista, de poupança e de depósito a prazo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204504,"enunciado":"O prazo de pagamento de um título de capitalização não necessariamente coincide com o seu prazo de vigência, que é o período no qual o título está em vigor, dando direito aos sorteios existentes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204505,"enunciado":"Se a taxa de carregamento do plano PGBL for igual a 5%, isso significará que, anualmente, será debitado o valor equivalente a esse percentual do saldo mantido no referido plano.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":204506,"enunciado":"Um produto de previdência do tipo VGBL ou PGBL, por lei, pode resultar apenas em valorização positiva, ainda que esse plano seja considerado agressivo e aplique parte dos recursos em renda variável.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233935,"enunciado":"De acordo com a Lei nº 4.595/1964, as Cooperativas de Crédito são equiparadas às demais instituições financeiras, e seu funcionamento deve ser autorizado e regulado pelo Banco Central do Brasil. O principal objetivo de uma Cooperativa de Crédito é a","opcoes":["concessão de cartas de crédito, que estejam vinculadas a títulos do Governo Federal, às demais instituições financeiras.","fiscalização das operações de crédito realizadas pelas demais instituições financeiras","prestação de assistência creditícia e de serviços de natureza bancária a seus associados, em condições mais favoráveis que as praticadas pelo mercado.","prestação do serviço de proteção ao crédito ao mercado financeiro, atuando principalmente como um Fundo Garantidor de Crédito.","regulamentação da prestação do serviço de concessão de crédito, realizado por pessoas físicas associadas a uma determinada instituição financeira."],"correta":2,"explicacao":"Gabarito: <strong>prestação de assistência creditícia e de serviços de natureza bancária a seus associados, em condições mais favoráveis que as praticadas pelo mercado.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233936,"enunciado":"O mercado de seguros surgiu da necessidade que as pessoas e as empresas têm de se associar para suportar coletivamente suas perdas individuais. Foram criadas, então, as seguradoras, as corretoras de seguro, além de algumas instituições encarregadas não só de fixar normas e políticas, mas também de regular e fiscalizar esse mercado. Com o surgimento de tal necessidade, qual instituição foi criada para, além de fiscalizar as seguradoras e corretoras, também regulamentar as operações de seguro, fixando as condições da apólice e dos planos de operação e valores de tarifas?","opcoes":["Seguradora Líder","Câmara Especial de Seguros","Superintendência dos Seguros Privados","Conselho Nacional de Seguros Privados","Instituto de Resseguros do Brasil"],"correta":2,"explicacao":"Gabarito: <strong>Superintendência dos Seguros Privados</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233937,"enunciado":"As instituições financeiras, controladas pelos Governos Estaduais, que fornecem crédito de médio e longo prazos para as empresas de seus respectivos Estados são as(os)","opcoes":["Caixas Econômicas","Cooperativas de Crédito","Sociedades Distribuidoras","Bancos Comerciais","Bancos de Desenvolvimento"],"correta":4,"explicacao":"Gabarito: <strong>Bancos de Desenvolvimento</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233938,"enunciado":"As seguradoras também se preocupam com os riscos que as cercam por conta da possibilidade de um colapso no mercado ou, até mesmo, pela ocorrência simultânea de muitos sinistros. Nesse sentido, para se aliviar parcialmente do risco de um seguro já feito, a companhia poderá contrair um novo seguro em outra instituição, através de uma operação denominada","opcoes":["corretagem de seguro","resseguro","seguro de incêndio","seguro de veículos","seguro de vida"],"correta":1,"explicacao":"Gabarito: <strong>resseguro</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233939,"enunciado":"No mercado financeiro, além dos bancos, existem outras instituições que podem realizar transações financeiras. Entre elas, estão as Sociedades de Fomento Mercantil, que prestam o serviço de compra de direitos de um contrato de venda mercantil, como, por exemplo, a compra de duplicatas de uma empresa mediante um deságio. No mercado financeiro, essa operação é denominada","opcoes":["Aval bancário","Hot Money","Leasing","Factoring","Finança bancária"],"correta":3,"explicacao":"Gabarito: <strong>Factoring</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233940,"enunciado":"Os bancos comerciais são o tipo de instituição financeira que mais realizam movimentação monetária em número de transações, devido ao grande número de instituições e clientes. Dentre os tipos de captação de recursos dos clientes, os bancos possuem um tipo de captação conhecida como “captação a custo zero”, realizada por meio das contas-correntes dos clientes. O tipo de operação em que são realizadas entradas de dinheiro em contas-correntes é denominado captação de","opcoes":["clientes","dinheiro","depósitos à vista","recursos a prazo","investimentos a curto prazo"],"correta":2,"explicacao":"Gabarito: <strong>depósitos à vista</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233941,"enunciado":"Atualmente, o mercado financeiro oferece para as empresas algumas modalidades de captação de recursos, algumas delas sem a intermediação bancária. Com essa característica, o título de crédito emitido pelas empresas visando à captação pública de recursos para o seu capital de giro é denominado","opcoes":["Factoring","Hot Money","Export Note","Commercial Paper","Certificado de Depósito Bancário (CDB)"],"correta":3,"explicacao":"Gabarito: <strong>Commercial Paper</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233943,"enunciado":"O mercado cambial é o segmento financeiro em que ocorrem operações de negociação com moedas internacionais. A operação que envolve compra e venda de moedas estrangeiras em espécie é denominada","opcoes":["câmbio manual","câmbio sacado","exportação","importação","transferência"],"correta":0,"explicacao":"Gabarito: <strong>câmbio manual</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233945,"enunciado":"Atualmente, os bancos possuem diversos tipos de produtos para financiar as relações comerciais, desde as realizadas por microempresas até as realizadas por grandes empresas. Qual é o nome da operação realizada quando pequenas indústrias vendem para grandes lojas comerciais e estas procuram os bancos para dilatar o prazo de pagamento mediante a retenção de juros?","opcoes":["Compror Finance","Vendor Finance","Capital de Giro","Contrato de Mútuo","Crédito Rotativo"],"correta":0,"explicacao":"Gabarito: <strong>Compror Finance</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233946,"enunciado":"Nos dias de hoje, o uso do “dinheiro de plástico” está superando cada vez mais outras modalidades de pagamento, que, com o passar dos anos, estão ficando obsoletas. Um tipo de “dinheiro de plástico” muito utilizado no comércio de rua é o","opcoes":["cartão cidadão","cartão de crédito","cartão de senhas","talão de cheques","internet banking"],"correta":1,"explicacao":"Gabarito: <strong>cartão de crédito</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233947,"enunciado":"Com o crescente avanço tecnológico, está cada vez mais fácil realizar operações bancárias sem que se precise ir pessoalmente a uma agência. Que nome se dá ao tipo de acesso bancário realizado em terminais de computadores, caixas eletrônicos e bancos 24 horas?","opcoes":["Banco de Dados","Débito Automático","Home Office Banking","Internet Banking","Remote Banking"],"correta":4,"explicacao":"Gabarito: <strong>Remote Banking</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233948,"enunciado":"Devido à grande exposição ao risco de crédito, os bancos precisam utilizar meios para garantir suas operações e salvaguardar seus ativos. Qual o tipo de operação que garante o cumprimento de uma obrigação na compra de um bem a crédito, em que há a transferência desse bem, móvel ou imóvel, do devedor ao credor?","opcoes":["Hipoteca","Fiança bancária","Alienação fiduciária","Penhor","Aval bancário"],"correta":2,"explicacao":"Gabarito: <strong>Alienação fiduciária</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233949,"enunciado":"Dentre os principais papéis privados negociados no mercado financeiro estão as letras de câmbio, que são emitidas pelos financiados dos contratos de crédito e aceitas pelas instituições financeiras participantes da operação. Posteriormente, elas são vendidas a investidores, por meio dos mecanismos de intermediação do mercado financeiro Nesse sentido, as letras de câmbio se caracterizam como títulos","opcoes":["emitidos por instituições que atuam com crédito imobiliário.","transferíveis por meio de endosso, que podem ser pré-fixados ou pós-fixados.","lastreados em ações ordinárias, podendo ser lançados no exterior.","nominativos, com renda fixa e prazo determinado de vencimento.","ao portador e com limite de valor definido pelo proprietário."],"correta":3,"explicacao":"Gabarito: <strong>nominativos, com renda fixa e prazo determinado de vencimento.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":233950,"enunciado":"A lavagem de dinheiro é uma das ações realizadas para tentar tornar lícito um dinheiro proveniente de atividades ilícitas. Para ajudar na prevenção e combate a esse tipo de crime, a Lei nº 9.613/1998, dentre outras ações, determina que as instituições financeiras devem","opcoes":["identificar seus clientes e manter o cadastro atualizado.","identificar as cédulas de dinheiro, mantendo seu registro atualizado.","instalar portas eletrônicas com detector de metais.","instalar câmeras nos caixas eletrônicos.","proibir o uso de telefone celular nas agências bancárias."],"correta":0,"explicacao":"Gabarito: <strong>identificar seus clientes e manter o cadastro atualizado.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236929,"enunciado":"No ato de abertura de uma conta-corrente, os bancos devem apresentar aos clientes todas as condições básicas para movimentação e encerramento de conta. Essas condições devem constar, obrigatoriamente, no(a)","opcoes":["folheto de propaganda do banco","contrato de abertura de conta-corrente","site do banco, para consulta de todos os interessados","intranet do banco, para consulta dos funcionários","proposta para cadastro no Banco Central"],"correta":1,"explicacao":"Gabarito: <strong>contrato de abertura de conta-corrente</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236934,"enunciado":"O prazo de bloqueio dos cheques varia em função dos seus valores. Para a liberação dos depósitos de cheques com valores inferiores a R$ 300,00, o prazo é de até","opcoes":["um dia útil, a contar da data do depósito.","dois dias úteis, contados a partir do dia útil seguinte ao do depósito.","dois dias corridos, contados a partir do dia útil seguinte ao depósito.","três dias corridos, a contar da data do depósito.","quatro dias úteis, a contar da data do depósito"],"correta":1,"explicacao":"Gabarito: <strong>dois dias úteis, contados a partir do dia útil seguinte ao do depósito.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236935,"enunciado":"Na composição do sistema financeiro, as principais instituições estão constituídas sob a forma de banco múltiplo, que oferece ampla gama de serviços bancários. Uma das funções básicas dos bancos comerciais é a","opcoes":["atuação centrada nos mercados de câmbio, nos títulos públicos e privados, nos valores mobiliários e nas mercadorias e futuros.","concessão de crédito aos cooperados, quase sempre produtores rurais.","concessão de financiamento de longo prazo para a realização de investimentos em todos os segmentos da economia nacional, com baixas taxas de juros.","captação de depósitos à vista e de depósitos de poupança.","captação dos depósitos do Fundo de Garantia por Tempo de Serviço (FGTS)."],"correta":3,"explicacao":"Gabarito: <strong>captação de depósitos à vista e de depósitos de poupança.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236936,"enunciado":"O cheque é considerado pelo Banco Central uma ordem de pagamento à vista e um título de crédito com características peculiares. O cheque cruzado, por exemplo, poderá ser pago somente em forma de","opcoes":["depósito em conta","documento de crédito (DOC)","saque direto no caixa","ordem de pagamento","transferência eletrônica direta (TED)"],"correta":0,"explicacao":"Gabarito: <strong>depósito em conta</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236937,"enunciado":"As sociedades corretoras de títulos e valores mobiliários são constituídas sob a forma de sociedade anônima ou por quotas de responsabilidade limitada. Um dos seus objetivos principais é","opcoes":["controlar o mercado de seguros.","regular o mercado de valores imobiliários.","assegurar o funcionamento eficiente do mercado de Bolsa de Valores.","subscrever emissões de títulos e valores mobiliários no mercado.","estimular a formação de poupança e sua aplicação em valores mobiliários."],"correta":3,"explicacao":"Gabarito: <strong>subscrever emissões de títulos e valores mobiliários no mercado.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236938,"enunciado":"Qual é a Companhia de Capital Aberto, instituída pelo Conselho Monetário Nacional, que atua como integradora do mercado financeiro, oferecendo serviços de registro, de central depositária, de negociação e liquidação de ativos e títulos?","opcoes":["BNDES","Banco Central do Brasil","Selic","Cetip","Caixa Econômica Federal"],"correta":3,"explicacao":"Gabarito: <strong>Cetip</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236942,"enunciado":"As sociedades de arrendamento mercantil são constituídas sob a forma de sociedade anônima, devendo constar obrigatoriamente na sua denominação social a expressão “Arrendamento Mercantil”. Uma das operações típicas realizadas por essas sociedades é o(a)","opcoes":["leasing","factoring","underwriting","câmbio internacional","venda de ações"],"correta":0,"explicacao":"Gabarito: <strong>leasing</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236946,"enunciado":"No mercado à vista de ações, ocorre a compra ou a venda de uma determinada quantidade de ações. Quando há a realização do negócio, a operação é liquidada no terceiro dia útil após o fechamento da compra. Nesse mercado, os preços das ações são formados, diretamente, de acordo com a(o)","opcoes":["projeção futura de mercado","força de oferta e demanda de cada papel","probabilidade futura de lucros de cada papel","cálculo estatístico de mercado","histórico de rentabilidade de cada papel"],"correta":1,"explicacao":"Gabarito: <strong>força de oferta e demanda de cada papel</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":236947,"enunciado":"No mercado financeiro, a intermediação financeira desenvolve-se de forma segmentada, com base em quatro subdivisões: mercados monetário, cambial, de crédito e de capitais. O mercado de crédito visa, fundamentalmente, a","opcoes":["fiscalizar as operações dos seus agentes econômicos.","controlar a liquidez da economia com operações de curto e curtíssimo prazos.","realizar as operações de compra e venda de moedas internacionais conversíveis.","suprir as necessidades de investimentos dos agentes econômicos a médio e longo prazos.","suprir as necessidades de caixa de curto e médio prazos dos agentes econômicos, sejam eles pessoas físicas ou jurídicas."],"correta":4,"explicacao":"Gabarito: <strong>suprir as necessidades de caixa de curto e médio prazos dos agentes econômicos, sejam eles pessoas físicas ou jurídicas.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":261052,"enunciado":"Considerando o disposto na Lei n.º 9.613/1998, nas Resoluções n.º 3.224/2004 e n.º 3.844/2010 e nas Cartas-Circulares do BACEN n.º 3.442/2010 e n.º 3.542/2012, julgue os itens seguintes.\n\n\nA Carta-Circular n.º 3.442 divulga as operações que configuram indícios dos crimes de lavagem ou ocultação de bens.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":261053,"enunciado":"Considerando o disposto na Lei n.º 9.613/1998, nas Resoluções n.º 3.224/2004 e n.º 3.844/2010 e nas Cartas-Circulares do BACEN n.º 3.442/2010 e n.º 3.542/2012, julgue os itens seguintes.\n\n\nA Carta-Circular n.º 3.542 trata das operações que configuram indícios dos crimes previstos na Lei n.º 9.613, como, por exemplo, da realização de saques que apresentem atipicidade em relação à atividade econômica do cliente e dos aumentos substanciais no volume de depósitos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":290723,"enunciado":"Após estabelecer claramente objetivos e opositores, as empresas precisam definir quais as estratégias de ataque, visando ao alcance de vantagem competitiva. A empresa atacante se iguala à sua oponente, no que se refere a produto, propaganda, preço e distribuição, por meio da estratégia de","opcoes":["ataque pelo flanco.","manobra de cerco.","ataque frontal.","bypass.","guerrilha."],"correta":2,"explicacao":"Gabarito: <strong>ataque frontal.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":290732,"enunciado":"No Brasil, com a estabilidade econômica a partir dos anos 1990 e a abertura do mercado bancário brasileiro para a entrada de bancos estrangeiros, o setor financeiro tornou- se bem mais competitivo. Com esse aumento da competitividade, torna-se fundamental, às organizações que almejam um melhor posicionamento no mercado, diferenciar seus serviços de maneira significativa aos consumidores. Uma ação para diferenciação eficaz de serviços é a","opcoes":["restrição dos serviços de autoatendimento.","depreciação de informações sobre desejos e necessidades dos clientes.","padronização dos serviços.","extinção do “gerente de fila” (pré-atendimento).","alocação de gerentes para atendimentos especiais (gerentes de negócios)."],"correta":4,"explicacao":"Gabarito: <strong>alocação de gerentes para atendimentos especiais (gerentes de negócios).</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":290744,"enunciado":"A operação por meio da qual a instituição financeira garante em contrato, perante terceiros, o cumprimento de obrigações decorrentes de riscos assumidos por parte do seu cliente é denominada","opcoes":["fiança bancária.","penhor mercantil.","alienação fiduciária.","adiantamento de contrato de câmbio.","aval."],"correta":0,"explicacao":"Gabarito: <strong>fiança bancária.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":290745,"enunciado":"O crime de lavagem de dinheiro caracteriza-se por um conjunto de operações comerciais ou financeiras que buscam a incorporação na economia de cada país, de modo transitório ou permanente, de recursos, bens e valores de origem ilícita e que se desenvolvem por meio de um processo dinâmico que envolve, teoricamente, três fases independentes:","opcoes":["cobrança, conversão e destinação.","colocação, ocultação e integração.","contratação, registro e utilização.","exportação, tributação e distribuição.","aplicação, valorização e resgate."],"correta":1,"explicacao":"Gabarito: <strong>colocação, ocultação e integração.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":290746,"enunciado":"Produto que, após um período de acumulação de recursos, proporciona aos investidores uma renda mensal - que poderá ser vitalícia ou por período determinado - ou um pagamento único, é o","opcoes":["CDB - Certificado de Depósito Bancário.","FIDC - Fundo de Investimento em Direitos Creditórios.","Ourocap - Banco do Brasil.","BB Consórcio de Serviços.","PGBL - Plano Gerador de Benefício Livre."],"correta":4,"explicacao":"Gabarito: <strong>PGBL - Plano Gerador de Benefício Livre.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317285,"enunciado":"De acordo com a Resolução n° 2.682/1999, do Banco Central do Brasil, pode-se afirmar que I. uma empresa com saldo vencido e não pago há mais de 360 dias deve ser classificada em nível de risco \"F\". II. uma empresa classificada em nível de risco \"A\" deve ter 0,5% do seu saldo devedor provisionado pela instituição financeira para crédito de liquidação duvidosa. III. uma operação classificada em nível de risco \"H\" deve ter 100% do seu saldo devedor provisionado pela instituição financeira para crédito de liquidação duvidosa. Quais afirmações estão correias?","opcoes":["Apenas a I.","Apenas a II.","Apenas a III.","Apenas a I e a II.","Apenas a II e a III."],"correta":4,"explicacao":"Gabarito: <strong>Apenas a II e a III.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317289,"enunciado":"Considerando os ativos financeiros emitidos pelos participantes dos mercados financeiros, quais, dentre as seguintes instituições, captam recursos via emissão de letras de câmbio, letras imobiliárias, e certificados de depósitos bancários, respectivamente?","opcoes":["Corretoras de câmbio, sociedades de arrendamento mercantil e bancos comerciais.","Corretoras de câmbio sociedades de crédito imobiliário e bancos comerciais.","Corretoras de câmbio, sociedades de arrendamento mercantil e bancos de investimento.","Bancos comerciais, sociedades de arrendamento mercantil e bancos de investimento.","Sociedades de crédito investimento e financiamento sociedades de crédito imobiliário e bancos comerciais."],"correta":4,"explicacao":"Gabarito: <strong>Sociedades de crédito investimento e financiamento sociedades de crédito imobiliário e bancos comerciais.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317291,"enunciado":"Segundo o princípio do relacionamento, embora o marketing de relacionamento destine-se diretamente ao trato do c l ie n te _________ , não é demais lembrar que o relacionamento com o cliente começa___________ p r im e iro ___________ ocorrer. Assinale a alternativa cujas palavras ou expressões completam corretamente as lacunas da frase acima.","opcoes":["pré-compra — no momento em que o — negócio","pós-compra — no momento em que o — empréstimo","pré-compra — depois de o — depósito","pós-compra — antes de o — negócio","pré-compra — antes de o — depósito"],"correta":3,"explicacao":"Gabarito: <strong>pós-compra — antes de o — negócio</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317292,"enunciado":"As reclamações de clientes das instituições bancárias brasileiras que têm fugido ao controle dessas instituições referem-se, em especial,","opcoes":["à dificuldade em operar caixas eletrônicos.","a empregados sem vontade ou vagarosos na ajuda ao cliente.","a falhas nos sistemas mecânicos de segurança.","à falta de estratégias de recuperação de serviços.","às longas filas de espera para atendimento."],"correta":2,"explicacao":"Gabarito: <strong>a falhas nos sistemas mecânicos de segurança.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317293,"enunciado":"A evolução do conceito de marketing de serviços vem ocorrendo à medida que o setor terciário, do qual os bancos fazem parte, vem obtendo mais destaque, já sendo, em países desenvolvidos, responsável pela maior parte do PIB (Produto Interno Bruto). Para se atender aos clientes de maneira diferenciada, é imprescindível conhecer as características específicas desse setor de serviços. Relacione as colunas, associando a descrição da característica do setor de serviços à sua respectiva denominação. A ordem correta dos números da segunda coluna, de cima para baixo, é","opcoes":["5-4-2-3.","5-2-1-3.","4-2-1-5.","3-5-4-1.","2-1-3-4."],"correta":2,"explicacao":"Gabarito: <strong>4-2-1-5.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317294,"enunciado":"Considere as afirmações abaixo a respeito dos fatores da satisfação com o atendimento bancário. I. Quando um cliente avalia a sua satisfação com relação ao atendimento bancário, ele normalmente não estende seus defeitos a todo o serviço da instituição. II. A satisfação pode ser classificada em categorias de acordo com as reações afetivas, tais como contentamento, surpresa e, até, alívio. III. A satisfação, do ponto de vista do cliente, é fundamental tanto para o seu bem-estar individual como para os lucros da empresa. Quais estão corretas?","opcoes":["Apenas a I.","Apenas a III.","Apenas a I e a II.","Apenas a II e a III.","A I, a II e a III."],"correta":3,"explicacao":"Gabarito: <strong>Apenas a II e a III.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317295,"enunciado":"A discussão sobre governança corporativa envolve a criação de mecanismos internos e externos que assegurem","opcoes":["um maior investimento cm marketing bancário e vendas.","a prioridade da instituição na remuneração dos conselheiros bancários.","a prática de atividades de responsabilidade social que promovam comunidades.","a adoção de monitoramento bancário por meio de indicadores de desempenho contábil.","a tomada de decisões pela organização no melhor interesse dos investidores."],"correta":4,"explicacao":"Gabarito: <strong>a tomada de decisões pela organização no melhor interesse dos investidores.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317296,"enunciado":"A adoção, cada vez maior, de tecnologia pelas agências não permite apenas agilizar procedimentos, mas também, de maneira destacada,","opcoes":["identificar melhor o perfil de cada cliente.","evitar erros nos cálculos e nos resultados das operações.","definir um bom ponto de venda para uma nova agência.","estabelecer linhas para as políticas de governança corporativa,","alavancar a propaganda bancária."],"correta":0,"explicacao":"Gabarito: <strong>identificar melhor o perfil de cada cliente.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317297,"enunciado":"Assinale V para as afirmativas verdadeiras e F para as falsas, considerando a temática da propaganda bancária. ( ) A função da propaganda institucional é mostrar os diferenciais e as vantagens dos diversos produtos bancários. ( ) Um slogan não é adequado para resumir o posicionamento da marca da instituição junto ao mercado. ( ) Estudos de comportamento do consumidor têm indicado que as pessoas estão mais interessadas na qualidade das empresas bancárias do que no atendimento de suas necessidades e desejos. A seqüência correta de preenchimento dos parênteses, de cima para baixo, é","opcoes":["F-F-F.","F-F-V.","F-V-V.","V-V-F.","V-V-V."],"correta":0,"explicacao":"Gabarito: <strong>F-F-F.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":317298,"enunciado":"Os bancos têm travado uma verdadeira batalha para atrair um grupo de clientes denominado private. Sobre esse promissor segmento, é INCORRETO afirmar que","opcoes":["é um dos três grupos (juntamente com clicntes consumer e corporate) que, há algum tempo, as instituições bancárias do País buscam conquistar.","os clientes private são também conhecidos como grandes fortunas.","os bancos têm criado serviços diferenciados para esse público-alvo, inclusive com o lançamento de grifes.","alguns benefícios estão sendo proporcionados aos clientes private, tais como rede exclusiva de agências e taxa diferenciada do cheque especial.","o que os indivíduos desse segmento geralmente procuram é investimento em produtos e eventos culturais."],"correta":4,"explicacao":"Gabarito: <strong>o que os indivíduos desse segmento geralmente procuram é investimento em produtos e eventos culturais.</strong>.","banca":"FDRH","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321879,"enunciado":"As técnicas de vendas podem ampliar a penetração de mercado de determinados produtos financeiros. Sabe-se que caminham, em paralelo com o processo de marketing de relacionamento, o planejamento e a fidelização. Sobre esse assunto, é correto afirmar que","opcoes":["o especialista em vendas tem a função de apresentar o produto, preocupando-se com a imagem e a credibilidade da instituição perante os clientes finais.","o especialista em vendas se preocupa com a burocracia dos serviços para fidelização dos clientes.","as vendas visam prioritariamente ao crescimento da instituição, sem preocupação com os clientes.","as instituições não focam apenas os aspectos humanos e nem sempre se preocupam com sua imagem.","as instituições focam a impessoalidade através do sistema hierarquizado."],"correta":0,"explicacao":"Gabarito: <strong>o especialista em vendas tem a função de apresentar o produto, preocupando-se com a imagem e a credibilidade da instituição perante os clientes finais.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321880,"enunciado":"O marketing de relacionamento favorece o vendedor, em nível proativo, de forma que ele vende os serviços e faz consultas posteriores ao consumidor para obter o feedback quanto ao nível de satisfação e auxiliá-lo na utilização do produto. O processo de feedback, nesta ação e reação de relacionamento e comunicação, favorece","opcoes":["um sistema de relacionamento ineficaz.","um sistema de comunicação e relacionamento que movem a retroalimentação das informações.","uma comunicação variada em que existem várias maneiras de administrar.","uma comunicação limitada por normas escritas.","a comunicação em massa através da linha de vendas."],"correta":1,"explicacao":"Gabarito: <strong>um sistema de comunicação e relacionamento que movem a retroalimentação das informações.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321881,"enunciado":"Ao nível de planejamento estratégico, as ações de vendas estão voltadas, para fins de execução, ao consumidor final. Com vistas ao planejamento de vendas em si,","opcoes":["as vendas estão relacionadas ao planejamento estratégico de longo prazo.","as vendas estão relacionadas com os níveis estratégico, tático e operacional.","cabe ao planejamento estratégico contratar uma assessoria para implantar programas de metas de retenção de clientes.","cabe aos subsistemas de planejamento a integração das diversas partes.","cabe aos sistemas de informação a definição do nível a ser aplicado aos recursos humanos."],"correta":1,"explicacao":"Gabarito: <strong>as vendas estão relacionadas com os níveis estratégico, tático e operacional.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321882,"enunciado":"A promoção de vendas é uma das ferramentas de comunicação integrada de marketing mais eficazes e vem ganhando cada vez mais importância dentro do composto de marketing. Sua utilização é feita, principalmente, para completar as demais ferramentas, e é nesse sentido que consiste a sua força Dessa forma, as promoções de vendas são direcionadas .","opcoes":["aos produtos em relação aos serviços ofertados ao consumidor final.","à divulgação de um novo produto em aberto, internamente na empresa, buscando o aproveitamento das sugestões dos empregados para o seu desenvolvimento.","à avaliação de novos clientes e produtos em busca da comunicação integrada.","à relação entre custos e benefícios no perfil desejado da venda.","aos intermediários, atacadistas e varejistas e aos clientes e consumidores finais."],"correta":4,"explicacao":"Gabarito: <strong>aos intermediários, atacadistas e varejistas e aos clientes e consumidores finais.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321883,"enunciado":"Forças dinâmicas e inter-relacionadas, externas ao processo de planejamento estratégico, apresentam ameaças e oportunidades, devendo ser consideradas ao reunir os mercados- alvo aos compostos de marketing. (Sandhusen; 2007) Em uma análise do ambiente do mercado, enquadram-se dentre as variáveis ambientais que influem no planejamen- to estratégico as de","opcoes":["planejamento tático e interferências no planejamento do plano de negócios.","política de regras e políticas disciplinares, em relação ao ambiente externo.","nível macroambiental e microambiental que favorecem a análise ambiental.","política de regras e políticas disciplinares, em relação ao ambiente interno.","planejamento estratégico empresarial e o plano de negócios que possibilita a análise e o trabalho em grupo."],"correta":2,"explicacao":"Gabarito: <strong>nível macroambiental e microambiental que favorecem a análise ambiental.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321884,"enunciado":"A diretoria do Banco ABC tem tentado ampliar suas atividades de “linha de frente” (front office), aumentando o contato dos clientes com suas atividades bancárias. Uma vantagem para o Banco, dentre outras, advinda dessa decisão, é","opcoes":["a proposta de relacionamento menos próximo.","a liberação de tempo do front office para um relacionamento de melhor qualidade.","o menor conhecimento técnico exigido dos colaboradores.","a imagem de serviço personalizado e customizado.","a menor possibilidade de venda cruzada."],"correta":3,"explicacao":"Gabarito: <strong>a imagem de serviço personalizado e customizado.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321885,"enunciado":"Neymar Neto considera-se cliente fiel do Banco STU. Consultado sobre as razões de sua fidelidade, afirmou que, sem dúvida, o que o fez escolher esse banco foi a maneira como é atendido. A qualidade do atendimento bancário pode ser uma estratégia para atrair e fidelizar clientes, pois","opcoes":["o varejo bancário tem dificuldades na igualação das tarifas praticadas pelos diferentes bancos.","o serviço pode ser percebido pelo cliente como um diferencial.","a grande diferenciação de produtos, entre bancos de varejo, faz com que o cliente perca referências competitivas.","os clientes não estão aptos a perceber pequenas gradações na qualidade de atendimento.","as estruturas físicas de atendimento dos bancos de varejo apresentam forte customização."],"correta":1,"explicacao":"Gabarito: <strong>o serviço pode ser percebido pelo cliente como um diferencial.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321886,"enunciado":"Para melhor atender e convencer o cliente em uma ação de telemarketing, o atendente não deve interromper a fala do cliente, deve anotar as solicitações e as informações importantes. A comunicação clara e objetiva favorece um bom atendimento. Contribui com essas ações o comportamento","opcoes":["atencioso, solícito e prestativo.","tolerante, impassível e impositivo.","cordial, com clareza e intolerância.","impositivo, com clareza e refutação constante.","persuasivo, com imprestabilidade e clareza."],"correta":0,"explicacao":"Gabarito: <strong>atencioso, solícito e prestativo.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321887,"enunciado":"A utilização de uma voz alegre, clara e calorosa é essencial para gerar empatia e garantir êxito em um contato telefônico profissional. Dentre outras, uma característica da empatia é a capacidade de","opcoes":["agir em benefício próprio.","interromper a fala do cliente no momento exato.","motivar o contato telefônico, por meio de entonação lenta e pausada com refutação contínua.","compreender o sentimento ou reação da outra pessoa, imaginando-se nas mesmas circunstâncias.","ter firmeza no ritmo e tom vocal para persuadir com autoritarismo."],"correta":3,"explicacao":"Gabarito: <strong>compreender o sentimento ou reação da outra pessoa, imaginando-se nas mesmas circunstâncias.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321888,"enunciado":"Segundo a Resolução CMN no3.849/2010, no tocante à instituição do componente organizacional de ouvidoria, o estatuto ou contrato social da Instituição Financeira deve conter, de forma expressa,","opcoes":["o nome do ouvidor, que deverá ser o do ouvidor da associação de classe, bolsa de valores ou bolsa de mercadorias e de futuros, entidade ou empresa que constituir a ouvidoria.","o compromisso expresso da instituição no sentido de criar condições adequadas para o funcionamento da ouvidoria, bem como para que sua atuação seja pautada pela transparência, independência, imparcialidade e isenção.","o relatório semestral, na forma definida pelo Banco Central do Brasil, relativo às atividades da ouvidoria, sempre que identificada ocorrência relevante.","as obrigações da instituição a fim de dificultar o acesso da ouvidoria às informações necessárias para a elaboração de resposta adequada às reclamações recebidas, prescindindo do apoio administrativo.","o relatório quantitativo e qualitativo acerca da atuação da ouvidoria, contendo as proposições quanto às medidas corretivas ou de aprimoramento de procedimentos e rotinas, em decorrência da análise das reclamações recebidas."],"correta":1,"explicacao":"Gabarito: <strong>o compromisso expresso da instituição no sentido de criar condições adequadas para o funcionamento da ouvidoria, bem como para que sua atuação seja pautada pela transparência, independência, imparcialidade e isenção.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321889,"enunciado":"A tabela abaixo apresenta em sua primeira coluna uma relação contendo as três “estratégias genéricas” que um banco pode escolher, a fim de enfrentar a concorrência. A segunda coluna apresenta três ações ligadas a cada uma delas. As estratégias e suas respectivas ações estão correta- mente correlacionadas em:","opcoes":["I-1; II-3; III-2.","I-2; II-1; III-3.","I-1; II-2; III-3.","I-2; II-3; III-1.","I-3; II-1; III-2."],"correta":0,"explicacao":"Gabarito: <strong>I-1; II-3; III-2.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321890,"enunciado":"Considere um setor bancário hipotético com as seguintes características: inexistência de economias de escala; clientes com baixo custo de troca de banco; baixa necessidade de capital para abertura do negócio; ausência de políticas públicas restritivas. Dentre as denominadas cinco forças competitivas de Porter, a mais relevante como ameaça a um banco em funcionamento, diante da estrutura setorial apresentada, é","opcoes":["a ausência de rivalidade entre os concorrentes.","o baixo poder de negociação dos clientes.","a possibilidade de novos entrantes.","o poder de negociação dos fornecedores.","a pressão de produtos e serviços complementares."],"correta":2,"explicacao":"Gabarito: <strong>a possibilidade de novos entrantes.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321891,"enunciado":"O Banco LMN deseja incrementar a fidelização de deter- minado segmento de clientes atuais. Para tanto, elaborou uma estratégia que visa à ampliação do valor entregue aos correntistas, com base na teoria do marketing que define o conceito de proposta de valor. Segundo essa teoria, uma ação que representa a proposta de entrega de alto valor ao cliente é","opcoes":["o aumento dos investimentos em automação bancária","a fusão de agências de uma mesma praça.","o investimento visando a redução do consumo de energia e redução de gastos com material de escritório.","a oferta de solidez institucional, confiabilidade, rapidez e simpatia no atendimento.","o projeto de melhora na distribuição de dividendos aos acionistas."],"correta":3,"explicacao":"Gabarito: <strong>a oferta de solidez institucional, confiabilidade, rapidez e simpatia no atendimento.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321892,"enunciado":"O Banco Lovelock encomendou uma pesquisa tentando identificar fatores associados à fidelização de clientes que, potencialmente, podem fazer sua lucratividade crescer. NÃO representa um fator ligado ao aumento da lucratividade por fidelização do cliente:","opcoes":["o aumento do número de compras.","a redução de custos operacionais.","a indicação a outros clientes.","a disposição para pagar preços mais elevados.","a constituição de barreira à entrada de novos competidores."],"correta":4,"explicacao":"Gabarito: <strong>a constituição de barreira à entrada de novos competidores.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321898,"enunciado":"A Cetip S.A. - Mercados Organizados é uma câmara utilizada pelos participantes do mercado financeiro e de capitais para o registro eletrônico da colocação, o depósito e a liquidação financeira de diversos ativos, dentre os quais estão os","opcoes":["Bônus de Subscrição e as Notas do Tesouro Nacional.","Certificados de Depósito Bancário e as Letras Financeiras do Tesouro.","Certificados de Recebíveis do Agronegócio e as Debêntures.","Commercial Papers e os Brazilian Depositary Receipts.","Títulos da Dívida Agrária e os Contratos a Termo de Ações"],"correta":2,"explicacao":"Gabarito: <strong>Certificados de Recebíveis do Agronegócio e as Debêntures.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321899,"enunciado":"O Comitê de Política Monetária (COPOM), instituído pelo Banco Central do Brasil em 1996 e composto por membros daquela instituição, toma decisões","opcoes":["sobre a Taxa de Juros de Longo Prazo (TJLP).","a respeito dos depósitos compulsórios dos bancos comerciais.","de acordo com a maioria dos participantes nas reuniões periódicas de dois dias.","a serem ratificadas pelo Ministro da Fazenda.","conforme os votos da Diretoria Colegiada."],"correta":4,"explicacao":"Gabarito: <strong>conforme os votos da Diretoria Colegiada.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321900,"enunciado":"Em 2010 ocorreu, simultaneamente, a distribuição pública primária e secundária de ações de emissão do Banco do Brasil, com registros na Comissão de Valores Mobiliários. Neste caso, como em outras operações da mesma natureza e produto no mercado de capitais, a relação entre capital próprio e de terceiros da empresa","opcoes":["passou a ser influenciada pela cotação das ações em bolsa de valores.","não sofreu nenhuma influência.","sofreu alteração em função da venda das ações dos acionistas do grupo controlador.","foi modificada pela captação integral dos recursos obtidos nas ofertas primária e secundária.","foi alterada pela parcela de recursos originada com as novas ações emitidas."],"correta":4,"explicacao":"Gabarito: <strong>foi alterada pela parcela de recursos originada com as novas ações emitidas.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321901,"enunciado":"O COAF - Conselho de Controle de Atividades Financeiras compõe a estrutura legal brasileira para lidar com o problema da lavagem de dinheiro e tem como missão","opcoes":["autorizar, em conjunto com os bancos, o ingresso de recursos internacionais por meio de contratos de câmbio.","julgar se é de origem lícita a incorporação na economia, de modo transitório ou permanente, de recursos, bens e valores.","identificar e apontar para a Secretaria da Receita Federal do Brasil os casos de ilícito fiscal envolvendo lavagem de dinheiro.","prevenir a utilização dos setores econômicos para lavagem de dinheiro e financiamento do terrorismo.","discriminar as atividades principal ou acessória de pessoas físicas e jurídicas sujeitas às obrigações previstas em lei."],"correta":3,"explicacao":"Gabarito: <strong>prevenir a utilização dos setores econômicos para lavagem de dinheiro e financiamento do terrorismo.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321902,"enunciado":"As linhas bancárias de crédito rural possibilitam ao cliente acessar financiamento","opcoes":["para atividades de comercialização da produção.","do custeio das despesas pessoais e familiares.","com liberação de uma só vez, independentemente do cronograma de aquisições e serviços","sem apresentação de garantias ao financiador.","para investimento em bens ou serviços cujo aproveitamento se estenda por um único ciclo produtivo."],"correta":0,"explicacao":"Gabarito: <strong>para atividades de comercialização da produção.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321903,"enunciado":"O penhor mercantil é modalidade de garantia que pode ser exigida por operadores do Sistema Financeiro Nacional na formalização de operações de crédito em que","opcoes":["haja dispensa de fiel depositário.","o valor atualizado do bem não exceda 50% do valor financiado.","esse direito recaia sobre bens móveis.","o devedor possa substituir os bens empenhados sem autorização prévia do credor.","os recursos liberados permaneçam depositados na mesma instituição financeira."],"correta":2,"explicacao":"Gabarito: <strong>esse direito recaia sobre bens móveis.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":321904,"enunciado":"As operações denominadas Crédito Direto ao Consumidor são caracterizadas","opcoes":["pela não incidência de IOF para contratos com pessoa física.","por destinação ao financiamento de bens e serviços para pessoas físicas ou jurídicas.","pela dispensa da informação do Custo Efetivo Total para clientes correntistas dos bancos.","pela impossibilidade de antecipação de pagamento de parcelas.","pela ausência de gravame no caso de financiamento de veículos usados."],"correta":1,"explicacao":"Gabarito: <strong>por destinação ao financiamento de bens e serviços para pessoas físicas ou jurídicas.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":332634,"enunciado":"A SUSEP editou a Circular nº 200, de 9 de setembro de 2002, que dispõe sobre a identificação de clientes e manutenção de registros, a relação de operações e transações que denotem indícios dos crimes previstos na Lei nº 9.613, de 3 de março de 1998, ou que com eles possam relacionar-se, a comunicação das operações financeiras e a responsabilidade administrativa de que trata aquela Lei. NÃO se sujeitam às obrigações previstas na referida Circular","opcoes":["os resseguradores locais.","os corretores de seguros.","as sociedades seguradoras.","as sociedades de capitalização.","as entidades fechadas de previdência complementar."],"correta":4,"explicacao":"Gabarito: <strong>as entidades fechadas de previdência complementar.</strong>.","banca":"CONSULPLAN","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":351556,"enunciado":"Acerca do Sistema Financeiro Nacional e do Sistema de Pagamentos Brasileiro (SPB), julgue os itens subsecutivos.\n\nO Sistema de Transferência de Reservas é um sistema de transferência de fundos híbrido, pois reúne características dos sistemas de liquidação diferida com compensação de obrigações e dos sistemas de liquidação bruta em tempo real.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":354017,"enunciado":"Em um regime com câmbio fixo, a expansão dos gastos do governo leva ao aumento da renda e das exportações líquidas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362018,"enunciado":"O superintendente de vendas do Banco A, submetido a regime de metas, determina a suas equipes que, em todos os contratos de empréstimos, vinculem o fechamento da operação à realização de contrato de seguro. Com tal determinação, as metas impostas são realizadas, com reflexo financeiro positivo na remuneração dos empregados. Nos termos do Código de Defesa e Proteção ao Consumidor, tal operação é:","opcoes":["admitida, por ser inerente às relações de mercado.","permitida, por ser integrante de regime de remuneração por metas.","vedada, por caracterizar prática abusiva.","vedada, por não ser possível a conjugação prática das operações.","permitida, por configurar habitualidade das relações."],"correta":2,"explicacao":"Gabarito: <strong>vedada, por caracterizar prática abusiva.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362019,"enunciado":"O processo de vendas tem-se transformado, ao longo do tempo, em função da crescente competição existente no mercado entre empresas de mesmo setor. Em função disso, o foco da administração de vendas também mudou. Hoje, em função do mercado, o foco dessa área é no(a)","opcoes":["produção, estabelecendo metas de vendas que ultrapassem sua capacidade produtiva.","orçamento, proporcionando a expectativa de ganhos futuros em função das vendas a serem realizadas.","cliente, avaliando suas necessidades e expectativas em relação aos produtos ofertados.","território de vendas, delimitando assim a atuação de cada vendedor, que concentrará seus esforços na área para ele determinada.","vendedor, visando a aumentar os ganhos do profissional, já que seu salário é a comissão sobre as vendas realizadas."],"correta":2,"explicacao":"Gabarito: <strong>cliente, avaliando suas necessidades e expectativas em relação aos produtos ofertados.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362020,"enunciado":"Um funcionário de um banco, preocupado em atingir as metas estabelecidas pela sua gerência, precisava vender alguns produtos bancários em pouco tempo. Tentando atingir a meta estabelecida, ele procurou algumas informações sobre como melhorar seu desempenho no processo de vendas. A informação de como proceder no processo de vendas, que contribuirá positivamente para a melhoria de seu desempenho, é:","opcoes":["minimizar as informações passadas aos clientes sobre os riscos envolvidos em cada um dos produtos oferecidos.","oferecer os produtos aos clientes, independentemente de seus perfis já que, ao categorizar os clientes, estaria discriminando-os.","falar mais do que ouvir, durante a abordagem inicial, exaltando os benefícios de cada um dos produtos.","mostrar conhecimento em relação aos produtos, po- rém não mencionar a política do banco e as formas de cobrança referentes aos produtos, já que esses detalhes tomam o tempo do cliente.","buscar informações essenciais sobre os clientes com perspectiva de negócios, antes e durante a interação no processo de compra e venda."],"correta":4,"explicacao":"Gabarito: <strong>buscar informações essenciais sobre os clientes com perspectiva de negócios, antes e durante a interação no processo de compra e venda.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362021,"enunciado":"O setor bancário, de maneira geral, tem investido na criação de novos produtos para atender a um mercado emergente nos últimos anos, em função do aumento da renda per capita no país – as camadas mais populares da população brasileira. Com base nesse pressuposto, os bancos, para avaliar se valeria a pena ou não investir na criação desses novos produtos, em seu planejamento de vendas, iniciaram seu processo de planejamento de vendas, analisando o(a).","opcoes":["potencial de mercado, que é um processo em que é estimada a capacidade do mercado brasileiro no ramo da atuação da empresa – estimativa que vai refletir a situação econômica do momento.","potencial de vendas, que é um processo em que é calculado, a partir da análise da empresa e de seu ambiente, da concorrência e de outros fatores pertinentes ao processo, o mercado existente.","mix de marketing, que pode ser utilizado pela empresa para influenciar a resposta dos consumidores.","campanha de marketing, procurando entender o comportamento do consumidor visando a estabelecer os objetivos e as metas de cada produto para que a campanha atinja o público-alvo.","previsão de vendas, que é um processo em que a capacidade de vendas da empresa e do mercado parte da análise da demanda total do mercado para definir o público-alvo em que vai atuar"],"correta":0,"explicacao":"Gabarito: <strong>potencial de mercado, que é um processo em que é estimada a capacidade do mercado brasileiro no ramo da atuação da empresa – estimativa que vai refletir a situação econômica do momento.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362022,"enunciado":"A carteira de clientes é o principal ativo de uma agência bancária. Portanto, na relação com os clientes, é essencial nortear-se pelo seguinte princípio:","opcoes":["A responsabilidade pelo bom atendimento bancário é unicamente da área comercial da agência bancária.","Os clientes que necessitam de crédito bancário devem ter um atendimento bancário inferior aos clientes que têm investimentos nas agências bancárias.","Todos os clientes devem ter o mesmo tipo de atendimento bancário, mesmo possuindo diferentes solicitações de serviços bancários","Qualquer tipo de agência bancária deve dar mais importância ao atendimento aos clientes pessoas físicas do que aos clientes pessoas jurídicas.","O bom relacionamento com todos os clientes deve ser feito independentemente do retorno financeiro que esses clientes proporcionam à agência bancária."],"correta":4,"explicacao":"Gabarito: <strong>O bom relacionamento com todos os clientes deve ser feito independentemente do retorno financeiro que esses clientes proporcionam à agência bancária.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362023,"enunciado":"As empresas, diante da concorrência existente no mercado, procuram medir a satisfação de seus clientes, buscando identificar possibilidades para sua fidelização. A satisfação do cliente em relação ao produto adquirido é representada pelo(a).","opcoes":["diminuição dos custos de produção.","proximidade entre as suas expectativas e o desempenho percebido do produto.","atendimento da empresa ao Código de Defesa do Consumidor.","turnover dos empregados da empresa que atuam no processo produtivo.","volume de estoque de produtos acabados da empresa, para atender ao cliente"],"correta":1,"explicacao":"Gabarito: <strong>proximidade entre as suas expectativas e o desempenho percebido do produto.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362024,"enunciado":"O relacionamento que os bancos mantêm com seus clientes é um fator que contribui para sua captação e sua fidelização. Pensando nisso, os bancos têm utilizado diferentes ferramentas e estratégias no desenvolvimento de sua liderança no mercado. De maneira geral, o marketing de relacionamento é conceituado como o processo pelo qual uma empresa constrói alianças com clientes atuais e potenciais de tal forma que ambos, vendedor e comprador, trabalhem em busca de um conjunto específico de objetivos comuns. Os objetivos do marketing de relacionamento são atingidos quando.","opcoes":["é estabelecida uma relação distante, formal e profissional com o cliente.","é estabelecido o relacionamento unilateral e satisfatório de curto prazo com o cliente.","é assegurado que a empresa busque relacionar-se com os clientes a cada ocasião de compra.","é assegurado que os funcionários satisfaçam às necessidades dos clientes.","é estabelecido um relacionamento satisfatório entre a empresa e o cliente, não havendo necessidade de compatibilidade entre a empresa e outras partes."],"correta":3,"explicacao":"Gabarito: <strong>é assegurado que os funcionários satisfaçam às necessidades dos clientes.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362025,"enunciado":"O grau de percepção de valor, pelo cliente, em relação ao produto ou serviço, é dinâmico, podendo variar de acordo com o momento – antes da aquisição, imediatamente após a aquisição, após longo tempo de aquisição e utilização, entre outras circunstâncias. Essa mudança na percepção de valor ocorre porque:","opcoes":["um gap é instaurado entre o que a empresa oferece ao mercado e o que o cliente adquire, aumentando assim a percepção de valor.","um cliente, ao adquirir um produto ou serviço, percebe que a sua expectativa de valor, em relação ao que está adquirindo, excede a sua expectativa de valor de qualquer outro produto ou serviço da concorrência.","o grau de importância dos atributos de valor muda, à medida que a relação do cliente com o produto aumenta, podendo aumentar ou diminuir o valor percebido.","o vendedor, ao adquirir um produto ou serviço, aumenta os benefícios do cliente e isso viabiliza a redução dos custos de aquisição, o que contribui para a diminuição da percepção de valor.","as empresas focam o que os clientes desejam, generalizando e padronizando as suas necessidades, resultando no aumento da percepção de valor, porque os clientes são tratados de maneira uniforme"],"correta":2,"explicacao":"Gabarito: <strong>o grau de importância dos atributos de valor muda, à medida que a relação do cliente com o produto aumenta, podendo aumentar ou diminuir o valor percebido.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362026,"enunciado":"Os produtos bancários têm certas características que os diferenciam dos demais produtos comercializados no mercado. Uma de suas características é determinada pela ausência de clareza ou precisão quando de sua oferta, que repercute na falta de compreensão e na dificuldade de o cliente elaborar mentalmente aquele produto que está sendo a ele ofertado. Essa característica está relacionada à(ao) sua(seu).","opcoes":["risco percebido","imaterialidade","tangibilidade","automação","invariabilidade"],"correta":1,"explicacao":"Gabarito: <strong>imaterialidade</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362027,"enunciado":"A motivação da força de vendas é um fator fundamental para o sucesso na área comercial, sendo então necessário respeitar a seguinte premissa:","opcoes":["A motivação financeira sempre será o aspecto motivacional mais importante em um time comercial.","Uma equipe motivada sempre conseguirá alcançar e superar as metas da área comercial.","O gasto financeiro da empresa em motivação é um fator essencial para manter a equipe de vendas constantemente motivada.","A motivação está diretamente ligada à valorização do funcionário.","A questão motivacional não tem relação com um ambiente propício ao desenvolvimento pessoal e profis- sional de seu colaborador"],"correta":3,"explicacao":"Gabarito: <strong>A motivação está diretamente ligada à valorização do funcionário.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362028,"enunciado":"No momento da venda, ao apresentar um serviço bancário, o funcionário deve levar em conta o conceito de custo total para o cliente. Esse conceito envolve, além das condições financeiras do serviço que se pretende adquirir, outros fatores, tais como:","opcoes":["tempo e energia física e psicológica","prazo e condições de pagamento","vantagens esperadas","necessidades e desejos","imagem funcional e psicológica"],"correta":0,"explicacao":"Gabarito: <strong>tempo e energia física e psicológica</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362029,"enunciado":"Campanhas de propaganda são instrumentos eficientes para aumentar o share of mind de uma marca, aumentando a confiança dos consumidores nos serviços bancários contratados. Por intermédio de pesquisa, um banco pode medir o nível de share of mind de sua marca, solicitando aos clientes que:","opcoes":["respondam a questões relacionadas aos fatores psicográficos","marquem o índice de satisfação com os serviços e benefícios recebidos","citem a primeira marca que lhes vêm à cabeça nesse segmento","demonstrem as percepções mentais relacionadas com a marca.","indiquem o grau de concordância com afirmações a respeito dos serviços."],"correta":2,"explicacao":"Gabarito: <strong>citem a primeira marca que lhes vêm à cabeça nesse segmento</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362030,"enunciado":"A gestão de marketing de um banco tem de lidar com variáveis incontroláveis, compreendidas como fatores que interferem na condução dos negócios e que não são determinados pela administração. Um exemplo de uma variável incontrolável é(são):","opcoes":["as campanhas institucionais","a página da empresa na internet","o composto de marketing","a localização das agências","a situação econômica do país"],"correta":4,"explicacao":"Gabarito: <strong>a situação econômica do país</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362031,"enunciado":"Um banco possui dentre os seus clientes pessoas jurídicas classificadas como microempresas pela legislação própria. Nesse caso, nos termos da Resolução CMN no 3.849/2010, é necessário instituir Ouvidoria que, dentre outras atribuições, deverá realizar, quanto a eventuais conflitos, a atividade de:","opcoes":["julgamento","acordo","arbitragem","juizado","mediação"],"correta":4,"explicacao":"Gabarito: <strong>mediação</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362032,"enunciado":"O gerente da Ouvidoria de uma instituição financeira deve ser rigoroso no cumprimento dos prazos para responder aos reclamos dos clientes. Nos termos da Resolução CMN no 3.849/2010, o prazo máximo, em dias, para resposta final aos reclamos será de.","opcoes":["trinta","vinte","cinco","dez","quinze"],"correta":4,"explicacao":"Gabarito: <strong>quinze</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362043,"enunciado":"No Brasil, a condução e a operação diárias da política monetária, com o objetivo de estabilizar a economia, atingindo a meta de inflação e mantendo o sistema financeiro funcionando adequadamente, são uma responsabilidade do(a).","opcoes":["Caixa Econômica Federal","Comissão de Valores Mobiliários","Banco do Brasil","Banco Central do Brasil","Banco Nacional de Desenvolvimento Econômico e Social"],"correta":3,"explicacao":"Gabarito: <strong>Banco Central do Brasil</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362044,"enunciado":"O Conselho Monetário Nacional (CMN) é a entidade máxima do sistema financeiro brasileiro, ao qual cabe.","opcoes":["intervir diretamente nas instituições financeiras ilíquidas","apurar e anunciar mensalmente a taxa de inflação oficial.","autorizar a emissão de papel-moeda.","fixar periodicamente a taxa de juros interbancária.","aprovar o orçamento do setor público federal."],"correta":2,"explicacao":"Gabarito: <strong>autorizar a emissão de papel-moeda.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362046,"enunciado":"Nos termos da circular no 3.542/2012, NÃO está inserida nas hipóteses de controle de situações relacionadas com atividades internacionais a:","opcoes":["existência de recursos pertencentes ou controlados, direta ou indiretamente, por pessoas que reconhecidamente tenham cometido atos terroristas.","realização de transferências unilaterais que, pela habitualidade, valor ou forma, não se justifiquem ou apresentem atipicidade.","utilização de operações complexas e com custos mais elevados que visem a dificultar o rastreamento dos recursos ou a identificação da natureza da operação.","realização de pagamentos de importação e recebimentos de exportação, antecipados ou não, por empresa sem tradição ou cuja avaliação econômico-financeira seja incompatível com o montante negociado.","realização de pagamentos a terceiros não relacionados a operações de importação ou de exportação"],"correta":0,"explicacao":"Gabarito: <strong>existência de recursos pertencentes ou controlados, direta ou indiretamente, por pessoas que reconhecidamente tenham cometido atos terroristas.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362047,"enunciado":"Um gerente participa de processo de treinamento sobre títulos de créditos e garantias do Sistema Financeiro Nacional. Durante a avaliação dos itens abordados no treinamento, o gerente, que se dedicou com afinco aos estudos, responde, apropriadamente, que o aval, nos termos do Código Civil,","opcoes":["gera direito de regresso contra o avalizado em caso de pagamento pelo avalista.","é garantia típica dos contratos bancários.","pode ser parcial quando firmado em título de crédito.","pode ser considerado até declaração judicial quando cancelado.","deve ser subscrito exclusivamente no anverso do título."],"correta":0,"explicacao":"Gabarito: <strong>gera direito de regresso contra o avalizado em caso de pagamento pelo avalista.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362048,"enunciado":"Um bancário, almejando promoção na carreira, realiza diversos cursos propostos pelo seu empregador. Ao final de um desses cursos, foi apresentada uma questão exigindo do aluno o conhecimento de que a hipoteca.","opcoes":["é inaplicável sobre as acessões do imóvel hipotecado","é relacionada aos títulos de crédito documentados","acarreta a proibição de alienação do imóvel hipotecado.","pode incidir sobre navios e aeronaves.","pode ser realizada por pessoa absolutamente incapaz."],"correta":3,"explicacao":"Gabarito: <strong>pode incidir sobre navios e aeronaves.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362049,"enunciado":"Os planos de previdência PGBL (Plano Gerador de Benefício Livre) e VGBL (Vida Gerador de Benefício Livre) são produtos de Previdência Complementar que visam à acumulação de recursos e à transformação de tais recursos em uma renda futura. Na modalidade PGBL, o imposto de renda incide sobre o.","opcoes":["ganho das aplicações financeiras","valor futuro calculado para a data do resgate","total resgatado ou recebido como renda","total de rendimentos bruto na data da aplicação","valor da aplicação inicial"],"correta":2,"explicacao":"Gabarito: <strong>total resgatado ou recebido como renda</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362050,"enunciado":"Atualmente, as instituições financeiras oferecem aos seus clientes diversos tipos de investimentos, dentre os quais está o investimento em ações de companhias abertas que podem ser negociadas na Bolsa de Valores. A característica mais atrativa do investimento em ações é a.","opcoes":["possibilidade de ganhos superiores aos oferecidos em fundos de investimento.","isenção de imposto sobre operações financeiras no ato de negociação das ações.","baixa probabilidade de perdas financeiras.","alta probabilidade de perdas financeiras.","isenção de imposto de renda"],"correta":0,"explicacao":"Gabarito: <strong>possibilidade de ganhos superiores aos oferecidos em fundos de investimento.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362051,"enunciado":"Os títulos de capitalização são emitidos pelas sociedades de capitalização e têm por objeto o depósito periódico de prestações pecuniárias pelo contratante, o qual terá, depois de cumprido o prazo contratado, os direitos de concorrer a sorteio de prêmios em dinheiro e o de.","opcoes":["resgatar o valor do título mediante lance em leilões periódicos","resgatar parte dos valores depositados corrigidos por uma taxa de juros.","aplicar parte dos recursos em ações das bolsas de valores","concorrer a imóveis nos feirões da casa própria","concorrer a prêmios em barras de ouro"],"correta":1,"explicacao":"Gabarito: <strong>resgatar parte dos valores depositados corrigidos por uma taxa de juros.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362052,"enunciado":"O mercado de seguros é cada vez mais crescente no Brasil. As seguradoras oferecem uma gama diferenciada de produtos e subprodutos para atender a essa grande demanda. O seguro de acidentes pessoais, por exemplo, garante o pagamento de indenização em caso de:","opcoes":["colisão do automóvel do segurado com veículos de terceiros, desde que esteja estipulado na apólice.","perda total do veículo sem danos ao segurado, desde que especificado na apólice.","paralisação das atividades laborais do segurado durante o período de uma eventual internação hospitalar causada por doença crônica.","invalidez permanente, total ou parcial, por acidente, ou indenização ao beneficiário em caso de falecimento do segurado.","incêndio, enchente ou qualquer outro tipo de fenômeno climático que danifique a residência do segurado."],"correta":3,"explicacao":"Gabarito: <strong>invalidez permanente, total ou parcial, por acidente, ou indenização ao beneficiário em caso de falecimento do segurado.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362053,"enunciado":"O Banco do Brasil é considerado um agente financeiro especial do Governo Federal, devido a algumas atividades que desempenha, como a(o).","opcoes":["seguro de bens imóveis","fiança bancária para investidores em bolsa","execução da política de preços mínimos de produtos agropecuários","extensão de crédito direto ao consumidor","concessão de cartões de crédito ao público"],"correta":2,"explicacao":"Gabarito: <strong>execução da política de preços mínimos de produtos agropecuários</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362054,"enunciado":"O Comitê de Política Monetária (Copom) do Banco Central do Brasil estabelece as ações que definem a política monetária do governo. O Copom","opcoes":["administra as reservas em divisas internacionais do Brasil.","determina periodicamente a taxa de juros interbancários de referência, a taxa Selic.","é presidido pelo Ministro da Fazenda.","impõe limites mínimos de capitalização aos bancos comerciais.","impede a entrada de capitais financeiros especulativos no país."],"correta":1,"explicacao":"Gabarito: <strong>determina periodicamente a taxa de juros interbancários de referência, a taxa Selic.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362055,"enunciado":"O poder regulatório e fiscalizador da Comissão de Valores Mobiliários (CVM) se estende a várias entidades e atividades. NÃO constituem uma dessas entidades ou atividades.","opcoes":["os Sistemas de Compensação de Títulos Públicos Federais – Selic.","os Mercados de Balcão Organizados de Valores Mobiliários","as Bolsas de Mercadorias e Futuros","as Auditorias de Companhias Abertas","as Entidades de Compensação e Liquidação de Valores Mobiliários"],"correta":0,"explicacao":"Gabarito: <strong>os Sistemas de Compensação de Títulos Públicos Federais – Selic.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362056,"enunciado":"Nos termos da Lei de regência, cabe ao Conselho Monetário Nacional determinar recolhimento de determinado percentual do total dos depósitos e/ou outros títulos contábeis das instituições financeiras, seja na forma de subscrição de letras ou obrigações do Tesouro Nacional, seja na compra de títulos da Dívida Pública Federal, ou ainda, através de recolhimento em espécie. Esse percentual corresponderá a até.","opcoes":["60%","50%","20%","30%","40%"],"correta":0,"explicacao":"Gabarito: <strong>60%</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":362057,"enunciado":"O Fundo Garantidor de Crédito foi criado para, dentre outras finalidades, proteger depositantes e investidores no âmbito do sistema financeiro, até os limites estabelecidos pela regulamentação. Tal fundo é pessoa jurídica caracterizada como","opcoes":["sociedade por ações","sociedade de economia mista","autarquia especial","associação civil","empresa financeira"],"correta":3,"explicacao":"Gabarito: <strong>associação civil</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367725,"enunciado":"Dentre as instituições que compõem o Sistema Financeiro Nacional, o Conselho Monetário Nacional tem como finalidade formular a política da moeda e do crédito, visando ao progresso econômico e social do País. Desta forma, a política do Conselho Monetário Nacional tem como objetivo:","opcoes":["propiciar o aperfeiçoamento das instituições e dos instrumentos financeiros, com vistas à maior eficiência do sistema de pagamentos e de mobilização de recursos e zelar pela liquidez e solvência das instituições financeiras.","receber recolhimentos compulsórios dos depósitos à vista das instituições financeiras públicas, para transformar em linhas de redescontos e empréstimos às instituições financeiras privadas.","praticar operações de câmbio, crédito e venda habitual de títulos da dívida pública federal, estadual ou municipal, ações, debêntures, letras hipotecárias e outros títulos de crédito ou mobiliários.","atuar no sentido de garantir o funcionamento regular do mercado cambial, a estabilidade relativa das taxas de câmbio e o equilíbrio no balanço de pagamentos, podendo, para esse fim, comprar e vender ouro e moeda estrangeira, bem como realizar operações de crédito no exterior.","emitir títulos de responsabilidade própria, de acordo com as condições estabelecidas pelo Congresso Nacional, para financiar a dívida pública do governo."],"correta":0,"explicacao":"Gabarito: <strong>propiciar o aperfeiçoamento das instituições e dos instrumentos financeiros, com vistas à maior eficiência do sistema de pagamentos e de mobilização de recursos e zelar pela liquidez e solvência das instituições financeiras.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367727,"enunciado":"Os bancos múltiplos são instituições financeiras privadas ou públicas que realizam as operações ativas, passivas e acessórias das diversas instituições financeiras, por intermédio das seguintes carteiras: comercial, de investimento e/ou de desenvolvimento, de crédito imobiliário, de arrendamento mercantil e de crédito, financiamento e investimento. Sobre essas instituições, assinale a alternativa CORRETA.","opcoes":["Os bancos múltiplos podem conceder crédito, somente a associados, por meio de desconto de títulos, empréstimos e financiamentos.","Os bancos múltiplos podem ser constituídos com, no mínimo, duas carteiras, sendo uma delas, obrigatoriamente, comercial ou de investimento","A legislação brasileira sobre bancos só permite a constituição dessa categoria de instituição financeira para atuar diretamente como cooperativa","Os bancos múltiplos oficiais atuam exclusivamente no financiamento aos governos, sendo vedadas as operações com pessoas físicas","A constituição de um banco múltiplo deve ser autorizada pelo Conselho Monetário e pelo Congresso Nacional."],"correta":1,"explicacao":"Gabarito: <strong>Os bancos múltiplos podem ser constituídos com, no mínimo, duas carteiras, sendo uma delas, obrigatoriamente, comercial ou de investimento</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367728,"enunciado":"Para a abertura de conta de depósito, é necessário preencher a ficha-proposta de abertura de conta, que é o contrato firmado entre banco e cliente; dispor de quantia mínima, caso exigida pelo banco; e apresentar os originais dos seguintes documentos, que deverão ser mantidos atualizados pela instituição financeira:","opcoes":["se pessoa física: comprovante de inscrição no Cadastro de Pessoa Física (CPF), documento de identificação (identidade ou equivalente) e comprovante de residência.","se pessoa física: comprovante de inscrição no Cadastro de Pessoa Física (CPF), documento de identificação (identidade ou equivalente) e título de eleitor comprovando ter votado nas últimas eleições.","se pessoa jurídica: comprovante de inscrição no Cadastro de Pessoa Física (CPF) do proprietário e título de eleitor dos sócios, comprovando ter votado nas últimas eleições","se pessoa jurídica: comprovante de inscrição no Cadastro Nacional de Pessoa Jurídica (CNPJ) e comprovante de depósito equivalente ao capital da empresa.","se pessoa jurídica: comprovante de inscrição no Cadastro de Pessoa Física (CPF) e documento de identificação (identidade ou equivalente) de todos os sócios."],"correta":0,"explicacao":"Gabarito: <strong>se pessoa física: comprovante de inscrição no Cadastro de Pessoa Física (CPF), documento de identificação (identidade ou equivalente) e comprovante de residência.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367729,"enunciado":"Dentre os serviços bancários oferecidos pelas instituições financeiras aos clientes, alguns se referem a diversos tipos de aplicações financeiras com características que atendam aos interesses destes, tais como prazo, risco e rendimento. Assinale a alternativa que caracteriza as aplicações descritas.","opcoes":["Os depósitos à vista são remunerados se o cliente deixar o dinheiro na conta corrente por mais de 90 dias.","O rendimento da caderneta de poupança é definido individualmente pelos bancos, sendo importante que o cliente pesquise aquele que oferece o melhor rendimento.","Os Certificados de Depósito Bancário (CDB) e os Recibos de Depósitos Bancários (RDB) são aplicações financeiras de longo prazo que sempre apresentam os maiores rendimentos dentre todas as modalidades financeiras.","Os títulos de capitalização são aplicações financeiras sem risco, por serem garantidos pelo Banco Central do Brasil.","Os valores depositados na caderneta de poupança são remunerados com base na Taxa Referencial (TR), acrescida de juros de 0,5% ao mês"],"correta":4,"explicacao":"Gabarito: <strong>Os valores depositados na caderneta de poupança são remunerados com base na Taxa Referencial (TR), acrescida de juros de 0,5% ao mês</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367730,"enunciado":"Com o intuito de promover a inclusão bancária e para estimular o microcrédito, foram criadas contas especiais de depósito à vista e de poupança, com características específicas, em bancos múltiplos com carteira comercial, em bancos comerciais e na Caixa Econômica Federal. Sobre o assunto, assinale a alternativa CORRETA.","opcoes":["Somente podem ser abertas por pessoa física e mantidas na forma de conta individual, sendo vetado o fornecimento de talonário de cheques.","Mesmo sendo uma conta simples, é permitido o fornecimento de talonário de cheques","Por ser uma conta simples, não há necessidade de preenchimento de contrato nem de apresentação de documentos de identificação","O cliente pode abrir mais de uma conta especial na mesma instituição financeira, mesmo se já tiver conta de depósito à vista.","Por serem contas destinadas à população de baixa renda, não podem ser beneficiadas com operações de crédito."],"correta":0,"explicacao":"Gabarito: <strong>Somente podem ser abertas por pessoa física e mantidas na forma de conta individual, sendo vetado o fornecimento de talonário de cheques.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367731,"enunciado":"0 cheque é uma ordem de pagamento à vista, devendo ser pago no momento de sua apresentação ao banco sacado. Com relação ao cheque, assinale a alternativa CORRETA.","opcoes":["O cheque não pode ser considerado um título de crédito, por não poder ser protestado ou executado em juízo","Por ser protegido por Lei, o recebimento de cheques é obrigatório pelas pessoas, lojas e empresas","A emissão de cheque sem fundo só acarretará a inclusão do nome do emitente no Cadastro de Emitentes de Cheques sem Fundos (CCF), a partir do terceiro cheque devolvido por insuficiência de fundos.","O emitente do cheque pagável no Brasil pode revogá-lo, mercê de contra-ordem dada por aviso epistolar, ou por via judicial ou extrajudicial, com as razões motivadoras do ato","Cheque no valor de até R$1.000,00 pode ser emitido ao portador, ou seja, não há necessidade de identificação do beneficiário."],"correta":3,"explicacao":"Gabarito: <strong>O emitente do cheque pagável no Brasil pode revogá-lo, mercê de contra-ordem dada por aviso epistolar, ou por via judicial ou extrajudicial, com as razões motivadoras do ato</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367732,"enunciado":"A regulamentação do sistema financeiro permite a abertura de diversos tipos de contas bancárias, que têm características e finalidades diversas. Sobre o assunto, assinale a alternativa CORRETA","opcoes":["A conta de poupança tem a finalidade única de movimentar recursos para o pagamento de planos de aposentadoria","Na conta de depósito à vista, o dinheiro do depositante fica à disposição para ser sacado a qualquer momento","A “Conta Salário” é destinada a receber salários, proventos, soidos, vencimentos, aposentadorias, pensões e similares, permitindo-se a livre movimentação de outros tipos de depósitos e por meio de cheques.","A “Conta Salário” é aberta por iniciativa do empregado, tendo como vantagem a não cobrança de tarifas em nenhuma transação","A conta de Poupança permite a livre movimentação sem perda de rendimentos, para saques anteriores a um mês do depósito"],"correta":1,"explicacao":"Gabarito: <strong>Na conta de depósito à vista, o dinheiro do depositante fica à disposição para ser sacado a qualquer momento</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367733,"enunciado":"A função clássica das instituições financeiras é a de fazer repasses dos recursos captados dos agentes econômicos superavitários aos agentes econômicos deficitários, por meio de operações de crédito. Com relação aos fundamentos do crédito, assinale a alternativa CORRETA.","opcoes":["O volume de crédito oferecido pelas instituições financeiras não é regulamentado pelo Banco Central.","A formação da taxa de juros cobrada nas operações de crédito é fixada pelo Banco Central para todas as modalidades operacionais.","Normalmente, os bancos cobram taxas de juros levando em conta a taxa de captação e o spread desejado, tendo em vista os custos e a margem de ganho desejada.","As operações de crédito oferecidas pelos bancos são garantidas pelo Banco Central, caso o cliente não honre seu compromisso.","O volume de crédito oferecido pelas instituições financeiras independe do seu patrimônio líquido."],"correta":2,"explicacao":"Gabarito: <strong>Normalmente, os bancos cobram taxas de juros levando em conta a taxa de captação e o spread desejado, tendo em vista os custos e a margem de ganho desejada.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367734,"enunciado":"Em relação às modalidades das operações de linhas de crédito no mercado financeiro brasileiro, assinale a alternativa CORRETA","opcoes":["O HotMoney, amplamente empregado por bancos comerciais, aplica-se a empréstimos de longo prazo, com a finalidade de financiar o capital fixo das empresas","A “Conta Garantida” é oferecida aos maiores clientes não possuindo limites para sua utilização pelos cheques emitidos","O empréstimo para capital de giro é uma linha de crédito vinculada ao processo de imobilização das empresas","O Desconto de Duplicatas é uma operação de crédito, realizada apenas pelos bancos públicos, tendo em vista os requisitos exigidos pelo Banco Central","O financiamento é um contrato de crédito entre o cliente e a instituição financeira, mas com destinação específica"],"correta":4,"explicacao":"Gabarito: <strong>O financiamento é um contrato de crédito entre o cliente e a instituição financeira, mas com destinação específica</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367735,"enunciado":"Tendo em vista a necessidade de manter o sistema bancário brasileiro sólido e eficiente, o Banco Central do Brasil tem ajustado as normas do mercado financeiro nacional às normas internacionais, com o objetivo de evitar riscos que comprometam essa solidez. Com relação a esse assunto, assinale a alternativa CORRETA","opcoes":["Considera-se risco de crédito a possibilidade de ocorrência de perdas associadas ao não cumprimento, pelo tomador ou contraparte, de suas respectivas obrigações financeiras nos termos pactuados.","Define-se como risco operacional a possibilidade de ocorrência de perdas resultantes de falha, deficiência ou inadequação de processos internos, pessoas e sistemas, ou de eventos externos, não incluindo o risco de fraudes internas e externas nem demandas trabalhistas.","Define-se como risco de mercado a possibilidade de ocorrência de perdas resultantes da flutuação nos valores de mercado de posições detidas por uma instituição financeira, não incluindo as operações sujeitas à variação cambial, de juros e de preços de ações.","Não é considerado risco de liquidez a ocorrência de desequilíbrios entre ativos negociáveis e passivos exigíveis - “descasamentos” entre pagamentos e recebimentos","O risco sistêmico está associado ao risco de operacionalização das transações bancárias que afete apenas os bancos comerciais e múltiplos."],"correta":0,"explicacao":"Gabarito: <strong>Considera-se risco de crédito a possibilidade de ocorrência de perdas associadas ao não cumprimento, pelo tomador ou contraparte, de suas respectivas obrigações financeiras nos termos pactuados.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367736,"enunciado":"As principais variáveis relacionadas ao risco de crédito estão associadas ao conhecimento e ao acompanhamento da capacidade de pagamento dos clientes, assim como das próprias operações de crédito autorizadas. Sobre risco de crédito, assinale a alternativa CORRETA.","opcoes":["A classificação das operações de crédito, de titularidade de pessoas físicas, deve levar em conta apenas a situação da renda e do patrimônio do devedor.","As instituições financeiras devem implementar estruturas de gerenciamento do risco de crédito, compatíveis com a natureza e a complexidade de suas operações de crédito.","O risco de crédito está associado ao cumprimento das obrigações contratuais das pessoas físicas, uma vez que não há regras para o controle de créditos para pessoa jurídica.","A existência de avais ou fianças elimina, totalmente, o risco de crédito existente nas operações de empréstimos das instituições financeiras.","Por não envolver risco de crédito, não há necessidade, por parte dos bancos, de estabelecer limites para a realização de operações de empréstimos, tanto individualmente, como para grupos econômicos."],"correta":1,"explicacao":"Gabarito: <strong>As instituições financeiras devem implementar estruturas de gerenciamento do risco de crédito, compatíveis com a natureza e a complexidade de suas operações de crédito.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367737,"enunciado":"Considera-se Crédito Rural o suprimento de recursos financeiros, por instituições do Sistema Nacional de Crédito Rural (SNCR), para aplicação exclusiva nas finalidades e condições estabelecidas nas normas do Banco Central do Brasil. Com relação ao crédito rural, assinale a alternativa CORRETA","opcoes":["O Crédito Rural tem a finalidade de financiar apenas o custeio e o investimento","O crédito de comercialização, por destinar-se a cobrir despesas próprias da fase posterior à coleta da produção, não é amparado pelo Crédito Rural.","Constitui função do Crédito Rural o financiamento de atividades sem caráter produtivo ou destinado a favorecer a retenção especulativa de bens.","São considerados beneficiários do Crédito Rural o produtor rural (pessoa física e jurídica) e as cooperativas de produtores rurais","São considerados beneficiários do Crédito Rural todos os produtores rurais, mesmo que estrangeiros residentes no exterior."],"correta":3,"explicacao":"Gabarito: <strong>São considerados beneficiários do Crédito Rural o produtor rural (pessoa física e jurídica) e as cooperativas de produtores rurais</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367738,"enunciado":"As microfinanças têm permitido maior acesso da população de baixa renda ao mercado financeiro, por intermédio da oferta de serviços e produtos bancários. Em relação à inserção dessa população no mercado bancário, assinale a alternativa CORRETA","opcoes":["Apenas os bancos oficiais estão autorizados a realziar operações de microcrédito destinadas à população de baixa renda e a microempreendedores","Consideram-se operações de microcrédito aquelas realizadas com pessoas jurídicas até o valor de até R$ 20.000,00 e de pessoas físicas até R$ 10.000,00","O Programa de Microcrédito Produtivo Orientado do Banco do Nordeste do Brasil S.A. (Crediamigo) facilita o acesso ao crédito a milhares de empreendedores que desenvolvem atividades relacionadas à produção, à comercialização de bens e à prestação de serviços.","Não se incluem no âmbito do Programa Nacional de Microcrédito Produtivo Orientado, instituído pela Lei Federal n°. 11.110, de 25 de abril de 2005, as operações de microcrédito concedidas por cooperativas singulares de crédito.","Nas operações de microcrédito, dentre as garantias exigidas, não é permitido o aval solidário em grupo"],"correta":2,"explicacao":"Gabarito: <strong>O Programa de Microcrédito Produtivo Orientado do Banco do Nordeste do Brasil S.A. (Crediamigo) facilita o acesso ao crédito a milhares de empreendedores que desenvolvem atividades relacionadas à produção, à comercialização de bens e à prestação de serviços.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367739,"enunciado":"Dentre as diversas modalidades de operações de crédito, os bancos direcionam linhas para a indústria, agroindústria, comércio e para a prestação de serviços, entre seus produtos bancários. Assinale a alternativa que caracteriza uma dessas operações.","opcoes":["As operações de leasing ou “arrendamento mercantil” são operações de financiamento destinadas ao comércio.","As operações de financiamento podem ser realizadas por bancos públicos e privados, respeitadas as normas do Banco Central.","As operações de financiamentos destinadas à agroindústria são exclusivas dos bancos múltiplos privados.","É proibido aos bancos financiar as empresas produtivas, na forma de adiantamento para pagamentos de tributos a serem recolhidos.","Os financiamentos à indústria têm finalidade exclusiva de destinar recursos para investimento em ativo fixo das empresas"],"correta":1,"explicacao":"Gabarito: <strong>As operações de financiamento podem ser realizadas por bancos públicos e privados, respeitadas as normas do Banco Central.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367740,"enunciado":"As principais operações de crédito geral, destinadas a pessoas físicas e jurídicas, apresentam características que dependem da destinação. Com relação a essas características, assinale a alternativa CORRETA.","opcoes":["O Crédito Consignado é uma modalidade de empréstimo em que o desconto da prestação é feito diretamente na folha de pagamento ou benefício previdenciário do contratante.","O Crédito Direto ao Consumidor é concedido para o financiamento de aquisição de imóveis pelos consumidores.","O Desconto de Duplicata é um empréstimo realizado pelos bancos a empresas, com garantia total de recebimento pelo banco, em caso de inadimplência do cliente","A linha de crédito oferecida sob a denominação de “Cheque Especial” não tem limite de utilização, porque sempre é garantida pelos bancos.","O Empréstimo para Capital de Giro é uma operação de crédito vinculada às necessidades de capital fixo das empresas."],"correta":0,"explicacao":"Gabarito: <strong>O Crédito Consignado é uma modalidade de empréstimo em que o desconto da prestação é feito diretamente na folha de pagamento ou benefício previdenciário do contratante.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367741,"enunciado":"As linhas de créditos do Programa Nacional de Fortalecimento da Agricultura Familiar (Pronaf) podem destinar-se a custeio, investimento ou integralização de cotas-parte de agricultores familiares em cooperativas de produção. Sobre o assunto, assinale a alternativa CORRETA.","opcoes":["Os créditos de custeio são destinados, exclusivamente, aos agricultores familiares enquadrados no Pronaf, não se sujeitando a limites de concessão de recursos por operação, podendo o mutuário contratar tantas operações de custeio quanto necessárias.","A linha de crédito para investimento em energia renovável e sustentabilidade ambiental pode ser concedida sem nenhuma exigência específica, tendo em vista a importância da preservação do meio ambiente.","Os créditos de investimento se destinam ao financiamento da implantação, ampliação ou modernização da infraestrutura de produção e serviços, agropecuários ou não-agropecuários, no estabelecimento rural ou em áreas comunitárias rurais próximas, de acordo com projetos específicos.","Os créditos ao amparo da Linha de Crédito de Custeio do Beneficiamento, Industrialização de Agroindústrias Familiares e de Comercialização da Agricultura Familiar (Pronaf Custeio e Comercialização de Agroindústrias Familiares) são destinados apenas às cooperativas.","Os créditos de investimento devem ser concedidos mediante apresentação de projeto técnico, não podendo ser substituído pela instituição financeira, por proposta simplificada de crédito, mesmo para inversões programadas que envolvam técnicas simples e bem assimiladas pelos agricultores da região"],"correta":2,"explicacao":"Gabarito: <strong>Os créditos de investimento se destinam ao financiamento da implantação, ampliação ou modernização da infraestrutura de produção e serviços, agropecuários ou não-agropecuários, no estabelecimento rural ou em áreas comunitárias rurais próximas, de acordo com projetos específicos.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367742,"enunciado":"0 Fundo Constitucional de Financiamento do Nordeste (FNE) é um instrumento de política pública federal operado pelo Banco do Nordeste do Brasil S.A., que objetiva “contribuir para o desenvolvimento econômico e social do Nordeste, através da execução de programas de financiamento aos setores produtivos, em consonância com o plano regional de desenvolvimento”. Sobre o FNE, assinale a alternativa CORRETA.","opcoes":["O Fundo Constitucional de Financiamento do Nordeste tem a finalidade específica de financiar, em condições compatíveis com as peculiaridades da área, atividades econômicas do semi-árido, às quais destinará todos os recursos disponíveis","São beneficiários dos recursos do Fundo Constitucional do Nordeste os produtores e empresas, pessoas físicas e jurídicas, além das cooperativas de produção que desenvolvam atividades produtivas nos setores agropecuário, mineral, industrial e agroindustrial da Região Nordeste.","O Fundo Constitucional do Nordeste dá tratamento preferencial às atividades produtivas de grandes produtores rurais e empresas de grande porte, às de uso intensivo de capital e que produzam bens de alta tecnologia.","Os financiamentos do Fundo Constitucional do Nordeste poderão ser concedidos a empresas em qualquer estado do Brasil, mas somente os destinados à Região Nordeste serão aplicados a fundo perdido.","A principal fonte de recursos do Fundo Constitucional do Nordeste é o repasse de 5% de toda a arrecadação dos impostos, de qualquer natureza, do Governo Federal."],"correta":1,"explicacao":"Gabarito: <strong>São beneficiários dos recursos do Fundo Constitucional do Nordeste os produtores e empresas, pessoas físicas e jurídicas, além das cooperativas de produção que desenvolvam atividades produtivas nos setores agropecuário, mineral, industrial e agroindustrial da Região Nordeste.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367743,"enunciado":"0 Fundo de Financiamento para Aquisição de Máquinas e Equipamentos Industriais (Finame) é administrado pela Agência Especial de Financiamento Industrial junto ao Banco Nacional de Desenvolvimento Econômico e Social (BNDES). Com relação às características desse Fundo, assinale a alternativa CORRETA.","opcoes":["São considerados agentes financeiros do Finame, além do BNDES, apenas os bancos regionais de desenvolvimento.","Não é passível, nas linhas do Finame, o financiamento ao capital de giro, mesmo que associado à aquisição de máquinas e equipamentos nacionais novos, em operações realizadas com micro, pequenas e médias empresas.","Os encargos financeiros dos programas de financiamento do Finame para todos os programas são de 12% ao ano.","No Programa Finame agrícola são financiáveis aquisição de terrenos e outros bens imóveis e quaisquer despesas que impliquem remessa de divisas, incluindo taxa de franquia paga no exterior","O Programa Finame de Modernização da Indústria Nacional e dos Serviços de Saúde objetiva financiar a aquisição de máquinas e equipamentos novos, de fabricação nacional, com vistas à dinamização do setor de bens de capital e à modernização geral da indústria e do setor de saúde"],"correta":4,"explicacao":"Gabarito: <strong>O Programa Finame de Modernização da Indústria Nacional e dos Serviços de Saúde objetiva financiar a aquisição de máquinas e equipamentos novos, de fabricação nacional, com vistas à dinamização do setor de bens de capital e à modernização geral da indústria e do setor de saúde</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367745,"enunciado":"0 Fundo de Amparo ao Trabalhador (FAT) é um fundo especial, vinculado ao Ministério do Trabalho e Emprego (MTE), destinado ao custeio do Programa do Seguro-Desemprego, do Abono Salarial e ao financiamento de Programas de Desenvolvimento Econômico. Com relação às características do FAT, assinale a alternativa CORRETA.","opcoes":["Os recursos do Fundo de Amparo ao Trabalhador (FAT) são destinados ao financiamento de programas de desenvolvimento econômico, por intermédio do Banco do Brasil.","Para fomentar a geração de emprego e renda, foi criado o Programa de Geração de Emprego e Renda (Proger), que direciona recursos, exclusivamente, para as regiões metropolitanas.","Os recursos do Fundo de Amparo ao Trabalhador (FAT) são destinados exclusivamente ao pagamento do seguro desemprego","O FAT é gerido pelo Conselho Deliberativo do Fundo de Amparo ao Trabalhador (Codefat), órgão colegiado, de caráter tripartite e paritário, composto por representantes dos trabalhadores, dos empregadores e do governo, que atua como gestor do FAT.","O FAT não pode destinar recursos para o Programa Nacional de Desenvolvimento da Agricultura Familiar (Pronaf), uma vez que este já dispõe de orçamento próprio, aprovado previamente pelo Congresso Nacional junto com o Orçamento Geral da União"],"correta":3,"explicacao":"Gabarito: <strong>O FAT é gerido pelo Conselho Deliberativo do Fundo de Amparo ao Trabalhador (Codefat), órgão colegiado, de caráter tripartite e paritário, composto por representantes dos trabalhadores, dos empregadores e do governo, que atua como gestor do FAT.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":367746,"enunciado":"As operações de crédito bancário estão sujeitas a exigências cadastrais e tributárias, tanto de pessoas físicas como jurídicas. Com relação ao assunto, assinale a alternativa CORRETA.","opcoes":["O Sistema de Informações de Crédito do Banco Central (SCR) é um banco de dados que registra informações sobre o montante de débitos e de responsabilidades de clientes em operações de crédito.","Todas as operações de crédito interno e externo, tanto as concedidas a pessoas físicas quanto a pessoas jurídicas, estão sujeitas a uma alíquota de Imposto Sobre Operações Financeiras (IOF).","Os bancos múltiplos e bancos comerciais, que fazem operações de crédito, podem ser constituídos na forma de Sociedades Limitadas","As empresas de Sociedade Anônima, para obter recursos de capital de giro, não podem tomar empréstimos nos bancos.","O Cadastro de Emitentes de Cheques sem Fundos (CCF) é um banco de dados que contém os nomes de empresas que emitem cheques sem dispor de saldo em sua conta para o pagamento."],"correta":0,"explicacao":"Gabarito: <strong>O Sistema de Informações de Crédito do Banco Central (SCR) é um banco de dados que registra informações sobre o montante de débitos e de responsabilidades de clientes em operações de crédito.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369848,"enunciado":"Julgue os próximos itens, relativos à abertura e à movimentação de contas-correntes.\n\nÉ vedada a abertura de conta-corrente em nome de pessoa física que não esteja inscrita no CPF","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369849,"enunciado":"Julgue os próximos itens, relativos à abertura e à movimentação de contas-correntes.\n\nCandidato a cargo legislativo que esteja inscrito no CCF não pode abrir conta-corrente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369850,"enunciado":"No que concerne ao uso de cheque, julgue os itens seguintes.\n\nA instituição financeira é obrigada a fornecer, gratuitamente, até dez folhas de cheques por mês ao correntista que reúna os requisitos legais para o uso desse documento","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369853,"enunciado":"Julgue os itens que se seguem, referentes ao SPB.\n\nAté 2002, o SPB não estava estruturado para que o BCB pudesse acompanhar as operações em tempo real, razão por que a autoridade monetária tinha de arcar com o risco de crédito em eventual inadimplência de alguma instituição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369854,"enunciado":"Julgue os itens que se seguem, referentes ao SPB.\n\nCaso a instituição financeira que será debitada não apresente saldo suficiente no momento da liquidação, a correspondente mensagem eletrônica enviada ao BCB por essa instituição será imediatamente cancelada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369855,"enunciado":"Julgue os itens que se seguem, referentes ao SPB.\n\nA conta de reserva bancária é de titularidade obrigatória para os bancos de investimento e bancos múltiplos sem carteira comercial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369856,"enunciado":"Com referência às funções do BCB, julgue os itens subsequentes.\n\nAs agências de turismo autorizadas a operar com câmbio não fazem parte do SFN, mas fazem parte do universo fiscalizável por parte do BCB","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369857,"enunciado":"Com referência às funções do BCB, julgue os itens subsequentes.\n\nAs operações de arrendamento mercantil, por não serem operações de crédito, não fazem parte do escopo de fiscalização do BCB.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369858,"enunciado":"Com referência às funções do BCB, julgue os itens subsequentes.\n\nO CMN, órgão normativo que estabelece as regras de funcionamento e fiscalização dos entes participantes do SFN, é hierarquicamente subordinado ao BCB.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369859,"enunciado":"Com referência às funções do BCB, julgue os itens subsequentes.\n\nNas operações de mercado aberto, o BCB emite títulos no mercado primário com o propósito de regular a taxa básica de juros SELIC","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369860,"enunciado":"Com referência às funções do BCB, julgue os itens subsequentes.\n\nO Brasil segue o regime de metas de inflação. Caso a meta não seja cumprida, o presidente do BCB divulgará publicamente as razões do descumprimento, por meio de carta aberta ao ministro de estado da Fazenda","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369867,"enunciado":"Acerca das funções e das características da CETIP e do SELIC, julgue os itens subsecutivos.\n\nAs transações realizadas na CETIP envolvem basicamente títulos públicos de renda fixa com alta liquidez.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369868,"enunciado":"Acerca das funções e das características da CETIP e do SELIC, julgue os itens subsecutivos.\n\nA liquidação das operações na CETIP restringe-se à compensação bilateral","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369869,"enunciado":"Acerca das funções e das características da CETIP e do SELIC, julgue os itens subsecutivos.\n\nO SELIC funciona em tempo real, com liquidação da operação mediante a transferência dos recursos para a instituição financeira vendedora e a transferência dos títulos para a instituição financeira compradora","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369870,"enunciado":"A respeito das funções da CVM, julgue os próximos itens.\n\nAs bolsas de mercadorias e futuros têm autonomia financeira, patrimonial e administrativa e são fiscalizadas pela CVM.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369871,"enunciado":"A respeito das funções da CVM, julgue os próximos itens.\n\nA CVM é uma entidade privada sem fins lucrativos, com personalidade jurídica e patrimônio próprios, dotada de autoridade administrativa independente","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369872,"enunciado":"A respeito das funções da CVM, julgue os próximos itens.\n\nCompete à CVM manter o registro de companhias para negociação em bolsa e em mercado de balcão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369875,"enunciado":"Julgue os seguintes itens, relativos à formulação e execução da política monetária no Brasil.\n\nA redução da alíquota do recolhimento compulsório e a compra de títulos em operações de mercado aberto são exemplos da adoção de política monetária expansionista, uma vez que ambas elevam a quantidade de moeda em circulação na economia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369876,"enunciado":"Julgue os seguintes itens, relativos à formulação e execução da política monetária no Brasil\n\nO Brasil adota, desde 1999, o sistema de metas para a inflação, em que o BCB define a meta para a inflação, medida pelo Índice Nacional de Preços ao Consumidor Amplo (IPCA), sobre a qual são aplicados intervalos de tolerância, definidos em lei, de mais ou menos 2%","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369877,"enunciado":"Julgue os seguintes itens, relativos à formulação e execução da política monetária no Brasil\n\nO BCB está autorizado a instituir recolhimento compulsório de até 100% sobre os depósitos à vista e de até 60% sobre as demais operações passivas das instituições financeiras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369878,"enunciado":"Julgue os seguintes itens, relativos à formulação e execução da política monetária no Brasil\n\nOperações de redesconto bancário são operações compromissadas realizadas entre o BCB e instituições previamente credenciadas, denominadas dealers, com o fim de assistência financeira de liquidez.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369879,"enunciado":"Julgue os seguintes itens, relativos à formulação e execução da política monetária no Brasil\n\nAs operações de mercado aberto são transações, realizadas diariamente, de compra e venda de títulos da dívida pública emitidos pelo BCB com o objetivo de controlar a liquidez do sistema bancário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369880,"enunciado":"Com relação às características e funções do mercado monetário e do mercado de crédito, julgue os itens que se seguem.\n\nNo mercado monetário, a oferta de moeda é definida pelo BCB e atende à seguinte relação: quanto maior for a taxa básica de juros da economia, maior será a demanda por moeda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369881,"enunciado":"Com relação às características e funções do mercado monetário e do mercado de crédito, julgue os itens que se seguem.\n\nSão operações típicas do mercado monetário e conhecidas como operações compromissadas as operações de compra com compromisso de revenda, assumido pelo comprador, ou venda com compromisso de recompra, assumido pelo vendedor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369882,"enunciado":"No que diz respeito às características das ações e das debêntures, bem como ao funcionamento do mercado de capitais, julgue os próximos itens\n\nO mercado de balcão compreende as operações realizadas fora do ambiente de bolsa, com ativos não padronizados, que se amoldam às necessidades específicas de cada parte envolvida na transação","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369883,"enunciado":"No que diz respeito às características das ações e das debêntures, bem como ao funcionamento do mercado de capitais, julgue os próximos itens\n\nEm caso de alienação do controle acionário de uma companhia, o acionista adquirente é obrigado a realizar oferta pública de aquisição das demais ações ordinárias e preferenciais, podendo, nesse caso, aplicar um desconto de, no máximo, 10% em relação ao valor pago pelo bloco de controle.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369884,"enunciado":"No que diz respeito às características das ações e das debêntures, bem como ao funcionamento do mercado de capitais, julgue os próximos itens .\n\nAs ações preferenciais, embora não deem direito a voto ou restrinjam o exercício desse direito, conferem prioridades na distribuição de dividendos aos seus titulares.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369885,"enunciado":"No que diz respeito às características das ações e das debêntures, bem como ao funcionamento do mercado de capitais, julgue os próximos itens .\n\nUma companhia é considerada fechada se menos de 50% dos valores mobiliários de sua emissão, inclusive as debêntures, são admitidos à negociação no mercado secundário","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369886,"enunciado":"No que diz respeito às características das ações e das debêntures, bem como ao funcionamento do mercado de capitais, julgue os próximos itens .\n\nDebêntures são títulos de dívida de médio e longo prazo, emitidos por sociedades por ações, de capital aberto ou fechado, e utilizados para o financiamento de seus projetos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369891,"enunciado":"Julgue os itens subsequentes, relativos às características dos mercados primário e secundário de títulos e valores mobiliários.\n\nA emissão de títulos públicos pelo Tesouro Nacional é uma operação de mercado primário; a compra e venda desses títulos pelo BCB, como medida de política monetária, é realizada no mercado secundário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369892,"enunciado":"Julgue os itens subsequentes, relativos às características dos mercados primário e secundário de títulos e valores mobiliários.\n\nA oferta pública de ações para o aumento do capital social de uma companhia de capital aberto é classificada como uma operação de mercado secundário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369893,"enunciado":"Julgue os itens subsequentes, relativos às características dos mercados primário e secundário de títulos e valores mobiliários.\n\nO mercado primário é aquele em que os investidores, após adquirirem títulos ou valores mobiliários diretamente do emissor, podem negociar e transferir entre si esses ativos, seja no ambiente de bolsa de valores, seja no mercado de balcão organizado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369894,"enunciado":"Com relação aos programas de governo e produtos oferecidos em agências ou correspondentes bancários da CAIXA, julgue os seguintes itens.\n\nO Microcrédito Crescer CAIXA oferece créditos de R$ 300 a R$ 15 mil, com prazo de pagamento de até doze meses, para o empreendedor pessoa física que deseje investir na compra de equipamentos ou material de construção para aprimorar o seu negócio.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369895,"enunciado":"Com relação aos programas de governo e produtos oferecidos em agências ou correspondentes bancários da CAIXA, julgue os seguintes itens.\n\nO Penhor CAIXA é uma linha de crédito não renovável, no valor de até 130% do bem oferecido em garantia, cujo pagamento pode ser parcelado pelo prazo de até cento e oitenta dias","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369896,"enunciado":"Com relação aos programas de governo e produtos oferecidos em agências ou correspondentes bancários da CAIXA, julgue os seguintes itens.\n\nAs casas lotéricas podem atuar como correspondentes bancários de outras instituições financeiras no país, mas a exploração dos serviços da Loteria Federal do Brasil é exclusiva da CAIXA.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369897,"enunciado":"Com relação aos programas de governo e produtos oferecidos em agências ou correspondentes bancários da CAIXA, julgue os seguintes itens.\n\nO programa Minha Casa Minha Vida oferece financiamentos imobiliários para famílias com renda mensal de até R$ 5 mil","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369898,"enunciado":"Com relação aos programas de governo e produtos oferecidos em agências ou correspondentes bancários da CAIXA, julgue os seguintes itens.\n\nNas cidades com população igual ou superior a 250 mil habitantes, são elegíveis a financiamento imobiliário no âmbito do programa Minha Casa Minha Vida os imóveis com valor de avaliação de até R$ 175 mil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369899,"enunciado":"A respeito dos meios de pagamento eletrônico conhecidos como cartões de crédito e cartões de débito, julgue os itens subsecutivos.\n\nA cobrança do uso de cartões de crédito emitidos por instituições financeiras está limitada a três tarifas específicas: anuidade, segunda via do cartão magnético e uso da função saque.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369900,"enunciado":"A respeito dos meios de pagamento eletrônico conhecidos como cartões de crédito e cartões de débito, julgue os itens subsecutivos.\n\nO valor mínimo da fatura de cartão de crédito emitida por instituições financeiras, a ser paga mensalmente, não pode ser inferior a 20% do saldo total da fatura.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":369901,"enunciado":"A respeito dos meios de pagamento eletrônico conhecidos como cartões de crédito e cartões de débito, julgue os itens subsecutivos.\n\nA cobrança de tarifa para a emissão de segunda via de cartões com a função débito é permitida nos casos de pedidos de reposição formulados pelo correntista e decorrentes de motivos não imputáveis à instituição financeira emitente","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397176,"enunciado":"À luz das normas da Carta Circular Bacen no 3.542/2012, são consideradas situações relacionadas com dados cadastrais de clientes:","opcoes":["negociações de moeda estrangeira em espécie, em municípios localizados em regiões de fronteira, que não apresentem compatibilidade com a natureza declarada da operação.","negociações de moeda estrangeira em espécie ou cheques de viagem denominados em moeda estrangeira, que não apresentem compatibilidade com a natureza declarada da operação.","negociações de moeda estrangeira em espécie ou cheques de viagem denominados em moeda estrangeira, realizadas por diferentes pessoas naturais, não relacionadas entre si, que informem o mesmo endereço residencial.","recebimentos de moeda estrangeira em espécie por pessoas naturais residentes no exterior, transitoriamente no País, decorrentes de ordens de pagamento a seu favor ou da utilização de cartão de uso internacional, sem a evidência de propósito claro.","resistência ao fornecimento de informações necessárias para o início de relacionamento ou para a atualização cadastral, oferecimento de informação falsa ou prestação de informação de difícil ou onerosa verificação."],"correta":4,"explicacao":"Gabarito: <strong>resistência ao fornecimento de informações necessárias para o início de relacionamento ou para a atualização cadastral, oferecimento de informação falsa ou prestação de informação de difícil ou onerosa verificação.</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397177,"enunciado":"À luz das normas da Circular Bacen no 3.461/2009, que estabelece regras de conduta quanto às atividades suspeitas de lavagem de dinheiro, as instituições financeiras que não tiverem efetuado comunicações nos termos da norma, em cada ano civil, deverão prestar declaração, atestando a não ocorrência de transações passíveis de comunicação, por meio do Sistema","opcoes":["de Controle de Atividades Financeiras","de Comunicação ao Ministério da Fazenda","de Registro de Operações do Banco Central","do Banco Central de apoio ao Judiciário","especial de Informações ao Ministério Público"],"correta":0,"explicacao":"Gabarito: <strong>de Controle de Atividades Financeiras</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397178,"enunciado":"Nos termos da Resoluçao CMN nº 4.222/2013, que regula o Fundo Garantidor de Crédito, o atraso no recolhimento das contribuições devidas sujeita a instituição associada sobre o valor de cada contribuição à multa de :","opcoes":["2%","3%","4%","5%","6%"],"correta":0,"explicacao":"Gabarito: <strong>2%</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397179,"enunciado":"À luz das normas que regulam a alienação fiduciária imobiliária, considera-se objeto desse negócio a","opcoes":["posse individual imobiliária","propriedade superficiária","servidão de passagem","expectativa de vista panorâmica","composse coletiva"],"correta":1,"explicacao":"Gabarito: <strong>propriedade superficiária</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397180,"enunciado":"Atualmente, o Sistema Financeiro Nacional é composto por órgãos normativos, entidades supervisoras e por operadores. Um dos órgãos normativos que compõe o Sistema Financeiro Nacional é o(a) :","opcoes":["Banco Nacional de Desenvolvimento Econômico e Social - BNDES","Banco Comercial","Conselho Monetário Nacional","Bolsa de Valores","Superintendência de Seguros Privados - SUSEP"],"correta":2,"explicacao":"Gabarito: <strong>Conselho Monetário Nacional</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397181,"enunciado":"O Conselho de Recursos do Sistema Financeiro Nacional (CRSFN) é um órgão colegiado, de segundo grau, integrante da estrutura do Ministério da Fazenda. Com o advento da Lei nº 9.069/1995, ampliou-se a competência do CRSFN, que recebeu a responsabilidade de:","opcoes":["administrar mecanismo de proteção a titulares de créditos contra instituições financeiras.","zelar pela adequada liquidez e estabilidade da economia, e promover o permanente aperfeiçoamento do sistema financeiro","atuar no sentido de proteger a captação de poupança popular que se efetua através das operações de seguro, de previdência privada aberta, de capitalização e de resseguro.","regular a constituição, organização, funcionamento e fiscalização dos que exercem atividades subordinadas ao Sistema Nacional de Seguros Privados (SNSP)","julgar os recursos interpostos contra as decisões do Banco Central do Brasil relativas à aplicação de penalidades por infração à legislação cambial, à legislação de capitais estrangeiros e à legislação de crédito rural e industrial"],"correta":4,"explicacao":"Gabarito: <strong>julgar os recursos interpostos contra as decisões do Banco Central do Brasil relativas à aplicação de penalidades por infração à legislação cambial, à legislação de capitais estrangeiros e à legislação de crédito rural e industrial</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397182,"enunciado":"As sociedades de arrendamento mercantil são supervisionadas pelo Banco Central do Brasil e realizam operações de arrendamento de bens móveis e imóveis. Uma das principais operações de arrendamento mercantil é denominada","opcoes":["Leasing","Factoring","Hot Money","Corporate finance","Commercial papers"],"correta":0,"explicacao":"Gabarito: <strong>Leasing</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397183,"enunciado":"A Comissão de Valores Mobiliários (CVM) é uma entidade que compõe o sistema financeiro nacional, além de ser uma autarquia vinculada ao Ministério da Fazenda. A CVM é responsável por:","opcoes":["realizar transações de compra e venda de títulos e valores mobiliários, em mercado livre e aberto.","regulamentar, desenvolver, controlar e fiscalizar o mercado de valores mobiliários do país","controlar e fiscalizar o mercado de seguro, a previdência privada aberta e a capitalização.","negociar contratos de títulos de capitalização.","garantir o poder de compra da moeda nacional."],"correta":1,"explicacao":"Gabarito: <strong>regulamentar, desenvolver, controlar e fiscalizar o mercado de valores mobiliários do país</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397184,"enunciado":"Os bancos de desenvolvimento são instituições financeiras controladas pelos governos estaduais e têm como objetivo principal prestar serviços que proporcionem o desenvolvimento econômico e social do Estado. Um serviço característico dos bancos de desenvolvimento é a(o):","opcoes":["captação de depósitos à vista","operação de participação societária de caráter temporário","operação no mercado imobiliário e no sistema financeiro da habitação","financiamento a longo prazo de programas e projetos","financiamento do capital de giro de uma empresa"],"correta":3,"explicacao":"Gabarito: <strong>financiamento a longo prazo de programas e projetos</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":397185,"enunciado":"A caderneta de poupança é um dos investimentos mais populares do Brasil, principalmente por ser um investimento de baixo risco. A poupança é regulada pelo Banco Central, e, atualmente, com a meta da taxa Selic superior a 8,5%, sua remuneração é de :","opcoes":["0,3% ao mês, mais a variação do CDB","IGPM (Índice Geral de Preços do Mercado), mais TR (Taxa Referencial)","TR (Taxa Referencial), mais 0,5% ao mês","0,5% ao mês","6% ao ano"],"correta":2,"explicacao":"Gabarito: <strong>TR (Taxa Referencial), mais 0,5% ao mês</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405202,"enunciado":"Leia o texto a seguir, extraído da home page do Banco do Nordeste do Brasil S.A. (BNB): “A atividade que define uma instituição financeira é a concessão de crédito”. Porém, para cumprir a missão de desenvolvimento em uma região com muitas potencialidades ainda não exploradas, o Banco do Nordeste entende que o crédito é necessário, mas não deve ser o único serviço oferecido. Com esta convicção, o Banco criou diversos instrumentos que lhe possibilitaram atuar mais próximo dos clientes e ampliar suas atividades, indo além da intermediação financeira, buscando contribuir para garantir a sustentabilidade dos empreendimentos financiados, associada à melhoria das condições de vida da população nordestina. São ações antecedentes e subsequentes à concessão de crédito que vêm contribuindo para maior efetividade dos recursos aplicados, seja por darem maior capilaridade ao Banco, possibilitando maior aproximação com o cliente e conhecimento de seu negócio, seja por favorecerem a identificação de parceiros para implementação de iniciativas conjuntas, por exemplo, nas áreas de pesquisa, assistência técnica e apoio à comercialização”. Com relação às ações e instrumentos utilizados pelo Banco do Nordeste, analise os itens a seguir: (I) O Programa de Desenvolvimento da Agricultura Familiar na Zona da Mata - PROMATA - de apoio aos pequenos produtores; (II) As políticas de desenvolvimento territorial; (III) O Crediamigo, programa de microcrédito produtivo orientado que facilita o acesso ao crédito a milhares de empreendedores; (IV) Os agentes de desenvolvimento e as agências itinerantes. Assinale se:","opcoes":["somente III estiver correto;","somente I e IV estiverem corretos;","somente I, II e III estiverem corretos;","somente II, III e IV estiverem corretos;","somente I, II e IV estiverem corretos."],"correta":3,"explicacao":"Gabarito: <strong>somente II, III e IV estiverem corretos;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405209,"enunciado":"O Sistema Financeiro Nacional (SFN) é composto por um conjunto de instituições que se dedica a manter o fluxo de recursos entre unidades superavitárias (poupadoras) e unidades deficitárias (tomadoras / investidoras). O SFN mantém a ordem no mercado financeiro por meio de normas e procedimentos. O SFN é composto por um sistema normativo, além dos agentes que o operam, tais como instituições (especiais e auxiliares) e intermediários financeiros – monetários e não monetários. Considerando as diferenças entre esses agentes, é correto afirmar que:","opcoes":["intermediários financeiros captam recursos junto ao público e investem na Bolsa de Valores; as instituições auxiliares, embora também captem junto ao público, investem no mercado imobiliário;","intermediários financeiros monetários captam recursos junto ao público e emprestam esses recursos, criando moeda escritural; as instituições auxiliares colocam em contato poupadores e investidores e não criam moeda escritural;","intermediários financeiros monetários captam recursos junto ao público e emprestam esses recursos, criando moeda escritural; as instituições auxiliares colocam em contato poupadores e investidores, criando também moeda escritural;","intermediários financeiros não monetários captam depósitos à vista e as instituições especiais não captam depósitos à vista;","instituições especiais fazem empréstimos especiais, enquanto as instituições auxiliares auxiliam o Banco Central a regular o sistema."],"correta":1,"explicacao":"Gabarito: <strong>intermediários financeiros monetários captam recursos junto ao público e emprestam esses recursos, criando moeda escritural; as instituições auxiliares colocam em contato poupadores e investidores e não criam moeda escritural;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405210,"enunciado":"O Banco Central do Brasil (BC ou BACEN) foi criado pela lei nº 4595, de 31/12/1964, para atuar como órgão executivo central do sistema financeiro, tendo como funções cumprir e fazer cumprir as disposições que regulam o funcionamento do sistema e as normas expedidas pelo CMN (Conselho Monetário Nacional). Entre as atribuições do Banco Central estão:","opcoes":["emitir papel-moeda, exercer o controle do crédito e exercer a fiscalização das instituições financeiras, punindo-as quando necessário;","determinar as taxas de recolhimento compulsório, autorizar as emissões de papel-moeda e estabelecer metas de inflação;","regulamentar as operações de redesconto de liquidez, coordenar as políticas monetárias creditícia e cambial e estabelecer metas de inflação;","regular o valor interno da moeda, regular o valor externo da moeda e zelar pela liquidez e solvência das instituições financeiras;","determinar as taxas de recolhimento compulsório, regular o valor interno e externo da moeda e autorizar as emissões de papel-moeda."],"correta":0,"explicacao":"Gabarito: <strong>emitir papel-moeda, exercer o controle do crédito e exercer a fiscalização das instituições financeiras, punindo-as quando necessário;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405211,"enunciado":"Os seguintes bens podem ser oferecidos como garantia na modalidade penhor: (I) joias e relógios; (II) imóveis; (III) aeronaves; (IV) navios. Assinale se:","opcoes":["somente I e III estiverem corretas;","somente II e IV estiverem corretas;","somente I estiver correta;","somente II estiver correta;","somente II, III e IV estiverem corretas."],"correta":2,"explicacao":"Gabarito: <strong>somente I estiver correta;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405212,"enunciado":"O Conselho Monetário Nacional (CMN) é o órgão responsável pela fixação das diretrizes das políticas monetária, creditícia e cambial do país. Não cabem ao CMN funções executivas. O número de membros do CMN foi variável desde a sua criação (31/12/1964), de acordo com as exigências políticas e econômicas de cada Governo. Em razão da Lei nº 9.069/95, em vigor, o CMN passou a ser integrado por:","opcoes":["11 (onze) membros;","10 (dez) membros;","8 (oito) membros;","4 (quatro) membros;","3 (três) membros."],"correta":4,"explicacao":"Gabarito: <strong>3 (três) membros.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405213,"enunciado":"Sobre o SPB (Sistema de Pagamentos Brasileiro), é correto afirmar que:","opcoes":["o SPB não possui interligação de nenhuma ordem com o Banco Central;","uma das funções do SPB é dar maior agilidade e segurança às transações bancárias;","o SPB diminuiu a carga de trabalho do BACEN, estimulando a criação e o desenvolvimento de sistemas e procedimentos que não se relacionam com a transferência de recursos financeiros;","os princípios básicos de funcionamento do SPB foram estabelecidos pelo Conselho Monetário Nacional (CMN) e pela Comissão de Valores Mobiliários (CVM);","o SPB é responsável pelo controle e fiscalização dos bancos de varejo no Brasil."],"correta":1,"explicacao":"Gabarito: <strong>uma das funções do SPB é dar maior agilidade e segurança às transações bancárias;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405214,"enunciado":"O Sistema normativo é composto pelas entidades que regulam e fiscalizam o funcionamento do Sistema Financeiro Nacional. Por esse motivo estão no topo do organograma, ou seja, as outras instituições têm que, obrigatoriamente, acatar as decisões do sistema normativo. Entre as entidades que compõem o Sistema Normativo, encontram-se:","opcoes":["sociedades corretivas e distribuidoras;","bancos múltiplos e de investimento;","Banco do Brasil e Caixa Econômica Federal;","Conselho Monetário Nacional e Banco Central do Brasil;","Bolsa de Valores e Comissão de Valores Mobiliários (CVM)."],"correta":3,"explicacao":"Gabarito: <strong>Conselho Monetário Nacional e Banco Central do Brasil;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405215,"enunciado":"Com relação à sociedade limitada, analise as afirmativas a seguir: I. Os sócios, após a integralização do capital social, respondem até o valor de suas quotas pelas obrigações sociais. II. Os sócios não têm responsabilidade solidária pela integralização do capital social. III. É disciplinada em capítulo próprio do Código Civil em vigor, podendo o contrato prever a regência supletiva pelas normas das companhias. IV. As quotas sociais poderão ser transferidas a terceiros, não sócios, caso o contrato seja omisso, com o consentimento de todos os sócios. Estão corretas somente as afirmativas:","opcoes":["I e II;","I e III;","II e III;","II e IV;","III e IV."],"correta":1,"explicacao":"Gabarito: <strong>I e III;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405216,"enunciado":"Com relação aos serviços bancários e financeiros, considere as seguintes afirmativas: (I) A conta especial de depósitos à vista (conta simplificada para clientes de baixa renda) é individual (apenas um titular). Cada cliente pode ter apenas uma conta e não pode ser correntista em qualquer outra instituição financeira. Essa conta está isenta de tarifa e possui franquia mensal de cinco extratos, cinco depósitos e cinco saques. (II) Bancos de investimento captam depósitos à vista e depósitos de poupança, atuando mais fortemente no crédito agrícola. (III) Depósitos a prazo, tais como CDB e RDB, são modalidades de investimento, geralmente classificadas em pós-fixadas, pré- fixadas e flutuantes. (IV) Só é possível a abertura de conta de investimento ao cliente que possuir pelo menos uma conta corrente de depósitos à vista, ainda que em instituição distinta. Assinale se:","opcoes":["somente II e III estiverem corretas;","somente III e IV estiverem corretas;","somente I, II e IV estiverem corretas;","I, II, III e IV estiverem corretas;","nenhuma afirmativa estiver correta."],"correta":0,"explicacao":"Gabarito: <strong>somente II e III estiverem corretas;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405217,"enunciado":"Os parâmetros básicos utilizados para orientar a concessão de crédito norteiam-se nos chamados “C’s do crédito”. São eles:","opcoes":["caráter, carreira, capacidade, condições e colateral;","cadastro, comunicação, caráter, coação e capital;","caráter, cadastro, capital, condições e composição;","caráter, capacidade, capital, condições e colateral;","caráter, cadastro, capacidade, condições e comunicação."],"correta":3,"explicacao":"Gabarito: <strong>caráter, capacidade, capital, condições e colateral;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405218,"enunciado":"Os bancos ganham dinheiro com receitas de intermediação financeira e com receitas de prestação de serviços e tarifas. Entre as principais receitas bancárias de prestação de serviços e tarifas, destacam-se: I. tarifas sobre depósito à vista e sobre aplicações em CDBs; II. tarifas sobre serviços de conta corrente e de corretagem e custódia; III. tarifas sobre emissões e anuidades de cartões de crédito; IV. receitas sobre administração de fundos de investimento e administração de consórcios. Está(ão) correta(s) somente:","opcoes":["I e IV;","II e III;","III;","IV;","II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>II, III e IV.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405219,"enunciado":"O Código Civil disciplina o empréstimo de coisas nos contratos de comodato e mútuo. Quanto às distinções entre esses contratos, analise as afirmativas a seguir: I- O comodato é um contrato consensual, unilateral e comutativo; o mútuo é um contrato real, bilateral e aleatório. II- O comodato é o empréstimo de coisas infungíveis; o mútuo é o empréstimo de coisas fungíveis. III- O comodato deve ser ajustado por escrito; o mútuo pode ser ajustado verbalmente ou por instrumento público. IV- O comodatário deverá conservar a coisa para aliená-la a terceiros; o mutuário não poderá aliená-la a terceiros. V- O comodato não transfere o domínio da coisa emprestada; o mutuário adquire o domínio da coisa do mutuante. Estão corretas somente as afirmativas:","opcoes":["I e III;","I e IV;","II e IV;","II e V;","III e V."],"correta":3,"explicacao":"Gabarito: <strong>II e V;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405220,"enunciado":"Nem todas as sociedades são obrigadas a elaborar e publicar sua Demonstração Financeira, tais como:","opcoes":["cooperativas de crédito;","companhias abertas;","microempresas enquadradas no Simples Nacional;","sociedades anônimas controladas por sociedades do tipo limitada;","bancos comerciais e de investimento."],"correta":2,"explicacao":"Gabarito: <strong>microempresas enquadradas no Simples Nacional;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405221,"enunciado":"Com relação à diferença entre aval e fiança, é correto afirmar que:","opcoes":["o aval é uma garantia pessoal, enquanto a fiança é uma garantia real;","o aval é uma garantia real, enquanto a fiança é uma garantia pessoal;","o aval é uma garantia constituída em um título de crédito, enquanto a fiança é uma garantia estabelecida em contrato ou carta;","no aval, o credor pode acionar diretamente o avalista, enquanto na fiança se aciona o fiel depositário;","o aval precisa da assinatura do cônjuge, enquanto a fiança não tem essa exigência."],"correta":2,"explicacao":"Gabarito: <strong>o aval é uma garantia constituída em um título de crédito, enquanto a fiança é uma garantia estabelecida em contrato ou carta;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405222,"enunciado":"As Instituições Financeiras podem ser classificadas em monetárias e não monetárias. Entre as instituições financeiras monetárias, encontram-se:","opcoes":["Bancos Comerciais e Bancos de Investimento;","Bancos de Investimento e Bancos de Desenvolvimento;","Bancos Comerciais e Bancos de Desenvolvimento;","Bancos de Investimento e Caixas Econômicas;","Bancos Comerciais e Caixas Econômicas."],"correta":4,"explicacao":"Gabarito: <strong>Bancos Comerciais e Caixas Econômicas.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405223,"enunciado":"O Plano Gerador de Benefício Livre (PGBL) se difere do Vida Gerador de Benefício Livre (VGBL) no que tange ao tratamento fiscal. No caso do PGBL:","opcoes":["o imposto de renda é pago no resgate e incide sobre o total do valor resgatado;","o imposto de renda é pago no resgate e incide sobre os ganhos de capital;","o imposto de renda é pago semestralmente e incide sobre os ganhos de capital;","ambas as aplicações são isentas de cobrança de imposto de renda;","ambas as aplicações estão sujeitas a alíquota fixa de 6% de imposto de renda."],"correta":0,"explicacao":"Gabarito: <strong>o imposto de renda é pago no resgate e incide sobre o total do valor resgatado;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405224,"enunciado":"Com relação ao CCF (cadastro de emitentes de cheques sem fundos), é correto afirmar que:","opcoes":["o CCF é operacionalizado pelo Banco Central do Brasil;","qualquer banco pode fornecer a seus clientes informação quanto à inclusão de seu nome no CCF, sem cobrar qualquer tarifa por essa pesquisa;","constitui motivo para inclusão do nome do correntista no CCF a devolução de um cheque por insuficiência de fundos na sua primeira apresentação;","quando se trata de conta corrente conjunta, são incluídos no CCF todos os nomes e CPF dos titulares da conta;","quando um cheque sem fundos é devolvido, além da cobrança de tarifas, o banco pode cobrar do correntista uma taxa de ressarcimento."],"correta":0,"explicacao":"Gabarito: <strong>o CCF é operacionalizado pelo Banco Central do Brasil;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405225,"enunciado":"O contrato de compra e venda é uma espécie de negócio jurídico pela qual um dos contratantes se obriga a transferir o domínio de certa coisa, e o outro, a pagar-lhe certo preço em dinheiro. Com relação a esse contrato, considere as afirmativas abaixo: I. O contrato de compra e venda é nulo, quando se deixa ao arbítrio exclusivo de uma das partes a fixação do preço. II. A compra e venda pode ter por objeto coisa atual ou futura. III. A lei civil autoriza expressamente a compra e venda entre cônjuges, com relação a bens excluídos da comunhão. IV. A fixação do preço não pode, de maneira nenhuma, ser deixada ao arbítrio de terceiro. Assinale se:","opcoes":["II e IV estiverem corretas;","I, II e IV estiverem corretas;","I, II e III estiverem corretas;","IV estiver correta;","I, II, III e IV estiverem corretas."],"correta":2,"explicacao":"Gabarito: <strong>I, II e III estiverem corretas;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405226,"enunciado":"O Conselho Monetário Nacional (CMN) é o órgão superior do Sistema Financeiro. A política do CMN objetiva:","opcoes":["regular o valor interno e externo da moeda;","controlar exclusivamente o fluxo de capitais estrangeiros;","realizar operações de redesconto e empréstimos, como instrumento de política monetária como auxílio a problemas de liquidez;","fiscalizar a interferência de outras sociedades nos mercados financeiros e de capitais;","emitir papel moeda e moeda metálica."],"correta":0,"explicacao":"Gabarito: <strong>regular o valor interno e externo da moeda;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405227,"enunciado":"As operações de empréstimo concedidas por instituições financeiras à pessoa física ou jurídica que se dedique à atividade comercial ou de prestação de serviços poderão ser representadas por Cédula de Crédito Comercial ou por Nota de Crédito Comercial. Sobre esses títulos de crédito e suas garantias, é correto afirmar que:","opcoes":["nas cédulas e notas de crédito comercial, não poderão ser pactuados juros capitalizados, sob pena de nulidade dos títulos e dos contratos a eles vinculados;","a não inscrição da cédula de crédito comercial no Cartório de Registro de Imóveis retira sua validade tanto entre as partes quanto em relação a terceiros;","o beneficiário da cédula de crédito comercial é a instituição financeira concedente do empréstimo; na nota de crédito comercial, a instituição financeira é a emitente do título;","a não identificação dos bens objeto da alienação fiduciária cedular não retira a eficácia da garantia, que incidirá sobre outros de mesmo gênero, quantidade e qualidade;","é obrigatória a descrição dos bens objeto de penhor e do local de seu depósito quando a garantia se constituir através de penhor de títulos de crédito."],"correta":3,"explicacao":"Gabarito: <strong>a não identificação dos bens objeto da alienação fiduciária cedular não retira a eficácia da garantia, que incidirá sobre outros de mesmo gênero, quantidade e qualidade;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405228,"enunciado":"Com relação aos títulos de crédito, é correto afirmar que:","opcoes":["para a execução de uma duplicata não aceita e não devolvida, há obrigatoriedade do protesto por falta de pagamento e comprovação da remessa da mercadoria;","a omissão de qualquer requisito legal, que tire ao escrito a sua validade como título de crédito, implica a invalidade do negócio jurídico que lhe deu origem;","o aval deve ser dado no verso ou no anverso do próprio título, sendo necessário conter a data e a assinatura do avalista;","em nenhuma hipótese o emitente de uma nota promissória pode opor ao portador endossatário as exceções que poderia opor contra o endossante;","caso a quantia, em uma nota promissória, esteja escrita mais de uma vez, quer por extenso, quer em algarismos, havendo divergência, prevalecerá a indicação da quantia de menor valor."],"correta":4,"explicacao":"Gabarito: <strong>caso a quantia, em uma nota promissória, esteja escrita mais de uma vez, quer por extenso, quer em algarismos, havendo divergência, prevalecerá a indicação da quantia de menor valor.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405229,"enunciado":"O processo do crédito à pessoa física começa com a coleta e a verificação da veracidade das informações obtidas na ficha de cadastro e em consultas às agências especializadas. Essas informações permitem a atribuição de uma pontuação (credit score), após a qual se aceita ou não o potencial cliente como merecedor de um limite para uma ou mais operações. No caso da pessoa física, a informação que mais interfere na não aceitação de um potencial cliente é:","opcoes":["idade entre 45 e 60 anos;","existência de restrições e/ou desabonos no nome do potencial cliente;","baixo patrimônio em nome do potencial cliente;","participação do potencial cliente em sociedades de pequeno porte;","renda familiar entre R$ 1.500,00 e R$ 3.000,00."],"correta":1,"explicacao":"Gabarito: <strong>existência de restrições e/ou desabonos no nome do potencial cliente;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405230,"enunciado":"Pedreira Pedra Mole Ltda. pretende descontar duplicatas perante o Banco X. Todos os títulos estão vencidos há mais de quarenta dias e sem pagamento pelo aceitante; também não houve protesto por falta de pagamento. Considerando-se que a orientação do Banco X para desconto de duplicatas é sempre poder cobrar do endossante através de processo de execução, a conduta a ser adotada, com a correspondente justificativa, é:","opcoes":["recusar o desconto das duplicatas, porque, caso o Banco figure como endossatário, não poderá exercer o direito de regresso em face do endossante;","recusar o desconto das duplicatas, porque o aceite na duplicata é proibido, e seu descumprimento acarreta a perda do direito de ação em face dos coobrigados;","aceitar o desconto das duplicatas, porque será possível promover ação de execução em face do endossante, já que este é sempre um coobrigado pelo pagamento;","aceitar o desconto das duplicatas, porque será possível promover ação de execução em face do endossante, já que este é sempre um coobrigado pelo pagamento;","aceitar o desconto das duplicatas, desde que os títulos estejam protestados por falta de pagamento e acompanhados do comprovante de entrega da mercadoria."],"correta":0,"explicacao":"Gabarito: <strong>recusar o desconto das duplicatas, porque, caso o Banco figure como endossatário, não poderá exercer o direito de regresso em face do endossante;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405231,"enunciado":"Zabelê tem 17 (dezessete) anos de idade e pediu a seu pai a abertura de uma conta corrente bancária para depositar recursos. O pai concordou com o pedido do filho e procurou a instituição financeira. Na abertura de conta, o empregado responsável irá orientar o futuro correntista que:","opcoes":["o pai de Zabelê é considerado representante legal do absolutamente incapaz e deverá movimentar a conta corrente simultaneamente com ele;","o pai de Zabelê deverá obter autorização judicial prévia à abertura de conta corrente em favor do relativamente incapaz e deverá movimentá-la com ele;","Zabelê poderá abrir a conta corrente e movimentá-la independentemente de autorização de seu pai porque é plenamente capaz para os atos civis;","o pai de Zabelê deverá ser identificado na abertura da conta corrente como responsável assistente do relativamente incapaz, que poderá movimentá-la;","por ser relativamente incapaz, Zabelê deverá estar autorizado pelos seus pais e tutor, que os assistirão na abertura da conta e responderão solidariamente com ele."],"correta":3,"explicacao":"Gabarito: <strong>o pai de Zabelê deverá ser identificado na abertura da conta corrente como responsável assistente do relativamente incapaz, que poderá movimentá-la;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405232,"enunciado":"O cheque é um dos instrumentos disponibilizados pelos bancos para os clientes movimentarem suas contas correntes. Acerca desse título de crédito, considere as seguintes afirmativas: I. Os cheques cruzados só podem ser pagos presencialmente ao beneficiário no estabelecimento sobre o qual foi sacado. II. Os bancos podem recusar o pagamento de um cheque, caso haja insuficiência ou divergência na assinatura constante de seus cadastros. III. Os cheques emitidos acima de R$ 75,00 (setenta e cinco reais) devem, obrigatoriamente, ser nominais. Assinale se:","opcoes":["somente I e II estiverem corretas;","somente I e III estiverem corretas;","apenas II estiver correta;","somente II e III estiverem corretas;","somente I, II e III estiverem corretas."],"correta":2,"explicacao":"Gabarito: <strong>apenas II estiver correta;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405233,"enunciado":"Na assinatura de contrato pelo Banco X com sociedade empresária do tipo limitada foram emitidas pelo administrador da sociedade cinco notas promissórias, cada uma no valor de R$12.000,00 (doze mil reais), vinculadas ao cumprimento do contrato. Rosa de Lima, empregada do banco, recebeu o contrato e os títulos para conferência e verificou que em nenhum deles foi indicado o lugar de emissão. Ao consultar seu superior, recebeu a informação correta de que as notas promissórias são:","opcoes":["nulas e deverão ser substituídas por outras onde conste expressamente o lugar de emissão;","válidas, por se tratar de título de crédito causal vinculado a um contrato de mútuo de fins econômicos;","válidas, pois na falta de indicação do lugar de emissão presume-se que esta se deu no domicílio do subscritor;","nulas, porque deveria ter sido emitida cédula de crédito bancário para qualquer contrato bancário;","nulas, porque não houve, pela sociedade, prestação de garantia real vinculada ao cumprimento do contrato."],"correta":2,"explicacao":"Gabarito: <strong>válidas, pois na falta de indicação do lugar de emissão presume-se que esta se deu no domicílio do subscritor;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405234,"enunciado":"Foi celebrado contrato no âmbito do mercado financeiro entre o Banco W e a sociedade empresária Telha Empreendimentos Turísticos Ltda. pela qual o primeiro terá a propriedade fiduciária em caráter resolúvel de certo bem móvel fungível, em garantia do financiamento concedido, e a segunda, uso e gozo do referido bem. De acordo com as disposições legais relativas a esse contrato e ao procedimento de cobrança, é correto afirmar que, em caso de inadimplemento ou mora da obrigação garantida:","opcoes":["o credor poderá vender a terceiros o bem objeto da propriedade fiduciária independente de leilão, hasta pública ou qualquer outra medida judicial ou extrajudicial;","o credor deverá interpor o protesto extrajudicial e, com a obtenção da lavratura e registro do protesto, requerer judicialmente a busca e apreensão do bem para posterior venda em hasta pública;","o credor poderá adjudicar em juízo imediatamente o bem, independentemente de previsão contratual ou purgação da mora pelo devedor;","o devedor poderá reter o bem em seu poder até que o credor lhe pague as despesas feitas com a coisa, e os prejuízos que da sua conservação provierem, se devidamente provados;","verificada a mora, independentemente de notificação ou interpelação, o devedor poderá requerer o depósito judicial da coisa para evitar sua alienação extrajudicial pelo credor."],"correta":0,"explicacao":"Gabarito: <strong>o credor poderá vender a terceiros o bem objeto da propriedade fiduciária independente de leilão, hasta pública ou qualquer outra medida judicial ou extrajudicial;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405235,"enunciado":"Augusto Cardoso contraiu obrigação perante o Banco W S/A com garantia pessoal (fiança) prestada por Cristóvão Carira. No contrato de fiança ficou estabelecido que o fiador é garante solidário ao afiançado, inexistindo qualquer benefício de ordem a seu favor. Na data do vencimento, Augusto Cardoso obteve do credor uma prorrogação de prazo para o pagamento por 120 (cento e vinte) dias, sendo tal acordo celebrado por escrito e sem a anuência ou ciência de Cristóvão Carira. Com base nas disposições do Código Civil relativas ao contrato de fiança, é correto afirmar que:","opcoes":["o fiador permanece obrigado ao pagamento porque ao prestar a fiança se declarou garante solidário ao afiançado;","o fiador ficou desobrigado ao pagamento da obrigação em caso de inadimplemento, operando-se a extinção da fiança;","do fiador poderá ser exigido o pagamento imediato da dívida, mas perante o afiançado prevalecerá o acordo entre este e o credor;","deverá o fiador interpelar judicialmente o afiançado para ser incluído como parte no acordo firmado por este e o credor;","o credor deverá interpelar o fiador para se manifestar sobre a prorrogação, em 2 (dois) dias, sob pena de nulidade do acordo."],"correta":1,"explicacao":"Gabarito: <strong>o fiador ficou desobrigado ao pagamento da obrigação em caso de inadimplemento, operando-se a extinção da fiança;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405236,"enunciado":"O Fundo Constitucional do Nordeste (FNE) tem seus recursos administrados pelo Banco do Nordeste do Brasil (BNB). Quanto a esse Fundo, analise as afirmativas a seguir: I. Na formulação dos programas de financiamento do FNE, será observada a proibição de aplicação de recursos a fundo perdido. II. Os planos regionais de desenvolvimento poderão estabelecer prioridades para fins de distribuição dos recursos entre os beneficiários do FNE. III. Os recursos do FNE devem ser aplicados no Nordeste, assim compreendido como a região abrangida pelos Estados do Maranhão, Piauí, Ceará, Rio Grande do Norte, Paraíba, Pernambuco, Alagoas, Sergipe e Bahia. Está(ão) correta(s) somente a(s) afirmativa(s):","opcoes":["I e II;","I e III;","II e III;","II;","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>I e II;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405237,"enunciado":"Num contrato bancário de concessão de crédito com garantia hipotecária de bem imóvel de propriedade do mutuário Cooperativa do Vale do Rio Pardo, cujo valor de avaliação é de R$4.590.000,00 (quatro milhões quinhentos e noventa mil reais), é imprescindível que:","opcoes":["seja lavrado instrumento particular de hipoteca, tendo em vista que o devedor é uma cooperativa e o elevado valor do imóvel;","seja lavrada escritura pública de hipoteca, tendo em vista o valor do imóvel e o negócio jurídico ser constitutivo de garantia real;","as partes escolham previamente qual será o instrumento de constituição da hipoteca; sendo instrumento particular, deverá ser averbado no Registro de Títulos e Documentos;","seja lavrado instrumento particular de hipoteca, sob pena de nulidade por descumprimento da forma prescrita em lei para constituição de garantias reais;","as partes escolham previamente qual será o instrumento de constituição da hipoteca; sendo instrumento público, deverá ser lavrado pelo Registro Empresarial."],"correta":1,"explicacao":"Gabarito: <strong>seja lavrada escritura pública de hipoteca, tendo em vista o valor do imóvel e o negócio jurídico ser constitutivo de garantia real;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":405238,"enunciado":"Simão Dias depositou em sua conta corrente um cheque emitido por Tobias Barreto no valor de R$ 2.590,00 (dois mil quinhentos e noventa reais). No verso do cheque, o tomador realizou um endosso em favor do sacado. Em conformidade com as normas legais referentes ao cheque, é correto afirmar que:","opcoes":["o sacado não poderá efetuar a compensação desse cheque porque o endosso ao sacado é nulo;","o sacado torna-se coobrigado pelo pagamento do cheque, respondendo solidariamente com o emitente;","com o endosso ao sacado, o emitente está se exonerando da garantia em caso de não pagamento do cheque;","o sacado não poderá efetuar a compensação deste cheque porque ele não pode figurar como endossatário;","o endosso ao sacado vale apenas como quitação, não podendo o cheque ser transferido por novo endosso."],"correta":4,"explicacao":"Gabarito: <strong>o endosso ao sacado vale apenas como quitação, não podendo o cheque ser transferido por novo endosso.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":424835,"enunciado":"Risco de Compliance pode se definido como:","opcoes":["perda financeira e queda no nível de produção que um banco pode sofrer como resultado da falha no cumprimento da aplicação dos acordos feitos comos sindicatos e comos funcionários.","diminuição do market share, perda financeira ou de reputação que um banco pode sofrer como resultado da falha no cumprimento da aplicação dos acordos feitos comos clientes e parceiros","risco de sanções legais ou regulatórias por ferir o código de conduta e das Boas Práticas Bancárias e o código de éticas dos funcionários, com consequente perda financeira e quebra de confiança.","risco de sanções regulatórias, de perda financeira ou de reputação que um banco pode sofrer como resultado da falha no cumprimento da aplicação de regulamentos, do código de conduta e das Boas Práticas Bancárias.","risco de sanções legais ou regulatórias, de perda financeira ou de reputação que um banco pode sofrer como resultado da falha no cumprimento da aplicação de leis, regulamentos, código de conduta e das Boas Práticas Bancárias."],"correta":4,"explicacao":"Gabarito: <strong>risco de sanções legais ou regulatórias, de perda financeira ou de reputação que um banco pode sofrer como resultado da falha no cumprimento da aplicação de leis, regulamentos, código de conduta e das Boas Práticas Bancárias.</strong>.","banca":"FUNCAB","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":446298,"enunciado":"O gerente de uma empresa (A) solicita à sua secretária que realize uma transferência de R$ 5.000,00 para a empresa (B). O gerente ressalta que o valor deve estar disponível na conta B no mesmo dia. Conhecendo os trâmites bancários e os serviços eletrônicos, sua secretária deve:","opcoes":["realizar o depósito na boca do caixa em dinheiro.","realizar o depósito via cheque ao portador.","transferir o dinheiro via DOC.","transferir o dinheiro via TED.","depositar o dinheiro ou cheque em caixa eletrônico."],"correta":3,"explicacao":"Gabarito: <strong>transferir o dinheiro via TED.</strong>.","banca":"Quadrix","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":446310,"enunciado":"O gerente de uma empresa, ao repor o mobiliário, adquirir novos equipamentos e renovar a frota de veículos, poderá solicitar um financiamento tendo como base linhas de crédito para:","opcoes":["capital de giro.","investimento fixo.","investimento misto.","hipoteca menor.","fiança."],"correta":1,"explicacao":"Gabarito: <strong>investimento fixo.</strong>.","banca":"Quadrix","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":452291,"enunciado":"Os bancos são instituições financeiras que têm como atividade básica receber do público, sob a forma de depósitos ou sob outras formas, fundos que serão empregados em operações de desconto, de crédito ou aplicações financeiras. (Dicionário Internacional de Economia e Finanças - Bernard Yves. Editora Forense Universitária). Aponte a atividade vedada aos bancos.","opcoes":["A faculdade de ativar diversos meios para a concessão de créditos, seja por meio da transformação de depósitos à vista ou de poupança líquida em empréstimos.","A possibilidade, para os bancos, de criar moeda escritural.","Conceder empréstimos ou adiantamentos a seus diretores e membros dos conselhos consultivo ou administrativo, fiscais e semelhantes, bem como aos respectivos cônjuges.","Adquirir bens imóveis destinados ao próprio uso.","Serviços de cobrança e desconto de duplicadas."],"correta":2,"explicacao":"Gabarito: <strong>Conceder empréstimos ou adiantamentos a seus diretores e membros dos conselhos consultivo ou administrativo, fiscais e semelhantes, bem como aos respectivos cônjuges.</strong>.","banca":"Quadrix","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472174,"enunciado":"No que se refere à estrutura, à regulação e à fiscalização do Sistema Financeiro Nacional, bem como à sua evolução recente, julgue o item a seguir.\n\nOs títulos cambiais de emissão de instituições financeiras, caso distribuídos publicamente, devem ser subordinados às normas e condições estabelecidas pela comissão de valores mobiliários.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472175,"enunciado":"No que se refere à estrutura, à regulação e à fiscalização do Sistema Financeiro Nacional, bem como à sua evolução recente, julgue o item a seguir.\n\nO Conselho de Recursos do Sistema Financeiro Nacional, instituído no âmbito do Plano Real, passou a deter a competência, antes atribuída ao Conselho Monetário Nacional, para julgar recursos contra decisões do Banco Central do Brasil, relativas à aplicação de penalidades por infrações à legislação cambial, de capitais estrangeiros e de crédito rural e industrial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472176,"enunciado":"No que se refere à estrutura, à regulação e à fiscalização do Sistema Financeiro Nacional, bem como à sua evolução recente, julgue o item a seguir.\n\nCompete ao Conselho Monetário Nacional estabelecer as diretrizes de aplicação dos recursos garantidores dos planos administrados pelas entidades fechadas de previdência complementar.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472177,"enunciado":"Em relação às operações ativas e passivas das instituições financeiras, julgue o item que se segue.\n\nÉ vedada às instituições financeiras a aquisição de títulos e valores mobiliários emitidos por empresas em que participem, direta ou indiretamente, com 10% ou mais do capital social, exceto quando se tratar da aquisição de debêntures de emissão de sociedade de arrendamento mercantil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472178,"enunciado":"Em relação às operações ativas e passivas das instituições financeiras, julgue o item que se segue.\n\nNa captação de recursos para realização de operações ativas vinculadas, é vedada a prestação de qualquer tipo de garantia pela instituição financeira contratante, postergando-se todos os pagamentos ao credor, inclusive a título de encargos ou amortização, em caso de inadimplemento da operação ativa à qual se vincula a captação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472179,"enunciado":"Julgue o item subsequente considerando a legislação relativa ao Sistema Financeiro da Habitação (SFH) e ao Sistema Financeiro Imobiliário (SFI).\n\nNo financiamento imobiliário garantido pela alienação fiduciária de coisa imóvel, o devedor segue, na esfera extrajudicial, com obrigações relativas à operação de crédito contratada, ainda que, no segundo leilão público do bem alienado fiduciariamente, o maior lance oferecido seja inferior ao valor da dívida.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472180,"enunciado":"Julgue o item subsequente considerando a legislação relativa ao Sistema Financeiro da Habitação (SFH) e ao Sistema Financeiro Imobiliário (SFI).\n\nNo âmbito do SFH, admite-se a contratação de financiamento habitacional com taxa efetiva de juros superior a 12% ao ano, caso o contrato não preveja a atualização do saldo devedor pela taxa referencial (TR) e o percentual que exceda àquela taxa efetiva respeite o limite máximo apurado de acordo com metodologia estabelecida pelo Conselho Monetário Nacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472181,"enunciado":"Como parte de ações voltadas à prevenção do superendividamento das famílias, o Banco Central do Brasil editou regras relacionadas ao pagamento das faturas de cartões de crédito. Acerca dessas regras, julgue o item seguinte.\n\nCom exceção das modalidades de cartões de crédito cujos contratos preveem a consignação da fatura diretamente em folha de pagamento, o valor mínimo da fatura de cartão de crédito, a ser pago a cada mês, deve corresponder a percentual não inferior a 15% do respectivo saldo mensal total.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472182,"enunciado":"Em relação aos sistemas de consórcio de bens, julgue o item abaixo.\n\nOs bancos múltiplos com carteira comercial podem atuar como administradores de consórcios de bens, desde que designem diretor responsável exclusivamente pela atividade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472183,"enunciado":"Considere um cliente que tenha contratado empréstimo pessoal no valor de R$ 5.000,00 e possua, na mesma instituição financeira, limite de cheque especial de R$ 3.000,00, estando em utilização apenas R$ 500,00; com base nessas informações, julgue o item a seguir.\n\nPara fins de prestação de informações ao Sistema de Informações de Créditos (SCR), a instituição financeira deve fornecer informações individualizadas apenas sobre a operação de empréstimo pessoal de R$ 5.000,00, com os dados sobre as demais exposições, inclusive o limite de crédito, devendo ser fornecidos de forma agregada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472185,"enunciado":"Suponha que o cliente de um banco múltiplo com carteira de arrendamento mercantil tenha adquirido letra de arrendamento mercantil (LAM) de valor nominal de R$ 250.000,00, não possuindo qualquer outro direito de crédito contra o banco emissor ou contra outra instituição do mesmo conglomerado econômico. Com base nessas informações, julgue o item abaixo.\n\nNa hipótese da liquidação extrajudicial do banco emissor, o cliente titular da LAM contará com garantia ordinária do Fundo Garantidor de Créditos pelo saldo total remanescente do título.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472186,"enunciado":"Em relação à legislação e à regulamentação que dispõem sobre a prevenção dos crimes de lavagem ou ocultação de bens, direitos e valores, julgue o item seguinte.\n\nAs instituições financeiras e demais instituições autorizadas a funcionar pelo Banco Central do Brasil (BCB) devem comunicar ao Conselho de Controle de Atividades Financeiras (COAF) as propostas de transferência de fundos contra pagamento em espécie, de valor igual ou superior a R$100.000,00.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472189,"enunciado":"No que concerne aos contratos de crédito, suas características, espécies e eficácia jurídica, julgue o item a seguir.\n\nNos mútuos bancários originados a partir de contratos de abertura de crédito, mesmo que não haja termo inicial para o cumprimento da obrigação de liquidar a dívida, é cabível a cobrança de juros moratórios pelo credor, constituindo-se a mora mediante interpelação judicial ou extrajudicial do devedor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472190,"enunciado":"No que concerne aos contratos de crédito, suas características, espécies e eficácia jurídica, julgue o item a seguir.\n\nO contrato de mútuo bancário é um contrato bilateral, uma vez que estabelece obrigações para o mutuante, de entregar o capital contratado, e para o mutuário, de restituir o capital emprestado, acrescido de juros, nos termos ajustados em contrato.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472191,"enunciado":"Em relação aos produtos e serviços bancários e suas características quanto a prazos, garantias, taxas e tarifas, julgue o item abaixo.\n\nA letra financeira com vencimento pactuado superior a trinta e seis meses pode ser resgatada antecipadamente pela instituição emissora, desde que decorridos ao menos vinte e quatro meses da data de emissão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472193,"enunciado":"Acerca dos instrumentos de política monetária e cambial, seus efeitos e características julgue o item seguinte.\n\nPara evitar as desvalorizações excessivas da moeda brasileira, o BCB pode vender dólares no mercado à vista ou vender contratos de swap cambial, assumindo posição passiva em dólares.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472195,"enunciado":"A respeito da Lei de Responsabilidade Fiscal (LRF) e de seus impactos sobre a atuação do BCB, julgue o próximo item.\n\nAo BCB é vedada, conforme dispõe a LFR, a aquisição de títulos públicos federais no mercado primário, exceto quando a operação objetivar o refinanciamento de dívida mobiliária federal vincenda em sua carteira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472196,"enunciado":"Em relação às modalidades de aplicação de investidor não residente nos mercados financeiro e de capitais, julgue o item a seguir.\n\nOs DR (depositary receipts) são certificados representativos de ações ou outros valores mobiliários que representem direitos a ações, emitidos no exterior por instituição depositária, com lastro em valores mobiliários depositados em custódia específica no Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472201,"enunciado":"Com relação ao mercado de capitais, julgue o item.\n\nA Lei da Reforma Bancária, de 1964, reestruturou o sistema financeiro nacional e, um ano depois, a Lei do Mercado de Capitais disciplinou esse mercado e estabeleceu as medidas necessárias para seu desenvolvimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472202,"enunciado":"Com relação ao mercado de capitais, julgue o item.\n\nDe acordo com a regulamentação vigente, o BCB é a entidade supervisora responsável por controlar o mercado de capitais, nclusive no que se refere à publicação de autorizações e circulares para seu funcionamento eficiente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472203,"enunciado":"Com relação ao mercado de capitais, julgue o item.\n\nAs bolsas de valores são sociedades anônimas que mantêm local e sistema adequados ao encontro de seus membros para realização de transações de compra e venda de títulos e valores mobiliários; tais sociedades não possuem, porém, autonomia financeira, patrimonial e administrativa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472204,"enunciado":"Com relação ao mercado de capitais, julgue o item.\n\nNo mercado de opções, a operação put-call-parity transforma operações de opções em operação de renda fixa e envolve uma operação de opção de compra, uma operação de opção de venda e uma operação no mercado à vista para o mesmo vencimento e com o mesmo número de contratos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472205,"enunciado":"Com relação ao mercado de capitais, julgue o item.\n\nA estratégia spread butterfly é operada de modo a se utilizar somente opções de compra, ou apenas opções de venda ou uma mistura de ambas. Sua finalidade única é especular para que o rendimento aumente sem a preocupação de se delimitar o risco do investidor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472206,"enunciado":"Acerca dos seguros privados e resseguros, julgue o item subsequente.\n\nOs seguros de dados contêm cláusulas contratuais que estabelecem as obrigações e direitos do segurado e do segurador. As condições contratuais podem agregar condições gerais, condições especiais e condições particulares.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472207,"enunciado":"Acerca dos seguros privados e resseguros, julgue o item subsequente.\n\nO mercado de seguros privados não permite que, após o dano, o segurado receba uma indenização com reposição integral do bem segurado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472208,"enunciado":"Acerca dos seguros privados e resseguros, julgue o item subsequente.\n\nResseguro é a operação pela qual uma seguradora se alivia de forma integral do risco de um seguro já feito, adquirindo novo seguro em outra seguradora.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472209,"enunciado":"Acerca dos seguros privados e resseguros, julgue o item subsequente.\n\nO contrato de seguro assume que existem direitos e obrigações de ambas as partes. Deve o segurado pagar o prêmio e o segurador arcar com as despesas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472210,"enunciado":"Acerca dos seguros privados e resseguros, julgue o item subsequente.\n\nNa grande variedade de seguros existentes, os seguros de danos à propriedade são representados pelos seguros de roubo e delito contra o patrimônio praticado por empregados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472211,"enunciado":"Acerca dos seguros privados e resseguros, julgue o item subsequente.\n\nOs seguros de pessoas garantem o pagamento de indenização ao segurado e seus beneficiários de acordo com as condições contratuais. Nessa categoria tem-se, como exemplo, o seguro funeral, o seguro educacional e o seguro desemprego.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472212,"enunciado":"Acerca dos seguros privados e resseguros, julgue o item subsequente.\n\nO seguro de garantia estendida procura complementar a garantia original de fábrica, mas não é aplicável aos contratos de compra e venda de bens de consumo duráveis.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472213,"enunciado":"No que tange a capitalização, previdência privada, loterias e sorteios, julgue o item seguinte.\n\nOs fundos de pensão podem ser organizados como fundação com fins lucrativos e são acessíveis, unicamente, aos empregados de uma empresa, grupo de empresas e aos servidores da União, dos estados, do Distrito Federal e dos municípios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472214,"enunciado":"No que tange a capitalização, previdência privada, loterias e sorteios, julgue o item seguinte.\n\nO objetivo da modalidade tradicional de títulos de capitalização consiste em se viabilizar a participação do titular em sorteios sem a necessidade de devolução ao titular do valor total pago.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472215,"enunciado":"No que tange a capitalização, previdência privada, loterias e sorteios, julgue o item seguinte.\n\nA sociedade de capitalização utiliza os resultados de loterias oficiais para a geração dos seus números sorteados ou realiza sorteios próprios com ampla divulgação aos titulares, prevendo livre acesso aos participantes e a presença obrigatória de auditores independentes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472216,"enunciado":"No que tange a capitalização, previdência privada, loterias e sorteios, julgue o item seguinte.\n\nUm título de capitalização deve, obrigatoriamente, prever sorteios, de modo que, quanto maiores forem os prêmios, menores serão as cotas de capitalização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472217,"enunciado":"No que tange a capitalização, previdência privada, loterias e sorteios, julgue o item seguinte.\n\nAs condições gerais do título de capitalização devem informar o critério de apuração dos números sorteados, além de definirem os múltiplos dos prêmios dos sorteios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":472218,"enunciado":"No que tange a capitalização, previdência privada, loterias e sorteios, julgue o item seguinte.\n\nO título de capitalização é o produto em que uma parte dos pagamentos efetuados pelo subscritor deve ser utilizada a fim de se formar capital.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":495804,"enunciado":"Controle de recibos e depósitos bancários, controle de débitos, elaboração e envio de recibos; envio de relação de devedores ao coordenador do setor; controle de contas a pagar; emissão e controle de cheques para pagamentos; enfim, monitoramento das finanças, é uma das atribuições do assistente administrativo do CREF-11. Sendo assim, é  importante ter conhecimento de que o prazo de bloqueio de cheque acolhido em depósito varia apenas em função do valor do cheque. Para liberação dos valores depositados, esse prazo é contado:","opcoes":["a partir do dia útil seguinte ao do depósito, sendo de: até dois dias úteis para cheques de valor inferior a R$ 300,00; um dia útil para cheques de valor igual ou superior a R$ 500,00.","a partir do dia seguinte ao do deposito, sendo de: até dois dias úteis para cheques de valor inferior a R$ 500,00; um dia útil para cheques de valor igual ou superior a R$ 300,00","a partir do mesmo dia do depósito, sendo de: até dois dias úteis para cheques de valor inferior a R$ 300,00; um dia útil para cheques de valor igual ou superior a R$ 300.00.","a partir do dia útil seguinte ao do depósito, sendo de: até dois dias úteis para cheques de valor inferior a R$ 300,00; um dia útil para cheques de valor igual ou superior a R$ 300,00.","a partir do mesmo dia do depósito, sendo de: até dois dias úteis para cheques de valor inferior a R$ 500,00; um dia útil para cheques de valor igual ou superior a R$ 300.00."],"correta":3,"explicacao":"Gabarito: <strong>a partir do dia útil seguinte ao do depósito, sendo de: até dois dias úteis para cheques de valor inferior a R$ 300,00; um dia útil para cheques de valor igual ou superior a R$ 300,00.</strong>.","banca":"Quadrix","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":504072,"enunciado":"A empresa Correios e Telégrafos, responsável pelo serviço postal brasileiro, oferece diferentes tipos de produtos no tocante ao envio de cartas, encomendas, documentos, mensagens, entre outros. O serviço de transferência de dinheiro por meio eletrônico recebe o nome de:","opcoes":["Sistema de Postagem Eletrônica.","Encomenda Expressa.","SEDEX10.","Vale Postal Eletrônico.","PAC Eletrônico."],"correta":2,"explicacao":"Gabarito: <strong>SEDEX10.</strong>.","banca":"Quadrix","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":504073,"enunciado":"O cheque é uma ordem de pagamento à vista. Pode ser recebido diretamente na agência em que o emitente mantém conta ou depositado em outra agência, para ser compensado e creditado na conta do correntista. A compensação de cheques é considerada \"serviço essencial\" e não pode ser cobrada pela instituição financeira. Sobre as formas de emissão, assinale a alternativa correta.","opcoes":["O cheque só pode ser emitido ao portador (sem a indicação do beneficiário) até o valor de R$ 1.000,00.","A partir de R$ 1.000,00, o emitente é obrigado a indicar o nome do beneficiário (pessoa ou empresa a quem está efetuando o pagamento).","O cheque nominal só poderá ser pago pelo banco mediante identificação do beneficiário ou de pessoa por ele indicada no verso do cheque (endosso), ou ainda por meio do sistema de compensação, caso seja depositado.","O cheque ao portador não pode ser cruzado, com a colocação de dois traços paralelos, em sentido diagonal, na frente do documento. Esse procedimento só é aceito no cheque nominal.","O cheque especial é quando o banco concede, ao titular da conta, um limite de crédito para saque quando não dispuser de fundos. A solicitação e a liberação do cheque especial são feitas via caixa eletrônico."],"correta":0,"explicacao":"Gabarito: <strong>O cheque só pode ser emitido ao portador (sem a indicação do beneficiário) até o valor de R$ 1.000,00.</strong>.","banca":"Quadrix","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":511453,"enunciado":"Um cheque é uma ordem de pagamento à vista expedida contra um banco sobre fundos depositados na conta de um emitente para pagamento ao beneficiário do cheque. Pode ser recebido diretamente na agência onde o cliente mantém conta ou depositado em outra agência para ser compensado e creditado na conta do correntista. As seguintes afirmações estão corretas, exceto:","opcoes":["Tanto o cheque ao portador quanto o nominal podem ser cruzados com a colocação de dois traços paralelos em sentido diagonal na frente do documento. Nesse caso, só será pago por meio de depósito em conta corrente.","O cheque administrativo é o cheque emitido pelo próprio banco. Pode ser comprado pelo cliente em qualquer agência bancária. O banco o emite em nome de quem o cliente efetuará o pagamento.","O cheque especial é assim denominado porque o banco concedeu ao titular da conta um limite de crédito para saque quando não dispuser de fundos. O cheque especial é concedido ao cliente mediante contrato firmado previamente.","Um cheque pré-datado é aquele em que o emitente, no rodapé do cheque ou no verso, estabelece a data em que o mesmo deverá ser pago. Nesse caso o banco não poderá pagá-lo ou devolvê-lo por falta de fundos, se for apresentado para pagamento antes da data prevista.","O correntista com cheques perdidos, furtados ou extraviados deve comunicar a ocorrência o mais rapidamente possível e pedir o cancelamento se estavam em branco ou a sustação se já estavam preenchidos. As despesas de registro e de controle de cancelamento ou sustação dos cheques são de responsabilidade do correntista, que terá como garantia do banco o não acolhimento desses cheques."],"correta":3,"explicacao":"Gabarito: <strong>Um cheque pré-datado é aquele em que o emitente, no rodapé do cheque ou no verso, estabelece a data em que o mesmo deverá ser pago. Nesse caso o banco não poderá pagá-lo ou devolvê-lo por falta de fundos, se for apresentado para pagamento antes da data prevista.</strong>.","banca":"Quadrix","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":566991,"enunciado":"As instituições financeiras são obrigadas a divulgar, em local e formato visível ao público, nas suas dependências e nas respectivas páginas na internet: tabela com os serviços essenciais (os que não podem ser cobrados); tabela com os serviços prioritários; tabelas contendo informações sobre os pacotes padronizados; tabelas de demais serviços prestados pela instituição, inclusive pacotes de serviços; esclarecimento de que os valores das tarifas foram estabelecidos pela própria instituição; outras informações estabelecidas pela regulamentação em vigor. São exemplos de serviços prioritários: I. o fornecimento de 2ª via de cartão nos casos decorrentes de perda, roubo, furto, danificação e outros motivos não imputáveis à instituição emitente; II. exclusão do Cadastro de Emitentes de Cheques sem Fundos (CCF); III. emissão de cheque administrativo; IV. prestação de qualquer serviço por meios eletrônicos, no caso de contas cujos contratos prevejam utilizar exclusivamente meios eletrônicos; V. realização de consultas mediante utilização da internet. É correto o que se afirma em:","opcoes":["I, II e IV, somente.","I, IV e V, somente.","III, IV e V, somente.","I, II e III, somente.","todos."],"correta":3,"explicacao":"Gabarito: <strong>I, II e III, somente.</strong>.","banca":"Quadrix","ano":2015,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":567040,"enunciado":"As letras de crédito imobiliário serão emitidas","opcoes":["sob forma nominativa, podendo ser transferidas mediante endosso em branco.","sob forma nominativa, podendo ser transferidas apenas mediante endosso em preto.","sob forma nominativa ou ao portador.","sob forma nominativa, sendo intransferíveis."],"correta":1,"explicacao":"Gabarito: <strong>sob forma nominativa, podendo ser transferidas apenas mediante endosso em preto.</strong>.","banca":"FAURGS","ano":2015,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":576971,"enunciado":"As operações bancárias estão diretamente ligadas às transações comerciais e administrativas de qualquer instituição que se utilize desses serviços. O empréstimo mediante caução de duplicatas é um exemplo de operação bancária. Nesse caso, o banco exige:","opcoes":["títulos de capitalização.","pagamento parcelado dos encargos financeiros, sendo estipulado um prazo de 6 (seis) meses para o pagamento total.","pagamento total em, no máximo, 1 (um) ano.","transferência de aplicações financeiras ou títulos imobiliários ou, ainda, imóveis hipotecados.","transferência da posse e da propriedade dos títulos."],"correta":4,"explicacao":"Gabarito: <strong>transferência da posse e da propriedade dos títulos.</strong>.","banca":"Quadrix","ano":2015,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":670945,"enunciado":"A regulamentação atualmente em vigor classifica em quatro modalidades os tipos de serviços prestados às pessoas físicas pelas instituições financeiras e demais instituições autorizadas a funcionar pelo Banco Central: serviços essenciais, serviços prioritários, serviços especiais e serviços diferenciados. A emissão de um cheque administrativo é um:","opcoes":["serviço essencial.","serviço prioritário.","serviço diferenciado.","serviço especial.","serviço essencial ou diferenciado, podendo este último ser cobrado pelo banco desde que explicitadas ao cliente ou ao usuário as condições de utilização e de pagamento."],"correta":0,"explicacao":"Gabarito: <strong>serviço essencial.</strong>.","banca":"Quadrix","ano":2016,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":677722,"enunciado":"Operações bancárias são rotineiras no setor administrativo de qualquer instituição. O Banco Central executa a política cambial definida pelo Conselho Monetário Nacional. Para tanto, regulamenta o mercado de câmbio e autoriza as instituições que nele operam. Leia as afirmativas seguintes. I. A posição de câmbio comprada é o saldo em moeda estrangeira registrado em nome de uma instituição autorizada que tenha efetuado vendas, prontas ou para liquidação futura, de moeda estrangeira, de títulos e documentos que as representem e de ouroinstrumento cambial, em valores superiores às compras. II. A operação de câmbio (compra ou venda) pronta é a operação a ser liquidada em até três dias úteis da data de contratação. III. A operação de câmbio (compra ou venda) para liquidação futura é a operação a ser liquidada em prazo maior que dois dias. Pode-se afirmar que:","opcoes":["somente I está correta.","somente II está correta.","somente III está correta.","há apenas duas afirmativas corretas.","todas estão corretas."],"correta":2,"explicacao":"Gabarito: <strong>somente III está correta.</strong>.","banca":"Quadrix","ano":2016,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":730628,"enunciado":"Os bancos são instituições, privadas ou públicas, que fornecem serviços financeiros à sociedade. O dinheiro depositado dos clientes (pessoas físicas, empresas, indústrias e/ou governo) é utilizado pelos bancos para conceder empréstimos a outros clientes, cobrando juros e tarifas, pela prestação dos serviços oferecidos. São instituições essenciais à circulação do dinheiro porque, além de oferecer serviços financeiros, facilitam transações de pagamento e oferecem crédito pessoal, ajudando no desenvolvimento do comércio nacional e internacional. Uma das formas de movimentação do dinheiro é por meio do cheque. Qual das opções apresentadas está incorreta?","opcoes":["O cheque pode ser emitido contra instituição industrial, ou comercial não financeira, valendo em qualquer caso como cheque.","O emitente deve ter fundos disponíveis em poder do sacado e estar autorizado a sobre eles emitir cheque, em virtude de contrato expresso ou tácito.","O cheque não admite aceite considerando-se não escrita qualquer declaração com esse sentido.","Pode o sacado, a pedido do emitente ou do portador legitimado, lançar e assinar, no verso do cheque não ao portador e ainda não endossado, visto, certificação ou outra declaração equivalente, datada e por quantia igual à indicada no título.","Feita a indicação da quantia em algarismos e por extenso, prevalece esta no caso de divergência. Indicada a quantia mais de uma vez, quer por extenso, quer por algarismos, prevalece, em caso de divergência, a indicação da menor quantia."],"correta":4,"explicacao":"Gabarito: <strong>Feita a indicação da quantia em algarismos e por extenso, prevalece esta no caso de divergência. Indicada a quantia mais de uma vez, quer por extenso, quer por algarismos, prevalece, em caso de divergência, a indicação da menor quantia.</strong>.","banca":"Quadrix","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":751940,"enunciado":"O Banco Nacional de Desenvolvimento Econômico e Social (BNDES) é uma importante instituição federal de financiamento de longo prazo. O banco vem prestando, ao longo de mais de seis décadas, relevante serviço de apoio ao desenvolvimento nacional, marcadamente nos setores de infraestrutura e energia. Um recente exemplo no estado de Minas Gerais foi o apoio do BNDES à instalação da fábrica das Havaianas. Contudo, o banco vem sendo criticado pelos excessos na política de apoio aos “campeões nacionais”. De acordo com essa política, o BNDES apoia grandes empresas brasileiras a se tornarem grandes multinacionais. Ao apoiar essas empresas em suas atividades no mercado internacional, a alternativa abaixo que melhor descreve a atividade desempenhada pelo BNDES é:","opcoes":["financiar e apoiar estudos técnicos, inclusive não reembolsáveis, que promovam o desenvolvimento econômico e social do país ou sua integração à América Latina;","promover a aplicação de recursos vinculados ao PIS-PASEP, ao Fundo da Marinha Mercante (FMM) e a outros fundos especiais instituídos pelo Poder Público;","financiar e fomentar a exportação de produtos e de serviços, inclusive de instalação, compreendidas as despesas realizadas no exterior, associadas à exportação;","apoiar e fomentar a criação de distritos industriais que promovem o desenvolvimento local e sua integração com o plano nacional de desenvolvimento;","fomentar e financiar a entrada no Brasil de empresas multinacionais que promovem a absorção de novas tecnologias e a criação de centros de pesquisa."],"correta":2,"explicacao":"Gabarito: <strong>financiar e fomentar a exportação de produtos e de serviços, inclusive de instalação, compreendidas as despesas realizadas no exterior, associadas à exportação;</strong>.","banca":"FGV","ano":2015,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":751942,"enunciado":"O FINAME – Financiamento de máquinas e equipamentos – é uma importante fonte de financiamento de longo prazo (em torno de cinco anos). Dentre as modalidades de apoio, encontram-se:","opcoes":["financiamento ao setor de atividade bancária; financiamento à compradora para a aquisição; financiamento ao fabricante para a produção;","financiamento ao setor de jogos de prognósticos; financiamento ao fabricante para a comercialização; financiamento à compradora para a aquisição;","financiamento à compradora para a aquisição; financiamento ao fabricante para a produção; financiamento ao setor de motéis, saunas e termas;","financiamento ao fabricante para a produção; financiamento ao fabricante para a comercialização; financiamento ao comércio de armas;","financiamento à compradora para a aquisição; financiamento ao fabricante para a produção; financiamento ao fabricante para a comercialização."],"correta":4,"explicacao":"Gabarito: <strong>financiamento à compradora para a aquisição; financiamento ao fabricante para a produção; financiamento ao fabricante para a comercialização.</strong>.","banca":"FGV","ano":2015,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":791569,"enunciado":"O segmento que supre as necessidades de recursos de médio e de longo prazo, principalmente com vistas à realização de investimentos de capital, e que comercializa títulos como os commercial papers e as debêntures é denominado:","opcoes":["Mercado monetário.","Mercado de capitais.","Mercado cambial.","Mercado de crédito."],"correta":1,"explicacao":"Gabarito: <strong>Mercado de capitais.</strong>.","banca":"IESES","ano":2017,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":799706,"enunciado":"O Comunicado 25.164/2014 enumera os sistemas de compensação e de liquidação, depósito centralizado e registro de ativos financeiros e de valores mobiliários que atualmente integram o Sistema de Pagamentos Brasileiro. Temos no primeiro grupo os sistemas de transferência de fundos e num segundo grupo os sistemas de liquidação de operações com títulos, valores mobiliários, derivativos e câmbio. Assinale a alternativa que NÃO pertence ao segundo grupo:","opcoes":["Sistema Especial de Liquidação e de Custódia (Selic).","Central de Cessão de Crédito (C3) da Câmara Interbancária de Pagamentos (CIP).","Câmara de Registro, Compensação e Liquidação de Ativos da BM&FBovespa.","Sistema de Transferência de Fundos (Sitraf)."],"correta":2,"explicacao":"Gabarito: <strong>Câmara de Registro, Compensação e Liquidação de Ativos da BM&FBovespa.</strong>.","banca":"IESES","ano":2017,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":841414,"enunciado":"São identificados diferentes regimes no mercado cambial, que sofrem influências singulares de origem, em que se despontam a oferta e a demanda, além da política econômica usada como instrumento pela autoridade monetária, a exemplo do Banco Central do Brasil. Com base nesses regimes, marque V para as afirmativas verdadeiras e F para as falsas. ( ) No regime de câmbio flutuante, a oferta de moeda estrangeira tem suporte nas divisas recebidas pelos exportadores. ( ) No regime de câmbio fixo ou misto, a política de intervenção da autoridade monetária, mediante adoção de “banda cambial”, por exemplo, independe de suporte de reservas cambiais. ( ) No regime de câmbio flutuante, quanto maior a taxa real de câmbio, maior a demanda por moeda estrangeira. ( ) No regime de câmbio flutuante, quanto menor a taxa real de câmbio, maior a motivação para a demanda por moeda estrangeira. Assinale a sequência correta.","opcoes":["V, F, F, V","V, V, F, F","F, V, F, V","F, F, V, V"],"correta":0,"explicacao":"Gabarito: <strong>V, F, F, V</strong>.","banca":"IF-MT","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":878213,"enunciado":"Se uma instituição financeira antecipar a determinado cliente o valor de crédito não vencido desse cliente contra terceiro e receber o crédito em cessão, então, essa situação configura","opcoes":["o mútuo bancário.","a faturização.","o desconto bancário.","o depósito bancário.","a abertura de crédito."],"correta":0,"explicacao":"Gabarito: <strong>o mútuo bancário.</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":879389,"enunciado":"Com relação à transação bancária denominada TED, é correto afirmar que se trata de","opcoes":["uma operação de antecipação de recebíveis.","um nome dado a certa taxa cobrada pelos bancos para a abertura de crédito.","uma transferência de valores de um banco para o outro, na qual o valor transferido é creditado na conta do favorecido no dia seguinte ao da transferência.","uma operação de crédito de curtíssimo prazo.","uma transferência de valores de um banco para o outro, na qual o valor transferido é creditado na conta do favorecido no mesmo dia."],"correta":4,"explicacao":"Gabarito: <strong>uma transferência de valores de um banco para o outro, na qual o valor transferido é creditado na conta do favorecido no mesmo dia.</strong>.","banca":"IADES","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890984,"enunciado":"Somente pessoas físicas podem participar e todos possuem responsabilidade ilimitada e solidária perante as obrigações assumidas pela empresa. Ou seja, cada sócio responde ilimitadamente e isoladamente por qualquer obrigação social da empresa, mesmo que o montante do capital exceda o valor do capital social. Essas características referem-se a(à)","opcoes":["sociedades anônimas.","sociedades por quotas de responsabilidade limitada.","firma individual.","sociedades em nome coletivo.","sociedade em comandita simples."],"correta":3,"explicacao":"Gabarito: <strong>sociedades em nome coletivo.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890987,"enunciado":"As Sociedades Anônimas podem ser classificadas em abertas e fechadas. Pode-se dizer que são características das Sociedades Anônimas Fechadas","opcoes":["negociação em bolsas de valores ou mercado de balcão organizado e concentração do capital na mão de poucos acionistas.","negociação em bolsas de valores ou mercado de balcão organizado e divisão do capital entre muitos sócios.","negociação no balcão das empresas, sem garantia e divisão do capital entre muitos sócios.","negociação no balcão das empresas, sem garantia e cumprimento de várias normas exigidas pelo agente regulador.","concentração do capital na mão de poucos acionistas e negociação no balcão das empresas, sem garantia."],"correta":4,"explicacao":"Gabarito: <strong>concentração do capital na mão de poucos acionistas e negociação no balcão das empresas, sem garantia.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890988,"enunciado":"O Mercado Secundário é onde ocorre a negociação contínua dos papéis (ações) emitidos no passado. Sendo assim, um investidor que queira operar nesse mercado deve","opcoes":["pedir autorização para Comissão de Valores Mobiliários (CVM).","dirigir-se a uma sociedade corretora membro de uma bolsa de valores, na qual receberá orientações e esclarecimentos na seleção dos investimentos.","procurar um banco, uma corretora ou uma distribuidora de valores mobiliários, que participem do lançamento das ações pretendidas.","solicitar autorização no Banco Central do Brasil, o qual é o responsável pela gestão financeira do mercado de capitais brasileiro.","entrar em contato direto com a empresa da qual tenha interesse em adquirir ações."],"correta":1,"explicacao":"Gabarito: <strong>dirigir-se a uma sociedade corretora membro de uma bolsa de valores, na qual receberá orientações e esclarecimentos na seleção dos investimentos.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890989,"enunciado":"Considerado um serviço de intermediação que permite ao consumidor adquirir bens e serviços em estabelecimentos comerciais previamente credenciados, mediante a comprovação de sua condição de usuário. Essas características referem-se ao","opcoes":["Crédito Rotativo.","Crédito Direto ao Consumidor.","empréstimo em consignação.","Mobile Bank.","Cartão de Crédito."],"correta":4,"explicacao":"Gabarito: <strong>Cartão de Crédito.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890990,"enunciado":"Refere-se a uma operação de crédito bancário com um valor limite. Normalmente é movimentada pelo cliente através de seus cheques, desde que não haja saldo disponível em sua conta corrente de movimentação. À medida que entram recursos na conta corrente do cliente, eles são usados para cobrir o saldo devedor. Essas características dizem respeito ao(às)","opcoes":["Hot Money.","Crédito Rotativo.","Contas Garantidas.","Banco Virtual.","transferências automáticas de fundos."],"correta":2,"explicacao":"Gabarito: <strong>Contas Garantidas.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890991,"enunciado":"A conta poupança é um tipo de conta bancária considerada de baixo risco. Em relação à caderneta de poupança, é correto afirmar que","opcoes":["a remuneração da aplicação é mensal e não há incidência de imposto de renda (IR) sobre ganhos de capital para pessoas físicas e jurídicas sem fins lucrativos.","a remuneração é mensal e há incidência do imposto de renda (IR) para pessoas jurídicas com fins lucrativos.","a remuneração da aplicação é mensal e há incidência de imposto de renda (IR) sobre ganhos de capital para pessoas físicas e jurídicas sem fins lucrativos.","a caderneta recebe depósitos tanto de pessoas físicas quanto de pessoas jurídicas, sendo que sua abertura deve ser feita somente no quinto dia útil de cada mês.","a remuneração da aplicação é diária e não há incidência de imposto de renda (IR) sobre ganhos de capital para pessoas físicas e jurídicas sem fins lucrativos."],"correta":0,"explicacao":"Gabarito: <strong>a remuneração da aplicação é mensal e não há incidência de imposto de renda (IR) sobre ganhos de capital para pessoas físicas e jurídicas sem fins lucrativos.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890992,"enunciado":"Em relação aos elementos que fazem parte de um contrato de seguro, pode-se afirmar que:","opcoes":["a franquia é a importância que o segurado recebe em caso de sinistro.","a indenização refere-se à prestação paga pelo segurado.","o sinistro é o valor do prejuízo que fica a cargo do segurado.","a indenização refere-se à importância que o segurado recebe em caso de sinistro.","o prêmio refere-se à importância que o segurado recebe em caso de sinistro."],"correta":3,"explicacao":"Gabarito: <strong>a indenização refere-se à importância que o segurado recebe em caso de sinistro.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890993,"enunciado":"Em relação ao leasing financeiro e ao leasing operacional, é correto afirmar que","opcoes":["as contraprestações e demais pagamentos devidos pela arrendatária previstos em contrato no leasing financeiro são normalmente suficientes para que a arrendadora recupere o custo do bem arrendado durante o prazo contratual da operação.","as despesas de manutenção, assistência técnica e serviços correlatos à operacionalidade do bem arrendado são de responsabilidade da arrendatária no leasing operacional.","o leasing operacional, em geral, possibilita ao arrendatário adquirir o bem no final do contrato.","existe um intermediário entre o arrendador e o arrendatário no leasing operacional, que é a instituição financeira.","não há previsão de pagamento de valor residual garantido no leasing financeiro."],"correta":0,"explicacao":"Gabarito: <strong>as contraprestações e demais pagamentos devidos pela arrendatária previstos em contrato no leasing financeiro são normalmente suficientes para que a arrendadora recupere o custo do bem arrendado durante o prazo contratual da operação.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890994,"enunciado":"O Documento de Ordem de Crédito (DOC) e a Transferência Eletrônica Disponível (TED) são importantes formas de transferências de recursos operacionalizadas pelos bancos. Referente a esses dois tipos de transferências bancárias, é correto afirmar que","opcoes":["o TED é uma forma de transferência de recursos entre bancos para crédito no mesmo dia, e o valor mínimo para transação é de R$ 4.999,99.","o DOC é uma forma de transferência de recursos entre contas de bancos diferentes, e não existe valor mínimo nem máximo para transferência.","o crédito, na transferência por DOC, só é liberado na conta de destino no dia útil seguinte da data de efetivação, e não é possível realizar o estorno, porém, se forem detectados dados incorretos inseridos pelo emissor, o DOC pode ser devolvido.","o DOC é uma forma de transferência de recursos entre bancos para crédito no mesmo dia, e não existe mais valor mínimo para esse tipo de transferência.","o crédito, na transferência por TED, só é liberado na conta de destino no dia útil seguinte da data de efetivação, e não é possível realizar o estorno, porém, se forem detectados dados incorretos inseridos pelo emissor, o TED pode ser devolvido."],"correta":2,"explicacao":"Gabarito: <strong>o crédito, na transferência por DOC, só é liberado na conta de destino no dia útil seguinte da data de efetivação, e não é possível realizar o estorno, porém, se forem detectados dados incorretos inseridos pelo emissor, o DOC pode ser devolvido.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890995,"enunciado":"Diversos são os documentos comerciais e títulos de créditos que fazem parte das operações das instituições financeiras. Em relação a esses títulos e documentos, é correto afirmar que","opcoes":["nota promissória é um título de crédito formal e nominativo, emitido pelo vendedor com a mesma data, valor global e vencimento da fatura que lhe deu origem, e representa um direito de crédito do sacador (vendedor) contra o sacado (comprador).","duplicata é um título cambiário em que o emitente assume a obrigação direta e principal de pagar a soma constante no título ao respectivo beneficiário.","nota promissória é um documento fiscal, comprovante obrigatório da saída de mercadoria de um estabelecimento comercial ou industrial.","duplicata é um documento fiscal, comprovante obrigatório da saída de mercadoria de um estabelecimento comercial ou industrial.","fatura é o documento que comprova a existência de uma operação de compra e venda de mercadorias e produtos e nela podem ser incluídas várias notas fiscais."],"correta":4,"explicacao":"Gabarito: <strong>fatura é o documento que comprova a existência de uma operação de compra e venda de mercadorias e produtos e nela podem ser incluídas várias notas fiscais.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890996,"enunciado":"Quanto à rotina do processo de cobrança, pode-se dizer que uma ordem lógica seria:","opcoes":["primeiro, o banco credita o valor na conta do cliente (cedente); segundo, o banco emite os bloquetes aos sacados; terceiro, o sacado paga; e, finalmente, os títulos a serem cobrados são passados ao banco.","primeiro, os títulos a serem cobrados são passados ao banco; segundo, o banco emite os bloquetes aos sacados; terceiro, o sacado paga; e, finalmente, o banco credita o valor na conta do cliente (cedente).","primeiro, os títulos a serem cobrados são passados ao banco; segundo, o banco emite os bloquetes aos sacados; terceiro, o banco credita o valor na conta do cliente (cedente); e, finalmente, o sacado paga.","primeiro, os títulos a serem cobrados são passados ao banco; segundo, o banco credita o valor na conta do cliente (cedente); terceiro, o banco emite os bloquetes aos sacados; e, finalmente, o sacado paga.","primeiro, o banco credita o valor na conta do cliente (cedente); segundo, o banco emite os bloquetes aos sacados; terceiro, os títulos a serem cobrados são passados ao banco; e, finalmente, o sacado paga."],"correta":1,"explicacao":"Gabarito: <strong>primeiro, os títulos a serem cobrados são passados ao banco; segundo, o banco emite os bloquetes aos sacados; terceiro, o sacado paga; e, finalmente, o banco credita o valor na conta do cliente (cedente).</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890997,"enunciado":"Partindo-se do pressuposto de que cobrança bancária serve para aumentar o relacionamento instituição financeira x empresa (cliente) e que essa operação gera vantagens para ambos, pode-se afirmar que","opcoes":["o fluxo das cobranças bancárias permite aos bancos o aumento dos depósitos à vista pelos créditos das liquidações.","a cobrança bancária provoca nas empresas (clientes) o aumento das receitas pela cobrança de tarifas sobre os serviços prestados.","ainda existe risco de crédito nesse tipo de operação, apesar das diversas vantagens que promove para os bancos.","ainda existe dificuldade quanto ao crédito imediato dos títulos cobrados, apesar das diversas vantagens que promove para as empresas (clientes).","a cobrança bancária não possibilita à empresa (cliente) a garantia do processo de cobrança, quando necessário o protesto."],"correta":0,"explicacao":"Gabarito: <strong>o fluxo das cobranças bancárias permite aos bancos o aumento dos depósitos à vista pelos créditos das liquidações.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890998,"enunciado":"Ainda em relação ao Recibo de Depósito Bancário (RDB) e ao Certificado de Depósito Bancário (CDB), é correto afirmar que","opcoes":["os CDB e RDB são títulos de renda fixa que servem como captação de recursos dos bancos. Ambos são empréstimos que o banco faz para seus clientes e a rentabilidade vem dos juros pagos pelo cliente à instituição.","o RDB é um recibo que pode ser negociado a qualquer momento desde que seja entre correntistas do mesmo banco.","o CDB, por ser um depósito à vista, permite negociação do título antes do vencimento.","o RDB, por ser um depósito à vista, é inegociável e intransferível.","o CDB, por ser considerado um título de crédito, é negociável e pode ser endossável e vendido para outra pessoa."],"correta":4,"explicacao":"Gabarito: <strong>o CDB, por ser considerado um título de crédito, é negociável e pode ser endossável e vendido para outra pessoa.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":890999,"enunciado":"Em relação ao Recibo de Depósito Bancário (RDB) e ao Certificado de Depósito Bancário (CDB), é correto afirmar que","opcoes":["o RDB é considerado um depósito à vista enquanto o CDB é considerado um depósito a prazo.","o RDB é considerado um depósito a prazo enquanto o CDB é considerado um depósito à vista.","o RDB e o CDB são considerados depósitos à vista.","o RDB e o CDB são considerados depósitos a prazo.","o RDB e o CDB podem ser tanto depósitos à vista quanto depósitos a prazo."],"correta":3,"explicacao":"Gabarito: <strong>o RDB e o CDB são considerados depósitos a prazo.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891000,"enunciado":"As instituições financeiras podem receber depósitos à vista e depósitos a prazo. As instituições financeiras que não recebem depósitos à vista são","opcoes":["bancos comerciais e bancos cooperativos.","bancos comerciais e bancos de investimentos.","bancos de investimentos e bancos de desenvolvimento.","bancos de desenvolvimento e bancos comerciais.","bancos cooperativos e cooperativas de crédito."],"correta":2,"explicacao":"Gabarito: <strong>bancos de investimentos e bancos de desenvolvimento.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891001,"enunciado":"A previdência complementar proporciona um seguro previdenciário adicional ao trabalhador ou seu beneficiário, conforme a necessidade e vontade. Sobre isso, é correto afirmar que","opcoes":["existem três modelos de previdência privada no Brasil: a previdência aberta, a previdência fechada e a previdência privada mista, que envolve características da aberta e da fechada simultaneamente.","os planos, no modelo de previdência privada aberta, são oferecidos por bancos, entidades ou seguradoras, sendo fiscalizados pela Superintendência de Seguros Privados (SUSEP) e pela Superintendência Nacional de Previdência Complementar (PREVIC).","as entidades de previdência fechada funcionam como empresas administradoras da previdência, lucrando com esta atividade, ao cobrar taxas pelos serviços prestados.","o modelo de previdência privada mista é administrado por empresas e bancos e dele podem fazer parte funcionários de uma única empresa ou funcionários de empresas diferentes.","as entidades de previdência fechada, também chamadas de fundo de pensão, oferecem planos criados por empresas e voltados exclusivamente aos seus funcionários, não podendo ser oferecidos para quem não é funcionário daquela empresa."],"correta":4,"explicacao":"Gabarito: <strong>as entidades de previdência fechada, também chamadas de fundo de pensão, oferecem planos criados por empresas e voltados exclusivamente aos seus funcionários, não podendo ser oferecidos para quem não é funcionário daquela empresa.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891002,"enunciado":"Quanto aos conhecimentos referentes às Associações de Poupança e Empréstimo (APE), é correto afirmar que","opcoes":["é uma instituição criada para facilitar aos associados a aquisição da casa própria, bens de consumo e veículo próprio, além captar, incentivar e disseminar a poupança.","os associados podem participar da APE de duas formas básicas: ao adquirir financiamento imobiliário ou ao depositar seu dinheiro para formar poupança.","suas operações ativas são, além dos depósitos de poupança, constituídas de letras hipotecárias; repasses e refinanciamentos contraídos no País; empréstimos e financiamentos contraídos no exterior; letras de crédito imobiliário, letra financeira e depósitos interfinanceiros, já as operações passivas são, basicamente, direcionadas aos financiamentos imobiliários.","esse tipo de entidade, por ter característica de associação, em hipótese alguma pode distribuir dividendos da totalidade dos resultados líquidos a seus associados.","os depositantes dessas entidades são considerados acionistas da associação e, por isso, os recursos dos associados são classificados no passivo exigível e não no patrimônio líquido."],"correta":1,"explicacao":"Gabarito: <strong>os associados podem participar da APE de duas formas básicas: ao adquirir financiamento imobiliário ou ao depositar seu dinheiro para formar poupança.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891003,"enunciado":"A Central de Liquidação Financeira e de Custódia de Títulos (CETIP) foi criada pelas instituições financeiras em parceria com o Banco Central com o objetivo de garantir mais segurança e agilidade às operações do mercado financeiro nacional. Quanto às normas de segurança de sigilo adotadas pela CETIP, é correto afirmar que o participante tem acesso","opcoes":["somente às informações do vendedor, por questão de segurança.","somente às informações do comprador, por questão de segurança.","apenas às suas próprias operações, por questão de segurança.","a todas as informações que desejar conhecer, por questão de transparência.","somente às informações de caráter público e a suas próprias operações."],"correta":4,"explicacao":"Gabarito: <strong>somente às informações de caráter público e a suas próprias operações.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891004,"enunciado":"As bolsas de mercadorias e futuros (BM&F) são associações privadas civis, com objetivo de efetuar o registro, a compensação e a liquidação, física e financeira, das operações realizadas em pregão ou em sistema eletrônico. Quanto à regulamentação das BM&F, pode-se afirmar que são regulamentadas pela(pelo)","opcoes":["Comissão de Valores Mobiliários e pelo Banco Central do Brasil.","Comissão de Valores Mobiliários e pela Receita Federal do Brasil.","Banco Central do Brasil e pela Receita Federal do Brasil.","Banco Central do Brasil e pelo Banco do Brasil.","Comissão de Valores Mobiliários, pelo Banco Central do Brasil, pela Receita Federal do Brasil e pelo Banco do Brasil."],"correta":0,"explicacao":"Gabarito: <strong>Comissão de Valores Mobiliários e pelo Banco Central do Brasil.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891005,"enunciado":"Quantos às instituições financeiras públicas e privadas, é correto afirmar que","opcoes":["os bancos de investimento são instituições financeiras controladas pelos governos estaduais e têm como objetivo precípuo proporcionar o suprimento oportuno e adequado dos recursos necessários ao financiamento, a médio e a longo prazos, de programas e projetos que visem a promover o desenvolvimento econômico e social do respectivo Estado.","os bancos de desenvolvimento são instituições privadas especializadas em operações de participação societária de caráter temporário, de financiamento da atividade produtiva para suprimento de capital fixo e de giro e de administração de recursos de terceiros.","os bancos comerciais são instituições financeiras privadas ou públicas que têm como objetivo principal proporcionar suprimento de recursos necessários para financiar, a curto e a médio prazos, o comércio, a indústria, as empresas prestadoras de serviços, as pessoas físicas e terceiros em geral.","as cooperativas de crédito são instituições financeiras constituídas sob a forma de sociedades cooperativas, tendo por objeto a prestação de serviços financeiros aos associados, porém, por questões éticas, não podem ser dirigidas e controladas pelos próprios associados.","os bancos comerciais devem ser constituídos sob a forma de sociedade por quotas de responsabilidade limitada ou sociedade empresária e na sua denominação social deve constar a expressão \"Banco\"."],"correta":2,"explicacao":"Gabarito: <strong>os bancos comerciais são instituições financeiras privadas ou públicas que têm como objetivo principal proporcionar suprimento de recursos necessários para financiar, a curto e a médio prazos, o comércio, a indústria, as empresas prestadoras de serviços, as pessoas físicas e terceiros em geral.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891006,"enunciado":"O Sistema Financeiro Nacional encontra-se estruturado pelo Conselho Monetário Nacional, pelo Banco Central do Brasil, pelo Banco do Brasil, pelo Banco Nacional de Desenvolvimento Econômico e pelas demais instituições financeiras públicas e privadas. Nesse sentido, pode-se afirmar que","opcoes":["compete, privativamente ao Banco Central do Brasil e ao Banco do Brasil, a emissão de papel-moeda e moeda metálica, nas condições e nos limites autorizados pelo Conselho Monetário Nacional.","o Banco Nacional do Desenvolvimento Econômico opera como agente financeiro do Governo Federal e é o principal executor das políticas de crédito rural e industrial e de banco comercial do governo.","as demais instituições financeiras públicas e privadas são responsáveis pela política de investimentos a longo prazo do Governo Federal, necessários ao fortalecimento da empresa privada nacional.","o Banco Central do Brasil opera exclusivamente com instituições financeiras públicas e privadas, vedadas operações bancárias de qualquer natureza com outras pessoas de direito público ou privado, salvo as expressamente autorizadas por lei.","o Banco Nacional do Desenvolvimento Econômico tem a responsabilidade primordial de formular a política da moeda e do crédito, objetivando a estabilidade da moeda e o desenvolvimento econômico e social do País."],"correta":3,"explicacao":"Gabarito: <strong>o Banco Central do Brasil opera exclusivamente com instituições financeiras públicas e privadas, vedadas operações bancárias de qualquer natureza com outras pessoas de direito público ou privado, salvo as expressamente autorizadas por lei.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891008,"enunciado":"De acordo com a subdivisão do Sistema Financeiro Nacional (SFN) em entidades normativas, supervisoras e operacionais, pode-se afirmar que:","opcoes":["funcionam como entidades normativas: o Banco Central do Brasil (BCB), a Comissão de Valores Mobiliários (CVM), a Superintendência de Seguros Privados (SUSEP) e a Superintendência Nacional de Previdência Complementar (PREVIC).","funcionam como entidades supervisoras: o Conselho Monetário Nacional (CMN), o Conselho Nacional de Seguros Privados (CNSP) e o Conselho Nacional de Previdência Complementar (CNPC).","funcionam como entidades operacionais: Agências de Fomento, Associações de Poupança e Empréstimo, Bancos de Câmbio, Bancos de Desenvolvimento, Bancos de Investimento, Companhias Hipotecárias, Cooperativas Centrais de Crédito, Sociedades de Crédito, Financiamento e Investimento, Sociedades de Crédito Imobiliário e Sociedades de Crédito ao Microempreendedor.","funcionam como entidades supervisoras: entidades operadoras auxiliares, administradores de mercados organizados de valores mobiliários, como os de Bolsa, de Mercadorias e Futuros e de Balcão Organizado, as companhias seguradoras, as sociedades de capitalização, as entidades abertas de previdência complementar e os fundos de pensão.","funcionam como entidades operacionais o Banco Central do Brasil (BCB), a Comissão de Valores Mobiliários (CVM), a Superintendência de Seguros Privados (SUSEP) e a Superintendência Nacional de Previdência Complementar – PREVIC."],"correta":2,"explicacao":"Gabarito: <strong>funcionam como entidades operacionais: Agências de Fomento, Associações de Poupança e Empréstimo, Bancos de Câmbio, Bancos de Desenvolvimento, Bancos de Investimento, Companhias Hipotecárias, Cooperativas Centrais de Crédito, Sociedades de Crédito, Financiamento e Investimento, Sociedades de Crédito Imobiliário e Sociedades de Crédito ao Microempreendedor.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891399,"enunciado":"Em referência aos papéis exercidos pelo Copom e pela mesa de operações do mercado aberto do Banco Central do Brasil, com relação à taxa Selic, é estabelecido que:","opcoes":["a mesa de operações determina a meta para a Selic e o Copom é responsável por manter a taxa diária próxima da meta;","o Copom determina a meta para a Selic e é também responsável por manter a taxa diária próxima da meta;","o Copom determina a meta para a Selic e a mesa de operações é responsável por manter a taxa diária próxima da meta;","a mesa de operações determina a meta para a Selic e é também responsável por manter a taxa diária próxima da meta;","o Copom persegue uma meta estabelecida pelo Conselho Monetário Nacional (CMN)."],"correta":3,"explicacao":"Gabarito: <strong>a mesa de operações determina a meta para a Selic e é também responsável por manter a taxa diária próxima da meta;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891400,"enunciado":"A remuneração atual da caderneta de poupança possui um componente básico, baseado na taxa referencial (TR), e um adicional, dependente da política monetária corrente. O parâmetro de política monetária utilizado no cálculo é a:","opcoes":["taxa do CDI – Certificado de Depósito Interbancário;","meta da taxa Selic;","meta de inflação;","taxa Selic diária;","rentabilidade média das NTN-B’s."],"correta":1,"explicacao":"Gabarito: <strong>meta da taxa Selic;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891401,"enunciado":"A fiança bancária é uma operação tradicional no mercado brasileiro, em que um banco, por meio da “carta de fiança”, assume o papel de fiador de uma outra companhia numa operação comercial, concorrência pública ou de crédito. Do ponto de vista dos riscos envolvidos para as partes, há mitigação do risco:","opcoes":["de crédito envolvido entre o fiador (banco) e o afiançado (empresa);","de mercado envolvido entre a empresa afiançada e sua contraparte – um fornecedor, por exemplo;","operacional envolvido entre a empresa afiançada e sua contraparte – um fornecedor, por exemplo;","de crédito envolvido entre a empresa afiançada e sua contraparte – um fornecedor, por exemplo;","de mercado envolvido entre o fiador (banco) e o afiançado (empresa)."],"correta":0,"explicacao":"Gabarito: <strong>de crédito envolvido entre o fiador (banco) e o afiançado (empresa);</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891402,"enunciado":"Em 7 de fevereiro de 2018, o Copom reduziu a meta da taxa Selic para 6,75% ao ano. Em termos práticos, isso significa que a mesa de operações de mercado aberto do Banco Central deve atuar para que a Selic diária fique próxima dessa meta. Se a Selic diária estiver em 7% num certo dia, a mesa de operações do Banco Central deve:","opcoes":["comprar títulos públicos no mercado e mantê-los em sua carteira, até que a taxa diária atinja a meta de 6,75%;","vender títulos públicos de sua carteira no mercado, até que a taxa diária atinja a meta de 6,75%;","emitir títulos no mercado até que a taxa diária atinja a meta de 6,75%;","imprimir mais papel-moeda;","pleitear uma mudança no superávit primário."],"correta":0,"explicacao":"Gabarito: <strong>comprar títulos públicos no mercado e mantê-los em sua carteira, até que a taxa diária atinja a meta de 6,75%;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891403,"enunciado":"O mecanismo pelo qual a mesa de operações de mercado aberto do Banco Central persegue a meta da Selic definida pelo Copom é denominado “operações de mercado aberto”. Se num certo dia a mesa de operações vendeu títulos públicos que estavam na carteira do Banco Central - uma típica operação de mercado aberto - o efeito na economia seria:","opcoes":["uma contração na oferta de moeda e consequente diminuição da Selic diária;","um aumento na oferta de moeda e consequente aumento da Selic diária;","uma expansão da base monetária;","uma contração na oferta de moeda e consequente aumento da Selic diária;","um aumento na oferta de moeda e consequente diminuição da Selic diária."],"correta":3,"explicacao":"Gabarito: <strong>uma contração na oferta de moeda e consequente aumento da Selic diária;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891404,"enunciado":"O Fundo Garantidor de Créditos (FGC) é uma entidade privada, sem fins lucrativos, e que administra um mecanismo de proteção aos correntistas, poupadores e investidores. Sua função primordial é a recuperação dos depósitos ou créditos mantidos em instituição financeira, até determinado valor, em caso de:","opcoes":["fusão, cisão ou aquisição;","abertura de capital;","fechamento de capital;","oferta pública inicial;","intervenção, liquidação ou falência."],"correta":2,"explicacao":"Gabarito: <strong>fechamento de capital;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891405,"enunciado":"O cartão de crédito é um meio de pagamento que permite ao cliente pagar compras ou serviços até um limite de crédito previamente definido no contrato de uso do cartão. O ideal é que o cliente sempre pague suas faturas nas datas acordadas – o valor inteiro ou pelo menos um percentual do valor devido. Esse procedimento evita:","opcoes":["o cancelamento do cartão de crédito;","o cancelamento da conta-corrente do cliente;","a entrada no crédito rotativo;","a entrada no Sistema de Proteção ao Crédito (SPC);","um processo junto ao Banco Central."],"correta":4,"explicacao":"Gabarito: <strong>um processo junto ao Banco Central.</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891406,"enunciado":"O mercado de capitais é um sistema de distribuição de valores mobiliários que visa proporcionar liquidez aos títulos de emissão de empresas e viabilizar seu processo de capitalização. É constituído pelas bolsas, corretoras e outras instituições financeiras autorizadas, e seus produtos principais incluem:","opcoes":["certificados de depósitos bancários e letras financeiras;","títulos emitidos pelo Tesouro Nacional;","cartas de fiança e garantias;","empréstimos-ponte e financiamentos de projetos;","ações e debêntures."],"correta":2,"explicacao":"Gabarito: <strong>cartas de fiança e garantias;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891407,"enunciado":"Se a taxa de câmbio estiver num patamar muito baixo, por exemplo, R$ 2,00 por dólar americano, e o Banco Central desejar realizar uma intervenção para aproximar a taxa de R$ 3,00, é preciso que a instituição:","opcoes":["venda dólares no mercado de câmbio à vista;","venda dólares no mercado de câmbio futuro;","fique comprada num swap cambial reverso;","fique comprada num swap cambial tradicional;","realize a emissão de títulos cambiais no mercado."],"correta":1,"explicacao":"Gabarito: <strong>venda dólares no mercado de câmbio futuro;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891408,"enunciado":"O Banco Central possui autorização para realizar intervenções no mercado de câmbio e um dos instrumentos para tal consiste num acordo em que o Banco Central paga aos investidores os juros do período e recebe em troca a variação da taxa de câmbio. Trata-se da seguinte operação:","opcoes":["compra de dólar pronto;","venda de dólar pronto;","swap cambial reverso;","swap cambial;","venda futura de dólar."],"correta":3,"explicacao":"Gabarito: <strong>swap cambial;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891409,"enunciado":"Em 2008 foi constituído um sistema de normas pelas próprias instituições financeiras, com compromissos de conduta estabelecidos para que o mercado atue de forma ainda mais eficaz, clara e transparente, em benefício do consumidor e da sociedade. O comprometimento com as normas em questão é voluntário por parte das instituições financeiras brasileiras, sendo um exemplo de:","opcoes":["adequação ao acordo da Basileia;","cumprimento das resoluções do Banco Central;","supervisão bancária;","autorregulação bancária;","cumprimento das normas do mercado de capitais."],"correta":0,"explicacao":"Gabarito: <strong>adequação ao acordo da Basileia;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891410,"enunciado":"Será parte de seu trabalho no Banestes o atendimento a clientes com determinados perfis. Suponha que um cliente com certa disponibilidade de recursos e perfil mais conservador (mais avesso ao risco) lhe pergunte sobre a possibilidade de atingir a maior rentabilidade possível, líquida de imposto de renda, durante o próximo ano. Se as projeções do Banestes indicarem a Selic em 8%, a taxa do CDI em 8% e a TR (taxa referencial) em 3% para o próximo ano, você deve dizer ao cliente que é melhor:","opcoes":["investir em títulos do Tesouro Nacional que rendem a Selic;","aplicar num CDB 100% CDI emitido pelo próprio Banestes;","aplicar em letras financeiras se a rentabilidade projetada também for de 8%;","aplicar numa caderneta de poupança fornecida pelo próprio Banestes;","aplicar num CDB 100% Selic emitido pelo próprio Banestes."],"correta":3,"explicacao":"Gabarito: <strong>aplicar numa caderneta de poupança fornecida pelo próprio Banestes;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891411,"enunciado":"Acerca dos riscos ligados às chamadas criptomoedas ou moedas virtuais, o Banco Central do Brasil, em comunicado de novembro de 2017, alertou para questões relacionadas à conversibilidade e ao lastro de tais ativos, destacando que não é responsável por regular, autorizar ou supervisionar o seu uso. Assim, é correto afirmar que seu valor:","opcoes":["decorre da garantia de conversão em moedas soberanas;","decorre da emissão e garantia por conta de autoridades monetárias;","decorre de um lastro em ativos reais;","é associado ao tamanho da base monetária;","decorre exclusivamente da confiança conferida pelos indivíduos ao seu emissor."],"correta":4,"explicacao":"Gabarito: <strong>decorre exclusivamente da confiança conferida pelos indivíduos ao seu emissor.</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891412,"enunciado":"Recomenda-se que, antes de contratar uma operação de crédito, o consumidor pesquise as diversas opções disponíveis, pois as condições da operação podem variar de uma instituição para outra. Para facilitar a comparação entre as ofertas, o Conselho Monetário Nacional (CMN) determinou que as instituições financeiras e sociedades de arrendamento mercantil, antes da contratação da operação, divulguem ao consumidor:","opcoes":["a taxa de juros do contrato;","o custo efetivo total;","a taxa de juros do contrato e a projeção para o CDI;","a taxa de juros do contrato e a projeção para a Selic;","o spread cobrado e embutido na taxa de juros."],"correta":2,"explicacao":"Gabarito: <strong>a taxa de juros do contrato e a projeção para o CDI;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891414,"enunciado":"Alfredo contraiu uma dívida com o Banco X e assinou uma cédula de crédito bancário com o aval de João. Em relação ao aval, é correto afirmar que o avalista:","opcoes":["passa a ser o único responsável pelo pagamento, exonerando o avalizado Alfredo de responsabilidade;","responderá subsidiariamente pelo pagamento, na ausência de bens suficientes de Alfredo para pagar a dívida;","torna-se devedor solidário pelo pagamento perante o Banco X, podendo esse cobrar a dívida tanto dele quanto do avalizado;","não se obriga pelo pagamento porque é nulo aval prestado em favor de instituição financeira, caso do Banco X;","responderá pelo pagamento solidariamente com Alfredo, desde que esse celebre simultaneamente contrato de fiança com o Banco X."],"correta":4,"explicacao":"Gabarito: <strong>responderá pelo pagamento solidariamente com Alfredo, desde que esse celebre simultaneamente contrato de fiança com o Banco X.</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891415,"enunciado":"Em garantia de empréstimo concedido pelo Banco W, Tereza deu um imóvel de sua propriedade ao credor. A garantia constituída abrange todas as acessões, melhoramentos ou construções do imóvel e não impede a proprietária de aliená-lo. Com base nessas informações, a garantia prestada por Tereza é:","opcoes":["aval;","fiança bancária;","alienação fiduciária em garantia;","hipoteca;","anticrese."],"correta":2,"explicacao":"Gabarito: <strong>alienação fiduciária em garantia;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891416,"enunciado":"Uma das garantias ao cumprimento de um contrato celebrado no âmbito do Sistema de Financiamento Imobiliário (SFI) é a alienação fiduciária. Sobre o instituto e suas disposições legais, analise as afirmativas a seguir. I. Por meio da alienação fiduciária o devedor, ou fiduciante, com a finalidade de garantia, contrata a transferência ao credor, ou fiduciário, da propriedade resolúvel de bem imóvel. II. A alienação fiduciária poderá ser contratada por pessoa física ou jurídica, não sendo privativa das entidades que operam no SFI. III. Constitui-se a propriedade fiduciária de bem imóvel através do registro do contrato que lhe serve de título no competente Registro de Imóveis. Está correto o que se afirma em:","opcoes":["somente I;","somente II;","somente I e III;","somente II e III;","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>somente I e III;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891417,"enunciado":"Durante a vigência de um contrato de fiança, o credor Atílio concedeu prorrogação do prazo de pagamento da dívida (moratória) ao afiançado sem consentimento do fiador Jerônimo. Com esse ato por parte do credor, é correto afirmar que:","opcoes":["deverá Jerônimo requerer a Atílio prorrogação do prazo de duração do contrato para se adequar à moratória concedida ao afiançado;","Jerônimo, ainda que solidário pelo pagamento da dívida perante Atílio, ficará desobrigado pela falta de consentimento com a moratória;","Jerônimo permanecerá obrigado pelo pagamento da dívida pelos 6 meses seguintes ao dia do vencimento; findo tal prazo ficará desobrigado;","caberá a Atílio decidir se Jerônimo ficará ou não desobrigado da fiança com a concessão da moratória;","Jerônimo poderá pedir a anulação do contrato porque é proibido ao credor conceder moratória ao afiançado."],"correta":3,"explicacao":"Gabarito: <strong>caberá a Atílio decidir se Jerônimo ficará ou não desobrigado da fiança com a concessão da moratória;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891418,"enunciado":"Analise as três situações a seguir. I. Clara, para ocultar a utilização de bens provenientes de infração penal de receptação, os converte em ativos lícitos. II. Joana, para dissimular a utilização de bens provenientes de crime anterior praticado por terceiro, os adquire e, posteriormente, troca aqueles bens. III. Paloma oculta a origem de direitos provenientes indiretamente de infração penal de peculato. De acordo com as previsões do Art. 1º da Lei nº 9.613/98, é correto afirmar que configura(m) crime de “lavagem” ou ocultação de bens, direitos e valores, a(s) conduta(s) de:","opcoes":["Clara, Joana e Paloma;","Clara e Joana, apenas;","Clara, apenas;","Joana, apenas;","Paloma, apenas."],"correta":3,"explicacao":"Gabarito: <strong>Joana, apenas;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891419,"enunciado":"Em vendas, ao apresentar um produto bancário, o técnico bancário deve:","opcoes":["focar na necessidade do cliente;","deixar que o cliente controle a entrevista;","usar linguagem culta e sofisticada para causar boa impressão;","mostrar ao comprador o máximo de conhecimento técnico sobre o produto;","manter um clima de simpatia para que o cliente não faça objeções."],"correta":4,"explicacao":"Gabarito: <strong>manter um clima de simpatia para que o cliente não faça objeções.</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891420,"enunciado":"Todo atendimento passa por momentos da verdade, que são os contatos entre o cliente e as empresas. Esses contatos são preciosos porque:","opcoes":["são avaliados apenas nos primeiros momentos;","criam as condições para que as objeções sejam vencidas;","podem favorecer uma venda, se forem de boa qualidade;","são construídos unicamente pelos profissionais de atendimento;","podem ser uniformizados e replicados no momento da verdade."],"correta":1,"explicacao":"Gabarito: <strong>criam as condições para que as objeções sejam vencidas;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891421,"enunciado":"Em relação à política institucional de relacionamento com clientes e usuários, a Resolução BACEN nº 4.539, de 24 de novembro de 2016, estabelece que as instituições financeiras devem instituir mecanismos de acompanhamento, de controle e de mitigação de riscos, devendo os dados, os registros e as informações relativas aos mecanismos de controle, processos, testes e trilhas de auditoria serem mantidos à disposição do Banco Central do Brasil pelo prazo mínimo de:","opcoes":["1 ano;","2 anos;","3 anos;","4 anos;","5 anos."],"correta":4,"explicacao":"Gabarito: <strong>5 anos.</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891422,"enunciado":"Com relação à satisfação do cliente, pode-se dizer que é:","opcoes":["o fruto do julgamento do colaborador de atendimento;","o resultado da criação de uma expectativa alta;","o encantamento do cliente com o que ele recebeu do serviço;","o conjunto de percepções do serviço positivas e comuns aos clientes;","a relação entre o que o cliente percebeu do serviço e o que ele esperava."],"correta":2,"explicacao":"Gabarito: <strong>o encantamento do cliente com o que ele recebeu do serviço;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891423,"enunciado":"Para um cliente, o serviço tem valor se:","opcoes":["o preço for apropriado ao praticado no mercado;","o custo financeiro do serviço estiver dentro do seu orçamento;","os benefícios financeiros e emocionais forem percebidos como satisfatórios;","o somatório de benefícios for maior que os custos financeiros e emocionais;","o atendimento for à altura da satisfação financeira e emocional."],"correta":3,"explicacao":"Gabarito: <strong>o somatório de benefícios for maior que os custos financeiros e emocionais;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891424,"enunciado":"Uma ação que faz parte do mix de marketing, muito utilizada pelas organizações que prestam serviços, como é o caso das instituições bancárias, representada pela oferta de incentivos e vantagens para os clientes, e que visa a aumentar significativamente as vendas é a(o):","opcoes":["promoção;","publicidade;","propaganda;","merchandising;","posicionamento."],"correta":4,"explicacao":"Gabarito: <strong>posicionamento.</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891426,"enunciado":"A atividade de gestão de marketing de um banco lida com o ambiente externo e com o ambiente interno. São muitas as variáveis que interferem nos processos de negócios, sendo que diversas delas encontram-se fora do controle da empresa. Um exemplo de variável incontrolável pelo banco é:","opcoes":["o mix de marketing;","a localização das filiais;","o marketing institucional;","o site da empresa na internet;","a situação social, econômica e cultural do país."],"correta":0,"explicacao":"Gabarito: <strong>o mix de marketing;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891427,"enunciado":"Em vendas, o conhecimento dos produtos e serviços bancários é imprescindível, por permitir que:","opcoes":["o vendedor passe autoridade ao discorrer sobre o acúmulo de informações que ele detém;","o comprador perceba a profundidade do conhecimento do vendedor;","o vendedor mostre segurança e habilidade para responder objeções;","o comprador obtenha as informações técnicas que só o vendedor pode dar;","comprador e vendedor possam estar em equilíbrio com relação às informações."],"correta":0,"explicacao":"Gabarito: <strong>o vendedor passe autoridade ao discorrer sobre o acúmulo de informações que ele detém;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891428,"enunciado":"Os serviços diferem dos produtos por terem características próprias. Em razão das características dos serviços, o técnico bancário deve estar ciente de que:","opcoes":["o cliente não julgará os aspectos físicos e tangíveis;","o serviço não tem como ser experimentado antes da compra;","a participação do cliente na produção dos serviços deve ser voluntária;","a produção de um serviço é feita antecipadamente, permitindo que o serviço esteja armazenado;","o fornecimento de serviços é uniforme e sem variabilidade."],"correta":2,"explicacao":"Gabarito: <strong>a participação do cliente na produção dos serviços deve ser voluntária;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891454,"enunciado":"As casas lotéricas possuem autorização para receber pagamentos de contas de luz, água, telefone e, em alguns municípios, até certos tributos. Esse tipo de função, própria do setor bancário tradicional, só é possível por autorização:","opcoes":["do Ministério da Fazenda;","do Banco Central do Brasil;","da Comissão de Valores Mobiliários;","do Comitê de Política Monetária;","do Conselho Monetário Nacional."],"correta":4,"explicacao":"Gabarito: <strong>do Conselho Monetário Nacional.</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891516,"enunciado":"O acordo da Basileia tem sido um importante instrumento de regulação bancária prudencial, visando especialmente fazer frente ao risco do sistema financeiro mundial. Inicialmente, o Basileia I, divulgado em 1988, teve como objetivo criar exigências mínimas de capital para instituições financeiras como forma de fazer face ao risco de crédito. Em 2004, foi revisto e divulgado o Basileia II, com o objetivo de buscar uma medida mais precisa dos riscos incorridos pelos bancos internacionalmente ativos. A partir de 2010, os países passaram a implementar o Basileia III, como parte de um movimento contínuo de aprimoramento da estrutura prudencial aplicável às instituições financeiras. Sobre o Basileia III, analise as afirmativas a seguir. I. Procura reduzir o risco das variações dos preços dos títulos, e consequentemente o risco de mercado, mediante o controle das bolhas especulativas pelos Bancos Centrais. II. Busca ampliar a qualidade do capital regulatório, além de requerer montantes superiores de capital, principalmente das parcelas com maior capacidade de absorver perdas. III. Introduziu na regulação os pilares de definição do capital mínimo para bancar o risco de crédito, de mercado e operacional, aprimorou a supervisão bancária e estabeleceu regras para disciplina de mercado. IV. Visa ao aperfeiçoamento da capacidade das instituições financeiras absorverem choques provenientes do próprio sistema financeiro ou dos demais setores da economia, reduzindo o risco de transferência de crises financeiras para a economia real. Está correto somente o que se afirma em:","opcoes":["I e III;","I e IV;","II e III;","II e IV;","II, III e IV."],"correta":3,"explicacao":"Gabarito: <strong>II e IV;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":891678,"enunciado":"A respeito da contratação dos seguros, regulamentada pelo Decreto nº 60.459/67, em especial quanto ao início de vigência das apólices, o início de cobertura do risco constará da apólice e coincidirá com:","opcoes":["a aceitação da proposta;","o envio da proposta;","a data de vencimento do prêmio;","a data de pagamento do prêmio;","a data de sua emissão."],"correta":0,"explicacao":"Gabarito: <strong>a aceitação da proposta;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":892269,"enunciado":"O Sistema Financeiro Nacional (SFN) é dividido em segmentos especializados e um dos ramos de maior importância é o Mercado de Crédito, responsável por:","opcoes":["fornecer recursos para o consumo das pessoas em geral e para o funcionamento das empresas;","fornecer à economia papel-moeda e moeda escritural, aquela depositada em conta-corrente;","permitir às empresas em geral captar recursos de terceiros e, portanto, compartilhar os ganhos e os riscos;","facilitar a compra e a venda de moeda estrangeira;","permitir operações em mercados futuros."],"correta":0,"explicacao":"Gabarito: <strong>fornecer recursos para o consumo das pessoas em geral e para o funcionamento das empresas;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":892270,"enunciado":"Uma das entidades do Sistema Financeiro Nacional (SFN) é responsável pelo controle da inflação no país e também atua para garantir a estabilidade financeira do sistema e das instituições. Essa entidade é o Banco Central, também responsável por:","opcoes":["autorizar as ofertas públicas iniciais de empresas;","autorizar as emissões de debêntures;","controlar o fluxo de capitais estrangeiros no Brasil;","definir a meta de inflação no país;","definir o superávit primário."],"correta":2,"explicacao":"Gabarito: <strong>controlar o fluxo de capitais estrangeiros no Brasil;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":892271,"enunciado":"O Sistema Financeiro Nacional (SFN) possui órgãos normativos, supervisores e executores, com papéis bem definidos. A supervisão do mercado de capitais é responsabilidade:","opcoes":["do Conselho Monetário Nacional (CMN);","do Banco Central do Brasil;","da Bolsa de Valores;","do Ministério da Fazenda;","da Comissão de Valores Mobiliários (CVM)."],"correta":4,"explicacao":"Gabarito: <strong>da Comissão de Valores Mobiliários (CVM).</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":892272,"enunciado":"É competência do Comitê de Política Monetária – Copom a fixação:","opcoes":["da taxa do CDI;","da taxa Selic diária;","da meta para a taxa Selic;","da Taxa de Juros de Longo Prazo;","do superávit primário."],"correta":2,"explicacao":"Gabarito: <strong>da meta para a taxa Selic;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":892273,"enunciado":"Acerca do tratamento dado pelo Código de Conduta Ética do Sistema Financeiro Banestes (SFB) ao regime de presentes e outros benefícios recebidos pelos seus profissionais, analise as afirmativas a seguir. I. É dever do profissional do SFB recusar presentes, favores, promessas, valor em espécie, benefícios, serviços e materiais, de quem quer que seja, para si ou para terceiros, que possam representar benefício pessoal. II. É permitido ao profissional do SFB aceitar franquia na participação em eventos institucionais e refeições com objetivo estritamente comercial e relevante para os negócios do SFB, desde que não sejam frequentes, e, se possível, de promoção recíproca entre as partes. II. Caso o profissional do SFB receba presentes que excedam ao valor de R$ 100,00, deve informar, por escrito, e entregá-lo mediante recibo ao Conselho de Conduta Ética, para oportuna destinação a instituições filantrópicas, a critério dos servidores lotados no mesmo órgão administrativo do donatário. Está correto o que se afirma em:","opcoes":["somente II;","somente III;","somente I e II;","somente I e III;","I, II e III."],"correta":1,"explicacao":"Gabarito: <strong>somente III;</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":922226,"enunciado":"Os serviços possuem quatro características principais, que são: a imaterialidade ou intangibilidade, a inseparabilidade, a perecibilidade e a variabilidade dos produtos securitários com as suas respectivas premissas, que afetam a elaboração de programas de marketing pelas seguradoras. A opção que se mostra incompatível com a característica específica dos serviços mencionados é:","opcoes":["os seguros vendidos são intangíveis, pois não podem ser vistos, nem sentidos e nem ouvidos, sendo que a percepção de qualidade se faz pelas imagens tangíveis das instalações, funcionários e equipamentos da seguradora;","a característica da inseparabilidade na venda de seguros ocorre porque a pessoa encarregada de prestar o serviço é parte dele, e, na maioria das vezes, o cliente também está presente quando o serviço é executado, havendo a interação entre eles;","na área da prestação de serviços de assistência 24 horas, a variabilidade está presente, por exemplo, quando se solicita um reboque ou um chaveiro; pelo fato de dependerem de quem os fornece, de onde e quando serão fornecidos, tais serviços não são padronizados;","de forma diferenciada dos produtos tangíveis, os serviços de seguro não podem ser estocados e, portanto, se não forem realizados no momento adequado, perdem a finalidade, o que caracteriza a sua perecibilidade;","a imaterialidade dos serviços se evidencia quando um determinado serviço precisa ser realizado por um prestador específico, sendo o serviço produzido e consumido simultaneamente, inclusive com a participação ativa do cliente, o que pode vir a afetar os resultados."],"correta":4,"explicacao":"Gabarito: <strong>a imaterialidade dos serviços se evidencia quando um determinado serviço precisa ser realizado por um prestador específico, sendo o serviço produzido e consumido simultaneamente, inclusive com a participação ativa do cliente, o que pode vir a afetar os resultados.</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950796,"enunciado":"A respeito do Banco do Nordeste do Brasil S.A. (BNB), de programas de atuação que permitem a promoção do desenvolvimento da região Nordeste, do Fundo Constitucional de Financiamento do Nordeste (FNE) e do Fundo de Desenvolvimento do Nordeste (FDNE), julgue o item a seguir.\n\n\n\n\nPara efeito do Acordo de Basileia, o FNE é registrado como capital de terceiro no balanço do BNB.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950797,"enunciado":"A respeito do Banco do Nordeste do Brasil S.A. (BNB), de programas de atuação que permitem a promoção do desenvolvimento da região Nordeste, do Fundo Constitucional de Financiamento do Nordeste (FNE) e do Fundo de Desenvolvimento do Nordeste (FDNE), julgue o item a seguir.\n\n\n\n\nOs recursos do FNE podem ser direcionados para o financiamento estudantil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950798,"enunciado":"A respeito do Banco do Nordeste do Brasil S.A. (BNB), de programas de atuação que permitem a promoção do desenvolvimento da região Nordeste, do Fundo Constitucional de Financiamento do Nordeste (FNE) e do Fundo de Desenvolvimento do Nordeste (FDNE), julgue o item a seguir.\n\n\n\n\nPara financiamento de pessoa jurídica, o FNE cobra a taxa de juros SELIC acrescida da inflação medida pelo índice nacional de preços ao consumidor amplo (IPCA) e de spread bancário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950799,"enunciado":"A respeito do Banco do Nordeste do Brasil S.A. (BNB), de programas de atuação que permitem a promoção do desenvolvimento da região Nordeste, do Fundo Constitucional de Financiamento do Nordeste (FNE) e do Fundo de Desenvolvimento do Nordeste (FDNE), julgue o item a seguir.\n\n\n\n\nOs recursos do FDNE são aplicados exclusivamente para o desenvolvimento da região Nordeste.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950801,"enunciado":"No que se refere aos programas financiados pelo BNB, julgue o próximo item.\n\nOs recursos do FNE são destinados, principalmente, para o financiamento do setor de comércio e serviços.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950802,"enunciado":"No que se refere aos programas financiados pelo BNB, julgue o próximo item.\n\nOs resultados das operações de crédito e a expansão dos negócios têm assegurado consistente crescimento do índice de Basileia do BNB.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950803,"enunciado":"No que se refere aos programas financiados pelo BNB, julgue o próximo item.\n\nNo âmbito do programa da agricultura familiar, parte dos recursos financeiros é destinada a financiamentos na região semiárida.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950805,"enunciado":"No que se refere aos programas financiados pelo BNB, julgue o próximo item.\n\nOs recursos setoriais estabelecidos de acordo com as diretrizes da Superintendência do Desenvolvimento do Nordeste (SUDENE) podem ser utilizados para o financiamento da indústria de defesa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950819,"enunciado":"Julgue o item a seguir, relativos a riscos decorrentes do processo de concessão de crédito, com base na regulamentação em vigor.\n\nA possibilidade de perda associada ao decréscimo dos ganhos esperados provocado pela deterioração da qualidade creditícia do tomador do crédito é uma situação contemplada no conceito de risco de mercado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950820,"enunciado":"Julgue o item a seguir, relativos a riscos decorrentes do processo de concessão de crédito, com base na regulamentação em vigor.\n\nO risco legal associado à inadequação ou à deficiência em contratos firmados com clientes beneficiários de recursos faz parte do risco operacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950821,"enunciado":"Com relação ao Fundo Constitucional de Financiamento do Nordeste (FNE), julgue o próximo item.\n\nAs empresas instaladas em municípios do Espírito Santo e de Minas Gerais incluídos na área de atuação da Superintendência do Desenvolvimento do Nordeste (SUDENE) podem ser beneficiadas com os recursos do FNE.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950822,"enunciado":"Com relação ao Fundo Constitucional de Financiamento do Nordeste (FNE), julgue o próximo item.\n\nEntre as fontes de recursos do FNE incluem-se os financiamentos obtidos em entidades públicas ou privadas, nacionais ou estrangeiras, nos quais incide o imposto sobre operações de crédito, câmbio e seguro (IOF).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950823,"enunciado":"Com relação às operações de crédito realizadas pelas instituições financeiras, julgue o item subsequente.\n\nO crédito direto ao consumidor (CDC) é uma modalidade de financiamento destinada à aquisição de bens e serviços cujo beneficiário é o consumidor ou usuário final.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950825,"enunciado":"Com relação às operações de crédito realizadas pelas instituições financeiras, julgue o item subsequente.\n\nA operação de crédito rural destinada à aquisição de bens ou serviços que serão usufruídos em vários períodos de produção é classificada como uma operação de custeio.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950826,"enunciado":"Acerca de elementos e de requisitos relativos aos Cs de crédito (caráter, capacidade, capital, colateral e condições), julgue o item que se segue.\n\nO C de colateral diz respeito à capacidade de o cliente oferecer ativos que garantam à instituição financeira que lhe tenha concedido o crédito uma segurança adicional quanto ao retorno dos recursos emprestados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950827,"enunciado":"Acerca de elementos e de requisitos relativos aos Cs de crédito (caráter, capacidade, capital, colateral e condições), julgue o item que se segue.\n\nO C de capital representa exclusivamente o volume de recursos que o tomador do crédito mantém disponível em caixa com o objetivo de honrar obrigação resultante de crédito que lhe tenha sido concedido por instituição financeira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950828,"enunciado":"A respeito do Banco Central do Brasil e das instituições públicas federais, julgue o item subsecutivo.\n\nÉ competência privativa do Banco Central do Brasil autorizar as instituições financeiras a alienar ou, de alguma outra forma, transferir o seu controle acionário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950829,"enunciado":"A respeito do Banco Central do Brasil e das instituições públicas federais, julgue o item subsecutivo.\n\nÉ vedada às instituições públicas federais a realização de operações de crédito com empresas controladas pela União.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950830,"enunciado":"No que se refere a instituições do Sistema Financeiro Nacional, julgue o próximo item.\n\nA sociedade de crédito ao microempreendedor e à empresa de pequeno porte está autorizada a captar recursos do público e a emitir títulos e valores mobiliários destinados a oferta pública.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950831,"enunciado":"Com relação a microcrédito e a operações de microcrédito, julgue o seguinte item.\n\nO microcrédito é um tipo de crédito especializado que não se destina ao financiamento do consumo, mas que, de forma assistida, apoia negócios de pequeno porte conduzidos por pessoas de baixa renda.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950832,"enunciado":"Com relação a microcrédito e a operações de microcrédito, julgue o seguinte item.\n\nAs operações de microcrédito podem ser realizadas sem o respaldo de garantias reais, sendo admitido o uso do aval solidário, ou da fiança solidária, como forma de minimizar o risco de crédito associado a essas operações.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950833,"enunciado":"No que se refere a procedimentos para abertura, movimentação e encerramento de conta-corrente, julgue o item a seguir.\n\nPara a abertura de conta-corrente, é obrigatória a completa identificação do depositante, mediante o preenchimento de ficha-proposta, cujas informações deverão ser verificadas pela instituição financeira a partir dos documentos originais apresentados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950834,"enunciado":"No que se refere a procedimentos para abertura, movimentação e encerramento de conta-corrente, julgue o item a seguir.\n\nPara o cancelamento de autorização de débito automático em conta-corrente, é obrigatório, em quaisquer circunstâncias, que o cliente comprove a liquidação da fatura programada para pagamento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950835,"enunciado":"No que se refere a procedimentos para abertura, movimentação e encerramento de conta-corrente, julgue o item a seguir.\n\nO fato de o cliente manter em determinada instituição financeira compromissos decorrentes de outras obrigações contratuais caracteriza impedimento para o encerramento, a seu pedido, de sua conta-corrente nessa instituição.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950836,"enunciado":"Determinado banco comercial incluiu o nome de um cliente no cadastro de emitentes de cheques sem fundos (CCF), visto que, na segunda apresentação do cheque por seu credor, o cliente não possuía recursos suficientes em conta para a liquidação da obrigação. Posteriormente, o cliente pagou a obrigação ao credor e ficou de posse do cheque emitido.\n\nConsiderando essa situação hipotética, julgue o item que se segue.\n\n\n\n\nA exclusão do nome do cliente do CCF ocorrerá mediante sua solicitação ao administrador do cadastro, a quem, para comprovar o cumprimento da obrigação, apresentará o cheque que tenha motivado a inclusão do seu nome naquele cadastro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950837,"enunciado":"Determinado banco comercial incluiu o nome de um cliente no cadastro de emitentes de cheques sem fundos (CCF), visto que, na segunda apresentação do cheque por seu credor, o cliente não possuía recursos suficientes em conta para a liquidação da obrigação. Posteriormente, o cliente pagou a obrigação ao credor e ficou de posse do cheque emitido.\n\nConsiderando essa situação hipotética, julgue o item que se segue.\n\n\n\n\nComprovado o cumprimento da obrigação ao credor, o banco em questão deverá comandar a exclusão do nome do cliente do CCF dentro do prazo de cinco dias úteis, contados da data da entrega do pedido do cliente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950838,"enunciado":"Acerca de depósitos bancários, julgue o item subsequente.\n\nNa captação de recursos por meio de depósitos à vista, as instituições financeiras podem oferecer a seus clientes bonificações, prêmios e outras vantagens, como o pagamento de juros pelos recursos depositados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950839,"enunciado":"Acerca de depósitos bancários, julgue o item subsequente.\n\nAs diferenças entre recibo de depósito bancário e certificado de depósito bancário incluem o fato de o certificado poder ser transferido por meio de endosso, sendo, portanto, negociável em mercado secundário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950840,"enunciado":"Com relação a fundos de investimentos, depósitos de poupança e títulos de capitalização, julgue o item subsecutivo.\n\nUm valor que for depositado em conta de poupança no dia 10 de outubro e sacado no dia 9 de novembro do mesmo ano será remunerado à taxa de juros de 0,5% ao mês mais a taxa referencial, caso a meta da taxa SELIC seja superior a 8,5% ao ano.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950841,"enunciado":"Com relação a fundos de investimentos, depósitos de poupança e títulos de capitalização, julgue o item subsecutivo.\n\nUm capital aplicado em título de capitalização produzirá montante inferior ao gerado pela aplicação do mesmo capital, pelo mesmo período, em caderneta de poupança, visto que, nos títulos de capitalização, os custos relativos a premiações, no caso de haver sorteios, e as despesas administrativas do emissor são descontados dos pagamentos efetuados no título.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950842,"enunciado":"Com relação a fundos de investimentos, depósitos de poupança e títulos de capitalização, julgue o item subsecutivo.\n\nOs fundos de investimento que se destinam a clientes com perfil mais conservador e que invistam em ativos cuja rentabilidade acompanhe, direta ou indiretamente, indicador de desempenho predefinido qualificam-se como fundos referenciados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950843,"enunciado":"Carlos pretende adquirir um plano de previdência privada para complementar os benefícios que obtiver no regime geral de previdência social. Seu projeto é investir por mais de dez anos e deseja que os recursos investidos no plano de previdência privada sejam deduzidos do imposto de renda.\n\nCom referência a essa situação hipotética, julgue o próximo item.\n\n\n\n\nO plano mais indicado para Carlos é um vida gerador de benefícios livres (VGBL) com tributação progressiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950844,"enunciado":"Carlos pretende adquirir um plano de previdência privada para complementar os benefícios que obtiver no regime geral de previdência social. Seu projeto é investir por mais de dez anos e deseja que os recursos investidos no plano de previdência privada sejam deduzidos do imposto de renda.\n\nCom referência a essa situação hipotética, julgue o próximo item.\n\n\n\n\nCaso Carlos deseje adquirir um seguro de vida associado ao plano de previdência, o produto mais adequado é um plano gerador de benefícios livres (PGBL), que permite deduzir o prêmio do seguro do imposto de renda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950845,"enunciado":"Julgue o item seguinte, acerca dos serviços de compensação de cheques e outros títulos.\n\nA Centralizadora da Compensação de Cheques (COMPE), sistema operado pelo Banco do Brasil S.A., é responsável pela compensação interbancária de cheques.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950846,"enunciado":"Julgue o item seguinte, acerca dos serviços de compensação de cheques e outros títulos.\n\nO saldo depositado em conta-corrente por meio de cheque pode ficar bloqueado para saque do titular da conta por até cinco dias úteis.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950847,"enunciado":"Julgue o item que se segue, a respeito do Sistema de Pagamentos Brasileiro (SPB).\n\nAs operações com títulos públicos federais são liquidadas financeiramente no Sistema Especial de Liquidação e de Custódia (SELIC), que integra o SPB como uma infraestrutura do mercado financeiro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950848,"enunciado":"Julgue o item que se segue, a respeito do Sistema de Pagamentos Brasileiro (SPB).\n\nO Banco Central do Brasil atua como provedor de serviços de liquidação, operando o Sistema de Transferência de Reservas, no qual ocorre a liquidação final de todas as obrigações financeiras do Sistema Financeiro Nacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950849,"enunciado":"Julgue o próximo item, a respeito de garantias fidejussórias, considerando a instrumentalidade na formalização dessas garantias e a responsabilidade atribuída ao avalista e(ou) ao fiador.\n\n\n\n\nNo caso do aval, a responsabilidade pelo pagamento da dívida é solidária, ou seja, tanto o devedor quanto o avalista são responsáveis pelo montante integral da dívida; no caso da fiança, a responsabilidade é subsidiária, e existe o benefício de ordem, isto é, o fiador somente será acionado se o devedor principal não cumprir a obrigação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950850,"enunciado":"Julgue o próximo item, a respeito de garantias fidejussórias, considerando a instrumentalidade na formalização dessas garantias e a responsabilidade atribuída ao avalista e(ou) ao fiador.\n\n\n\n\nPara que um dos cônjuges possa prestar fiança ou aval, é necessário, exceto no caso de casamento em regime de separação absoluta de bens, que haja o consentimento expresso do outro cônjuge, situação denominada outorga uxória ou marital.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950851,"enunciado":"Acerca de títulos de crédito, julgue o item a seguir.\n\nCaso um cheque seja apresentado para pagamento em data anterior à que nele esteja estipulada, ele deverá ser devolvido pela instituição financeira, mesmo que a conta sacada disponha de saldo suficiente para honrá-lo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950852,"enunciado":"Acerca de títulos de crédito, julgue o item a seguir.\n\nO prazo de apresentação de um cheque para pagamento é de seis meses, a contar da data de sua emissão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950853,"enunciado":"Acerca de títulos de crédito, julgue o item a seguir.\n\nNa nota promissória, é requisito essencial o nome do credor no título, não se admitindo nota promissória ao portador.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950854,"enunciado":"Acerca de títulos de crédito, julgue o item a seguir.\n\nA triplicata é extraída em caso de haver extravio ou perda da duplicata.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950855,"enunciado":"Um contrato pode ser definido, de modo geral, como um acordo de vontade entre partes. Acerca de contratos, julgue o item que se segue.\n\nO Código Civil brasileiro nomina diversos tipos de contratos, sendo ilícito às partes estipular contratos inominados ou atípicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950856,"enunciado":"Um contrato pode ser definido, de modo geral, como um acordo de vontade entre partes. Acerca de contratos, julgue o item que se segue.\n\nOs requisitos de validade dos contratos, como de qualquer negócio jurídico, incluem agente capaz, objeto lícito, possível, determinado ou determinável, e forma prescrita ou não defesa em lei.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950858,"enunciado":"Julgue o item a seguir, a respeito de cédulas e notas de créditos, que são instrumentos facilitadores das operações bancárias.\n\nA cédula de crédito industrial é uma promessa de pagamento em dinheiro sem garantia real, ao passo que a nota de crédito industrial é uma promessa de pagamento em dinheiro com garantia real.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":950859,"enunciado":"Julgue o item a seguir, a respeito de cédulas e notas de créditos, que são instrumentos facilitadores das operações bancárias.\n\nA cédula de crédito bancário é um título executivo extrajudicial e representa dívida em dinheiro, certa, líquida e exigível, decorrente de operação de crédito de qualquer modalidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":957644,"enunciado":"As empresas constituídas nas modalidades de sociedades por ações devem observar as seguintes características:","opcoes":["Emitir apenas ações preferenciais, sem direito a voto.","Emitir ações preferenciais que assegurem aos proprietários o direito a voto.","Emitir ações ordinárias que assegurem aos proprietários o direito a tão somente a participação nos lucros.","Registrar-se nos órgãos competentes, como sendo de capital aberto, negociando suas ações no mercado de capitais.","Emitir ações preferenciais, que não dão direito a voto, no máximo a 50% do total das ações emitidas."],"correta":4,"explicacao":"Gabarito: <strong>Emitir ações preferenciais, que não dão direito a voto, no máximo a 50% do total das ações emitidas.</strong>.","banca":"FUNDATEC","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1032308,"enunciado":"O grau de êxito econômico obtido por uma organização em relação ao capital investido denomina-se:","opcoes":["Lucratividade.","Patrimônio Líquido.","Rentabilidade","Liquidez."],"correta":2,"explicacao":"Gabarito: <strong>Rentabilidade</strong>.","banca":"IESES","ano":2019,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1049340,"enunciado":"O emitente de um cheque preenche esse título de crédito indicando o nome do beneficiário e inserindo cláusula “não à sua ordem”. Sendo assim, é correto afirmar que o beneficiário","opcoes":["poderá transferir esse título por simples endosso.","não poderá transferir esse título sem prévia aquiescência do emitente.","poderá transferir esse título mediante endosso em preto.","não poderá transferir esse título a terceiro.","poderá transferir esse título por cessão civil."],"correta":4,"explicacao":"Gabarito: <strong>poderá transferir esse título por cessão civil.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1087867,"enunciado":"Sobre operações bancárias, leia o trecho abaixo e assinale a alternativa que preencha correta e respectivamente as lacunas. “O depósito à vista e a conta corrente são exemplos de _____. As _____ são aquelas em que o banco oferece crédito aos clientes. As _____ são aquelas em o banco presta serviço como por exemplo a arrecadação de tributos e impostos.”","opcoes":["operações passivas / operações ativas / operações acessórias","operações passivas / operações acessórias / operações ativas","operações ativas / operações acessórias / operações passivas","operações acessórias / operações passivas / operações ativas"],"correta":0,"explicacao":"Gabarito: <strong>operações passivas / operações ativas / operações acessórias</strong>.","banca":"IBFC","ano":2019,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1088078,"enunciado":"O Sistema de Pagamentos Brasileiro (SPB) é regulado pela Lei nº 10.214/2001 que trata da atuação das câmaras e dos prestadores de serviços de compensação e de liquidação. Sobre os sistemas que fazem parte do SPB, analise as afirmativas abaixo e assinale a alternativa correta. I. de compensação de cheques. II. de compensação e liquidação de ordens eletrônicas de débito e de crédito. III. de troca de moedas estrangeiras. IV. de transferência de dívidas bancárias. V. de transferência de fundos e outros ativos financeiro. VI. de compensação e de liquidação de operações com títulos e valores mobiliários. VII. de operações com derivativos financeiros, cujas câmaras ou prestadores de serviços tenham sido autorizados.","opcoes":["Apenas as afirmativas I, II, III, IV e VI estão corretas","Apenas as afirmativas I, III, IV, V e VI estão corretas","Apenas as afirmativas I, II, V, VI e VII estão corretas","Apenas as afirmativas I, III, V, VI e VII estão corretas"],"correta":2,"explicacao":"Gabarito: <strong>Apenas as afirmativas I, II, V, VI e VII estão corretas</strong>.","banca":"IBFC","ano":2019,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1122939,"enunciado":"O Banco Central do Brasil é uma autarquia federal integrante do Sistema Financeiro Nacional, sendo vinculado ao Ministério da Economia. Dentre as suas diversas funções, o Banco Central é responsável por","opcoes":["negociar ações de sociedades de capital aberto e outros valores mobiliários.","certificar os profissionais do mercado financeiro e de capitais do Brasil.","gerenciar as reservas cambiais do país em ouro e em moeda estrangeira.","fazer o registro das companhias abertas.","organizar o funcionamento e as operações das bolsas de valores."],"correta":2,"explicacao":"Gabarito: <strong>gerenciar as reservas cambiais do país em ouro e em moeda estrangeira.</strong>.","banca":"FCC","ano":2019,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1129952,"enunciado":"Sobre os participantes dos mercados derivativos, é correto afirmar que o","opcoes":["hedger é um agente que busca proteção diante de riscos de flutuações nos preços e nas taxas de juros, tendo por meta reduzir o risco de eventuais oscilações desfavoráveis nos preços de mercado.","arbitrador é um agente econômico que procura tirar proveito de alguma informação de mercado, geralmente desconsiderada pelos demais participantes, com o intuito de realizar lucros.","especulador é um participante que procura tirar vantagens financeiras quando percebe que os preços em dois ou mais mercados apresentam-se distorcidos.","arbitrador é um agente que busca proteção diante de riscos de flutuação nos preços e nas taxas de juros, tendo por meta aumentar o risco de eventuais oscilações desfavoráveis nos preços de mercado.","hedger é um participante que procura tirar vantagens financeiras quando percebe que os preços em dois ou mais mercados apresentam-se distorcidos."],"correta":0,"explicacao":"Gabarito: <strong>hedger é um agente que busca proteção diante de riscos de flutuações nos preços e nas taxas de juros, tendo por meta reduzir o risco de eventuais oscilações desfavoráveis nos preços de mercado.</strong>.","banca":"FCC","ano":2019,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1137040,"enunciado":"No que se refere às políticas e aos instrumentos de política fiscal, regulatória e monetária, julgue o item subsecutivo.\n\n\n\n\nO Banco Central do Brasil, ao estabelecer norma que limita as taxas de juros das operações de cheque especial, atua no âmbito da política monetária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1167694,"enunciado":"Sobre o assunto, assinale a alternativa correta.","opcoes":["Se o público mantiver 68% dos recursos líquidos sob a forma de depósitos à vista e os encaixes totais dos bancos comerciais representarem 32% do total de seus depósitos, o multiplicador bancário será de 9,76.","O multiplicador bancário será de 3,3 caso o público mantiver 90% de seus recursos em depósitos à vista e os bancos mantiverem reservas de 27% do total de seus depósitos.","Se o público mantiver 35% dos seus recursos em depósitos à vista e os bancos mantiverem reservas de 65% do total de seus depósitos, o multiplicador bancário será de 1,14. Caso o Banco Central deseje expandir os meios de pagamento em circulação na economia, poderá elevar o percentual de encaixes compulsórios.","Caso o público mantiver 50% de seus recursos líquidos sob a forma de depósitos à vista e os encaixes totais dos bancos comerciais representarem 20% do total de depósitos, cada unidade monetária, a mais, de base monetária, dá origem a 1,67 unidade monetária adicional de meios de pagamento.","Quanto maior for a relação encaixe total dos bancos comerciais como proporção dos depósitos à vista nos bancos comerciais, maior será o multiplicador bancário."],"correta":3,"explicacao":"Gabarito: <strong>Caso o público mantiver 50% de seus recursos líquidos sob a forma de depósitos à vista e os encaixes totais dos bancos comerciais representarem 20% do total de depósitos, cada unidade monetária, a mais, de base monetária, dá origem a 1,67 unidade monetária adicional de meios de pagamento.</strong>.","banca":"CETRO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1167700,"enunciado":"Quanto ao sistema financeiro e ao multiplicador bancário, assinale a alternativa correta.","opcoes":["No balanço estilizado do Banco Central, os títulos públicos federais estão lançados como passivo.","Quando uma empresa desconta duplicatas em um banco comercial e recebe o valor descontado em sua conta corrente, não há nem destruição nem criação de moeda. Há apenas deslocamento de saldos monetários.","Depósitos à vista e depósitos a prazo são lançados nas contas do Ativo no balancete consolidado dos bancos comerciais.","Quando a quantidade de depósitos à vista, em relação ao total de meios de pagamento, é aumentada, dada uma quantidade de reservas bancárias em relação ao total de depósitos à vista, maior será o multiplicador monetário.","As operações de redesconto servem basicamente para determinar qual será a massa de recursos que ficará disponível para os bancos comerciais emprestarem."],"correta":3,"explicacao":"Gabarito: <strong>Quando a quantidade de depósitos à vista, em relação ao total de meios de pagamento, é aumentada, dada uma quantidade de reservas bancárias em relação ao total de depósitos à vista, maior será o multiplicador monetário.</strong>.","banca":"CETRO","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1174603,"enunciado":"O Sistema Financeiro Brasileiro tem uma função essencial no desenvolvimento do país, sendo um mecanismo facilitador da transferência de recursos financeiros dos agentes com sobra para os agentes que demandam tais fundos para realização de investimentos produtivos. Para que essa canalização dos fluxos financeiros ocorra, inúmeros agentes ou órgãos têm funções importantes e delimitadas dentro desse sistema. Analise as seguintes funções de alguns dos agentes do sistema financeiro nacional. I. Realizar a política de financiamento de médio e longo prazo na economia, uma vez que é o principal agente do governo federal para tal função. II. Fixar as diretrizes das políticas de crédito, monetária e cambial, uma vez que é o órgão mais importante desse sistema, sendo exclusivamente normativo. III. Emitir a moeda em circulação e gerenciar vendas e compras de títulos públicos federais. IV. Atuar como responsável pela câmera de compensação de cheques, além das carteiras comerciais típicas. Assinale a alternativa que relaciona corretamente o órgão que compõe esse sistema à sua respectiva função.","opcoes":["I. BNDES / II. CMN / III. BACEN / IV. BB","I. BNDES / II. CVM / III. BB / IV. CMN","I. SUSEP / II. CVM / III. BB / IV. BACEN","I. CMN / II. BB / III. BACEN / IV. SUSEP"],"correta":0,"explicacao":"Gabarito: <strong>I. BNDES / II. CMN / III. BACEN / IV. BB</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2019,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1276831,"enunciado":"A Superintendência Nacional de Previdência Complementar (Previc) é uma autarquia de natureza especial, dotada de autonomia administrativa e financeira e patrimônio próprio, com atuação em todo território nacional. Compete a essa autarquia","opcoes":["apreciar e julgar, encerrando a instância administrativa, os recursos interpostos contra decisão do Conselho Nacional de Previdência Complementar.","exercer a função de órgão regulador do regime de previdência complementar operado pelas entidades fechadas de previdência complementar.","atuar como entidade de fiscalização e de supervisão das atividades das entidades fechadas de previdência complementar e de execução das políticas para o regime de previdência complementar, operado pelas entidades fechadas de previdência complementar.","acompanhar e avaliar os recursos, bem como os ganhos sociais e o desempenho dos programas e projetos das entidades abertas de previdência complementar."],"correta":2,"explicacao":"Gabarito: <strong>atuar como entidade de fiscalização e de supervisão das atividades das entidades fechadas de previdência complementar e de execução das políticas para o regime de previdência complementar, operado pelas entidades fechadas de previdência complementar.</strong>.","banca":"IV - UFG","ano":2018,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303126,"enunciado":"A escrituração contábil, quando realizada por instituições financeiras e demais entidades autorizadas a funcionar pelo Banco Central do Brasil (BCB), constituídas na forma de companhia aberta, deve observar as disposições:","opcoes":["da Lei n.º 4.728/78 e dos atos normativos dela decorrentes.","da Lei n.º 11.138/07 e dos atos normativos dela decorrentes.","da Lei n.º 4.595/64 e dos atos normativos dela decorrentes.","da Lei n.º 6.385/76 e dos atos normativos dela decorrentes."],"correta":2,"explicacao":"Gabarito: <strong>da Lei n.º 4.595/64 e dos atos normativos dela decorrentes.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303127,"enunciado":"O BCB é uma autarquia federal, ligada ao Ministério da Fazenda, criada para atuar como ente executivo central do Sistema Financeiro Nacional (SFN), para cumprir e fazer cumprir as disposições legais e as normas expedidas pelo Conselho Monetário Nacional (CMN) e tem competência privativa para as atribuições abaixo, entre outras, EXCETO a de:","opcoes":["emitir papel-moeda e moeda metálica nas condições e limites autorizados pelo CMN.","regular o valor interno da moeda, prevenindo ou corrigindo os surtos inflacionários ou deflacionários de origem interna ou externa, as depressões econômicas e outros desequilíbrios oriundos de fenômenos conjunturais.","exercer a fiscalização das instituições financeiras, punindo-as quando necessário.","exercer o controle de crédito sob todas as suas formas."],"correta":1,"explicacao":"Gabarito: <strong>regular o valor interno da moeda, prevenindo ou corrigindo os surtos inflacionários ou deflacionários de origem interna ou externa, as depressões econômicas e outros desequilíbrios oriundos de fenômenos conjunturais.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303128,"enunciado":"As normas que dispõem sobre o Estatuto e o Regulamento do Fundo Garantidor de Créditos (FGC), o total de créditos de cada pessoa contra a mesma instituição associada, ou contra todas as instituições associadas do mesmo conglomerado financeiro, será garantido até o valor de:","opcoes":["R$200.000,00.","R$250.000,00.","R$300.000,00.","R$350.000,00."],"correta":1,"explicacao":"Gabarito: <strong>R$250.000,00.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303129,"enunciado":"Com relação às normas que dispõem sobre a contratação de correspondentes no País, o contrato de correspondente pode ter por objeto, entre outras, as atividades de atendimento, que visam ao fornecimento de produtos e serviços de responsabilidade da instituição contratante a seus clientes e usuários. Acerca desse assunto, aponte, entre os itens abaixo, as atividades de atendimento e, em seguida, assinale a opção CORRETA. I - Recepção e encaminhamento de propostas de abertura de contas de depósitos à vista, a prazo e de poupança mantidas pela instituição contratante. II - Realização de recebimentos, pagamentos e transferências eletrônicas visando à movimentação de contas de depósitos de titularidade de clientes mantidas pela instituição contratante. III - Recebimentos e pagamentos de qualquer natureza, e outras atividades decorrentes da execução de contratos e convênios de prestação de serviços mantidos pela instituição contratante com terceiros. Estão certos os itens:","opcoes":["I e II, apenas.","I e III, apenas","II e III, apenas.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303130,"enunciado":"São consideradas instituições financeiras monetárias aquelas que:","opcoes":["captam somente recursos para empréstimos por meio de emissão de títulos e, portanto, intermediam a moeda.","emitem valores mobiliários para colocação no mercado primário e, posteriormente, serem negociação em bolsa de valores.","possuem a autorização para receber depósitos à vista e detêm recursos assim depositados, os quais são, em todo ou em parte, emprestados; portanto, multiplicam a moeda.","operam com compra, venda e distribuição de títulos e valores mobiliários por conta de terceiros."],"correta":2,"explicacao":"Gabarito: <strong>possuem a autorização para receber depósitos à vista e detêm recursos assim depositados, os quais são, em todo ou em parte, emprestados; portanto, multiplicam a moeda.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303131,"enunciado":"É vedado à sociedade corretora de títulos e valores mobiliários:","opcoes":["realizar operações que caracterizem, sob qualquer forma, a concessão de financiamento, empréstimos ou adiantamentos aos seus clientes, inclusive cessão de direitos, ressalvadas as hipóteses de conta margem e as demais previstas na regulamentação em vigor.","prestar assistência aos contratantes das operações em que intervierem, até a final liquidação dos contratos respectivos.","proceder à compra e venda de valores mobiliários, por conta e ordem de terceiros, seus clientes.","responsabilizar-se nas operações em bolsas de valores, para com seus comitentes e para com outras sociedades corretoras com as quais esteja operando, pela liquidação e pela legitimidade dos títulos e valores entregues."],"correta":0,"explicacao":"Gabarito: <strong>realizar operações que caracterizem, sob qualquer forma, a concessão de financiamento, empréstimos ou adiantamentos aos seus clientes, inclusive cessão de direitos, ressalvadas as hipóteses de conta margem e as demais previstas na regulamentação em vigor.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303132,"enunciado":"O BCB poderá adotar medidas prudenciais preventivas destinadas a assegurar a solidez, a estabilidade e o regular funcionamento do SFN ao verificar a ocorrência de situações que comprometam o seu regular funcionamento ou das instituições que o compõe. Para tanto, deverá considerar, na sua análise e avaliação das situações e circunstâncias apuradas nos processos de supervisão/fiscalização das referidas instituições, indicadores como os elencados abaixo, EXCETO o de:","opcoes":["liquidez.","concentração de operações ativas e/ou passivas.","grau de dispersão do controle acionário.","alavancagem."],"correta":2,"explicacao":"Gabarito: <strong>grau de dispersão do controle acionário.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303133,"enunciado":"Nas opções abaixo, são apresentadas algumas medidas prudenciais que o BCB pode determinar como adoção obrigatória para instituição financeira que apresente indicadores de ocorrência de situações que comprometam ou possam comprometer o regular funcionamento do SFN, EXCETO:","opcoes":["a restrita observância dos limites operacionais.","o aumento do grau de risco das exposições.","o cumprimento dos procedimentos operacionais e de controles internos regulamentares.","a limitação ou suspensão da distribuição de resultados."],"correta":1,"explicacao":"Gabarito: <strong>o aumento do grau de risco das exposições.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303134,"enunciado":"O Risco de Crédito compreende, entre outras, a possibilidade de perdas, EXCETO:","opcoes":["de a contraparte não cumprir com as obrigações de liquidação de operações que envolvam a negociação de ativos financeiros, inclusive de instrumentos financeiros derivativos.","do não cumprimento de obrigações financeiras nos termos pactuados, quando o tomador ou a contraparte localizados fora do País, em decorrência de ações realizadas pelo governo do país estrangeiro respectivo e ainda a possibilidade de ocorrência de entraves na conversão cambial dos valores recebidos.","de cumprimento de obrigações financeiras nos termos pactuados por parte intermediária ou convenente de operações de crédito.","de desembolsos para honrar avais, fianças, coobrigações, compromissos de crédito ou outras operações de natureza semelhante."],"correta":2,"explicacao":"Gabarito: <strong>de cumprimento de obrigações financeiras nos termos pactuados por parte intermediária ou convenente de operações de crédito.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303135,"enunciado":"Assinale a opção que apresenta um evento NÃO considerado pelas normas do CMN como de risco operacional.","opcoes":["Fraudes internas e externas.","Falhas em sistemas de tecnologia de informação.","Ocorrência de flutuação relevante de taxa de juros.","Demandas trabalhistas e segurança deficiente do local de trabalho."],"correta":2,"explicacao":"Gabarito: <strong>Ocorrência de flutuação relevante de taxa de juros.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303136,"enunciado":"O diretor responsável pelo gerenciamento do risco de mercado em uma instituição pode desempenhar outras funções dentro da instituição, EXCETO as:","opcoes":["relacionadas à administração de recursos de terceiros e de operações de crédito.","relacionadas à administração de recursos de terceiros e de operações de tesouraria.","relativas às operações de câmbio.","relativas às operações de câmbio e de operações de crédito."],"correta":1,"explicacao":"Gabarito: <strong>relacionadas à administração de recursos de terceiros e de operações de tesouraria.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303137,"enunciado":"O total dos recursos aplicados no Ativo Permanente não pode ultrapassar 50% (cinquenta por cento) do valor do Patrimônio de Referência (PR) das instituições financeiras. Para efeitos da aplicação desse limite de imobilizações, NÃO são computados os valores correspondentes a operações de:","opcoes":["aquisição de investimentos de caráter permanente.","arrendamento mercantil.","ativação de intangíveis por incorporação de outra instituição.","ativação de bens não destinados ao uso por recuperação de créditos."],"correta":1,"explicacao":"Gabarito: <strong>arrendamento mercantil.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303138,"enunciado":"O Banco XYZ, de pequeno porte, opera em financiamentos de veículos e em empréstimos diretos ao usuário na modalidade “consignados”. A partir da origem das operações da espécie, forma blocos de prestações a receber dos tomadores de crédito e os vende para bancos de maior porte, ficando coobrigado com a liquidez e solvência dos créditos vendidos. O Banco XYZ substitui as prestações inadimplidas por prestações de outros contratos, acumulando, no tempo, uma carteira de créditos problemáticos de valor relevante, prejudicando o resultado e fragilizando o patrimônio líquido, o que se acelerou em 2013. Preventivamente, efetuou teste de estresse de suas operações de crédito, na posição de 30.12.13, com o deslocamento da carteira em dois níveis de risco, como apresentado abaixo. Considerando o resultado do teste e o fato de que o BCB também testa dessa forma e age com muito rigor nesses casos, por conta das exigências da regulamentação prudencial em vigor, a Administração do Banco XYZ deve tomar iniciativas adequadas para precaver-se das possíveis consequências danosas a sua continuidade. Acerca desse assunto, considere a tabela a seguir. De acordo com os dados apresentados, assinale a opção que apresenta uma situação NÃO adequada às circunstâncias citadas.","opcoes":["Vender para os acionistas controladores, ainda em 30.12.13, os créditos constantes do nível H, com transferência integral de risco.","Constituir de provisão adicional, de forma que, em conjunto com a provisão já constituída, atinja o percentual de 28% do valor da carteira de operações de crédito e exame e providências para posterior capitalização, se o caso.","Vender com coobrigação os créditos constantes do nível H, para os acionistas controladores, ainda em 30.12.13.","Constituir de provisão adicional, de forma que, em conjunto com a provisão já constituída, atinja o percentual de 28% do valor da carteira de operações de crédito e captar recursos diretamente dos seus acionistas controladores, em modalidade de instrumentos de capital e dívida, no valor de R$3.000.000,00, condicionando a sua liquidação com devolução dos recursos aos acionistas a possível recuperação desses créditos e, no caso de insucesso dessa recuperação, obrigatória e automática é a capitalização dos recursos correspondentes ao valor dos créditos não recuperados."],"correta":2,"explicacao":"Gabarito: <strong>Vender com coobrigação os créditos constantes do nível H, para os acionistas controladores, ainda em 30.12.13.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303139,"enunciado":"A regulamentação prudencial estabelecida pelo CMN dá competência para que o BCB possa alterar o limite relativo à exposição em ouro, em moeda estrangeira e em operações sujeitas à variação cambial das referidas instituições, exceto as sociedades de crédito ao microempreendedor e as instituições independentes do Sistema Brasileiro de Poupança e Empréstimo (SBPE), sendo vigente, atualmente, o limite de:","opcoes":["15% (quinze por cento) do PR.","75% (setenta e cinco por cento) do PR.","50% (cinquenta por cento) do PR.","30% (trinta por cento) do PR."],"correta":3,"explicacao":"Gabarito: <strong>30% (trinta por cento) do PR.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303140,"enunciado":"A aplicação no exterior de disponibilidades em moeda estrangeira de bancos autorizados a operar no mercado de câmbio deve limitar-se a algumas modalidades. Com relação a esse assunto, aponte, entre os itens abaixo, quais são essas modalidades. - Títulos de emissão do governo brasileiro. II - Títulos de dívida soberana emitidos por governos estrangeiros. III - Ações de companhias abertas negociadas em bolsa. IV - Debêntures emitidas por empresas privadas. Estão certos os itens","opcoes":["I e II, apenas.","I, II e III, apenas.","I, II e IV, apenas.","I, II, III e IV."],"correta":0,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303141,"enunciado":"Em 31 de janeiro de 2014, o Banco RST deferiu operação de crédito para reforçar o capital de giro da Rioverdense Industrial e Comercial de Alimentos Ltda. em R$1.000.000,00, com taxa prefixada de 2,3% a.m. (dois vírgula três por cento ao mês) e pagamento de juros e principal ao final de um prazo de seis meses. Qual o impacto dessa operação nas adequadas contas (patrimonial e de resultados) constantes no balancete de 30/4/2014 da referida empresa?","opcoes":["Financiamentos com R$1.069.000,00 e Rendas de Financiamentos com R$69.000,00.","Empréstimos com R$1.070.599,17 e Rendas de Empréstimos com R$70.599,17.","Financiamentos com R$1.070.599,17 e Rendas de Financiamentos com R$70.599,17.","Empréstimos com R$1.069.000,00 e Rendas de Empréstimos com R$69.000,00."],"correta":1,"explicacao":"Gabarito: <strong>Empréstimos com R$1.070.599,17 e Rendas de Empréstimos com R$70.599,17.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303142,"enunciado":"A Cia. Agroindustrial e Exportadora Trespassense, para financiar projeto de expansão de seu parque industrial, contatou o Banco DEF e teve deferida operação de crédito por repasse de recursos do BNDES/Finame, na ordem de R$3.000.000.000,00. As condições foram de liberação em 31 de março de 2014, com carência de seis meses para amortização do principal, mas com pagamento de juros mensais e saldo em 60 (sessenta) prestações mensais consecutivas de amortização de principal e juros, sendo pactuada taxa pós-fixada, vinculada a TJLP e mais juros 0,4% a.m. O que deve constar no balancete de 31 de maio de 2014 do Banco DEF, como reflexo dessa operação, nas respectivas e adequadas contas do sistema patrimonial e de resultados? (Considerar a TJLP de 0,5% a.m. no período para efeitos de cálculo).","opcoes":["Empréstimos com R$3.054.255,30 e Rendas de Empréstimos com R$54.255,30.","Empréstimos com R$3.030.075,00 e Rendas de Empréstimos com R$54.255,30.","Financiamentos com R$3.054.255,30 e Rendas de Financiamentos com R$54.255,30.","Financiamentos com R$3.030.075,00 e Rendas de Financiamentos com R$54.255,30."],"correta":3,"explicacao":"Gabarito: <strong>Financiamentos com R$3.030.075,00 e Rendas de Financiamentos com R$54.255,30.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303145,"enunciado":"As operações com instrumentos financeiros derivativos por meio de operações a termo, realizadas por conta própria pelas instituições financeiras, devem ser registradas observando adequados procedimentos. Considerando as operações acima citadas, assinale a opção que se encontra de acordo com as normas do SFN.","opcoes":["Na data da operação, o valor final contratado deduzido da diferença entre esse valor e o preço à vista do bem ou direito em subtítulo retificador de uso interno da adequada conta de ativo ou passivo, reconhecendo as receitas e despesas em razão do prazo de fluência dos contratos, no mínimo, por ocasião dos balancetes mensais e balanços.","Na data da operação, o valor dos prêmios pagos ou recebidos na adequada conta de ativo ou passivo, respectivamente, nela permanecendo até o efetivo exercício da opção, se for o caso, quando então deve ser baixado como redução ou aumento do custo do bem ou direito, pelo efetivo exercício, ou como receita ou despesa, no caso de não exercício, conforme o caso.","O valor dos ajustes diários na adequada conta de ativo ou passivo, devendo ser apropriados como receita ou despesa, no mínimo, por ocasião dos balancetes mensais e balanços.","O diferencial a receber ou a pagar na adequada conta de ativo ou passivo, deve ser apropriado como receita ou despesa, no mínimo, por ocasião dos balancetes mensais e balanços."],"correta":0,"explicacao":"Gabarito: <strong>Na data da operação, o valor final contratado deduzido da diferença entre esse valor e o preço à vista do bem ou direito em subtítulo retificador de uso interno da adequada conta de ativo ou passivo, reconhecendo as receitas e despesas em razão do prazo de fluência dos contratos, no mínimo, por ocasião dos balancetes mensais e balanços.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303146,"enunciado":"De acordo com as normas do CMN/BCB, é vedado às instituições financeiras realizarem determinadas operações com Títulos e Valores Mobiliários. Acerca desse assunto, assinale a opção que apresenta a modalidade que NÃO está inclusa nas referidas vedações.","opcoes":["Carteira particular de renda fixa.","Carteira não individualizada de títulos.","Operações denominadas “carteirões”.","Carteira própria bancada."],"correta":3,"explicacao":"Gabarito: <strong>Carteira própria bancada.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303147,"enunciado":"As normas que disciplinam a realização de operações compromissadas, envolvendo títulos de renda fixa, admitem a livre movimentação dos títulos objeto de compromissos de revenda, desde que atendidas adequadas condições: I - As partes firmem acordo de livre movimentação. II - Os compromissos sejam liquidados em sistema de registro e de liquidação financeira de ativos autorizado pelo Banco Central do Brasil ou pela Comissão de Valores Mobiliários e administrado por câmara ou prestador de serviços que assuma a posição de parte contratante para fins de liquidação das operações realizadas por seu intermédio. III - As operações compromissadas contratadas entre instituições financeiras e para aquelas que tenham como objeto títulos emitidos pelo Tesouro Nacional ou pelo Banco Central do Brasil, quaisquer que sejam as partes exigirão o atendimento das condições previstas em II acima. Ao considerar as condições de I a III acima, aponte as que estão em consonância com as regras do SFN, e, em seguida, assinale a opção CORRETA.","opcoes":["Apenas as condições I e II estão corretas.","Apenas as condições II e III estão corretas.","Todas as condições estão corretas.","Todas as condições estão incorretas."],"correta":0,"explicacao":"Gabarito: <strong>Apenas as condições I e II estão corretas.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303148,"enunciado":"Na constituição de cooperativa de crédito, é exigida, entre outras, a apresentação de plano de negócios, abrangendo um horizonte de, no mínimo, três anos de funcionamento, sendo contemplados determinadas condições: I - Estabelecimento dos objetivos estratégicos da instituição. II - Definição dos padrões de governança corporativa a serem observados, incluindo-se o detalhamento da estrutura de incentivos e da política de remuneração dos administradores. III - Definição da estrutura dos controles internos, com mecanismos que garantam adequada supervisão por parte da administração e a efetiva utilização de auditoria interna e externa como instrumentos de controle. IV - Definição dos principais produtos e serviços, das políticas de captação e de crédito, tecnologias a serem utilizadas e dimensionamento da rede de atendimento. Ao considerar as condições de 1 a 4 acima, aponte as que estão em consonância com as regras do SFN, e, em seguida, assinale a opção CORRETA.","opcoes":["Apenas as condições I e II estão incorretas.","Apenas as condições I e III estão corretas.","Todas as condições estão corretas.","Todas as condições estão incorretas."],"correta":2,"explicacao":"Gabarito: <strong>Todas as condições estão corretas.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1303149,"enunciado":"Pelas normas relativas à constituição e ao funcionamento de cooperativas de crédito, aplicam-se à auditoria externa, quando realizada por entidade de auditoria cooperativa, algumas disposições. Com relação a esse assunto, julgue os itens abaixo e, em seguida, assinale a opção CORRETA. I - Não são necessários o registro da referida entidade na Comissão de Valores Mobiliários (CVM) e a substituição periódica do auditor. II - Não representa impedimento à realização de auditoria a existência de vínculo societário indireto entre a entidade de auditoria cooperativa e a cooperativa auditada. III - Não se aplica o limite do percentual de faturamento anual de que trata o inciso V do Art. 6º do Regulamento anexo à Resolução CMN n.º 3.198. IV - Deve ser providenciada a substituição periódica do responsável técnico e dos demais membros da equipe envolvida na auditoria de cada cooperativa, na mesma periodicidade originalmente estabelecida para a substituição do auditor na Resolução CMN n.º 3.198, de 2004. Estão certos os itens:","opcoes":["I, III e IV, apenas.","II, III e IV, apenas.","III e IV, apenas.","I, II, III e IV."],"correta":3,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"CFC","ano":2014,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1316566,"enunciado":"O comportamento do balanço de pagamentos é sensível ao regime cambial adotado pelo país. Assim, em um regime de","opcoes":["taxa de câmbio flutuante, a política monetária é eficaz em determinar a taxa de câmbio real, muito embora não tenha controle sobre a taxa nominal de câmbio.","flutuação suja ou controlada, a taxa de câmbio nominal é mantida fixa de sorte a atrair capitais estrangeiros interessados em carry trade.","câmbio fixo, o crescimento sustentado da economia baseado em déficits em transações correntes torna o equilíbrio das contas externas diretamente dependente da liquidez no mercado financeiro internacional.","câmbio fixo, aumenta a eficácia da política monetária ao isolar a economia de variações nos preços internacionais dos bens importados.","câmbio fixo, é maior o espaço de decisão à política monetária doméstica, razão pela qual é preferível ao regime de flutuação."],"correta":1,"explicacao":"Gabarito: <strong>flutuação suja ou controlada, a taxa de câmbio nominal é mantida fixa de sorte a atrair capitais estrangeiros interessados em carry trade.</strong>.","banca":"FCC","ano":2020,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626270,"enunciado":"No que se refere à evolução do SFN, aos órgãos normativos e às entidades supervisoras, julgue o item subsequente.\n\n\n\n\nO arcabouço legal criado para o SFN era composto pelo Plano Nacional de Habitação, pela Lei da Reforma Bancária e pela Lei do Mercado de Capitais. Essas leis, importantes para criar as condições necessárias da intermediação financeira, deixaram de vigorar somente a partir de 1994, com o reordenamento da economia brasileira, adotado para reduzir os níveis inflacionários e permitir a maior abertura da economia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626271,"enunciado":"No que se refere à evolução do SFN, aos órgãos normativos e às entidades supervisoras, julgue o item subsequente.\n\n\n\n\nA Superintendência Nacional de Previdência Complementar é uma autarquia responsável pela fiscalização e pela supervisão das atividades exercidas por entidades fechadas de previdência complementar e pela execução das políticas destinadas ao regime de previdência complementar operado pelas entidades fechadas de previdência complementar.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626272,"enunciado":"No que se refere à evolução do SFN, aos órgãos normativos e às entidades supervisoras, julgue o item subsequente.\n\n\n\n\nA SUMOC foi criada para exercer algumas funções de banco central, entre as quais o recebimento dos depósitos voluntários e compulsórios de bancos privados e a administração dos serviços de compensação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626273,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nAs administradoras de consórcio são empresas que têm como responsabilidade o acompanhamento da formação e da administração dos grupos de consórcio. As atividades do sistema de consórcio são supervisionadas pelo BCB.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626274,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nAs sociedades corretoras de câmbio têm o objetivo de intermediar as operações de câmbio e de praticar operações do mercado de câmbio com taxas flutuantes. Essas sociedades são constituídas sob a forma de sociedade anônima ou por quotas de responsabilidade limitada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626275,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nOs bancos múltiplos são, obrigatoriamente, captadores de depósitos à vista ou de investimento e podem representar instituições financeiras públicas ou privadas. Uma particularidade dessas instituições é que a carteira de desenvolvimento somente pode ser operada por banco público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626276,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nAs bolsas de valores possuem autonomia financeira, patrimonial e administrativa, conforme resolução do CMN. Os objetivos das bolsas de valores incluem a manutenção de local ou sistema adequado para o encontro de seus membros e a realização, entre eles, das transações de compra e venda de títulos e valores mobiliários.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626277,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nOs fundos de pensão são organizados sob a forma de fundação ou sociedade civil sem fins lucrativos, sendo acessíveis aos empregados de uma empresa ou grupo de empresas ou ainda aos servidores da União, dos estados, do Distrito Federal e dos municípios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626278,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nAs sociedades corretoras de títulos e valores mobiliários são constituídas sob a forma de sociedade anônima ou por quotas de responsabilidade limitada. Entre suas atividades estão a intermediação da oferta pública e a distribuição de títulos e valores mobiliários no mercado, bem como a administração e a custódia das carteiras de títulos e valores mobiliários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626279,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nAs sociedades de capitalização são entidades constituídas, unicamente, sob a forma de sociedades anônimas, as quais negociam contratos e têm por objetivo instituir e operar planos de benefícios de caráter previdenciário concedidos em forma de renda continuada ou pagamento único.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626280,"enunciado":"A respeito de participantes do SFN, julgue o item seguinte.\n\n\n\n\nO Sistema de Informações de Crédito do BCB (SCR) possibilita o registro e a consulta de informações sobre operações de crédito, avais prestados e limites de crédito concedidos por instituições financeiras a pessoas físicas e jurídicas no país. Os clientes podem consultar seus dados diretamente no BCB ou nas instituições financeiras, oportunidade em que poderão obter dados detalhados por instituição financeira, e não somente de forma agregada para todo SFN.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626281,"enunciado":"A respeito de participantes do SFN, julgue o item seguinte.\n\n\n\n\nO Fundo Garantidor de Créditos — uma associação civil sem fins lucrativos com personalidade jurídica de direito privado — presta garantia de créditos contra instituição a ele associada quando ocorre o reconhecimento, pelo BCB, de estado de insolvência da instituição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626282,"enunciado":"A respeito de participantes do SFN, julgue o item seguinte.\n\n\n\n\nContribuir para a manutenção da estabilidade do Sistema Nacional de Crédito Cooperativo e ressarcir crédito de cooperados, mesmo daqueles que não sejam clientes de instituições associadas ao Fundo Garantidor de Cooperativismo de Crédito (FGCoop), são finalidades do FGCoop.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626283,"enunciado":"Em relação ao papel e ao funcionamento dos bancos centrais em perspectiva histórica, julgue o item a seguir.\n\n\n\n\nNo Brasil, com a criação da SUMOC, o BB perdeu completamente suas funções de banco central.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626286,"enunciado":"Considerando a perspectiva histórica da função de banqueiro central no Brasil, julgue o item que se segue.\n\n\n\n\nCom o advento da LRF, a utilização de recursos públicos para socorro a instituições financeiras ficou proibida.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626287,"enunciado":"Considerando a perspectiva histórica da função de banqueiro central no Brasil, julgue o item que se segue.\n\n\n\n\nAs receitas provenientes do imposto sobre operações financeiras foram, por duas décadas, fundamentais para a constituição da reserva monetária.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626288,"enunciado":"A respeito das funções do BCB, julgue o item subsecutivo.\n\n\n\n\nCom a edição da LRF, o BCB deixou de emitir títulos para a execução da política monetária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626289,"enunciado":"A respeito das funções do BCB, julgue o item subsecutivo.\n\n\n\n\nAtualmente, a Casa da Moeda do Brasil divide com o BCB o monopólio da emissão de moeda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626290,"enunciado":"A respeito das funções do BCB, julgue o item subsecutivo.\n\n\n\n\nO BB compartilha com o BCB as funções de provimento e de saneamento do meio circulante.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626291,"enunciado":"Em relação ao SPB, julgue o item a seguir.\n\n\n\n\nCom a reestruturação do SPB, as transferências de fundos interbancários passaram a ser realizadas em tempo real, em caráter irrevogável.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626292,"enunciado":"Em relação ao SPB, julgue o item a seguir.\n\n\n\n\nAté 2002, o SPB ainda não estava estruturado de modo que o BCB pudesse acompanhar as operações realizadas pelas instituições financeiras em tempo real, o que trazia a possibilidade de o BCB ter de arcar com o risco de crédito em caso de inadimplência de alguma instituição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626293,"enunciado":"A respeito das características dos sistemas de transferências de fundos, julgue o item seguinte.\n\n\n\n\nA compensação de cheques é liquidada em D + 1 da data de acolhimento dos documentos; eventual inadimplência por parte de instituição financeira acarreta imediata sanção por parte do BCB.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626294,"enunciado":"A respeito das características dos sistemas de transferências de fundos, julgue o item seguinte.\n\n\n\n\nAs transações realizadas na Central de Custódia e de Liquidação Financeira de Títulos envolvem títulos privados e títulos públicos, como os títulos da dívida agrária.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626295,"enunciado":"A respeito das características dos sistemas de transferências de fundos, julgue o item seguinte.\n\n\n\n\nAs contas de reservas bancárias mantidas no BCB podem, eventualmente, apresentar saldo negativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626296,"enunciado":"Em relação ao campo de atuação do BCB, julgue o item a seguir.\n\n\n\n\nAlterações de controle societário de instituições só podem ser realizadas mediante autorização do BCB, ao passo que fusões e incorporações devem ser previamente autorizadas pela Receita Federal do Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626297,"enunciado":"Em relação ao campo de atuação do BCB, julgue o item a seguir.\n\n\n\n\nO BCB fiscaliza exclusivamente as instituições que fazem parte do SFN.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626298,"enunciado":"Acerca dos Acordos de Basileia, julgue o item abaixo.\n\n\n\n\nAs deliberações do Comitê de Supervisão Bancária de Basileia possuem força de lei.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626299,"enunciado":"Em relação às atividades de supervisão e fiscalização realizadas pelo BCB, julgue o item seguinte.\n\n\n\n\nRisco de crédito, risco de liquidez, risco de mercado e risco operacional são fatores de risco focalizados primordialmente pela supervisão do BCB.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626300,"enunciado":"Em relação às atividades de supervisão e fiscalização realizadas pelo BCB, julgue o item seguinte.\n\n\n\n\nNão existe obrigatoriedade de alocação de capital para o risco de imagem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626301,"enunciado":"Em relação às atividades de supervisão e fiscalização realizadas pelo BCB, julgue o item seguinte.\n\n\n\n\nNo Brasil, a supervisão executada pelo BCB segue os modelos de atuação direta e indireta: a atuação direta é executada pelo Departamento de Supervisão de Bancos e Conglomerados Bancários (DESUP), pelo Departamento de Supervisão de Cooperativas e de Instituições não Bancárias (DESUC) e pelo Departamento de Supervisão de Conduta (DECON), a atuação indireta, pelo Departamento de Monitoramento do Sistema Financeiro (DESIG).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626302,"enunciado":"Em relação às atividades de supervisão e fiscalização realizadas pelo BCB, julgue o item seguinte.\n\n\n\n\nSe uma instituição não encaminhar, no prazo regulamentar, demonstrativo do risco de liquidez, o BCB aplicará a penalidade de suspensão do exercício do cargo, por até três anos, ao administrador principal dessa instituição financeira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626303,"enunciado":"Em relação às atividades de supervisão e fiscalização realizadas pelo BCB, julgue o item seguinte.\n\n\n\n\nA prevenção ao crime de lavagem de dinheiro, no âmbito do SFN, compete a todas as instituições autorizadas a funcionar pelo BCB.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626304,"enunciado":"A execução da política monetária é uma das principais funções dos bancos centrais, que podem desempenhá-las com ou sem autonomia perante outras esferas de governo. A respeito desse assunto, julgue o item a seguir.\n\n\n\n\nOs principais argumentos para a defesa da autonomia dos bancos centrais são a existência de uma taxa natural de desemprego e a neutralidade da política monetária em relação aos níveis de produto e de emprego no longo prazo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626305,"enunciado":"A execução da política monetária é uma das principais funções dos bancos centrais, que podem desempenhá-las com ou sem autonomia perante outras esferas de governo. A respeito desse assunto, julgue o item a seguir.\n\n\n\n\nAs operações de mercado aberto são, atualmente, o principal instrumento de política monetária disponível ao BCB, na medida em que permitem uma eficiente regulação da oferta de moeda e da taxa básica de juros.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626306,"enunciado":"A execução da política monetária é uma das principais funções dos bancos centrais, que podem desempenhá-las com ou sem autonomia perante outras esferas de governo. A respeito desse assunto, julgue o item a seguir.\n\n\n\n\nA elevação da alíquota dos recolhimentos compulsórios aumenta a capacidade dos bancos comerciais de multiplicar o volume de crédito, uma vez que mais recursos são direcionados para suas respectivas contas de reservas bancárias no BCB.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626307,"enunciado":"A execução da política monetária é uma das principais funções dos bancos centrais, que podem desempenhá-las com ou sem autonomia perante outras esferas de governo. A respeito desse assunto, julgue o item a seguir.\n\n\n\n\nDe forma complementar aos instrumentos tradicionais de política monetária, o BCB pode adotar medidas macroprudenciais para proteger o sistema bancário contra riscos de liquidez e solvência de instituições financeiras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626308,"enunciado":"A execução da política monetária é uma das principais funções dos bancos centrais, que podem desempenhá-las com ou sem autonomia perante outras esferas de governo. A respeito desse assunto, julgue o item a seguir.\n\n\n\n\nA fim de assegurar o sucesso do regime de metas para inflação no Brasil, as informações utilizadas para definição da meta da taxa SELIC e relativas aos cenários macroeconômicos, além dos riscos a eles associados, são mantidas em sigilo por um ano após as reuniões do Comitê de Política Monetária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626309,"enunciado":"Com referência à função do BCB como executor da política cambial, e à administração das reservas internacionais, julgue o item subsequente.\n\n\n\n\nCompete ao CMN estabelecer os objetivos estratégicos e o perfil de risco e de retorno da aplicação das reservas internacionais, as quais têm sua gestão e administração delegadas a gerentes externos, porém sob a supervisão do BCB.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626310,"enunciado":"Com referência à função do BCB como executor da política cambial, e à administração das reservas internacionais, julgue o item subsequente.\n\n\n\n\nA adoção de um regime de taxas de câmbio flexíveis, com mobilidade de capital, limita a capacidade do BCB de influir na oferta de moeda e na definição da taxa de juros básica da economia, uma vez que a política monetária torna-se passiva em relação à oferta cambial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626311,"enunciado":"Com referência à função do BCB como executor da política cambial, e à administração das reservas internacionais, julgue o item subsequente.\n\n\n\n\nO BCB tem realizado, com frequência, para fins de execução da política cambial, operações de swap cambial, por meio das quais oferece proteção cambial ao mercado sem reduzir o volume das reservas internacionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626317,"enunciado":"Com relação a funções, governança e objetivos de organismos, fundos e instituições financeiras internacionais e ao relacionamento dessas entidades com o Brasil, julgue o item subsequente.\n\n\n\n\nA subscrição de quotas, expressas em Direitos Especiais de Saque, é a maior fonte de recursos financeiros do FMI, além de determinar, para cada país-membro, seu poder de voto e o volume de recursos que cada um pode tomar emprestado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626318,"enunciado":"Com relação a funções, governança e objetivos de organismos, fundos e instituições financeiras internacionais e ao relacionamento dessas entidades com o Brasil, julgue o item subsequente.\n\n\n\n\nO governo brasileiro assinou, em 2009, o último acordo com o FMI, no qual foram disponibilizados ao Brasil US$ 10 bilhões para conter a fuga de capital do país para mercados considerados mais seguros, como reflexo da crise financeira mundial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626319,"enunciado":"Com relação a funções, governança e objetivos de organismos, fundos e instituições financeiras internacionais e ao relacionamento dessas entidades com o Brasil, julgue o item subsequente.\n\n\n\n\nA política de empréstimos do BIRD tem sido orientada, atualmente, para atender, preferencialmente, setores voltados à prestação de serviços públicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626320,"enunciado":"Com relação a funções, governança e objetivos de organismos, fundos e instituições financeiras internacionais e ao relacionamento dessas entidades com o Brasil, julgue o item subsequente.\n\n\n\n\nO Comitê da Basileia de Supervisão Bancária é uma autoridade supranacional voltada a assuntos de supervisão bancária, de forma que suas decisões têm força de lei nos países-membros do BIS.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626322,"enunciado":"Com relação a funções, governança e objetivos de organismos, fundos e instituições financeiras internacionais e ao relacionamento dessas entidades com o Brasil, julgue o item subsequente.\n\n\n\n\nOs fundos soberanos são constituídos com objetivos de estabilização — a fim de reduzir a volatilidade das receitas dos respectivos países que os instituem — e de poupança, cujo fim é assegurar recursos financeiros em favor de gerações futuras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626323,"enunciado":"Com relação a funções, governança e objetivos de organismos, fundos e instituições financeiras internacionais e ao relacionamento dessas entidades com o Brasil, julgue o item subsequente.\n\n\n\n\nO BIRD e o BIS foram criados a partir do Acordo de Bretton Woods, em 1944: o primeiro, com o objetivo de conceder empréstimos para reconstrução e desenvolvimento; o segundo, para promover a estabilidade cambial de países-membros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626331,"enunciado":"A respeito da estrutura e organização do BCB, julgue o item seguinte.\n\n\n\n\nUm servidor do BCB que ocupe a função comissionada designada por FCA–2 atua como consultor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626332,"enunciado":"A respeito da estrutura e organização do BCB, julgue o item seguinte.\n\n\n\n\nA análise do relatório de inflação é responsabilidade precípua do Comitê de Estabilidade Financeira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626333,"enunciado":"A respeito da estrutura e organização do BCB, julgue o item seguinte.\n\n\n\n\nOs recursos dos processos administrativos punitivos instaurados pelo BCB são encaminhados pelo Departamento de Controle e Análise de Processos Administrativos Punitivos (DECAP) ao Conselho de Recursos do Sistema Financeiro Nacional (CRSFN) e ao ministro de Estado da Fazenda, observadas as respectivas competências.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626334,"enunciado":"A respeito da estrutura e organização do BCB, julgue o item seguinte.\n\n\n\n\nCabe à Diretoria Colegiada do BCB decidir a respeito da meta da taxa do Sistema Especial de Liquidação e de Custódia (SELIC).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626335,"enunciado":"Com relação às áreas de atuação dos diretores do BCB e a funções comissionadas, hierarquia e componentes organizacionais dessa instituição, julgue o item que se segue.\n\n\n\n\nSe, no âmbito de uma mesma unidade da estrutura organizacional do BCB, onde exista grande quantidade de processos de trabalho, houver a necessidade de desmembrar as funções de aquisição de materiais e de pagamentos, recomenda-se a criação de gerências.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626336,"enunciado":"Com relação às áreas de atuação dos diretores do BCB e a funções comissionadas, hierarquia e componentes organizacionais dessa instituição, julgue o item que se segue.\n\n\n\n\nCabe ao diretor de administração do BCB acompanhar a realização dos inquéritos destinados a apurar as causas que levaram à decretação dos regimes especiais de intervenção, de liquidação extrajudicial e de administração especial temporária de instituições bancárias e não bancárias autorizadas a funcionar pelo BCB, bem como a responsabilidade de seus administradores.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626337,"enunciado":"Com relação às áreas de atuação dos diretores do BCB e a funções comissionadas, hierarquia e componentes organizacionais dessa instituição, julgue o item que se segue.\n\n\n\n\nNo BCB, os departamentos correspondem a unidades subordinadas, administrativamente, ao diretor de administração e, tecnicamente, às unidades responsáveis pelos assuntos específicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626350,"enunciado":"Julgue o item seguinte a respeito da evolução do Sistema Financeiro Nacional (SFN), desde a Segunda Guerra Mundial até hoje, em particular quanto aos órgãos normativos e às entidades supervisoras.\n\n\n\n\nAté o ano de 1994, o Brasil viveu um processo inflacionário crônico e acentuado, retroalimentado por uma indexação generalizada de preços na economia. A partir desse ano, o Conselho Monetário Nacional (CMN) passou a atuar no sentido de reestruturar e fortalecer o sistema financeiro, momento em que surgiram novas propostas, a exemplo do Programa de Incentivo à Redução do Setor Público Estadual na Atividade Bancária (PROES).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626351,"enunciado":"Julgue o item seguinte a respeito da evolução do Sistema Financeiro Nacional (SFN), desde a Segunda Guerra Mundial até hoje, em particular quanto aos órgãos normativos e às entidades supervisoras.\n\n\n\n\nO Banco Central do Brasil (BCB), criado pela Lei n.º 4.595/1964, tem a missão de assegurar o poder aquisitivo da moeda e manter um sistema financeiro sólido e eficiente. As responsabilidades do BCB incluem o estímulo à formação de poupança e a manutenção de reservas internacionais em níveis adequados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626352,"enunciado":"Julgue o item seguinte a respeito da evolução do Sistema Financeiro Nacional (SFN), desde a Segunda Guerra Mundial até hoje, em particular quanto aos órgãos normativos e às entidades supervisoras.\n\n\n\n\nNa evolução do SFN, o período posterior a 1988 representa uma época de várias mudanças, entre as quais a expansão da rede bancária para diversas regiões do país e a criação de instituições financeiras, como o Banco de Crédito da Amazônia S.A. e o Banco do Nordeste do Brasil, voltadas para o apoio a regiões carentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626353,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nBanco de investimento visa proporcionar o suprimento adequado de recursos para financiamento de programas e projetos que promovam o desenvolvimento econômico e social do país, a médio e longo prazos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626354,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nBancos múltiplos podem ser instituições financeiras públicas que realizam operações por intermédio de carteiras comercial, de crédito e de investimento. Para ser classificada como banco múltiplo, a instituição deve possuir carteira comercial ou carteira de investimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626355,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nA Caixa Econômica Federal (CAIXA), sociedade de economia mista criada em 1861 e regulada pelo Decreto-Lei n.º 759/1969, é considerada uma empresa pública pelo fato de a União possuir 50% de seu capital social.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626357,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nAs operações ativas das sociedades de crédito imobiliário incluem os financiamentos imobiliários residenciais ou comerciais, a aquisição de créditos hipotecários, os refinanciamentos de créditos hipotecários e os repasses de recursos para financiamentos imobiliários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626358,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nAs sociedades corretoras de câmbio podem realizar, sem restrições, operações de financiamento à exportação, adiantamentos sobre contratos de câmbio e recebimento de depósitos em contas sem remuneração.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626359,"enunciado":"Acerca das entidades operadoras do SFN, julgue o item.\n\n\n\n\nO Banco Nacional de Desenvolvimento Econômico e Social, vinculado ao Ministério do Desenvolvimento, Indústria e Comércio Exterior, tem por objetivo o apoio a empreendimentos que contribuam para o desenvolvimento do país.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626360,"enunciado":"No SFN, além dos órgãos normativos, das entidades supervisoras e dos operadores, existem outras instituições e sistemas que exercem funções importantes. A respeito desse assunto, julgue o item seguinte.\n\n\n\n\nAs atribuições do Fundo Garantidor de Créditos (FGC), do qual a CAIXA é uma instituição associada, incluem a contratação de operações de assistência ou suporte financeiro e, também, operações de liquidez.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626361,"enunciado":"No SFN, além dos órgãos normativos, das entidades supervisoras e dos operadores, existem outras instituições e sistemas que exercem funções importantes. A respeito desse assunto, julgue o item seguinte.\n\n\n\n\nNo Conselho de Recursos do SFN (CRSFN) — órgão integrante da estrutura do Ministério da Fazenda —, a Associação Nacional das Corretoras e Distribuidoras de Títulos e Valores Mobiliários, Câmbio e Mercadorias (ANCORD) atua como entidade de classe titular e a Associação de Investidores no Mercado de Capitais (AMEC) atua como entidade suplente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626363,"enunciado":"Considerando a atuação do BCB na implantação do Plano Real, julgue o item seguinte.\n\n\n\n\nO Plano Real valeu-se de uma política monetária robusta e um regime de câmbio estritamente fixo até 1999.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626364,"enunciado":"Considerando a atuação do BCB na implantação do Plano Real, julgue o item seguinte.\n\n\n\n\nO Plano Real foi o primeiro plano econômico do Brasil em que a política monetária foi idealizada de forma independente pelo BCB.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626365,"enunciado":"Considerando as funções do BCB, julgue o item abaixo.\n\n\n\n\nO Banco do Brasil é a única instituição custodiante de numerário contratada pelo BCB para a atividade de provimento de meio circulante.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626366,"enunciado":"Considerando as funções do BCB, julgue o item abaixo.\n\n\n\n\nO Banco do Brasil divide com o BCB a função de emissão de papel moeda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626367,"enunciado":"Em relação ao Sistema de Pagamentos Brasileiro (SPB), implantado em 2002, julgue o item a seguir.\n\n\n\n\nO SPB, antes de sua criação e reestruturação, não estava preparado para acompanhamento das operações em tempo real.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626368,"enunciado":"Em relação ao Sistema de Pagamentos Brasileiro (SPB), implantado em 2002, julgue o item a seguir.\n\n\n\n\nSomente a partir da criação do SPB o BCB passou a atuar como provedor da liquidação bancária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626369,"enunciado":"Considerando as características referentes aos sistemas de transferências de fundos, julgue o item seguinte.\n\n\n\n\nAs transações realizadas no Sistema Especial de Liquidação e Custódia (SELIC) envolvem unicamente títulos privados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626370,"enunciado":"Considerando as características referentes aos sistemas de transferências de fundos, julgue o item seguinte.\n\n\n\n\nAs contas de reservas bancárias mantidas no BCB não podem apresentar saldo negativo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626371,"enunciado":"Considerando as características referentes aos sistemas de transferências de fundos, julgue o item seguinte.\n\n\n\n\nA conta de reserva bancária é de titularidade obrigatória para os bancos múltiplos, como o Banco do Brasil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626372,"enunciado":"Em relação ao campo de atuação do BCB, julgue o item a seguir.\n\n\n\n\nAs atribuições do BCB incluem a fiscalização de administradoras de consórcio.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626373,"enunciado":"A respeito dos Acordos de Basileia, julgue o próximo item.\n\n\n\n\nO pilar I do Acordo de Basileia II refere-se à transparência das instituições em relação à gestão dos riscos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626374,"enunciado":"A respeito dos Acordos de Basileia, julgue o próximo item.\n\n\n\n\nO Brasil, em 2011, implementou integralmente o Acordo de Basileia III, diferentemente da adoção do Acordo de Basileia II, que seguiu um processo gradual.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626375,"enunciado":"Acerca das atividades de supervisão e fiscalização realizadas pelo BCB, julgue o item subsecutivo.\n\n\n\n\nOs bancos múltiplos devem possuir estrutura de gerenciamento dos riscos de mercado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626376,"enunciado":"Acerca das atividades de supervisão e fiscalização realizadas pelo BCB, julgue o item subsecutivo.\n\n\n\n\nAtender denúncias e reclamações feitas ao BCB constitui um dos objetivos da atividade de supervisão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626377,"enunciado":"A respeito da execução da política monetária, que é uma das principais funções dos bancos centrais, julgue o item a seguir.\n\n\n\n\nCabe ao presidente do BCB o voto de qualidade e a prerrogativa de alterar a meta para a taxa SELIC — no mesmo sentido do viés, se estabelecido —, sem a necessidade de convocação de reunião extraordinária do Comitê de Política Monetária (COPOM).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626378,"enunciado":"A respeito da execução da política monetária, que é uma das principais funções dos bancos centrais, julgue o item a seguir.\n\n\n\n\nÀ Diretoria Colegiada do BCB é permitida a alteração das alíquotas do recolhimento compulsório a qualquer tempo, desde que obedecidos os limites legais de 100% sobre os depósitos à vista e de 60% sobre as demais operações passivas das instituições financeiras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626379,"enunciado":"A respeito da execução da política monetária, que é uma das principais funções dos bancos centrais, julgue o item a seguir.\n\n\n\n\nOs bancos centrais exercem a função de banco dos bancos, mediante operações de redesconto bancário, nas quais oferecem financiamentos com o propósito de prover liquidez às instituições financeiras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626380,"enunciado":"A respeito da execução da política monetária, que é uma das principais funções dos bancos centrais, julgue o item a seguir.\n\n\n\n\nO BCB realiza operações de mercado aberto com instituições financeiras previamente credenciadas (dealers), por meio da compra e venda de títulos de sua própria emissão, para regular a liquidez do sistema bancário e a taxa básica de juros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626381,"enunciado":"A respeito da execução da política monetária, que é uma das principais funções dos bancos centrais, julgue o item a seguir.\n\n\n\n\nEm 1999, o Brasil adotou o sistema de metas para inflação e, desde então, a taxa de inflação, medida pelo Índice Nacional de Preços ao Consumidor Amplo (IPCA), foi registrada dentro do intervalo de tolerância estabelecido pelo BCB.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626382,"enunciado":"Com relação à função dos bancos centrais como executores da política cambial, bem como no que diz respeito à administração das reservas internacionais, julgue o item subsequente.\n\n\n\n\nO Brasil adota um regime de câmbio flutuante, no qual a atuação do BCB, utilizando suas reservas internacionais, visa diminuir o excesso de volatilidade na taxa de câmbio e evitar a falta ou o excesso de liquidez de divisas no mercado interbancário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626383,"enunciado":"Com relação à função dos bancos centrais como executores da política cambial, bem como no que diz respeito à administração das reservas internacionais, julgue o item subsequente.\n\n\n\n\nNo regime de câmbio fixo com mobilidade internacional de capital, o banco central possui liberdade para definir a oferta de moeda, a taxa básica de juros e o volume de reservas internacionais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626384,"enunciado":"Acerca de planejamento e gestão nos setores público e privado, julgue o item seguinte.\n\n\n\n\nConsidere que, no processo cíclico e abrangente de gestão, retratado pela expressão planejamento e gestão estratégica, um colaborador do BCB tenha analisado a situação atual da organização e projetado sua situação futura com o estabelecimento de orientações estratégicas para um ciclo de mais longo prazo. Diante dessa situação hipotética, é correto afirmar que o colaborador em questão vivenciou a fase do processo denominada formulação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626392,"enunciado":"No que se refere à alienação de bens e materiais de consumo, julgue o item subsecutivo.\n\n\n\n\nO DEMAP/DILOG deverá, pelo menos duas vezes ao ano (uma em cada semestre), determinar data para a realização de inventário de bens estocados nos almoxarifados. Esse procedimento será realizado por uma comissão específica designada pelo próprio DEMAP ou pelas gerências administrativas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626397,"enunciado":"Com relação aos procedimentos de serviços de patrimônio, julgue o item a seguir.\n\n\n\n\nO inventário de material de consumo no BCB, efetuado nos meses de maio e junho, deve ser realizado por comissão específica designada pela Diretoria Colegiada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1626398,"enunciado":"Com relação aos procedimentos de serviços de patrimônio, julgue o item a seguir.\n\n\n\n\nA gestão patrimonial do BCB visa assegurar a funcionalidade do ambiente institucional e zelar pelos bens patrimoniais da instituição por meio de processos multidisciplinares orientados ao planejamento, à execução e ao controle de serviços integrados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1635967,"enunciado":"A soma do papel-moeda em poder do público com os depósitos à vista nos bancos comerciais denomina-se:","opcoes":["quase-moeda","reserva de valor","unidade de conta","multiplicador","meios de pagamento"],"correta":4,"explicacao":"Gabarito: <strong>meios de pagamento</strong>.","banca":"CEPERJ","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1670893,"enunciado":"As alternativas a seguir apresentam modelos primários usados em mobile payment, à exceção de uma. Assinale‐a.","opcoes":["Transações baseadas em SMS/USSD.","Pagamento via aplicativos baseados em Web 3.0.","Pagamento via NFC (Near Field Communication).","Direct Mobile Billing.","Mobile Web Payment."],"correta":1,"explicacao":"Gabarito: <strong>Pagamento via aplicativos baseados em Web 3.0.</strong>.","banca":"FGV","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1783911,"enunciado":"O Banco Central lançou no dia 19 de fevereiro de 2020 um serviço que promete tornar mais rápida a realização de pagamentos e transferências online entre pessoas, empresas e entes governamentais. O novo serviço deve ser disponibilizado a partir de novembro deste ano. Com o serviço, a população terá uma nova alternativa para efetuar transações, além dos modelos tradicionais já existentes, como TED, DOC, boleto, cheque e cartões, afirma o BC. A ferramenta estará disponível a qualquer dia do ano, sem limite de horário, e com o dinheiro imediatamente disponível ao recebedor. Estamos falando do:","opcoes":["PIX","NECTON","BITCOIN","ETHEREUM","TED 20"],"correta":0,"explicacao":"Gabarito: <strong>PIX</strong>.","banca":"AMAUC","ano":2020,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1817553,"enunciado":"Acerca da teoria cambial da paridade do poder de compra, julgue o próximo item.\n\n\n\n\nCaso não existam custos de transação e os bens sejam homogêneos, a teoria da paridade do poder de compra, em sua versão relativa, postula que, a longo prazo, o valor da moeda de um país será completamente determinado pela razão entre o preço doméstico e o preço externo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1822456,"enunciado":"A bolsa de valores é o mercado organizado em que se negociam commodities por meio de derivativos agrícolas (contratos de entrega futura) e ativos financeiros, como taxas de juros e câmbio, e também por meio de títulos e índices.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1822492,"enunciado":"As Letras Financeiras do Tesouro (LFT), ou Tesouro SELIC, possuem baixo poder riqueza, o que limita o poder da política monetária.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825820,"enunciado":"Considerando a evolução tecnológica e as características atuais das criptomoedas, julgue o item a seguir. \n\n\n\n\nAs criptomoedas não conseguem atualmente exercer todas as funções relacionadas à moeda tradicional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825821,"enunciado":"Considerando a evolução tecnológica e as características atuais das criptomoedas, julgue o item a seguir. \n\n\n\n\nAs instituições que negociam ou guardam criptomoedas não são reguladas nem supervisionadas pelo Banco Central do Brasil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825822,"enunciado":"Considerando a evolução tecnológica e as características atuais das criptomoedas, julgue o item a seguir. \n\n\n\n\nAs criptomoedas não estão sujeitas às mesmas normas e regulamentos das moedas eletrônicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825823,"enunciado":"No que se refere às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nNas operações de mercado aberto, o Banco Central atua no mercado secundário para garantir o nível desejado da taxa SELIC.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825824,"enunciado":"No que se refere às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nO Tesouro Nacional, órgão vinculado ao Ministério da Economia, é o responsável pela emissão de moeda no Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825825,"enunciado":"No que se refere às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nOs bancos de desenvolvimento possuem a faculdade de expandir o meio circulante por intermédio da concessão de empréstimos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825826,"enunciado":"No que se refere às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nAs empresas de cartão de crédito não participam do SFN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825827,"enunciado":"Quanto aos principais riscos incorridos pelas instituições financeiras bancárias, julgue o item subsequente.\n\n\n\n\nA constituição de crédito tributário de diferenças temporais decorrente de provisão para suportar o risco das operações de crédito aumenta a capacidade dos bancos em realizar novos empréstimos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825828,"enunciado":"Quanto aos principais riscos incorridos pelas instituições financeiras bancárias, julgue o item subsequente.\n\n\n\n\nPara reduzir a exposição ao risco de mercado e mitigar problemas de crise bancária, as operações de swap cambial não podem ser feitas por bancos comerciais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825829,"enunciado":"Quanto aos principais riscos incorridos pelas instituições financeiras bancárias, julgue o item subsequente.\n\n\n\n\nO risco operacional está relacionado à possibilidade de funcionário entrar com ação trabalhista contra a instituição empregadora.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825830,"enunciado":"Quanto aos principais riscos incorridos pelas instituições financeiras bancárias, julgue o item subsequente.\n\n\n\n\nAs instituições não alocam capital para a cobertura do risco de liquidez.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825832,"enunciado":"Considerando as novas inovações promovidas pelo open banking e pelo sistema de pagamentos do PIX, julgue o próximo item.\n\n\n\n\nO PIX consiste na plataforma pública na qual os bancos fazem transações diretas e instantâneas com clientes e usuários.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825833,"enunciado":"Considerando as novas inovações promovidas pelo open banking e pelo sistema de pagamentos do PIX, julgue o próximo item.\n\n\n\n\nO open banking reduz a exposição ao risco operacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825971,"enunciado":"O Registrato é um sistema criado em 2014 e administrado pelo Banco Central, que permite aos cidadãos terem acesso pela internet a relatórios contendo informações sobre","opcoes":["seus relacionamentos com as instituições financeiras, suas operações de crédito e operações de câmbio.","suas receitas e despesas realizadas em todas as instituições financeiras onde têm conta-corrente.","seus dados registrados junto aos serviços de proteção de crédito.","seus relacionamentos interpessoais com pessoas da mesma família (ex: pai, filho e irmão, entre outros) que também possuem contas-correntes.","seus contratos de prestação de serviço firmados na esfera cível."],"correta":0,"explicacao":"Gabarito: <strong>seus relacionamentos com as instituições financeiras, suas operações de crédito e operações de câmbio.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825972,"enunciado":"Um token físico, no contexto de transações bancárias, é um dispositivo eletrônico que possui um botão de ativação e um pequeno visor. O token permite gerar senhas aleatórias, temporárias e numéricas (por exemplo, de seis dígitos). Essa senha é utilizada para dar mais segurança às transações bancárias realizadas via internet. No passado, os bancos comerciais disponibilizavam esses pequenos dispositivos aos seus clientes, de modo que pudessem ser afixados a um chaveiro. Mais recentemente, nos últimos 10 anos, esses dispositivos foram sendo gradativamente substituídos para a grande maioria dos clientes, por um","opcoes":["dispositivo que continua com apenas essa funcionalidade, porém um pouco maior, mas que ainda assim cabe em um bolso de camisa.","aplicativo de cada banco, instalado e configurado no celular do correntista.","porta-moedas eletrônico, semelhante aos cartões que dão acesso a meios de transporte.","cartão de crédito que permite autorizar operações por aproximação.","sensor específico para captura de impressões digitais."],"correta":1,"explicacao":"Gabarito: <strong>aplicativo de cada banco, instalado e configurado no celular do correntista.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825973,"enunciado":"A partir do início de 2021, começou a primeira fase de implantação do open banking (sistema financeiro aberto) no Brasil. As instituições financeiras participantes devem obedecer a regras definidas pelo Banco Central e pelo Conselho Monetário Nacional. O open banking tem, entre outros, o objetivo de","opcoes":["criar um mercado eletrônico exclusivo para operação das fintechs.","permitir que mais instituições participem como bancos comerciais do mercado brasileiro, abrindo esse mercado.","possibilitar o compartilhamento de informações, mediante autorização expressa de cada cliente, e a movimentação de suas respectivas contas bancárias, entre diferentes instituições financeiras.","controlar as operações de concessão de crédito de cada instituição financeira participante autorizada pelo Banco Central, dando mais transparência ao setor.","recomendar a utilização de um sistema de informações único, de código aberto, para gestão de contas-correntes e suas movimentações, de modo a ser adotado por todas as instituições financeiras em operação no Brasil."],"correta":2,"explicacao":"Gabarito: <strong>possibilitar o compartilhamento de informações, mediante autorização expressa de cada cliente, e a movimentação de suas respectivas contas bancárias, entre diferentes instituições financeiras.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825974,"enunciado":"Uma investidora está querendo saber a relação entre a blockchain e o bitcoin. Em sua pesquisa, ela esclareceu sua dúvida, ao descobrir que","opcoes":["blockchain é o meio utilizado para registrar e armazenar transações de bitcoin.","blockchain é a tecnologia de inteligência artificial aplicada na bitcoin.","bitcoin é uma moeda digital e blockchain é uma moeda em blocos.","bitcoin é tecnologia usada para implementar a blockchain.","bitcoin e blockchain são duas formas de implementar criptomoedas."],"correta":0,"explicacao":"Gabarito: <strong>blockchain é o meio utilizado para registrar e armazenar transações de bitcoin.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825980,"enunciado":"No Brasil, o órgão responsável pela fiscalização do Sistema Financeiro Nacional é o","opcoes":["Conselho Monetário Nacional","Ministério da Economia","Banco Central do Brasil","Banco do Brasil","Banco Nacional de Desenvolvimento Econômico e Social (BNDES)"],"correta":2,"explicacao":"Gabarito: <strong>Banco Central do Brasil</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825983,"enunciado":"Com evidências do enorme descolamento entre as taxas de juros de curto e de longo prazo no Brasil, o texto abaixo reproduz matéria jornalística, publicada no início de agosto de 2020, dando conta da enorme incerteza futura associada aos impactos adversos decorrentes da crise pandêmica da Covid-19 sobre a economia brasileira. Os juros futuros encerraram os negócios desta segunda-feira em alta firme, afetados por um movimento de maior incorporação de prêmio de risco ao longo da curva a termo, especialmente nos trechos mais longos (com vencimento no longo prazo). No fim da sessão regular, a taxa do contrato de Depósito Interfinanceiro (DI) para janeiro de 2021 passava de 1,87% no ajuste anterior para 1,88%; a do DI para janeiro de 2022 ia de 2,65% para 2,67%; a do contrato para janeiro de 2023 subia de 3,76% para 3,79%; a do DI para janeiro de 2025 escalava de 5,40% para 5,47%; e a do contrato para janeiro de 2027 saltava de 6,35% para 6,43%. REZENDE, V. Risco fiscal leva a alta das taxas de juros futuros e curva tem maior inclinação desde fim de junho. Valor Econômico, 10/08/2020. Disponível em: <https://valorinveste.globo.com/produtos/renda-fixa/noticia/2020/08/10/risco-fiscal-leva-a-alta--das-taxas-de-juros-futuro-e-curva-tem-maior-inclinacao-desde--fim-de-junho.ghtml>. Acesso em: 7 fev. 2021. Adaptado. Para minorar os impactos da crise, a Emenda Constitucional n° 106, de 7 de maio de 2020, conhecida como o “Orçamento de Guerra”, instituiu uma diversidade de medidas nos âmbitos fiscal, financeiro e de contratações para enfrentamento da calamidade pública nacional, decorrente da pandemia da Covid-19. Dentre as medidas aprovadas, o Banco Central do Brasil ficou autorizado, temporariamente, a operar com instrumentos de política monetária considerados não convencionais. A medida de política monetária não convencional, por parte do Banco Central do Brasil, que poderia ter estimulado a redução das taxas de juros de longo prazo no ano passado é a","opcoes":["redução da taxa de juros básica de curto prazo (Selic)","venda de títulos públicos e privados no mercado secundário","compra de títulos públicos e privados no mercado secundário","redução do percentual dos depósitos compulsórios","venda de títulos mediante operações compromissadas"],"correta":2,"explicacao":"Gabarito: <strong>compra de títulos públicos e privados no mercado secundário</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825984,"enunciado":"Dentre as escolhas mais populares de investimentos, a caderneta de poupança é uma das opções mais utilizadas pelos brasileiros, sendo considerada um investimento de renda fixa. São também investimentos de renda fixa","opcoes":["as Ações","as Opções","as Commodities","os CDB","os ETF de Ações"],"correta":3,"explicacao":"Gabarito: <strong>os CDB</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825985,"enunciado":"O Banco do Brasil (BB) oferece diversas linhas de crédito destinadas a custear os dispêndios realizados pelos produtores rurais. A modalidade de crédito rural, oferecida pelo BB, destinada ao beneficiamento, custeio e industrialização da produção é denominada","opcoes":["Funcafé Custeio","Custeio Agropecuário","Pronamp Custeio","Pronaf Agroindústria","Crédito Rural Pronaf Custeio"],"correta":3,"explicacao":"Gabarito: <strong>Pronaf Agroindústria</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825986,"enunciado":"O anúncio seguinte constava no site do Banco do Brasil no dia 8 de fevereiro de 2021: Financiamento de veículos Financie o seu veículo, novo ou usado, com as melhores opções e taxas reduzidas até 28 de fevereiro. Durante a promoção, é possível financiar* carros novos e seminovos (até 2 anos de fabricação) com condições diferenciadas. Você pode fazer tudo sem precisar comparecer a uma agência. Basta acessar o App BB para simular as condições, escolher a opção que se encaixa no seu orçamento e finalizar a contratação com o envio dos documentos. *Crédito sujeito à aprovação cadastral e demais condições do produto. Banco do Brasil. Disponível em:<https://www.bb.com.br/pbb/pagina-inicial/voce/produtos-e-servicos/financiamentos/financiar--veiculos#/> . Acesso em: 8 fev. 2021. A nota descrita em asterisco (*) destaca que, além da análise cadastral, a aprovação do crédito está sujeita às “demais condições do produto”. Uma dessas condições diz respeito à garantia do financiamento que, no caso supramencionado, será o próprio veículo a ser comprado pelo devedor. Trata-se de uma forma de garantia denominada","opcoes":["alienação fiduciária","aval","penhor mercantil","fiança","hipoteca"],"correta":0,"explicacao":"Gabarito: <strong>alienação fiduciária</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825987,"enunciado":"A revista inglesa The Economist publica periodicamente o famoso Índice do Big Mac, que consiste em avaliar os preços, em dólares, do conhecido sanduíche em diferentes países na economia global. Os resultados são frequentemente replicados pela imprensa internacional, incluindo a brasileira. A metodologia de apuração é simples: com base nas taxas de câmbio nominais das moedas nacionais em relação ao dólar, cotadas num mesmo dia, converte-se o preço do Big Mac avaliado nessas moedas para o seu respectivo valor em dólares. Considerando-se que na edição de 12 de janeiro de 2021, os cálculos da The Economist mostravam que o preço, em dólares, do Big Mac no Brasil estava cerca de 30% mais barato do que o sanduíche similar vendido e cotado, também em dólares, nos Estados Unidos, o resultado indicava que o real brasileiro estava","opcoes":["valorizado em relação ao dólar","sobrevalorizado em relação ao dólar","subvalorizado em relação ao dólar","com alinhamento nominal em relação ao dólar","na paridade real do poder de compra em relação ao dólar"],"correta":2,"explicacao":"Gabarito: <strong>subvalorizado em relação ao dólar</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1825988,"enunciado":"H é correntista da instituição financeira XYZ e mantém com esta instituição relação estável, com movimentação de recursos monetários correspondente a cem salários mínimos por ano. A partir de 2019, sua movimentação anual passou a ser de mil e duzentos salários mínimos, com aportes mensais de cem salários mínimos. A partir das regras apresentadas na Carta-Circular n° 4001/2020 do Banco Central do Brasil, nesse caso, as operações devem ser monitoradas como situações relacionadas com operações em espécie, em moeda nacional, com a utilização de contas de","opcoes":["aplicações","depósitos","fundos","garantia","preferência"],"correta":1,"explicacao":"Gabarito: <strong>depósitos</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1826005,"enunciado":"Atualmente, os sistemas de informação fornecem dados pormenorizados a respeito dos clientes em potencial, o que permite o planejamento de ações customizadas de vendas, tais como","opcoes":["apuração dos valores de divulgação em canais de rádio e tevê.","aumento do custo de aquisição pelos produtos adquiridos.","divulgação de ferramentas digitais como QR code e hot sites.","propostas de descontos em série para o público em geral.","postagens nas mídias sociais segundo os temas de interesse dos usuários"],"correta":4,"explicacao":"Gabarito: <strong>postagens nas mídias sociais segundo os temas de interesse dos usuários</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1826006,"enunciado":"Poucos clientes conhecem suficientemente o mercado financeiro, de modo a avaliar se o seu analista de investimentos conseguiu os melhores retornos para os seus fundos investidos. Sendo assim, verifica-se que este serviço é rico em atributos de","opcoes":["procura e resiliência","tangibilidade e variabilidade","confiança e experiência","risco sensorial e psicológico","risco social e temporal"],"correta":2,"explicacao":"Gabarito: <strong>confiança e experiência</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1826009,"enunciado":"Sr. X precisava planejar a comercialização de um serviço para um cliente exigente, que demanda a personalização e o serviço de alto contato. Para isso, ele planejou em sua estratégia comercial","opcoes":["reduzir a variação nas operações e na entrega do serviço.","garantir a intangibilidade do processo do serviço.","encorajar o cliente a realizar operações por internet ou caixa automático.","introduzir sofisticada rede de canais de distribuição eletrônicos.","interagir pessoalmente com o cliente ao longo da prestação do serviço."],"correta":4,"explicacao":"Gabarito: <strong>interagir pessoalmente com o cliente ao longo da prestação do serviço.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1826014,"enunciado":"As empresas, cada vez mais, procuram gerir seus negócios e suas atividades de forma que sua posição seja neutra ou positiva no atendimento ao Tripé da Sustentabilidade. Como a empresa YYZ não pensa de modo diferente, contratou consultores para levantarem os impactos gerados pelas atividades por ela desenvolvidas em sua prestação de serviços. Os consultores constataram os seguintes pontos: a política de capacitação da empresa ampliou a formação de 45% dos funcionários, a instalação de painéis fotovoltaicos fez com que toda a energia consumida pela empresa, naquele ano, fosse gerada a partir de fonte renovável, a taxa de reciclagem de resíduos cresceu 50% e, além disso, a empresa obteve lucro acima da média histórica e distribuiu bônus aos funcionários e fornecedores alinhados à preservação ambiental. Com base nesses dados, o diagnóstico dos consultores foi de que a empresa exerce impacto líquido positivo sobre o Tripé da Sustentabilidade. Dessa forma, em relação ao Tripé da Sustentabilidade, a YYZ é classificada como um negócio","opcoes":["neutro","reparador","sustentável","fundamental","insustentável"],"correta":1,"explicacao":"Gabarito: <strong>reparador</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1826015,"enunciado":"O cliente da empresa W, procurando um produto no site dessa empresa, ficou em dúvida a respeito das suas especificações técnicas, entrou no chat online para conhecer mais a respeito do equipamento e teve suas dúvidas sanadas. Naquele momento, não efetuou a compra, mas uma semana depois baixou o aplicativo W e, mesmo sem voltar ao site da empresa, passou a receber informações a respeito das mudanças de preço do produto que tinha procurado anteriormente. No final do mês, com o recebimento de seu salário, decidiu novamente acionar o aplicativo e realizar a compra. Como queria economizar no frete, decidiu pela retirada do produto na loja física próxima de sua casa. Alguns dias depois, recebeu uma mensagem em seu smartphone indicando que já poderia ir à loja recolher sua encomenda. Na semana seguinte, o cliente recebeu uma mensagem com o pedido de avaliação de sua compra e respondeu dando nota 9 ao atendimento feito pela empresa. Nesse caso, identifica-se que a empresa W utiliza um modelo de negócios denominado","opcoes":["Rede","Multinível","Multicanal","Horizontal","Omnichannel"],"correta":4,"explicacao":"Gabarito: <strong>Omnichannel</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1826016,"enunciado":"LL é aposentada pelo regime geral de previdência, recebendo o valor correspondente através de repasse do Instituto Nacional do Seguro Social (INSS). Três meses após receber a primeira parcela de sua aposentadoria, recebe, por telefone, várias ofertas de empréstimos mediante consignação em folha. Após consultar familiares, LL não aceita qualquer empréstimo. Para sua surpresa, dois meses após, o comprovante de pagamento de sua aposentadoria é remetido, constando desconto em decorrência de empréstimo consignado. Tendo em vista o fato, dirige-se à agência do INSS que lhe informa qual banco requereu a inscrição do empréstimo para pagamento mediante consignação. A aposentada apresenta requerimento ao banco para apresentar os documentos pertinentes ao empréstimo, sem qualquer resposta. Nos termos da Resolução CMN n° 3.694/2009, as instituições financeiras, na contratação de operações e na prestação de serviços, devem assegurar","opcoes":["fornecimento de contratos e documentos pertinentes aos atos praticados","composição dos danos causados, desde que por ordem judicial","declarações de idoneidade moral e financeira","divulgação de cadastros positivos ou negativos requeridos por fornecedores","recebimento de documentos de forma física, mesmo em dependência exclusivamente eletrônica"],"correta":0,"explicacao":"Gabarito: <strong>fornecimento de contratos e documentos pertinentes aos atos praticados</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1826017,"enunciado":"KO é gerente Júnior de um banco e atua no contato direto com os clientes que têm pouca experiência na atividade de investimentos financeiros. Buscando promoção no quadro interno da instituição financeira, o gerente realiza vários cursos de atualização, inclusive de educação financeira. Munido desses conhecimentos, ele contata os correntistas sob sua responsabilidade e oferece indicações sobre como investir. Os clientes compõem diversos segmentos econômicos, e alguns não possuem renda para propiciar saldos destinados a investimentos no momento em que são contatados. O supervisor de KO identifica essa situação e o adverte da perda de tempo com clientes que não gerariam lucros imediatos ao banco. Nos termos da Resolução n° 4.539, de 24 de novembro de 2016, verifica-se que a instituição financeira","opcoes":["deve privilegiar os clientes que gerem recursos imediatos.","deve apresentar a todos os clientes os produtos financeiros disponíveis.","deve preocupar-se com a formação de clientela futura.","pode criar segmentos especiais para atendimento privilegiado e secreto.","pode discriminar seus clientes livremente, analisando sua renda como dado essencial para produzir lucro."],"correta":1,"explicacao":"Gabarito: <strong>deve apresentar a todos os clientes os produtos financeiros disponíveis.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1826018,"enunciado":"A partir da análise do banco de dados da agência, o atendente bancário pode realizar vendas sugestivas, identificando as informações sobre o cliente para","opcoes":["diminuir os juros cobrados dos correntistas.","informar sobre a carga tributária dos investimentos.","propor o acesso a novos produtos do banco.","retirar os dados do mailing da companhia.","sugerir mudanças no horário das visitas à agência."],"correta":2,"explicacao":"Gabarito: <strong>propor o acesso a novos produtos do banco.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827392,"enunciado":"Com relação a modelagem de processos de negócio, julgue o item a seguir.\n\n\n\n\nA natureza sequencial, em que atividades são executadas consecutivamente para transformar insumos em resultados, é a principal característica dos processos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827393,"enunciado":"Com relação a modelagem de processos de negócio, julgue o item a seguir.\n\n\n\n\nProcessos de negócio são aqueles gerados internamente na organização e que envolvem um setor específico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827394,"enunciado":"Com relação a modelagem de processos de negócio, julgue o item a seguir.\n\n\n\n\nEm processos de negócio, o foco é tradicionalmente orientado ao cliente em detrimento da chefia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827395,"enunciado":"Com relação a modelagem de processos de negócio, julgue o item a seguir.\n\n\n\n\nNo mapeamento de processos de negócios, o nível estratégico é o que agrega tarefas e atividades.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827396,"enunciado":"Com relação a modelagem de processos de negócio, julgue o item a seguir.\n\n\n\n\nComparabilidade é um fator a ser considerado quando se estabelecem indicadores de processos para que se possa comparar o desempenho de um processo com o de outros processos semelhantes na própria organização e, também, em organizações similares.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827397,"enunciado":"Com relação a modelagem de processos de negócio, julgue o item a seguir.\n\n\n\n\nAutomatização de processos se refere à incorporação de técnicas de inteligência artificial e aprendizado de máquina à gestão de processos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827412,"enunciado":"Acerca das principais legislações que impactam o atendimento, a negociação e as vendas nas organizações brasileiras, julgue o item que se segue.\n\n\n\n\nAs instituições financeiras autorizadas a funcionar no Brasil são obrigadas a disponibilizar aos clientes meios para o cancelamento de seus contratos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827426,"enunciado":"Considerando a evolução tecnológica e as características atuais das criptomoedas, julgue o item a seguir.\n\n\n\n\nAs criptomoedas conseguem exercer plenamente a função de meio de troca.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827427,"enunciado":"Considerando a evolução tecnológica e as características atuais das criptomoedas, julgue o item a seguir.\n\n\n\n\nAs criptomoedas possuem a função de unidade de conta da moeda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827428,"enunciado":"Considerando a evolução tecnológica e as características atuais das criptomoedas, julgue o item a seguir.\n\n\n\n\nAs criptomoedas são superiores a outros ativos tradicionais nos quesitos reserva de valor e prêmio de liquidez.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827429,"enunciado":"No que concerne às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nA Casa da Moeda possui a função de emitir moeda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827430,"enunciado":"No que concerne às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nAo conceder empréstimos a pessoas jurídicas, o Banco Nacional de Desenvolvimento Econômico e Social (BNDES) cria moeda escritural.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827431,"enunciado":"No que concerne às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nAs emissões de debêntures são registradas como operações passivas das empresas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827432,"enunciado":"No que concerne às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nO Banco Central do Brasil fiscaliza instituições fora do escopo do SFN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827433,"enunciado":"No que concerne às instituições e ao funcionamento do Sistema Financeiro Nacional (SFN), julgue o item que se segue.\n\n\n\n\nNas operações de fusão e aquisição no âmbito do SFN, o Banco Central possui competência para autorizar alterações de controle acionário, independentemente de posicionamento prévio da Receita Federal do Brasil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827434,"enunciado":"Em relação aos principais riscos incorridos pelas instituições financeiras bancárias, julgue o item seguinte.\n\n\n\n\nOs bancos alocam capital de acordo com o conceito do conglomerado econômico-financeiro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827435,"enunciado":"Em relação aos principais riscos incorridos pelas instituições financeiras bancárias, julgue o item seguinte.\n\n\n\n\nOs bancos calculam a alocação de capital para a cobertura do risco operacional com base no volume de perdas incorridas nos três anos anteriores.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827436,"enunciado":"Em relação aos principais riscos incorridos pelas instituições financeiras bancárias, julgue o item seguinte.\n\n\n\n\nO risco de mercado compõe os riscos com foco primordial das ações de supervisão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827437,"enunciado":"Considerando as novas inovações promovidas pelo open banking e pelo sistema de pagamentos do PIX, julgue o item subsequente.\nO open banking compartilha dados de clientes com o objetivo de aumentar a concorrência bancária.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827438,"enunciado":"Considerando as novas inovações promovidas pelo open banking e pelo sistema de pagamentos do PIX, julgue o item subsequente.\n\n\n\n\nO open banking está restrito aos bancos com carteira comercial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827439,"enunciado":"Considerando as novas inovações promovidas pelo open banking e pelo sistema de pagamentos do PIX, julgue o item subsequente.\n\n\n\n\nO PIX está inserido no contexto do open banking e ameaça a receita de prestação de serviços dos bancos tradicionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827440,"enunciado":"Considerando as hipóteses e resultados relacionados ao modelo Black e Scholes, julgue o item a seguir.\n\n\n\n\nO modelo pressupõe que não existem custos de transações associados à gestão do portfólio.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827441,"enunciado":"Considerando as hipóteses e resultados relacionados ao modelo Black e Scholes, julgue o item a seguir.\n\n\n\n\nO modelo assume um componente determinístico e outro estocástico, o qual segue uma distribuição normal de probabilidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827443,"enunciado":"Considerando as operações de financiamento imobiliário, julgue o próximo item.\n\n\n\n\nNo sistema Price, as primeiras parcelas são sempre menores que as primeiras parcelas contratadas no sistema SAC.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827444,"enunciado":"Com relação aos principais instrumentos, normas e características relacionadas às operações de crédito e seus riscos, julgue o item que se segue.\n\n\n\n\nPara realizar uma operação de desconto comercial ou bancário, o banco precisa conhecer a taxa de desconto e o valor nominal do título.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827445,"enunciado":"Com relação aos principais instrumentos, normas e características relacionadas às operações de crédito e seus riscos, julgue o item que se segue.\n\n\n\n\nAntes da implementação do Sistema de Pagamentos Brasileiro (SPB), o Banco Central incorria em eventual risco de crédito decorrente de inadimplência de instituição participante.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827446,"enunciado":"No que se refere à abertura e ao encerramento de conta-corrente, julgue o item subsecutivo. \n\n\n\n\nÉ proibida a abertura de conta-corrente para agente com inscrição no Cadastro de Emitentes de Cheques sem Fundos (CCF).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827447,"enunciado":"No que se refere à abertura e ao encerramento de conta-corrente, julgue o item subsecutivo. \n\n\n\n\nO pedido de encerramento de conta de depósitos deve ser acatado mesmo na hipótese de existência de cheques sustados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827449,"enunciado":"Em uma análise financeira, foi modelado que os valores das despesas mensais e das receitas mensais de uma empresa podem, por determinado período, ser descritos pelas funções D(t) e R(t), respectivamente, cujas expressões são dadas a seguir:\n\n\n\n\n\n\n\nem que t, dado em meses, varia no intervalo [1, 24] e os valores de D(t) e de R(t) são expressos em milhões de reais. Nesse contexto, t = 1 representa o primeiro mês considerado na análise, t = 2 representa o segundo mês e assim sucessivamente. Com base nessas informações, julgue o item seguinte.\n\n\n\n\nNo período compreendido entre o 6.º mês e o 11.º mês da análise, de acordo com o modelo formulado, a despesa foi sempre superior à receita.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827450,"enunciado":"Em uma análise financeira, foi modelado que os valores das despesas mensais e das receitas mensais de uma empresa podem, por determinado período, ser descritos pelas funções D(t) e R(t), respectivamente, cujas expressões são dadas a seguir:\n\n\n\n\n\n\n\nem que t, dado em meses, varia no intervalo [1, 24] e os valores de D(t) e de R(t) são expressos em milhões de reais. Nesse contexto, t = 1 representa o primeiro mês considerado na análise, t = 2 representa o segundo mês e assim sucessivamente. Com base nessas informações, julgue o item seguinte.\n\n\n\n\nDe acordo com o modelo formulado, mesmo que as despesas correspondentes ao 15.º mês da análise fossem aumentadas em 40%, o resultado seria inferior às receitas correspondentes a esse mês.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827451,"enunciado":"Em uma análise financeira, foi modelado que os valores das despesas mensais e das receitas mensais de uma empresa podem, por determinado período, ser descritos pelas funções D(t) e R(t), respectivamente, cujas expressões são dadas a seguir:\n\n\n\n\n\n\n\nem que t, dado em meses, varia no intervalo [1, 24] e os valores de D(t) e de R(t) são expressos em milhões de reais. Nesse contexto, t = 1 representa o primeiro mês considerado na análise, t = 2 representa o segundo mês e assim sucessivamente. Com base nessas informações, julgue o item seguinte.\n\n\n\n\nA figura seguinte apresenta corretamente uma representação gráfica das funções D(t) e R(t).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827471,"enunciado":"Acerca do sigilo bancário, da proteção de dados pessoais e marco civil da Internet, julgue o item a seguir.\n\n\n\n\nConstitui violação do dever de sigilo a troca de informações entre instituições financeiras, para fins cadastrais, ainda que observadas as normas baixadas pelo Conselho Monetário Nacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827472,"enunciado":"Acerca do sigilo bancário, da proteção de dados pessoais e marco civil da Internet, julgue o item a seguir.\n\n\n\n\nServidor público que utilizar informação obtida em decorrência da quebra de sigilo de operação de instituição financeira poderá responder pessoal e diretamente pelos danos recorrentes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1827473,"enunciado":"Acerca do sigilo bancário, da proteção de dados pessoais e marco civil da Internet, julgue o item a seguir.\n\n\n\n\nÉ vedado ao poder público transferir a entidades privadas dados pessoais constantes na base de dados a que ele tenha acesso, inclusive na hipótese de visar exclusivamente a prevenção de fraudes e irregularidades.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829790,"enunciado":"A cliente de um banco está chateada com as taxas bancárias sobre as suas transações e para manter a sua conta -corrente. Ela está pensando em investir em criptomoedas para ter mais domínio sobre o seu dinheiro e não pagar tantas taxas. As criptomoedas válidas que ela tem para investir neste momento são","opcoes":["zen e bitemoeda","bitcoin e tokecardume","bitcoin e bitemoeda","bitcoin e ethereum","ethereum e tokecardume"],"correta":3,"explicacao":"Gabarito: <strong>bitcoin e ethereum</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829791,"enunciado":"As startups têm transformado os negócios. Um dos motivos para isso é que elas","opcoes":["são ágeis, sempre vendem os seus produtos mais barato e visam a tornar-se um unicórnio.","inovam, transformam processos e têm potencial de rápido crescimento.","sempre são compradas com valores mais baixos que o mercado.","sempre possuem aplicativos para agilizar suas operações.","são sempre empresas de internet."],"correta":1,"explicacao":"Gabarito: <strong>inovam, transformam processos e têm potencial de rápido crescimento.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829792,"enunciado":"Quando alguém vai a um shopping center pode observar que uma saia, por exemplo, apresenta o preço de R$40,00 e uma garrafa d’água, o preço de R$5,00. Apesar de não ser errado afirmar que o preço da saia são oito garrafas d’água e que o preço da garrafa d’água é 1/8 do preço da saia, os preços não costumam ser cotados assim. Quando se deseja mensurar e registrar valor econômico, usa-se a moeda como","opcoes":["meio de troca","reserva de valor","riqueza","unidade de conta","valor intrínseco"],"correta":3,"explicacao":"Gabarito: <strong>unidade de conta</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829793,"enunciado":"A inserção dos bancos digitais no Sistema Financeiro Nacional acarreta a disseminação de tecnologias e culturas inovadoras, dentre as quais merece menção o (a)","opcoes":["maior contato físico entre bancos e clientes","dispensa do armazenamento de dados dos clientes","uso de inteligência artificial","generalização de plataformas off-line","utilização mínima de big-data"],"correta":2,"explicacao":"Gabarito: <strong>uso de inteligência artificial</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829794,"enunciado":"Considere o texto a seguir, retirado de Relatório do Banco Central do Brasil. No sistema financeiro mundial, existem muitas entidades que oferecem serviços de intermediação financeira, mas funcionam à margem do sistema de supervisão e regulação bancária. No Relatório de Estabilidade Financeira, de 2015, o Banco Central do Brasil (BCB) estima o valor total dos ativos dessas entidades no país e adverte que elas podem “ser fonte de risco sistêmico, por envolver, sem a devida supervisão e regulação, riscos tipicamente bancários, tais como alavancagem, transformações de maturidade e de liquidez e transferência de risco de crédito”. BRASIL. Banco Central do Brasil. Relatório de Estabilidade Financeira, v.14, n.1. Brasília: Banco Central do Brasil, mar. 2015, p.33. Disponível em: <https://www.bcb.gov.br/publicacoes/ref/201503>. Acesso em: 24 jul. 2021. As entidades financeiras descritas formam o sistema denominado","opcoes":["shadow banking","internet banking","open banking","mobile banking","blockchain"],"correta":0,"explicacao":"Gabarito: <strong>shadow banking</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829800,"enunciado":"As relações internacionais implicam relações de trocas entre as moedas, ou seja, a variável econômica conhecida como taxa de câmbio. Assim, quanto mais valorizada for a moeda de um país, menor será o poder de competitividade do produto desse país, piorando o saldo em transações correntes. Nesse sentido, uma valorização cambial","opcoes":["desestimula tanto as importações quanto as exportações, mas com uma desvalorização cambial ocorre o inverso.","desestimula as importações e estimula as exportações, e com uma desvalorização cambial ocorre o mesmo.","desestimula as importações e estimula as exportações, mas com uma desvalorização cambial ocorre o inverso.","estimula as importações e desestimula as exportações, e com uma desvalorização cambial ocorre o mesmo.","estimula as importações e desestimula as exportações, mas com uma desvalorização cambial ocorre o inverso."],"correta":4,"explicacao":"Gabarito: <strong>estimula as importações e desestimula as exportações, mas com uma desvalorização cambial ocorre o inverso.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829801,"enunciado":"A relação entre a mudança de percentual na taxa de câmbio à vista, ao longo do tempo, e o diferencial entre taxas de juros comparáveis em diferentes mercados de capitais nacionais é conhecida como o efeito Fisher internacional. O Fisher-open, como é frequentemente chamado, indica que as taxas de câmbio à vista devem mudar em uma quantidade","opcoes":["diferente, mas em direção oposta à diferença nas taxas de juros entre dois países.","diferente, mas na mesma direção da diferença nas taxas de juros entre dois países","desconhecida, mas na mesma direção da diferença nas taxas de juros entre dois países.","igual, mas em direção oposta à diferença nas taxas de juros entre dois países.","igual, mas na mesma direção da diferença nas taxas de juros entre dois países."],"correta":3,"explicacao":"Gabarito: <strong>igual, mas em direção oposta à diferença nas taxas de juros entre dois países.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829802,"enunciado":"No mercado de capitais brasileiro, os principais responsáveis pela intermediação de compra e venda de títulos e valores mobiliários entre investidores e tomadores de recursos são as(os)","opcoes":["corretoras e distribuidoras","bolsas de valores","companhias abertas","empresas de auditoria","auditores da Comissão de Valores Mobiliários (CVM)"],"correta":0,"explicacao":"Gabarito: <strong>corretoras e distribuidoras</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829803,"enunciado":"Com a pandemia, observou-se intensa volatilidade das taxas de câmbio cotadas nos mercados de câmbio à vista no Brasil. Segundo dados do Banco Central do Brasil, a taxa de câmbio média negociada nos mercados à vista foi de R$5,46/US$ em agosto de 2020, comparativamente à taxa média de R$5,28/US$, observada em julho desse mesmo ano. Sendo assim, constata-se que, entre julho e agosto de 2020, o Real brasileiro mostrou, em relação ao Dólar norte-americano,","opcoes":["apreciação média de cerca de 3,41%, em termos nominais","apreciação média de cerca de 3,41%, em termos reais","depreciação média de cerca de 3,41%, em termos nominais","depreciação média de cerca de 3,41%, em termos reais","a mesma paridade nominal do poder de compra"],"correta":2,"explicacao":"Gabarito: <strong>depreciação média de cerca de 3,41%, em termos nominais</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829804,"enunciado":"É função precípua da Tesouraria, em um determinado banco,","opcoes":["acompanhar as operações em atraso, visando à instauração do processo de recuperação de crédito.","estreitar o relacionamento com os clientes do banco.","fixar as formas de garantias exigidas em função dos tipos de operação de crédito.","gerenciar os descasamentos existentes entre os fluxos de caixa das captações e as aplicações do banco.","ativar as atividades de marketing e publicidade do banco."],"correta":3,"explicacao":"Gabarito: <strong>gerenciar os descasamentos existentes entre os fluxos de caixa das captações e as aplicações do banco.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829805,"enunciado":"Considere o seguinte trecho de reportagem publicada no jornal Valor Econômico, em 3 de novembro de 2020: O plenário do Senado aprovou, agora há pouco, um projeto que possibilita ao Banco Central substituir as operações compromissadas pelo depósito voluntário remunerado das instituições financeiras. O texto segue agora para a Câmara dos Deputados. TRUFFI, R.; LIMA, V. Senado aprova projeto que permite ao BC usar depósitos voluntários. Valor Econômico, 3/11/2020. Disponível em: <https://valor.globo.com/politica/noticia/2020/11/03/senado-aprova-projeto-que-permite-ao-bc-utilizar-dispositivos-voluntarios.ghtml> . Acesso em: 27 jan. 2021. O principal argumento em defesa da adoção de depósitos das instituições financeiras, remunerados pelo Banco Central do Brasil (BCB), é que esse mecanismo adicional de política monetária","opcoes":["estimularia a redução das taxas de juros praticadas pelos bancos comerciais.","teria efeito nulo sobre o crescimento da dívida bruta do Tesouro Nacional.","teria efeito nulo sobre as despesas financeiras do BCB.","teria impacto financeiro idêntico ao das operações compromissadas.","fomentaria o sistema de crédito bancário."],"correta":1,"explicacao":"Gabarito: <strong>teria efeito nulo sobre o crescimento da dívida bruta do Tesouro Nacional.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829806,"enunciado":"Um dos fatos mais comemorados pelos analistas econômicos no Brasil foi a queda histórica das taxas de juros básicas de curto prazo (Selic), ocorrida nos últimos três anos. Entre fevereiro de 2018 e janeiro de 2021, a Selic havia recuado de 6,75% a.a. para 2,00% a.a. Considerando-se o arcabouço da política monetária vigente no Brasil, baseado no regime de metas para a inflação, os dois fatores que permitiram tamanha queda dos juros básicos no Brasil no período foram a","opcoes":["redução da dívida bruta do setor público como proporção do PIB e a prolongada recessão ocorrida no período.","queda dos preços das commodities e o menor impacto da desvalorização do real sobre os preços internos.","eficácia dos controles de preços e a melhora das condições externas.","ancoragem das expectativas de inflação e o elevado nível médio de capacidade ociosa registrado na economia brasileira no período.","queda dos preços dos alimentos e a redução dos spreads bancários."],"correta":3,"explicacao":"Gabarito: <strong>ancoragem das expectativas de inflação e o elevado nível médio de capacidade ociosa registrado na economia brasileira no período.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829808,"enunciado":"Com o intuito de incentivar o desenvolvimento de novos negócios voltados às futuras gerações, determinada instituição financeira estabeleceu convênio com duas renomadas instituições nacionais de ensino e pesquisa, possuidoras de organismos internos que incentivam empreendimentos inovadores. Ao final de cada ano, os projetos escolhidos devem receber aporte de recursos para desenvolvimento dos seus produtos. Nos termos da Política de Responsabilidade Socioambiental do Banco do Brasil, o critério que deve ser preponderante na escolha dos vencedores consiste em analisar o mais bem apresentado","opcoes":["custo","rendimento","benefício ambiental","influxo geracional","lucro"],"correta":2,"explicacao":"Gabarito: <strong>benefício ambiental</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829809,"enunciado":"Sr. W é gerente de área do Banco B, tendo-se especializado no setor de mercado de capitais e atuado no lançamento de diversas ações na Bolsa de Valores, sempre conseguindo bater suas metas, diante da quantidade de clientes abonados e afetos ao risco, que sua carteira possui. Sua área também atinge as operações diárias com o oferecimento de consultoria e aplicações. Um dos seus clientes, atuando diretamente na Bolsa, sem sua intermediação, obtém ganho expressivo em única operação, o que gerou a abertura de inquérito administrativo pela Comissão de Valores Mobiliários. Por força de relações pessoais, o responsável pelo inquérito solicita ao gerente W cópias das movimentações financeiras do investigado. Nos Termos da Lei Complementar n° 105/2001, a Comissão de Valores Mobiliários","opcoes":["pode quebrar o sigilo bancário do aplicador em ações no mercado de capitais investigado.","deve requerer, diretamente à instituição financeira conveniada, informações sobre as operações bancárias do investigado.","deve solicitar, à autoridade judiciária competente, o levantamento do sigilo do investigado.","deve oficiar ao Banco Central para compartilhar as informações bancárias do investigado.","tem vedada a possibilidade de obter informações vinculadas ao sigilo bancário do investigado."],"correta":2,"explicacao":"Gabarito: <strong>deve solicitar, à autoridade judiciária competente, o levantamento do sigilo do investigado.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829827,"enunciado":"Para implementar com sucesso uma estratégia de liderança em custos, uma empresa do mercado financeiro, após verificar","opcoes":["a redução do custo de utilização pelo comprador e as características do produto, escolheu um produto considerado único pelos clientes.","a paridade de preço e custo de um serviço, ofereceu um serviço melhor do que o dos concorrentes em termos de atributos técnicos, funcionalidade e confiabilidade.","o aspecto visual e funcional de um produto, ofereceu ao mercado um produto diferente e singular, com características distintas dos produtos concorrentes.","os esforços de redução de custos quanto à sustentabilidade, fez com que seu custo total fosse menor do que o de seus concorrentes.","as preferências dos potenciais compradores de um serviço, atendeu melhor ao seu alvo estratégico do que aos concorrentes do setor."],"correta":3,"explicacao":"Gabarito: <strong>os esforços de redução de custos quanto à sustentabilidade, fez com que seu custo total fosse menor do que o de seus concorrentes.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829829,"enunciado":"A elevada competitividade do mercado vem definindo novas formas de atuação dos bancários, que passam a ser avaliados por fatores como o(a)","opcoes":["nível de desculpas aos gerentes.","relacionamento com seus familiares.","número de reclamação de seus clientes.","regra de Pareto (80/20).","frequência com que alcançam metas."],"correta":4,"explicacao":"Gabarito: <strong>frequência com que alcançam metas.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829830,"enunciado":"Ao implantar ações para reduzir os custos (inclusive os não financeiros) nas transações dos clientes, os diretores de um banco têm o objetivo de","opcoes":["multiplicar o número de agências por estado.","dividir a atenção prestada pelos colaboradores.","diminuir os benefícios ofertados ao mercado.","ampliar a arrecadação de taxas administrativas.","aumentar o valor percebido pelos clientes."],"correta":4,"explicacao":"Gabarito: <strong>aumentar o valor percebido pelos clientes.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829831,"enunciado":"MX abre o aplicativo de seu banco em seu smartphone e tem a grata surpresa de constatar que a família chegou ao final do mês com algum dinheiro sobrando na conta conjunta que ela tem com seu marido, JV. Como eles não têm dívidas e não estão precisando realizar nenhuma compra, ela pensa em depositar o dinheiro na caderneta de poupança. Sabendo que seu marido estaria em intervalo de almoço, telefona para ele e pede: “vá à agência e solicite a aplicação do saldo de nossa conta na poupança”. JV foi à agência bancária e procurou seu gerente, manifestando o desejo de investir na poupança e ele lhe propôs: “Que tal aplicar em CDBs? Renderá mais e é tão seguro quanto a poupança.” JV seguiu a sugestão do gerente e aplicou o dinheiro em CDBs. Chegando a casa, ele encontrou sua cunhada e seu sobrinho conversando com MX e lhes contou a respeito da aplicação. A cunhada disse que também aplicava em CDBs. O sobrinho, contudo, discordou da escolha e defendeu aplicações mais arrojadas. Considerando os papéis de compra do consumidor, nesse caso, quem exerceu o papel decisor foi","opcoes":["MX","JV","o gerente","o sobrinho","a cunhada"],"correta":1,"explicacao":"Gabarito: <strong>JV</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829833,"enunciado":"O portfólio de fundos de investimento de um banco é formado por fundos de investimentos conservadores, moderados e arrojados. Segundo o diretor desse banco, os fundos conservadores são adequados para pessoas que preferem investir em fundos com baixo risco, pois têm pouca experiência em investimentos. Os fundos moderados são adequados para pessoas que já têm experiência em investimentos e conhecem melhor o mercado financeiro. Os investidores de fundos arrojados são mais experientes e não se abalam com eventuais variações nos rendimentos de suas aplicações porque entendem a dinâmica do mercado financeiro. Nesse caso, verifica-se que a oferta de fundos de investimento do banco é baseada na segmentação","opcoes":["afetiva","geográfica","demográfica","experimental","comportamental"],"correta":4,"explicacao":"Gabarito: <strong>comportamental</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1829837,"enunciado":"Para que o gestor de um banco implemente uma estratégia de posicionamento por diferenciação, visando à geração de valor superior para o cliente, deve-se buscar alinhamento entre elementos referentes à estrutura organizacional, sistemas de controle e políticas de incentivo. Assim, ao construir soluções orientadas a essa estratégia, é importante que ele identifique oportunidades relacionadas a","opcoes":["criação de equipes interfuncionais, recompensadas por assumir riscos, e ao desenvolvimento de produtos inovadores.","estrutura enxuta, com sistemas de controle de custos estreitos e com foco na estabilidade financeira.","produção eficiente, focada em melhoria de processos e princípios contábeis conservadores.","margens baixas, preços baixos, atuação em mercados amplos e realizando extensões de produto.","estruturas simples, com autoridade decisória centralizada e produção visando ganhos de escala."],"correta":0,"explicacao":"Gabarito: <strong>criação de equipes interfuncionais, recompensadas por assumir riscos, e ao desenvolvimento de produtos inovadores.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830865,"enunciado":"Uma pessoa estava querendo fazer um empréstimo e descobriu que algumas instituições que praticam o shadow banking (“sistema bancário sombra”) geralmente servem como intermediários entre credores e tomadores de empréstimos, fornecendo crédito e capital para investidores e corporações. Ao fazer uso dessas instituições para fazer um empréstimo, a pessoa incorre em riscos?","opcoes":["Não, pois vai ter toda a assessoria para fazer o empréstimo.","Não, pois o shadow banking realiza operações passando por toda a supervisão ou regulação dos sistemas financeiros/ bancários do país.","Sim, pois essas instituições não são bancárias, não recebem depósitos tradicionais como um banco tradicional e são estruturas paralelas aos mercados tradicionais.","Sim, pois o shadow banking é uma estrutura paralela aos mercados tradicionais, embora passe por todas as regulações e seja uma instituição bancária.","Sim, pois o shadow banking não é uma instituição financeira, embora tenha registro no Banco Central."],"correta":2,"explicacao":"Gabarito: <strong>Sim, pois essas instituições não são bancárias, não recebem depósitos tradicionais como um banco tradicional e são estruturas paralelas aos mercados tradicionais.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830866,"enunciado":"Um meio de troca é aquilo que os compradores oferecem aos vendedores quando aqueles adquirem bens e serviços. Quando um consumidor, por exemplo, compra um perfume numa loja localizada numa economia onde o nível inflacionário é baixo e controlado, o vendedor entrega o produto para o cliente em troca de","opcoes":["moeda, por ser o meio de troca de maior aceitabilidade.","mercadoria, por ser o meio de troca mais eficiente.","moeda-mercadoria, por ser o meio de troca mais durável.","outro bem, por ser o meio de troca com menor custo de carregamento.","outro serviço, por ser o meio de troca de maior divisibilidade."],"correta":0,"explicacao":"Gabarito: <strong>moeda, por ser o meio de troca de maior aceitabilidade.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830867,"enunciado":"A blockchain é um tipo específico de banco de dados distribuído, no qual há uma cadeia de blocos ordenados e interligados, com garantia de ordem cronológica. Os dados registrados nos blocos podem variar de transações financeiras a contratos inteligentes. Na blockchain da bitcoin, as entidades que registram novos blocos na cadeia são chamadas de","opcoes":["registradores","mineradores","trabalhadores","gerenciadores","conectores"],"correta":1,"explicacao":"Gabarito: <strong>mineradores</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830868,"enunciado":"Leia as considerações seguintes sobre o expressivo crescimento das criptomoedas nas movimentações financeiras internacionais. Criptomoeda, ou moeda criptografada, é um ativo digital denominado na própria unidade de conta que é emitido e transacionado de modo descentralizado, independentemente de registro ou validação por parte de intermediários centrais, com validade e integridade de dados assegurada por tecnologia criptográfica e de consenso em rede. Trata-se de instrumentos desenhados para viabilizar transferências de valores em rede de maneira segura e independente de um sistema de intermediação financeira (...). Outro aspecto econômico que merece destaque é o lado político-econômico da atribuição de valor a uma moeda. As moedas estatais de curso forçado contam não apenas com reservas legais, mas também com uma infraestrutura estatal ou privada (fortemente regulada) e com as políticas monetária e cambial oficiais (...). Muitas criptomoedas, mesmo que funcionem como instrumentos descentralizados, têm grande parte de sua base monetária em poder da organização que a desenvolveu. Stella, J.C. Moedas virtuais no Brasil: como enquadrar as criptomoedas. Revista da PGBC, v. 11, n. 2, dez. 2017, p. 151, 156. Disponível em: <https://revistapgbc.bcb.gov.br/index.php/revista/ issue/download/26/A9%20V.11%20-%20N.2>. Acesso em: 24 jul.2021. O texto sugere que o mercado de criptomoedas é fonte de enorme instabilidade e preocupação dos bancos centrais, porque as empresas emissoras desses ativos monetários","opcoes":["são reguladas pelos bancos centrais.","têm enorme capacidade de manipulação da taxa de câmbio entre a criptomoeda emitida e os demais ativos digitais.","conseguiram transformá-los no principal meio de troca utilizado nas transações financeiras internacionais.","vinculam a unidade de conta da criptomoeda às principais moedas conversíveis, como o dólar norte-americano e o euro.","forçam o enquadramento das criptomoedas emitidas na mesma categoria das demais moedas eletrônicas já existentes."],"correta":1,"explicacao":"Gabarito: <strong>têm enorme capacidade de manipulação da taxa de câmbio entre a criptomoeda emitida e os demais ativos digitais.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830875,"enunciado":"A pandemia do coronavírus, declarada em março de 2020, alterou significativamente as relações sociais e econômicas ao redor do globo. Em resposta, autoridades mundiais atuaram tempestivamente, recorrendo a instrumentos monetários para dinamizar a economia, associando estímulo monetário com controle inflacionário. Com essa finalidade, no Brasil, em agosto de 2020, o Banco Central do Brasil (Bacen) anunciou a utilização de um instrumento denominado","opcoes":["Teto dos gastos","Isenção tributária","Dominância fiscal","Foward guidance","Quantitative easing"],"correta":3,"explicacao":"Gabarito: <strong>Foward guidance</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830876,"enunciado":"Existem títulos de dívida de longo prazo emitidos por sociedades de ações e destinados, geralmente, ao financiamento de projetos de investimento ou para alongamento do perfil de endividamento das empresas. Tais títulos são","opcoes":["as ações","as debêntures","os dividendos","os Depositary Receipts (DR)","os Brazilian Depositary Receipts (BDR)"],"correta":1,"explicacao":"Gabarito: <strong>as debêntures</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830877,"enunciado":"Dentro do Sistema de Metas para a inflação, o Conselho Monetário Nacional (CMN) estabelece a meta para a inflação. A partir dessa meta, o Comitê de Política Monetária (Copom) do Banco Central do Brasil (Bacen) reúne-se periodicamente para analisar a economia brasileira. Nesse contexto, é atribuição do Copom","opcoes":["definir a meta da taxa Selic.","determinar o papel do Bacen no mercado cambial.","formular normas aplicáveis ao Sistema Financeiro Nacional (SFN).","divulgar, diariamente, a taxa de juros de curto prazo para operações realizadas no mercado financeiro.","autorizar o funcionamento das instituições financeiras e de outras entidades conforme legislação em vigor."],"correta":0,"explicacao":"Gabarito: <strong>definir a meta da taxa Selic.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830878,"enunciado":"A Comissão de Valores Mobiliários (CVM) foi criada em 07/12/1976, pela Lei nº 6.385/76. A CVM","opcoes":["é um órgão emissor de moeda-papel.","é vinculada à Casa Civil.","fornece crédito às instituições.","é responsável por formular a política de crédito.","regula mercados da Bolsa de balcão."],"correta":4,"explicacao":"Gabarito: <strong>regula mercados da Bolsa de balcão.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830880,"enunciado":"Um jovem atua em uma organização social com inúmeros projetos em comunidades carentes situada em região metropolitana de uma grande capital brasileira. A organização possui vários empregados, recrutados diretamente nas comunidades, e conta com financiamento de pessoas físicas e jurídicas. Com o intuito de ampliar sua base de colaboradores, agenda diversos compromissos com empreendedores que tenham interesse na região. Nos termos da Política de Responsabilidade Socioambiental do Banco do Brasil, seria adequado que houvesse","opcoes":["percentual de funcionários que exercesse atividade remunerada decorrente de atuação nas organizações sociais.","incentivo aos funcionários do banco para que desempenhassem atividades voluntárias no projeto.","colaboração não consistente em financiamento a programas e projetos sociais.","integração de outras instituições financeiras como requisito de participação.","neutralidade na intervenção em projetos sociais em comunidades carentes por ausência de recursos para todos."],"correta":1,"explicacao":"Gabarito: <strong>incentivo aos funcionários do banco para que desempenhassem atividades voluntárias no projeto.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830882,"enunciado":"Aqueles que participam do mercado de câmbio de um país podem ser divididos entre os que produzem divisas e os que cedem divisas. Produzem e cedem divisas, respectivamente, os","opcoes":["exportadores; os turistas estrangeiros.","importadores; os que fazem transferências para o exterior.","que recebem transferências do exterior; os que remetem lucro ao exterior.","tomadores de investimentos quando remetem dividendos ao exterior; os exportadores.","tomadores de empréstimos quando remetem o principal ao exterior; os importadores."],"correta":2,"explicacao":"Gabarito: <strong>que recebem transferências do exterior; os que remetem lucro ao exterior.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830883,"enunciado":"Essencialmente, o mercado de capitais canaliza a poupança da sociedade para suprir as necessidades das empresas por recursos produtivos. Promover o fortalecimento de mercados de capitais locais para que se tornem pilares para o desenvolvimento econômico tem sido um objetivo constante, em praticamente toda a comunidade internacional. A sociedade é beneficiada à medida que o mercado de capitais cumpre aquelas que são suas quatro principais funções:","opcoes":["aumento do consumo imediato, maior propensão ao risco, alocação de recursos em poucos ativos e aumento da autonomia gerencial corporativa.","desmobilização do investimento, maior aversão ao risco, alocação enviesada de recursos e afrouxamento da rígida disciplina de capital corporativa.","mobilização da poupança, gestão de riscos, alocação eficiente de recursos e aumento da disciplina corporativa.","transferência do investimento para o futuro, eliminação dos riscos sistemáticos, construção de carteiras diversificadas e estímulo à governança.","estabilidade da propensão a consumir, redução do risco assistemático, alocação aleatória de recursos e extinção dos custos de agência."],"correta":2,"explicacao":"Gabarito: <strong>mobilização da poupança, gestão de riscos, alocação eficiente de recursos e aumento da disciplina corporativa.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1830903,"enunciado":"Um grupo empresarial, atuando em transportes terrestres, recebeu autorização da ANAC para operar voos comerciais no território nacional e decidiu lançar ações no mercado, visando a encomenda de aeronaves. A estratégia do novo entrante é vista com cautela por analistas de mercado, uma vez que essa indústria demanda volumes elevados de investimento e apresentou baixas margens nos últimos anos. Adicionalmente, o grupo encontra-se em processo de recuperação judicial, e sua entrada no mercado de aviação comercial acontece em crise do setor aéreo, diante dos efeitos da pandemia. Sendo assim, o analista teve cautela ao interpretar as informações sobre a barreira de entrada relacionada a","opcoes":["diferenciação de serviços","identidade da marca","política governamental","retaliação esperada","requisitos de capital"],"correta":4,"explicacao":"Gabarito: <strong>requisitos de capital</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842531,"enunciado":"A principal característica do crédito direto ao consumidor (CDC) é que esse instrumento de financiamento dispensa","opcoes":["avalista","análise cadastral do cliente","limite de prazo de pagamento","limite de crédito","identificação do cliente"],"correta":0,"explicacao":"Gabarito: <strong>avalista</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842532,"enunciado":"O texto seguinte diz respeito à generalização das políticas monetárias consideradas não convencionais por parte dos bancos centrais do mundo inteiro. Os bancos centrais globais agora percebem que políticas monetárias antes consideradas não convencionais e temporárias agora se revelam convencionais e duradouras. Obrigados a encontrar novas soluções devido à crise financeira de 2008 e novamente neste ano por causa da pandemia de coronavírus, o Federal Reserve (Fed, na sigla em inglês), o Banco Central Europeu e a maioria dos bancos centrais internacionais se tornaram mais agressivos e inovadores do que nunca na defesa das economias contra a recessão e ameaça de deflação. KENNEDY, S; DODGE, S. Política monetária não convencional agora é ferramenta duradoura. Exame, São Paulo, 15 set. 2020. Adaptado.Disponível em: https://exame.com/. Acesso em: 29 ago. 2021. Um exemplo de política monetária não convencional é a","opcoes":["redução da taxa básica de juros","compra de títulos públicos e privados por parte dos bancos centrais","redução das taxas de redesconto","expansão da base monetária","venda de títulos com o compromisso de recompra pela autoridade monetária"],"correta":1,"explicacao":"Gabarito: <strong>compra de títulos públicos e privados por parte dos bancos centrais</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842533,"enunciado":"Embora as taxas de câmbio R$/US$, cotadas diariamente nos mercados de câmbio à vista, sejam expressas em valores nominais, ao longo do tempo essas taxas podem-se desviar de seus valores reais. Contribui para a apreciação real da moeda brasileira, em relação ao dólar norte-americano, a(o)","opcoes":["redução da produtividade média no Brasil, comparativamente à dos Estados Unidos","queda dos preços das commodities exportadas pelo Brasil","taxa de inflação no Brasil maior do que a taxa de inflação norte-americana","compra de reservas internacionais pelo Banco Central do Brasil","maior grau de incerteza no Brasil"],"correta":2,"explicacao":"Gabarito: <strong>taxa de inflação no Brasil maior do que a taxa de inflação norte-americana</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842534,"enunciado":"A principal marca distintiva do Pix, em relação aos mecanismos de pagamento com cartões de débito automático, é que o Pix é um sistema de pagamento instantâneo criado pelo(s)","opcoes":["Banco do Brasil","Banco do Nordeste","Banco Central do Brasil","bancos comerciais","bancos de investimento"],"correta":2,"explicacao":"Gabarito: <strong>Banco Central do Brasil</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842535,"enunciado":"Desde 1999, o Brasil adota um regime de câmbio flutuante (ou flexível). Considerando-se a prática brasileira desde então, nesse regime cambial, a","opcoes":["taxa de câmbio é fixada pelo Banco Central do Brasil.","taxa de câmbio é determinada pela oferta e demanda de moeda estrangeira.","taxa de câmbio não sofre interferência do Banco Central do Brasil.","taxa de câmbio não influencia a rentabilidade dos exportadores.","fixação da taxa básica de juros (Selic) torna-se dependente da política cambial."],"correta":1,"explicacao":"Gabarito: <strong>taxa de câmbio é determinada pela oferta e demanda de moeda estrangeira.</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842536,"enunciado":"Nos contratos de financiamento de automóveis, a garantia de pagamento da dívida é o próprio bem, isto é, o automóvel adquirido pelo devedor. Nesse caso, trata-se de","opcoes":["aval","fiança","hipoteca","alienação fiduciária","penhor mercantil"],"correta":3,"explicacao":"Gabarito: <strong>alienação fiduciária</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842554,"enunciado":"Com a introdução no Brasil, nos anos de 1990, dos primeiros caixas automáticos ou terminais bancários ou ATM, o processo de prestação de serviços se modificou. Desde então, os clientes passaram a integrar uma parte desse processo, realizando um conjunto de atividades que antes eram feitas pelo prestador do serviço. Assim, o cliente passou a ser parte da solução do serviço, que tem como característica a","opcoes":["coopetição","coprodução","estocagem","homogeneidade","simultaneidade"],"correta":1,"explicacao":"Gabarito: <strong>coprodução</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842555,"enunciado":"Um analista de investimentos precisa vender ao seu cliente os benefícios de um determinado fundo. Ele sabe que tem uma oportunidade, quando estiver frente a frente com o cliente, durante o atendimento, e, assim, poder explicar as vantagens e qualidades do fundo. Ele também sabe que, se o cliente deixar a agência, essa oportunidade não se repetirá tão cedo, e sua meta de vendas não será alcançada. Na avaliação da qualidade de serviços, essa oportunidade é denominada","opcoes":["tangíveis visíveis","prontidão de recuperação","qualidade de projeto","momento da verdade","técnica de design"],"correta":3,"explicacao":"Gabarito: <strong>momento da verdade</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842556,"enunciado":"No primeiro semestre de 2021, o câmbio do dólar fechou acima de R$5,90, no maior patamar dos últimos anos, devido à pandemia e ao cenário de recessão. Suponha que o administrador de produtos bancários cambiais de um grande banco deve entregar um relatório, analisando as forças macroambientais que impactam o produto. Diante desse contexto, o administrador deve considerar a valorização do dólar na dimensão do ambiente","opcoes":["econômico","político","tecnológico","cultural","demográfico"],"correta":0,"explicacao":"Gabarito: <strong>econômico</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842557,"enunciado":"Desde 2013, o setor bancário tradicional vem sendo afetado pela concorrência das Fintechs. No início, muitas delas abalaram a estabilidade de grandes bancos, por oferecer serviços completos de um banco, porém sem agências físicas e com operações de baixo custo. Essa estratégia lhes deu capacidade de praticar baixas tarifas e, ainda assim, gerar uma lucratividade considerável. Desse modo, verifica-se que a estratégia genérica de posicionamento das Fintechs foi de","opcoes":["diferenciação de produto","diversificação de indústria","expansão de mercados","extensão de marca","liderança em custo"],"correta":4,"explicacao":"Gabarito: <strong>liderança em custo</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842559,"enunciado":"Um correntista de um banco recebe proposta de fornecimento de cartão de crédito sem anuidade, justificado pelo fato de ele receber seu salário através da agência bancária proponente. No entanto, após um ano, ele é surpreendido com a cobrança de anuidade. Imediatamente apresenta reclamação para o seu gerente, que diz não ter alçada para solver tal questão. O caso é levado para gerência superior que resolve o litígio. Nos termos da Resolução n° 4.539/2016, as instituições devem assegurar a consistência de rotinas e de procedimentos operacionais afetos ao relacionamento com clientes e usuários, aplicando, no caso descrito, a técnica de","opcoes":["prêmio por desempenho","subordinação hierárquica","mediação de conflitos","defesa contratual","proteção institucional"],"correta":2,"explicacao":"Gabarito: <strong>mediação de conflitos</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842565,"enunciado":"Um banco decidiu criar um departamento on-line específico para atender a clientes pessoa física com grandes volumes de investimento. Esse departamento foi nomeado Agência VIP. A estratégia de atração de novos clientes envolveu o lançamento de uma campanha publicitária, que apresentava a seguinte mensagem: “Focado nos melhores negócios, o Banco Z criou as agências VIP. Somente para 100 clientes.” A ideia, claramente, era gerar a sensação de perda para aqueles que não se tornassem clientes da Agência VIP e, nesse caso, utilizar o gatilho mental da","opcoes":["Urgência","Surpresa","Escassez","Ancoragem","Prova Social"],"correta":2,"explicacao":"Gabarito: <strong>Escassez</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1842567,"enunciado":"Os diretores de um banco procuraram influenciadores digitais para lhes apresentar os fundos de investimento do banco. Eles sabem que os influenciadores digitais divulgam informalmente produtos bancários e oferecem conselhos ou informações sobre investimentos financeiros, dizendo, por exemplo, quais, dentre as diversas opções de aplicações financeiras, são as melhores para o tipo de audiência que o acompanha. Os influenciadores digitais, portanto, funcionam como","opcoes":["fontes de intervenção","grupo de afinidade","referências primárias","líderes de opinião","grupo de dissociação"],"correta":3,"explicacao":"Gabarito: <strong>líderes de opinião</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1851783,"enunciado":"Para alcançar a meta de inflação, o BACEN usa como principal instrumento a taxa básica de juros — a taxa de juros SELIC —, estabelecida atualmente em 5,25% ao ano pelo Comitê de Política Monetária (COPOM).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1860783,"enunciado":"O que é PIX?","opcoes":["Pagamento Instantâneo criado pelo Banco Mundial a partir de conta corrente, conta poupança, cartões de crédito ou conta pré-paga.","Forma de pagamento criado pelo Banco Interamericano para agilizar a circulação da moeda no mundo.","Pagamento Instantâneo criado pelo Programa Internacional de pagamentos em conta corrente e conta pré-paga.","Pagamento Instantâneo criado pelo Banco Central do Brasil a partir de conta corrente, conta poupança ou conta pré-paga","Programa de Pré Pagamento do Banco Central para substituir o DOC."],"correta":3,"explicacao":"Gabarito: <strong>Pagamento Instantâneo criado pelo Banco Central do Brasil a partir de conta corrente, conta poupança ou conta pré-paga</strong>.","banca":"FAFIPA","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1863507,"enunciado":"A debênture poderá, conforme dispuser a escritura de emissão,","opcoes":["ter garantia real ou garantia flutuante, desde que goze do direito de preferência, podendo ou não ser subordinada aos demais credores da companhia.","ter garantia real ou garantia flutuante, desde que goze do direito de preferência e seja subordinada aos demais credores da companhia.","ter apenas garantia real, não podendo gozar de preferência ou ser subordinada aos demais credores da companhia.","ter garantia real ou garantia flutuante, não podendo gozar de preferência.","ter apenas garantia flutuante, não podendo gozar de preferência."],"correta":1,"explicacao":"Gabarito: <strong>ter garantia real ou garantia flutuante, desde que goze do direito de preferência e seja subordinada aos demais credores da companhia.</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1866295,"enunciado":"O Sistema Financeiro Nacional (SFN) é o conjunto de instituições e instrumentos que possibilitam a transferência de recursos entre os agentes econômicos superavitários e os deficitários. Essa transferência é possível por conta:","opcoes":["dos mercados monetário, de crédito, de capitais e cambial;","da atuação dos bancos comerciais;","da atuação dos bancos centrais;","das bolsas de valores;","da atuação da CVM."],"correta":0,"explicacao":"Gabarito: <strong>dos mercados monetário, de crédito, de capitais e cambial;</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1866296,"enunciado":"Amparado pelo Conselho Monetário Nacional (CMN), o Banco Central do Brasil (BCB) tem por uma de suas atribuições:","opcoes":["a execução da política fiscal;","o regramento das bolsas de valores;","a execução da política monetária;","a determinação do superávit primário;","o regramento de ofertas públicas iniciais."],"correta":2,"explicacao":"Gabarito: <strong>a execução da política monetária;</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1866297,"enunciado":"Por meio da Lei nº 9.613/1998, o Brasil regulamentou pela primeira vez a prática de lavagem de dinheiro ou ocultação de bens. Dentre os delitos que configuram esse crime, encontra(m)-se:","opcoes":["o uso de informação privilegiada;","fraudes em demonstrativos contábeis;","o não recolhimento de IOF;","ocultar ou dissimular a natureza de bens e direitos;","a remessa de recursos para contas no exterior."],"correta":3,"explicacao":"Gabarito: <strong>ocultar ou dissimular a natureza de bens e direitos;</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1866298,"enunciado":"O Comitê de Política Monetária (Copom) do Banco Central do Brasil tem por principais objetivos: i) estabelecer as diretrizes da política monetária; e ii) definir a meta da taxa de juros básica no Brasil e seu eventual viés. Para a consecução do objetivo ii), dada a decisão do Copom, o Banco Central do Brasil:","opcoes":["emite títulos públicos;","emite títulos do próprio Banco Central;","realiza operações de mercado aberto;","realiza o controle da dívida pública;","controla as reservas internacionais do país."],"correta":2,"explicacao":"Gabarito: <strong>realiza operações de mercado aberto;</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1866300,"enunciado":"É competência do Conselho Monetário Nacional (CMN), a fiscalização:","opcoes":["da taxa do CDI;","da taxa Selic diária;","da meta para a taxa Selic;","das metas de inflação;","do superávit primário."],"correta":0,"explicacao":"Gabarito: <strong>da taxa do CDI;</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1866301,"enunciado":"Em 22 de setembro de 2021, o Copom aumentou a meta da taxa Selic para 6,25% ao ano. Em termos práticos, isso significa que a mesa de operações de mercado aberto do Banco Central deve atuar para que a Selic diária fique próxima dessa meta. Se a Selic diária estiver em 8% num certo dia, a mesa de operações do Banco Central deve:","opcoes":["comprar títulos públicos no mercado e mantê-los em sua carteira, até que a taxa diária atinja a meta de 6,25%;","vender títulos públicos de sua carteira no mercado, até que a taxa diária atinja a meta de 6,25%;","diminuir a oferta de moeda disponível na economia;","imprimir mais papel-moeda;","pleitear uma mudança no superávit primário."],"correta":0,"explicacao":"Gabarito: <strong>comprar títulos públicos no mercado e mantê-los em sua carteira, até que a taxa diária atinja a meta de 6,25%;</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1866302,"enunciado":"O Sistema Financeiro Nacional possui órgãos normativos, entidades supervisoras e operadores. Os órgãos normativos, além do Conselho Nacional de Seguros Privados (CNSP), incluem:","opcoes":["a Casa da Moeda e o Banco Central;","o Conselho Monetário Nacional (CMN) e o Conselho Nacional de Previdência Complementar (CNPC);","a Susep e o Banco Central;","o Banco Central e a CVM;","as caixas econômicas e as bolsas de valores."],"correta":1,"explicacao":"Gabarito: <strong>o Conselho Monetário Nacional (CMN) e o Conselho Nacional de Previdência Complementar (CNPC);</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1868283,"enunciado":"A indústria bancária internacional vem passando por profundas modificações: além da ampliação das empresas financeiras de tecnologia fintechs no mercado de banking, observam-se importantes mudanças no mercado bancário promovidas pelos principais reguladores globais. Nesse contexto, o open banking (sistema financeiro aberto, em tradução livre)","opcoes":["está restrito aos bancos de varejo.","busca reduzir o custo financeiro do dinheiro (spread) por meio dos ganhos relacionados à economia de escala e de escopo.","torna o compartilhamento de dados de clientes parte central do modelo de negócios.","não envolve transações relacionadas a pagamentos bancários.","reduz o risco de ataques cibernéticos."],"correta":4,"explicacao":"Gabarito: <strong>reduz o risco de ataques cibernéticos.</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1880744,"enunciado":"Cabe ao Conselho Monetário Nacional","opcoes":["formular a política da moeda e do crédito, com o objetivo de manter a estabilidade da moeda e o desenvolvimento econômico e social do país.","fiscalizar, normatizar, disciplinar e desenvolver o mercado de valores mobiliários no Brasil.","garantir a estabilidade do poder de compra da moeda, zelar por um sistema financeiro sólido, eficiente e competitivo e executar a política monetária com o objetivo de manter a inflação na meta.","intermediar e custodiar o dinheiro entre poupadores e aqueles que precisam de empréstimos, além de providenciar serviços financeiros para os clientes, como saques, empréstimos, investimentos, entre outros.","atuar nos mercados financeiro, cambial e de capitais, intermediando a negociação de títulos e valores mobiliários entre investidores e tomadores de recursos."],"correta":0,"explicacao":"Gabarito: <strong>formular a política da moeda e do crédito, com o objetivo de manter a estabilidade da moeda e o desenvolvimento econômico e social do país.</strong>.","banca":"CESGRANRIO","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1880745,"enunciado":"Existe um tipo de instituição financeira, formada pela associação de pessoas, cujo objetivo é prestar serviços financeiros exclusivamente aos seus associados, tais como conta-corrente, aplicações financeiras, cartão de crédito, empréstimos e financiamentos. Trata-se de instituição financeira que, embora supervisionada pelo Banco Central do Brasil, não tem acesso à câmara de compensação de cheques, aos créditos oficiais, à reserva bancária e ao mercado interfinanceiro. A instituição financeira descrita é denominada","opcoes":["banco comercial","caixa econômica","cooperativa de crédito","banco comercial cooperativo","corretora de títulos e valores mobiliários"],"correta":2,"explicacao":"Gabarito: <strong>cooperativa de crédito</strong>.","banca":"CESGRANRIO","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1880746,"enunciado":"Considere que um investidor estrangeiro, ao internalizar US$200 milhões no Brasil, tenha feito, no mesmo dia, uma aplicação financeira em Reais (R$) para resgate após 360 dias, à taxa de juros prefixada de 6,5% a.a. Admita, adicionalmente, que, no dia da aplicação, ele tenha convertido os Dólares internalizados em Reais à taxa de câmbio de R$5,40/US$, cotada no mercado à vista. Considerando-se que a aplicação tenha sido feita a descoberto (sem hedging cambial), caso no dia do resgate a taxa de câmbio no mercado à vista tenha sido de R$5,30/US$, o ganho nominal total (principal mais juros) do investidor, em Dólares, terá sido de","opcoes":["213 milhões","217,019 milhões","1,080 bilhão","1,150 bilhão","6,096 bilhões"],"correta":1,"explicacao":"Gabarito: <strong>217,019 milhões</strong>.","banca":"CESGRANRIO","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1880748,"enunciado":"Considere que a taxa de câmbio real de equilíbrio do Real em relação ao Dólar (R$/US$) tenha sido estimada em R$3,70/US$, em dezembro de 2019 (média do mês). Admita, adicionalmente, que as taxas acumuladas de inflação no Brasil e nos Estados Unidos tenham sido de, respectivamente, 15,90% e 5,66%, entre 1o de janeiro de 2020 e 31 de dezembro de 2021. Para que fosse mantida a paridade relativa real do poder de compra, a taxa de câmbio de equilíbrio, em dezembro de 2021, deveria ter sido, em média, de","opcoes":["R$3,70/US$","R$4,08/US$","R$4,29/US$","R$5,40/US$","R$13,94/US$"],"correta":1,"explicacao":"Gabarito: <strong>R$4,08/US$</strong>.","banca":"CESGRANRIO","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1880750,"enunciado":"As Letras de Crédito do Agronegócio (LCAs) se tornaram uma alternativa importante na aplicação e na captação de recursos financeiros no país. Elas apresentam inúmeras vantagens, tanto para o investidor quanto para as instituições emissoras, tal como a","opcoes":["proteção do Fundo Garantidor de Crédito (FGC) até o limite de R$ 500 mil.","garantia dupla para o investidor: do banco emissor e do contrato que representa a dívida do produtor rural.","emissão de letras com prazo mínimo de vencimento de apenas 1 mês.","redução de 50% do recolhimento do depósito compulsório.","vantagem fiscal para o investidor, pela redução de 50% do imposto de renda devido."],"correta":1,"explicacao":"Gabarito: <strong>garantia dupla para o investidor: do banco emissor e do contrato que representa a dívida do produtor rural.</strong>.","banca":"CESGRANRIO","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1880751,"enunciado":"A operação de leasing financeiro se aproxima de um empréstimo para a compra de um bem. Esse bem serve como garantia para o empréstimo, e a amortização do empréstimo é feita através de vários pagamentos futuros, em geral periódicos. Em um contrato de leasing,","opcoes":["a empresa arrendatária, que vai usar o bem em questão, é obrigada a comprá-lo no final do período de leasing, pelo valor residual estipulado no contrato.","a manutenção do bem em questão não é de responsabilidade do arrendatário.","o IOF (Imposto Sobre Operações Financeiras) deve ser pago.","o ISS (Imposto Sobre Serviços) não precisa ser pago.","os pagamentos futuros (aluguéis) podem ser lançados contabilmente como despesa operacional, pela empresa arrendatária."],"correta":4,"explicacao":"Gabarito: <strong>os pagamentos futuros (aluguéis) podem ser lançados contabilmente como despesa operacional, pela empresa arrendatária.</strong>.","banca":"CESGRANRIO","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1880752,"enunciado":"O Fundo Garantidor de Crédito (FGC), criado em 1995, tem como objetivo fundamental","opcoes":["garantir os bancos comerciais pelos seus empréstimos às empresas e às pessoas físicas brasileiras.","aprovar ou não os empréstimos feitos pelos bancos comerciais brasileiros.","aplicar os recursos provenientes dos recolhimentos compulsórios dos bancos comerciais, ao Banco Central, na garantia total dos créditos concedidos por esses bancos.","garantir, até um certo valor limite, os depositantes e os investidores das instituições financeiras associadas ao FGC.","garantir os credores das pessoas jurídicas brasileiras, financeiras ou não, no caso de inadimplência destas pessoas jurídicas."],"correta":3,"explicacao":"Gabarito: <strong>garantir, até um certo valor limite, os depositantes e os investidores das instituições financeiras associadas ao FGC.</strong>.","banca":"CESGRANRIO","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1899112,"enunciado":"Sobre o regime de capitalização, analise as assertivas abaixo e assinale V, se verdadeiras, ou F, se falsas. ( ) Em uma capitalização composta, são calculados o valor total da operação menos o valor dos juros simples. ( ) Quando a taxa de juros centra apenas sobre o capital, o regime de capitalização é simples. ( ) No regime de capitalização simples, as taxas de juros são aplicadas sobre o capital acumulado dos juros. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["F – F – V.","F – V – F.","V – V – V.","V – F – F.","V – V – F."],"correta":1,"explicacao":"Gabarito: <strong>F – V – F.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1904846,"enunciado":"Julgue o item seguinte quanto aos controles internos aplicados à prevenção e ao combate à lavagem de dinheiro e ao financiamento do terrorismo.\n\nPara mitigar riscos referentes aos procedimentos de lavagem de dinheiro e financiamento ao terrorismo, é necessário que as organizações conheçam a legislação e os regulamentos relativos ao assunto, as técnicas utilizadas, o perfil dos clientes, bem como os produtos e serviços mais utilizados para a referida prática.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1904848,"enunciado":"Julgue o item seguinte quanto aos controles internos aplicados à prevenção e ao combate à lavagem de dinheiro e ao financiamento do terrorismo.\n\nPara prevenção à lavagem de dinheiro, é importante que a instituição disponha de mecanismos que permitam o armazenamento sobre as transações realizadas pelo cliente, bem como sobre suas informações cadastrais, sendo, entretanto, ilícito utilizar-se das informações disponíveis para checar a compatibilidade entre a movimentação e a capacidade econômico-financeira do cliente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1904860,"enunciado":"Acerca dos tipos de riscos internos e externos relacionados aos fundos de pensão, julgue o item seguinte.\n\nHavendo a probabilidade de ocorrência de perdas resultantes da flutuação nos preços de mercado de posições financeiras detidas pelo fundo de pensão, pode-se dizer que a organização está sob o risco de mercado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1904861,"enunciado":"Acerca dos tipos de riscos internos e externos relacionados aos fundos de pensão, julgue o item seguinte.\n\nSensibilidade ao risco é determinada em função da relevância do de seu impacto, da possibilidade de sua ocorrência e da capacidade e preparo do fundo de pensão para reagir e responder à sua materialização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1904862,"enunciado":"Acerca dos tipos de riscos internos e externos relacionados aos fundos de pensão, julgue o item seguinte.\n\nQuando os procedimentos e rotinas das áreas críticas do fundo de pensão desrespeitam o ordenamento jurídico vigente, as alterações ocorridas na legislação ou as mudanças na interpretação judicial, pode-se afirmar que a organização está sob o risco legal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1904863,"enunciado":"Acerca dos tipos de riscos internos e externos relacionados aos fundos de pensão, julgue o item seguinte.\n\nNa análise de investimentos e riscos, o screening é considerado negativo quando a alocação de recursos a determinados setores pelo fundo de pensão é privilegiada por sua contribuição positiva para o desenvolvimento sustentável.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1904865,"enunciado":"Com relação aos controles internos aplicados à prevenção e ao combate à lavagem de dinheiro e ao financiamento do terrorismo na FUNPRESP-EXE, julgue o item seguinte.\n\nEmbora não haja riscos de práticas ligadas ao terrorismo, os procedimentos necessários se resumem à mitigação do risco de lavagem de dinheiro na seleção e contratação de servidores e prestadores de serviços terceirizados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1904918,"enunciado":"No que se refere aos órgãos colegiados da PREVIC, julgue o próximo item.\n\n\n\n\nCabe ao Conselho Nacional de Previdência Complementar a função de órgão regulador do regime de previdência complementar operado pelas entidades fechadas de previdência complementar.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1905689,"enunciado":"A respeito de previdência complementar, julgue o item a seguir.\n\n\n\n\nEm uma entidade fechada de previdência complementar, o cargo de administrador estatutário tecnicamente qualificado − AETQ é um cargo de assessor especial, sem função executiva, com funções relacionadas ao assessoramento da gestão de investimentos, sendo cargo de livre provimento do dirigente da entidade e estando vinculado à diretoria de investimentos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1905690,"enunciado":"A respeito de previdência complementar, julgue o item a seguir.\n\n\n\n\nEm se tratando de Entidade Fechada de Previdência Complementar sistemicamente importante (EFPC-ESI), a gestão de riscos deve ser exercida por comitê independente e do mais alto nível hierárquico, com equipe apartada da gestão dos investimentos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1905691,"enunciado":"A respeito de previdência complementar, julgue o item a seguir.\n\n\n\n\nPecúlio por morte, pecúlio por invalidez, pensão por morte, renda por invalidez e plano de saúde são exemplos de planos de previdência complementar administrados pelas entidades abertas de previdência complementar − EAPC’s.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1905710,"enunciado":"A partir das informações precedentes, julgue o item a seguir.\n\n\n\n\nAs informações apresentadas ilustram o paradoxo de Pareto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1905713,"enunciado":"A partir das informações precedentes, julgue o item a seguir.\n\n\n\n\nSe os indivíduos escolhem o tratamento I em detrimento do II e o tratamento IV em detrimento do III, há violação das propriedades da utilidade esperada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1905716,"enunciado":"Julgue o item seguinte, a respeito do planejamento tributário sucessório, que constitui importante ferramenta de preservação de patrimônio.\n\n\n\n\nO cônjuge figura entre os herdeiros necessários.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1905717,"enunciado":"Julgue o item seguinte, a respeito do planejamento tributário sucessório, que constitui importante ferramenta de preservação de patrimônio.\n\n\n\n\nO capital segurado por ocasião de seguro de vida deve fazer parte da partilha de bens da herança.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1905718,"enunciado":"Julgue o item seguinte, a respeito do planejamento tributário sucessório, que constitui importante ferramenta de preservação de patrimônio.\n\n\n\n\nNos planos de previdência privada do tipo VGBL (vida gerador de benefício livre) permite-se a dedução do valor investido no imposto de renda.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1940367,"enunciado":"De acordo com o COSIF – Plano Contábil das Instituições Reguladas pelo Banco Central do Brasil, assinale a opção que descreve a essência econômica de uma operação de compra de títulos públicos com o compromisso de revenda realizada por uma instituição financeira.","opcoes":["Aquisição de títulos públicos por meio de uma operação que concede ao vendedor a opção de recomprar referidos títulos no futuro.","Concessão de crédito a uma outra instituição financeira, que oferece títulos públicos como lastro da operação.","Aquisição do direito de uso temporário de títulos públicos de propriedade de terceiros, por meio do pagamento de uma taxa de aluguel.","Aquisição de um instrumento financeiro derivativo.","Aplicação de recursos financeiros no mercado à vista de títulos, com a garantia do resgate automático do investimento no futuro."],"correta":0,"explicacao":"Gabarito: <strong>Aquisição de títulos públicos por meio de uma operação que concede ao vendedor a opção de recomprar referidos títulos no futuro.</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1965099,"enunciado":"Acerca da Resolução nº 2828 do Conselho Monetário Nacional, analise as afirmativas abaixo e dê valores Verdadeiro (V) ou Falso (F). ( ) Dependem de autorização do Banco Central do Brasil a constituição e o funcionamento de agências de fomento sob controle acionário de Unidade da Federação. ( ) As agências de fomento não podem ser transformadas em qualquer outro tipo de instituição autorizada a funcionar pelo Banco Central do Brasil. ( ) As agências de fomento devem ser constituídas sob a forma de sociedade anônima de capital fechado ou aberto, nos termos da Lei nº. 6.404, de 15 de dezembro de 1976. Assinale a alternativa que apresenta a sequência correta de cima para baixo.","opcoes":["V - V - V","V - F - V","F - F - V","V - V - F"],"correta":3,"explicacao":"Gabarito: <strong>V - V - F</strong>.","banca":"IBFC","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1965100,"enunciado":"A Resolução nº 2828 do Conselho Monetário Nacional dispõe sobre a constituição e o funcionamento de agências de fomento. Sobre as disposições do mencionado ato normativo, assinale a alternativa que apresenta incorretamente a origem dos recursos que as agências de fomento podem empregar em suas atividades.","opcoes":["Fundos e programas oficiais","Organismos e instituições financeiras nacionais e internacionais de desenvolvimento","Recursos de associações constituídas há mais de um ano","Orçamentos federal, estaduais e municipais"],"correta":2,"explicacao":"Gabarito: <strong>Recursos de associações constituídas há mais de um ano</strong>.","banca":"IBFC","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1965101,"enunciado":"A constituição e o funcionamento de agências de fomento são regulamentados pela Resolução nº 2828 do Conselho Monetário Nacional (CMN). De acordo com a resolução, assinale a alternativa que apresenta, corretamente, uma operação ou atividade no âmbito das agências de fomento.","opcoes":["Acesso às linhas de assistência financeira e de redesconto do Banco Central do Brasil","Financiamento de capitais fixo e de giro associado a projetos","Acesso às contas Reservas Bancárias no Banco Central do Brasil","Contratação de depósitos interfinanceiros, na qualidade de depositante ou depositária, em qualquer caso"],"correta":1,"explicacao":"Gabarito: <strong>Financiamento de capitais fixo e de giro associado a projetos</strong>.","banca":"IBFC","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1965102,"enunciado":"No que se refere à Resolução nº 2828 do Conselho Monetário Nacional, analise as afirmativas abaixo. I. As agências de fomento devem constituir e manter, permanentemente, fundo de liquidez equivalente, no mínimo, a 10% (dez por cento) do valor de suas obrigações, a ser integralmente aplicado em títulos públicos federais. II. As agências de fomento devem observar limites mínimos de capital realizado e Patrimônio de Referência (PR) de R$4.000.000,00 (quatro milhões de reais). III. Excepcionalmente, quando o empreendimento visar benefícios de interesse comum, as agências de fomento podem prestar assistência a programas e projetos desenvolvidos em estado limítrofe à sua área de atuação. Estão corretas as afirmativas:","opcoes":["I, II e III","I e II apenas","II e III apenas","I apenas"],"correta":0,"explicacao":"Gabarito: <strong>I, II e III</strong>.","banca":"IBFC","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1965952,"enunciado":"A respeito do orçamento público, julgue o item, com base na legislação de regência do tema e na doutrina mais atual. \n\nA noção de orçamento, em seu sentido estrito, como a previsão de receitas e a fixação de despesas, remete ao ano de 1822, na Inglaterra, tendo sido difundida para outros países ao longo do século XIX.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1965953,"enunciado":"A respeito do orçamento público, julgue o item, com base na legislação de regência do tema e na doutrina mais atual. \n\nUm projeto de lei orçamentária anual em que não estejam previstas as dotações para custeio de determinada unidade orçamentária está em desacordo com o princípio da universalidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1965954,"enunciado":"A respeito do orçamento público, julgue o item, com base na legislação de regência do tema e na doutrina mais atual. \n\nOs instrumentos de planejamento atualmente à disposição dos gestores governamentais para efetivar as políticas públicas são o plano plurianual, a lei de diretrizes orçamentárias e a lei orçamentária anual, todas de iniciativa privativa do chefe do Poder Executivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1965955,"enunciado":"A respeito do orçamento público, julgue o item, com base na legislação de regência do tema e na doutrina mais atual.\n\nA lei orçamentária anual não poderá conter dispositivo estranho à previsão das receitas e à fixação das despesas, salvo a concessão de revisão geral anual dos servidores públicos, a fim de manter o poder de compra.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1979198,"enunciado":"O Brasil viu o número de transações em tempo real crescer quase seis vezes no ano passado (2021) com a entrada do PIX em operação; foram mais de 8,7 bilhões de reais movimentados. Porém, o Brasil não é o pioneiro na implementação do PIX, alguns países encabeçam essa implementação e são líderes na movimentação. Que países são esses?","opcoes":["Rússia, Japão e Coreia.","Índia, China e Tailândia.","Japão, EUA e França.","Inglaterra, Canadá e México.","EUA, China e Canadá."],"correta":2,"explicacao":"Gabarito: <strong>Japão, EUA e França.</strong>.","banca":"UNIOESTE","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1988696,"enunciado":"Considerando assuntos da atualidade brasileira relacionados à saúde, à sociedade e à economia, julgue o item.\n\n\n\n\nO Banco Central do Brasil, com o intuito de contribuir para a construção de um ecossistema de pagamentos instantâneos competitivo, eficiente, seguro e inclusivo, instituiu o grupo de trabalho que criou o PIX, que é a atual forma de pagamento mais popular do Brasil e que superou nacionalmente o volume de transações em cartões de crédito e de débito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":1988697,"enunciado":"Considerando assuntos da atualidade brasileira relacionados à saúde, à sociedade e à economia, julgue o item.\n\n\n\n\nO PIX é uma forma de transferência bancária em que o dinheiro circula mais rapidamente, porém, por não gerar nenhuma taxa ao correntista, faz as instituições bancárias perderem dinheiro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2001645,"enunciado":"Segundo o Manual de Normas e Procedimentos Operacionais do Fundo de Compensação de Variações Salariais (MNPO – FCVS), assinale a alternativa que apresente um documento que não se encontre no rol de documentos necessários aptos a comprovar a existência do financiamento habitacional com cobertura do Fundo de Compensação de Variações Salariais.","opcoes":["Contrato inicial de financiamento","Escritura de Compra e Venda","Certidão de Registro do contrato no Cartório de Imóveis","Carteira Nacional de Habilitação"],"correta":3,"explicacao":"Gabarito: <strong>Carteira Nacional de Habilitação</strong>.","banca":"IBFC","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2001646,"enunciado":"O Manual de Normas e Procedimentos Operacionais do Fundo de Compensação de Variações Salariais (MNPO – FCVS) trata da documentação para o financiamento habitacional. Sobre o assunto, analise as afirmativas abaixo. I. Não é possível, em nenhuma hipótese, documento sem registro em cartório de imóveis. II. O Manual prevê a apresentação de documentação complementar para comprovação de ocorrências casuais, específicas e previsíveis e de excepcionalidades permitidas por legislação específica ou por autorização dos órgãos competentes. III. O Fundo de Compensação de Variações Salariais considera como Aditivo Contratual documento por meio físico ou ótico, em que conste a solicitação e o tipo de opção exercida pelo mutuário, legalmente permitida, e a sua assinatura. Assinale a alternativa correta.","opcoes":["As afirmativas I, II e III estão corretas","Apenas as afirmativas I e II estão corretas","Apenas as afirmativas II e III estão corretas","Apenas as afirmativas I e III estão corretas"],"correta":2,"explicacao":"Gabarito: <strong>Apenas as afirmativas II e III estão corretas</strong>.","banca":"IBFC","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2001648,"enunciado":"Assinale a alternativa que apresente corretamente o prazo de encaminhamento da documentação básica, complementar e adicional.","opcoes":["Até o último dia útil do quinto mês subsequente ao da comunicação, pela CAIXA, de aceitação do pedido de habilitação do contrato","Até o primeiro dia útil do quinto mês subsequente ao da comunicação, pela CAIXA, de aceitação do pedido de habilitação do contrato","Até o primeiro dia útil do quarto mês subsequente ao da comunicação, pela CAIXA, de aceitação do pedido de habilitação do contrato","Até o último dia útil do quarto mês subsequente ao da comunicação, pela CAIXA, de aceitação do pedido de habilitação do contrato"],"correta":0,"explicacao":"Gabarito: <strong>Até o último dia útil do quinto mês subsequente ao da comunicação, pela CAIXA, de aceitação do pedido de habilitação do contrato</strong>.","banca":"IBFC","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2001649,"enunciado":"Acerca das disposições sobre documentação no Manual de Normas e Procedimentos Operacionais do Fundo de Compensação de Variações Salariais (MNPO – FCVS), analise as afirmativas abaixo: I. A CAIXA pode suspender o encaminhamento da documentação básica, complementar e adicional mediante comunicação ao Agente Financeiro. II. A penalidade pelo descumprimento do prazo de encaminhamento é a exclusão do contrato do cadastro do Sistema de Administração do Fundo de Compensação de Variações Salariais (SICVS), com a devida comunicação ao Agente Financeiro, facultado novo encaminhamento, em conformidade com o disposto no Manual. III. O prazo para guarda, pelo Agente Financeiro, dos originais da documentação básica, complementar e adicional habilitados ao Fundo de Compensação de Variações Salariais é 60 (sessenta) dias da data da homologação do valor. Assinale a alternativa correta.","opcoes":["As afirmativas I, II e III estão corretas","Apenas as afirmativas I e II estão corretas","Apenas as afirmativas II e III estão corretas","Apenas as afirmativas I e III estão corretas"],"correta":1,"explicacao":"Gabarito: <strong>Apenas as afirmativas I e II estão corretas</strong>.","banca":"IBFC","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2001650,"enunciado":"Sobre o encaminhamento e análise da documentação, conforme as disposições do Manual de Normas e Procedimentos Operacionais do Fundo de Compensação de Variações Salariais (MNPO – FCVS), analise as afirmativas abaixo e dê valores de Verdadeiro (V) ou Falso (F). ( ) Caso o Agente Financeiro opte pelo envio dos dossiês por serviço de entrega, este ocorrerá por sua exclusiva responsabilidade, inclusive quanto aos custos inerentes à contratação dos serviços de entrega e recuperação. ( ) Na necessidade de reapresentação da documentação habilitada, a CAIXA, mediante justificativa, a solicitará ao Agente Financeiro. ( ) A CAIXA comunicará ao Agente Financeiro acerca da disposição da documentação original para sua recuperação, mantendo-a sob seu poder por um prazo de até 5 (cinco) dias, a contar-se da data de comunicação. Assinale a alternativa que apresenta a sequência correta de cima para baixo.","opcoes":["V, V, V","V, V, F","F, F, V","F, V, F"],"correta":1,"explicacao":"Gabarito: <strong>V, V, F</strong>.","banca":"IBFC","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2001651,"enunciado":"Acerca do tratamento da documentação recebida pela CAIXA, conforme as disposições do Manual de Normas e Procedimentos Operacionais do Fundo de Compensação de Variações Salariais (MNPO – FCVS), assinale a alternativa incorreta.","opcoes":["A CAIXA manterá em arquivo os documentos recebidos em cópia, em papel, autenticada em cartório ou microfilmados de acordo com o Decreto nº 1.799, de 30 de janeiro de 1996","A CAIXA poderá inutilizar documentos sempre que estiverem ocupando muito espaço na repartição pública","A CAIXA digitalizará o original ou autenticará a cópia em papel por ela produzida a partir dos documentos originais entregues","A CAIXA devolverá ao Agente Financeiro no mesmo ato, os documentos originais recebidos acompanhados de cópia da capa do lote de dossiês entregues e das folhas de rosto desses dossiês, com seu ateste de recebimento"],"correta":1,"explicacao":"Gabarito: <strong>A CAIXA poderá inutilizar documentos sempre que estiverem ocupando muito espaço na repartição pública</strong>.","banca":"IBFC","ano":2021,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2072436,"enunciado":"As instituições financeiras e as demais instituições autorizadas a funcionar pelo Banco Central do Brasil devem observar as normas e procedimentos previstos no Plano Contábil das Instituições do Sistema Financeiro Nacional - COSIF. O COSIF foi instituído em 1987. Analise as afirmativas sobre os objetivos do COSIF. I. Uniformizar a escrituração pelas instituições financeiras e entidades seguradoras. II. Possibilitar o acompanhamento do sistema financeiro, análise, avaliação do desempenho e controle, pela Receita Federal do Brasil, em conjunto com o Banco Central do Brasil. III. Expressar com fidedignidade e clareza a real situação econômico-financeira das Instituições Financeiras e conglomerados financeiros. Assinale a alternativa correta","opcoes":["As afirmativas I, II e III estão corretas","Apenas as afirmativas I e III estão corretas","Apenas a afirmativa I está correta","Apenas a afirmativa III está correta","Apenas as afirmativas I e II estão corretas"],"correta":3,"explicacao":"Gabarito: <strong>Apenas a afirmativa III está correta</strong>.","banca":"IBFC","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2072448,"enunciado":"Fundado em 27 de novembro de 1995, o Instituto Brasileiro de Governança Corporativa (IBGC), organização da sociedade civil, é referência nacional e uma das principais no mundo em governança corporativa. Seu objetivo é gerar e disseminar conhecimento a respeito das melhores práticas em governança corporativa e influenciar os mais diversos agentes em sua adoção, contribuindo para o desempenho sustentável das organizações e, consequentemente, para uma sociedade melhor. A principal publicação do IBGC é o Código das Melhores Práticas de Governança Corporativa, lançado em 1999 e, no ano de 2022, está em sua sexta edição. Verifica-se, cada vez mais, uma quantidade crescente de empresas caminhando na direção da implementação e disseminação de práticas de governança corporativa pelas mais variadas razões. Assinale a alternativa correta.","opcoes":["A adoção de práticas de governança corporativa contribui para uma postura “politicamente correta” por parte de grandes corporações, logo, é importante adotá-las","A adoção de práticas de governança corporativa contribui para uma melhor avaliação de grandes corporações, pelo público em geral, que não necessariamente compreende o que são as práticas de governança corporativa","A adoção de práticas de governança corporativa é obrigatória para empresas com capital aberto e instituições financeiras, por força de lei, sendo assim uma questão de estar em compliance com a legislação vigente","A adoção de práticas de governança corporativa contribui para a longevidade das corporações e acesso facilitado ao capital, devido à percepção de menores riscos na condução da estratégia empresarial","A adoção de práticas de governança corporativa contribui para que as empresas, em um contexto geral, tenham maior facilidade na obtenção de empréstimos e financiamentos bancários"],"correta":3,"explicacao":"Gabarito: <strong>A adoção de práticas de governança corporativa contribui para a longevidade das corporações e acesso facilitado ao capital, devido à percepção de menores riscos na condução da estratégia empresarial</strong>.","banca":"IBFC","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2073403,"enunciado":"O Sistema Financeiro Nacional (SFN) é composto por um conjunto de entidades e instituições que promovem a intermediação financeira. Nesse sentido, analise as assertivas e assinale a alternativa que aponta as corretas. I. A organização do Sistema Financeiro Nacional (SFN) acontece por meio de agentes normativos, supervisores e operadores. II. O Conselho Monetário Nacional, órgão normativo, tem a responsabilidade de formular a política da moeda e do crédito. III. O Banco Central do Brasil, entidade supervisora, tem por objetivo monitorar e fiscalizar o sistema financeiro, além de executar as políticas monetária, cambial e de crédito. IV. A comissão de valores mobiliários (CVM), bancos, caixas econômicas e a bolsa de valores são exemplos de operadores do SFN.","opcoes":["Apenas I e II.","Apenas I, II e III.","I, II, III e IV.","Apenas II, III e IV.","Apenas II e III."],"correta":1,"explicacao":"Gabarito: <strong>Apenas I, II e III.</strong>.","banca":"INSTITUTO AOCP","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2073404,"enunciado":"Você foi escalado para desenvolver e implementar um projeto relacionado à tecnologia da informação (TI), que tem por objetivo colaborar com a avaliação dos principais papéis negociados no mercado de capitais, a respeito dos quais é correto afirmar que","opcoes":["as ações podem ser classificadas em três espécies: ordinárias, preferenciais e de fruição ou gozo.","as opções sobre ações representam um direito de compra de ações ao preço de mercado, válido por tempo determinado.","os DRs (Depositary Receipts) apresentam duas categorias quando negociados nas bolsas de valores norte-americanas.","os Brazilian Depositary Receipts (BDR) são uma forma de captar recursos no mercado internacional, mediante o lançamento de recibos de depósitos (DR).","as debêntures representam a menor parcela (fração) do capital social de uma sociedade anônima, destinadas ao financiamento de projetos de investimentos."],"correta":0,"explicacao":"Gabarito: <strong>as ações podem ser classificadas em três espécies: ordinárias, preferenciais e de fruição ou gozo.</strong>.","banca":"INSTITUTO AOCP","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2073405,"enunciado":"O mercado cambial pode ser definido como o segmento no qual ocorrem as operações de conversões de moeda nacional em estrangeiras e vice-versa. Nesse sentido, analise as assertivas e assinale a alternativa que aponta a(s) correta(s). I. A taxa de câmbio spot ocorre quando o pagamento da moeda estrangeira e a entrega de moeda nacional são realizados à vista. II. O mercado de câmbio no Brasil encontra-se segmentado em mercado de câmbio de taxas livres e mercado de câmbio de taxas flutuantes. III. O VET (Valor Efetivo Total) incorpora a taxa de câmbio, o Imposto sobre Operações Financeiras (IOF) e as tarifas incidentes na operação.","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"INSTITUTO AOCP","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2073406,"enunciado":"Em relação aos produtos financeiros (ativos e passivos) disponíveis, assinale a alternativa correta.","opcoes":["O Certificado de Depósito Bancário e o Recibo de Depósito Bancário podem ser transferidos, a qualquer momento, para outros investidores.","O hot money são operações de curto prazo e é utilizado para financiar o caixa das empresas. Tem como referencial a taxa CDI e o spread cobrado, sendo isento do IOF.","O CDI (Certificado de Depósito Interfinanceiro) é um título que lastreia as operações entre os bancos. É isento de IR e os juros são definidos pela taxa over.","Commercial papers são títulos privados bancários, emitidos para compensar o depósito compulsório realizado pelos bancos junto ao BACEN.","A caderneta de poupança é uma aplicação popular e possui como principais atrativos a liquidez imediata e a isenção de IR para pessoas físicas e jurídicas."],"correta":2,"explicacao":"Gabarito: <strong>O CDI (Certificado de Depósito Interfinanceiro) é um título que lastreia as operações entre os bancos. É isento de IR e os juros são definidos pela taxa over.</strong>.","banca":"INSTITUTO AOCP","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2073407,"enunciado":"Em relação aos crimes de lavagem de dinheiro e à Lei n.º 9.613/1998 e suas alterações, assinale a alternativa correta.","opcoes":["Os crimes de \"lavagem\" ou ocultação de bens, direitos e valores geram penas de reclusão que podem ser aumentadas, mas não diminuídas, de um a dois terços.","A atividade de lavagem de dinheiro pode ser subdividida em duas categorias: conversão em bens e movimentação do dinheiro/valores/direitos.","São quatro os estágios da atividade de lavagem de dinheiro, ou seja, colocação, ocultação, integração e aquisição de bens ou investimentos.","O conselho de controle de atividades financeiras (COAF) foi criado pela Lei nº 9.613/1998 e tem a incumbência de aplicar as sanções administrativas penais.","A lei brasileira relacionada ao crime de lavagem de dinheiro estabeleceu 8 capítulos, apresentados em uma sequência lógicoestrutural."],"correta":1,"explicacao":"Gabarito: <strong>A atividade de lavagem de dinheiro pode ser subdividida em duas categorias: conversão em bens e movimentação do dinheiro/valores/direitos.</strong>.","banca":"INSTITUTO AOCP","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2094282,"enunciado":"À luz da Previdência Complementar, julgue o item.\n\n\n\n\nPara garantia de todas as suas obrigações, as sociedades seguradoras constituirão reservas técnicas em conformidade com os critérios fixados pelo Conselho Nacional De Seguros Privados (CNSP) e pela Superintendência de Seguros Privados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2094286,"enunciado":"À luz da Previdência Complementar, julgue o item.\n\n\n\n\nO risco oriundo de uma situação econômica adversa que contraria tanto as expectativas da sociedade no momento da elaboração de sua política de aceitação do risco quanto as incertezas existentes na estimação das provisões é chamado de risco de subscrição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2094290,"enunciado":"À luz da Previdência Complementar, julgue o item.\n\n\n\n\nAs empresas autorizadas a elaborar, operar e comercializar títulos de capitalização são chamadas de sociedade de capitalização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2098562,"enunciado":"Em mercados em que há presença da assimetria de informação, o funcionamento não ocorre como o previsto em um mercado competitivo de bens e serviços. Stiglitz e Weiss (1982) desenvolvem o conceito de assimetria de informação aplicado aos mercados financeiros, na medida em que um participante deste mercado com frequência não sabe o suficiente sobre o outro participante. Tendo isso em vista, avalie as seguintes afirmativas. I - Risco moral é falha de mercado ex ante, decorrente do aumento dos juros cobrados pelo emprestador devido ao fato de este não conhecer adequadamente todos os tomadores. II - A despeito de a assimetria de informação elevar a taxa de juros, ela não está relacionada com a restrição de crédito, a qual está diretamente envolvida com a oferta de poupança no país. III - Em mercados marcados pela assimetria de informação, a regulação econômica possui um papel essencial para mitigar seus efeitos deletérios na dinâmica econômica. No Brasil, o Banco Central do Brasil (BCB) é responsável pela regulação dos bancos capazes de criar moeda, tais como os bancos comerciais e múltiplos, entre outros, já a Comissão de Valores Mobiliários (CVM) é responsável pela regulação dos bancos que não são capazes de criar moeda, a exemplo dos bancos de investimento e de desenvolvimento. IV - Para conseguir alcançar o objetivo de melhorar a eficiência e reduzir as assimetrias do sistema financeiro nacional (SFN), o BCB e a CVM devem atuar em conjunto e com apoio do congresso nacional no sentido de aprimoramento de leis, regulações e fiscalizações. Quais estão corretas?","opcoes":["Apenas I.","Apenas IV.","Apenas II e IV.","Apenas III e IV.","Apenas I, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>Apenas I, III e IV.</strong>.","banca":"FAURGS","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105907,"enunciado":"Sobre o sistema financeiro nacional, analise as afirmativas a seguir. I. Mercado monetário é o mercado que fornece moeda à economia, com transferências de recursos a curtíssimo prazo, como as realizadas entre as próprias instituições financeiras ou entre elas e o Banco Central do Brasil (BCB). II. Mercado de crédito é o mercado que fornece recursos para o consumo das pessoas em geral e para o funcionamento das empresas, em operações predominantemente de curto e médio prazos. III. Mercado de câmbio é o mercado em que são negociadas as trocas de moedas estrangeiras por moeda nacional, com a participação dos agentes econômicos que têm recebimentos ou pagamentos a realizar em moeda estrangeira, das instituições autorizadas a operar em câmbio e do Banco Central do Brasil (BCB). Está correto o que se afirma em","opcoes":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105908,"enunciado":"Sobre o sistema financeiro nacional, marque V para afirmativa verdadeira e F para a falsa. ( ) Quando o Banestes faz um empréstimo, o dinheiro recebido pelo cliente não tem destinação obrigatória. ( ) Nas operações de leasing (arrendamento mercantil), a regulamentação do Banco Central do Brasil (BCB) estabelece um prazo mínimo de duração do leasing operacional maior que do leasing financeiro. ( ) Quando o Banestes participa do processo de colocação no mercado de uma debênture, o Banestes não tem responsabilidade pelo pagamento dos juros e do principal, que é da emissora dessa debênture. As afirmativas são, respectivamente,","opcoes":["F, F e F.","F, F e V.","V, F e V.","V, F e F.","V, V e V."],"correta":2,"explicacao":"Gabarito: <strong>V, F e V.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105909,"enunciado":"Assinale qual dos agrupamentos de “carteiras” que compõem as instituições do conglomerado Banestes não atenderia aos requisitos necessários para o Banestes ser considerado um “banco múltiplo” pela regulamentação do Banco Central do Brasil (BCB).","opcoes":["Comercial; de investimento; de crédito imobiliário; de arrendamento mercantil.","Comercial; de crédito, financiamento e investimento; de arrendamento mercantil; distribuidora de títulos e valores mobiliários.","De investimento; de crédito, financiamento e investimento; de crédito imobiliário; de arrendamento mercantil.","De crédito, financiamento e investimento; de crédito imobiliário; de arrendamento mercantil; distribuidora de títulos e valores mobiliários.","De investimento; de crédito imobiliário; de arrendamento mercantil; distribuidora de títulos e valores mobiliários."],"correta":3,"explicacao":"Gabarito: <strong>De crédito, financiamento e investimento; de crédito imobiliário; de arrendamento mercantil; distribuidora de títulos e valores mobiliários.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105910,"enunciado":"Sobre o sistema financeiro nacional e o mercado bancário, assinale a afirmativa correta.","opcoes":["A carteira de desenvolvimento é exclusiva para bancos públicos.","Os depósitos em cooperativas de crédito têm a proteção do Fundo Garantidor de Crédito (FGC).","As agências de fomento nunca podem prestar assistência a programas e projetos desenvolvidos em estado limítrofe ao da unidade da Federação onde estiver sediada.","As corretoras de câmbio realizam financiamentos a exportações e importações, além de adiantamentos sobre contratos de câmbio.","O Conselho Nacional de Previdência Complementar (CNPC) é o órgão normativo superior sob o qual operam as entidades abertas de previdência."],"correta":0,"explicacao":"Gabarito: <strong>A carteira de desenvolvimento é exclusiva para bancos públicos.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105911,"enunciado":"Em relação ao sistema financeiro nacional, assinale a afirmativa correta.","opcoes":["As sociedades de arrendamento mercantil podem fazer colocação de debêntures de emissão pública ou particular e de notas promissórias destinadas à oferta pública.","As sociedades de crédito financiamento e investimento podem captar recursos por meio de depósitos à vista de seus clientes em contas corrente, letras de câmbio, RDB (recibos de depósitos bancários), DI (depósitos interfinanceiros).","As agências de fomento podem captar recursos junto ao público.","As sociedades de crédito ao microempreendedor e à empresa de pequeno porte não podem receber repasses de fundos oficiais.","As companhias hipotecárias podem captar depósitos de poupança para a concessão de financiamentos imobiliários residenciais ou comerciais."],"correta":0,"explicacao":"Gabarito: <strong>As sociedades de arrendamento mercantil podem fazer colocação de debêntures de emissão pública ou particular e de notas promissórias destinadas à oferta pública.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105912,"enunciado":"Em matéria de sistema financeiro nacional, analise as afirmativas a seguir. I. Caixas econômicas são empresas públicas que exercem atividades típicas de banco comercial, com prioridade institucional para concessão de empréstimos e financiamentos de programas e projetos de natureza social II. A principal diferença entre as corretoras de títulos e de valores mobiliários e as distribuidoras de títulos e de valores mobiliários é que só as corretoras podem operar diretamente nos ambientes e sistemas de negociação dos mercados organizados de bolsa de valores. III. As corretoras de câmbio atuam, exclusivamente, no mercado de câmbio. Está correto o que se afirma em","opcoes":["II, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105913,"enunciado":"Sobre o Conselho Monetário Nacional (CMN), assinale a afirmativa correta.","opcoes":["Um objetivo do CMN é estimular o desenvolvimento dos mercados de seguros.","Compete ao CMN coordenar as políticas monetária, creditícia, orçamentária e da dívida pública interna e externa.","Não pode acontecer mais de uma reunião do CMN por mês.","O CMN é presidido pelo presidente do Banco Central do Brasil (BCB).","É no CMN que se decidem as normas principais para o funcionamento das instituições financeiras e das entidades fechadas de previdência complementar."],"correta":1,"explicacao":"Gabarito: <strong>Compete ao CMN coordenar as políticas monetária, creditícia, orçamentária e da dívida pública interna e externa.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105914,"enunciado":"Acerca do Comitê de Política Monetária (Copom), assinale a afirmativa correta.","opcoes":["É no Copom que se define a meta para a inflação.","Os membros do Copom são o Presidente do Banco Central do Brasil e todos os seus diretores.","O regulamento do Copom estabelece que a deliberação tem de se dar por unanimidade dos votos.","Não se divulga qual foi o voto de cada membro do Copom.","Após a divulgação da decisão do Copom, as operações no sistema financeiro nacional têm de ser realizadas obrigatoriamente com base nas taxas de juros definidas pelo Copom."],"correta":1,"explicacao":"Gabarito: <strong>Os membros do Copom são o Presidente do Banco Central do Brasil e todos os seus diretores.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105915,"enunciado":"Em relação ao Banco Central do Brasil (BCB), assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) O BCB adota o sistema de metas para inflação para tentar manter a inflação dentro de limites pré-estabelecidos. ( ) Não há exigência de autorização do BCB para o Banestes oferecer produtos e serviços financeiros regulados, devendo ser observado o objeto social do Banestes. ( ) A supervisão de conduta do BCB não abrange o risco de reputação do Banestes. As afirmativas são, respectivamente,","opcoes":["F, F e F.","F, V e V.","V, V e F.","V, F e F.","V, V e V."],"correta":2,"explicacao":"Gabarito: <strong>V, V e F.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105916,"enunciado":"Sobre o Banco Central do Brasil (BCB), analise as afirmativas a seguir. I. Não há prazo máximo para decisão do BCB relativa à autorização para funcionamento de uma nova carteira que o Banestes queira operar. II. Faz parte da supervisão de conduta do BCB a verificação da adequação do Banestes em relação à prevenção à lavagem de dinheiro e ao financiamento do terrorismo (PLD/FT). III. Somente após o BCB decretar a intervenção ou a liquidação extrajudicial, ou reconhecer o estado de insolvência da instituição associada ao FGC (Fundo Garantidor de Crédito), é que os depositantes podem requisitar a garantia. Está correto o que se afirma em","opcoes":["III, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105917,"enunciado":"Em relação à Comissão de Valores Mobiliários (CVM), analise as afirmativas a seguir. I. A CVM é uma entidade autárquica em regime especial, vinculada ao Ministério da Fazenda. II. No caso de Fundos de Investimentos, tanto o administrador quanto o gestor do fundo devem estar credenciados junto à CVM. III. Em função dos requisitos de sigilo fiscal, a CVM somente pode encaminhar indícios de ilícito fiscal à Secretaria da Receita Federal após instaurado processo judicial. Está correto o que se afirma em","opcoes":["I, apenas.","II, apenas.","III, apenas.","I e II, apenas.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105918,"enunciado":"Sobre a Comissão de Valores Mobiliários (CVM), assinale V para afirmativa verdadeira e F para a falsa. ( ) A CVM não tem estabelecidos prazos máximos para decisão de autorização de funcionamento de novas instituições sob sua regulação. ( ) As corretoras e as distribuidoras de títulos e valores mobiliários são de supervisão exclusiva da CVM. ( ) As plataformas eletrônicas de investimento participativo (Crowdfunding de investimento) são reguladas pela CVM. As afirmativas são, respectivamente,","opcoes":["F, F e F.","F, F e V.","V, F e V.","V, F e F.","V, V e V."],"correta":1,"explicacao":"Gabarito: <strong>F, F e V.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105919,"enunciado":"Tendo por base as previsões do Guia de Conduta Ética do Banestes, assinale a afirmativa correta.","opcoes":["Com base no princípio de “objeção de consciência por motivo de crença religiosa” reconhecido pelo STF (Supremo Tribunal Federal), o funcionário do Banestes pode abster-se de atender a clientes de religiões que considera ofensivas à que professa.","A necessidade de o funcionário do Banestes assegurar a privacidade das informações pessoais do consumidor cessa quando o consumidor deixar de ser cliente.","Em qualquer situação, o funcionário do Banestes deve deixar claro que as contribuições científicas ou acadêmicas que fizer são realizadas em seu próprio nome e não representam posicionamento institucional.","A responsabilidade de o funcionário do Banestes observar, divulgar e propagar as diretrizes do Guia de Conduta Ética não aumenta quanto mais elevado for o cargo ou função que ocupa.","O funcionário do Banestes não tem a previsão de priorizar a utilização dos produtos e serviços do Banestes."],"correta":2,"explicacao":"Gabarito: <strong>Em qualquer situação, o funcionário do Banestes deve deixar claro que as contribuições científicas ou acadêmicas que fizer são realizadas em seu próprio nome e não representam posicionamento institucional.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105920,"enunciado":"Tendo por base as previsões do Guia de Conduta Ética do Banestes, analise os itens a seguir. I. O funcionário do Banestes tem o dever de avaliar a conformidade dos normativos internos com os normativos externos e buscar soluções para a atualização e adequação, caso necessário. II. Toda guarda de bens do Banestes para utilização fora do local de trabalho pelo funcionário do Banestes é considerada “para fins particulares”. III. O funcionário do Banestes deve se comprometer e colaborar com a atividade de investigação ou fiscalização de órgãos, entidades ou agentes públicos ou privados, ou no âmbito das agências reguladoras e dos órgãos de fiscalização do SFN (Sistema Financeiro Nacional). Está correto o que se afirma em","opcoes":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105921,"enunciado":"Em relação à prevenção do uso do Sistema Financeiro para atos ilícitos, em conformidade com a Lei nº 9.613/1998, assinale a afirmativa correta.","opcoes":["Na forma da Lei nº 9.613/1998, o Banestes tem de efetivar o registro de transações que ultrapassem os limites fixados pela autoridade competente, inclusive quando esse limite somente é alcançado pela soma de diversas transações do cliente com uma mesma pessoa, conglomerado ou grupo.","A Banestes Distribuidora de Títulos e Valores Mobiliários não se inclui entre as pessoas jurídicas que precisam fazer comunicações referentes a transações que ultrapassem os limites fixados pela autoridade competente estabelecidas na Lei nº 9.613/1998.","Os cadastros de clientes do Banestes requeridos pela Lei nº 9.613/1998 terão de ser eliminados imediatamente quando houver encerramento da conta desses clientes no Banestes.","O Conselho de Controle de Atividades Financeiras (Coaf), atual Unidade de Inteligência Financeira (UIF), somente pode comunicar indícios de crimes de “lavagem” ou ocultação de valores às autoridades competentes após a existência de processo judicial.","Somente se tiver autorização judicial é que o Conselho de Controle de Atividades Financeiras (Coaf), atual Unidade de Inteligência Financeira (UIF) pode requerer aos órgãos da Administração Pública as informações cadastrais bancárias e financeiras de pessoas envolvidas em atividades suspeitas."],"correta":0,"explicacao":"Gabarito: <strong>Na forma da Lei nº 9.613/1998, o Banestes tem de efetivar o registro de transações que ultrapassem os limites fixados pela autoridade competente, inclusive quando esse limite somente é alcançado pela soma de diversas transações do cliente com uma mesma pessoa, conglomerado ou grupo.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105922,"enunciado":"Em relação à prevenção da utilização do Sistema Financeiro para os atos ilícitos, em conformidade com a Lei nº 9.613/1998, assinale (V) para afirmativa verdadeira e (F) para a falsa. ( ) A identificação de clientes do Banestes, quando se tratar de pessoa jurídica, deverá abranger as pessoas físicas autorizadas a representá-la, bem como seus proprietários. ( ) O Banestes fica desobrigado de fazer comunicações, na periodicidade estabelecida pelo órgão competente, quando não ocorrerem propostas, transações ou operações passíveis de serem comunicadas. ( ) Uma pessoa condenada por crimes de \"lavagem\" ou ocultação de valores fica interditada para o exercício de cargo de diretor, de membro de conselho de administração ou de gerência do Banestes pelo dobro do tempo da pena privativa de liberdade aplicada. As afirmativas são, respectivamente,","opcoes":["F, F e F.","F, F e V.","V, F e F.","V, F e V.","V, V e V."],"correta":3,"explicacao":"Gabarito: <strong>V, F e V.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105923,"enunciado":"Em relação à ruptura digital no SFN (Sistema Financeiro Nacional) promovida pelo PIX; pelos criptoativos, CBDC (Central Bank Digital Currency – moeda digital de banco central) e outras moedas digitais, e a Lei nº 14.478/2022 (“Lei de Criptoativos”), assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) Todas as transações de “PIX Saque” e de “PIX Troco” podem ser cobradas das pessoas físicas. ( ) À semelhança das criptomoedas privadas de emissão descentralizada, como o Bitcoin, a CBDC não tem garantia de valor em relação à moeda soberana de um país. ( ) A Lei nº 14.478/2022 (“Lei de Criptoativos”) estabelece que o Código de Defesa do Consumidor não é aplicado às atividades ou operações com criptoativos. As afirmativas são, respectivamente,","opcoes":["F, F e F.","V, V e F.","V, F e V.","F, V e V.","V, V e V."],"correta":0,"explicacao":"Gabarito: <strong>F, F e F.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105924,"enunciado":"Em matéria de ruptura digital no setor bancário e financeiro promovida pelo “Open Finance” (sistema financeiro aberto), assinale a afirmativa correta.","opcoes":["Somente as instituições financeiras e demais instituições autorizadas a funcionar pelo Banco Central do Brasil (BCB) podem participar do “Open Finance”.","No “Open Finance”, o compartilhamento de dados e serviços se inicia com a solicitação do cliente à instituição participante que vai ceder os dados (instituição de origem dos dados).","No “Open Finance”, se as finalidades ou os dados ou serviços que são objeto de compartilhamento forem alterados, não haverá a necessidade de novo consentimento do cliente.","No “Open Finance”, o cliente tem a opção de definir o compartilhamento de dados sem prazo de término.","A Lei do Sigilo Bancário não se aplica à troca de informações no “Open Finance”."],"correta":0,"explicacao":"Gabarito: <strong>Somente as instituições financeiras e demais instituições autorizadas a funcionar pelo Banco Central do Brasil (BCB) podem participar do “Open Finance”.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105925,"enunciado":"Em tema de ruptura digital no SFN (Sistema Financeiro Nacional) promovida pelas Fintechs de crédito SCD (Sociedades de Crédito Direto) e SEP (Sociedades de Empréstimo entre Pessoas), assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) As SCD e as SEP têm por objeto a realização de operações exclusivamente por meio de plataforma eletrônica. ( ) As SCD podem obter recursos para concessão de créditos em operações de repasses e de empréstimos originários do BNDES (Banco Nacional de Desenvolvimento Econômico e Social). ( ) As SCD e as SEP não podem atuar como iniciadoras de transação de pagamento. As afirmativas são, respectivamente,","opcoes":["F, F e F.","F, F e V.","V, F e V.","V, V e F.","V, V e V."],"correta":3,"explicacao":"Gabarito: <strong>V, V e F.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2105926,"enunciado":"Em relação à ruptura digital no SFN (Sistema Financeiro Nacional) promovida pelas IPs (Instituições de Pagamento), assinale a afirmativa correta.","opcoes":["É possível a constituição de IP na qual figure pessoa natural como sócio único.","Todas as IPs devem solicitar autorização ao Banco Central do Brasil (BCB) para iniciar a prestação de serviços.","No curso das transações de iniciação de pagamentos por IPs, é vedado alterar o montante ou qualquer outro elemento da transação de pagamento autorizada pelo usuário final.","Para a realização de pagamentos por intermédio de IPs, é indispensável o relacionamento do cidadão com bancos e outras instituições financeiras.","Uma mesma IP não pode atuar em mais de uma modalidade de IP."],"correta":2,"explicacao":"Gabarito: <strong>No curso das transações de iniciação de pagamentos por IPs, é vedado alterar o montante ou qualquer outro elemento da transação de pagamento autorizada pelo usuário final.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106090,"enunciado":"A oferta de moeda varia","opcoes":["inversamente com a taxa de reservas compulsórias.","diretamente com a taxa de redesconto.","inversamente com os prazos de pagamento dos empréstimos de liquidez.","inversamente com os limites de operações e gama de títulos com acesso ao redesconto.","diretamente com a compra de títulos pelo BC no mercado aberto."],"correta":0,"explicacao":"Gabarito: <strong>inversamente com a taxa de reservas compulsórias.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106091,"enunciado":"Suponha que os títulos do Brasil paguem taxa de juros no período t igual a it . Para se ter títulos americanos, é necessário trocar reais por dólares. Para cada real, recebe-se 1/Et dólares. Seja it* a taxa de juros americana e Ee t+1 a expectativa da taxa de câmbio para o período t+1. Assim a condição de paridade não coberta pela taxa de juros é dada pela expressão:","opcoes":["(1+it ) = (1/Et ) (1+ it*) i t*","(1+it ) = (1/Et ) (1+ it*) Ee t","(1+it*) = (1/Et ) (1+ it ) Ee t+1","(1+it ) = (1+ it*) (1 + (Ee t+1 - Et )/Et )","(1+it ) = (1/Et ) (1+ it*) Ee t+1"],"correta":4,"explicacao":"Gabarito: <strong>(1+it ) = (1/Et ) (1+ it*) Ee t+1</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106103,"enunciado":"Relacione as funções do mercado financeiro com suas respectivas características. 1. Estímulo à formação de poupança. 2. Facilitação da transferência de poupança entre unidades econômicas. 3. Prover liquidez às unidades econômicas. ( ) A maior parte dos pagamentos realizados pelas unidades econômicas é processada por intermédio dos bancos. ( ) Os bancos são importantes facilitadores dessa função, pois repassam os recursos captados de poupadores a tomadores de empréstimos. ( ) Os fundos de pensão, os fundos de investimento e as seguradoras são importantes demandantes de títulos. Assinale a opção que indica a relação correta, na ordem apresentada.","opcoes":["1, 2 e 3.","2, 3 e 1.","2, 1 e 3.","3, 1 e 2.","3, 2 e 1."],"correta":4,"explicacao":"Gabarito: <strong>3, 2 e 1.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106104,"enunciado":"Em relação ao mercado monetário no Brasil, analise as afirmativas a seguir. I. As transferências de recursos a curtíssimo prazo, em geral com prazo de um dia, como aquelas realizadas entre as próprias instituições financeiras ou entre elas e o Banco Central, são realizadas no chamado mercado monetário. II. O mercado monetário é regido pela atuação do Banco Central que, por meio de suas operações de mercado aberto, regula o nível das reservas bancárias. III. A partir das taxas praticadas nas negociações diárias realizadas no SELIC, obtém-se a taxa SELIC (taxa média dos financiamentos diários, com lastro em títulos federais, apurados no SELIC), que representa importante referencial para a formação das taxas de juros no mercado, uma vez que é aceita, no Brasil, como a taxa de juros livre de risco, por envolver títulos públicos. Está correto o que se afirma em","opcoes":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106105,"enunciado":"Em relação ao mercado de capitais, avalie se as afirmativas a seguir são verdadeiras (V) ou falsas (F). ( ) Tem grande importância no desenvolvimento do país, pois estimula a poupança e o investimento produtivo, o que é essencial para o crescimento de qualquer sociedade econômica moderna. ( ) Os principais instrumentos financeiros transacionados no mercado de capitais são: ações, debêntures, notas promissórias, fundos de renda fixa e títulos públicos federais de longo prazo. ( ) O lançamento (emissão primária) de títulos e de ações de empresas é feito por intermédio de um banco de investimento (ou banco múltiplo com carteira de investimento), uma corretora ou uma distribuidora. As afirmativas são, respectivamente,","opcoes":["V, V e V.","V, V e F.","V, F e V.","F, V e V.","F, F e F."],"correta":2,"explicacao":"Gabarito: <strong>V, F e V.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106772,"enunciado":"Sobre o sistema financeiro nacional e o mercado bancário, assinale a instituição listada a seguir que é considerada uma instituição bancária.","opcoes":["Caixa Econômica Federal.","Associação de poupança e empréstimo.","Sociedade de crédito, financiamento e investimento.","Sociedade de crédito imobiliário.","Sociedade de arrendamento mercantil."],"correta":0,"explicacao":"Gabarito: <strong>Caixa Econômica Federal.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106773,"enunciado":"Entre as seguintes carteiras distribuídas entre as instituições do grupo Banestes, assinale a que é obrigatória para o Banestes ser classificado como um banco múltiplo.","opcoes":["Investimento.","Distribuidora de Títulos e Valores Mobiliários.","Crédito, financiamento e investimento.","Crédito imobiliário.","Arrendamento mercantil."],"correta":0,"explicacao":"Gabarito: <strong>Investimento.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106774,"enunciado":"Sobre o Conselho Monetário Nacional (CMN) e o Comitê de Política Monetária (Copom), analise as afirmativas a seguir. I. São objetivos do CMN a estabilidade da moeda e o desenvolvimento econômico e social do país. II. São órgãos supervisores sob a esfera de competência do CMN: o Banco Central do Brasil (BCB), a Comissão de Valores Mobiliários (CVM) e a Superintendência de Seguros Privados (Susep). III. A principal decisão de cada reunião do Copom é a definição da taxa de juros Selic pelo Banco Central do Brasil (BCB). Está correto o que se afirma em","opcoes":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106775,"enunciado":"Em relação ao Banco Central do Brasil (BCB), assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) A partir da Lei Complementar nº 179/2021, o BCB passou a ter autonomia para contratar servidores e definir salários. ( ) O BCB tem a missão institucional de garantir a estabilidade do poder de compra da moeda, zelar por um sistema financeiro sólido, eficiente e competitivo, e fomentar o bem-estar econômico da sociedade. ( ) O BCB se submete a auditoria independente. As afirmativas são, respectivamente,","opcoes":["F, F e F.","F, V e V.","F, F e V.","V, F e V.","V, V e V."],"correta":1,"explicacao":"Gabarito: <strong>F, V e V.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106776,"enunciado":"No mercado de capitais, as seguintes instituições são reguladas pela Comissão de Valores Mobiliários (CVM), à exceção de uma. Assinale-a.","opcoes":["Bolsa de Valores.","Fundos de Investimento.","Sociedades de Capitalização.","Auditores Independentes.","Agências Classificadoras de Risco (Rating)."],"correta":2,"explicacao":"Gabarito: <strong>Sociedades de Capitalização.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106777,"enunciado":"Em relação a seguros e previdência, assinale a afirmativa correta.","opcoes":["No seguro de acidentes pessoais, o suicídio, ou sua tentativa, não é equiparado a acidente pessoal, para fins de pagamento de indenização.","No seguro prestamista que estabelece indenização para quitação, amortização ou pagamento de um determinado número de parcelas de uma dívida, podem estar incluídas coberturas de desemprego involuntário ou voluntário.","O seguro de automóvel na modalidade de valor de mercado referenciado estabelece o pagamento de quantia fixa estipulada pelas partes no ato da contratação do seguro.","Em seguro de automóveis, a seguradora não pode estabelecer um prazo máximo para o segurado comunicar o sinistro.","O “seguro popular” é igual ao “microsseguro”, ambos são direcionados para as necessidades específicas das famílias de baixa renda."],"correta":3,"explicacao":"Gabarito: <strong>Em seguro de automóveis, a seguradora não pode estabelecer um prazo máximo para o segurado comunicar o sinistro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106778,"enunciado":"Em relação à previdência e aos seguros, assinale a afirmativa correta.","opcoes":["Todos os planos de previdência complementar aberta dão direito ao resgate antecipado.","Os planos de previdência complementar aberta não são passíveis de portabilidade.","No Vida Gerador de Benefício Livres (VGBL), o imposto de renda incide sobre o valor total a ser resgatado ou recebido sob a forma de renda; já no Plano Gerador de Benefício Livres (PGBL), o imposto de renda incide apenas sobre os rendimentos.","Nos planos de fundos de pensão organizados por associações ou entidades de classe, estas associações ou entidades de classe têm de fazer contribuições conjuntamente às feitas pelos associados.","Nos planos de benefícios de contribuição definida (CD) dos fundos de pensão, não se tem assegurado o valor do benefício que o participante vai receber no futuro."],"correta":4,"explicacao":"Gabarito: <strong>Nos planos de benefícios de contribuição definida (CD) dos fundos de pensão, não se tem assegurado o valor do benefício que o participante vai receber no futuro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106779,"enunciado":"Em relação aos produtos bancários, analise as afirmativas a seguir. I. A remuneração dos depósitos de poupança composta pela Taxa Referencial (TR) acrescida de 0,5% ao mês só é aplicada enquanto a meta da taxa de juros Selic ao ano for superior a 8,5%. II. O cartão de crédito pode ser emitido tanto por instituição financeira quanto por instituição de pagamento. III. O crédito rural pode ser destinado a custeio, investimento, comercialização e industrialização de produtos agropecuários e de sua produção. Está correto o que se afirma em","opcoes":["II, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>II, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106780,"enunciado":"Quanto a noções do mercado de capitais (“mercado de valores mobiliários”), assinale (V) para afirmativa verdadeira e (F) para a falsa. ( ) No mercado de capitais, os títulos (valores mobiliários) resultantes do investimento que estabelecem uma relação de crédito e débito entre as partes tomadora e poupadora, constituem-se em títulos patrimoniais ou de capital. ( ) No mercado de capitais, o investidor que adquiriu uma ação pode, passado um prazo pré-estabelecido, solicitar o resgate do valor da ação diretamente à empresa. ( ) No mercado de capitais, os investidores não podem adquirir os títulos (valores mobiliários) indiretamente. As afirmativas são, respectivamente,","opcoes":["F, F e F.","F, V e V.","F, F e V.","V, F e F.","V, V e V."],"correta":0,"explicacao":"Gabarito: <strong>F, F e F.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106781,"enunciado":"Quanto a noções do mercado de câmbio, analise os itens a seguir. I. O mercado de câmbio é regulamentado e fiscalizado pelo Banco Central do Brasil (BCB) em conjunto com a Comissão de Valores Mobiliários (CVM). II. As taxas de compra e venda de moeda estrangeira no mercado de câmbio brasileiro são livremente pactuadas entre as partes. III. As pessoas físicas e as pessoas jurídicas podem comprar e vender moeda estrangeira, sem limitação de valor, desde que observada a legislação, as diretrizes estabelecidas pelo Conselho Monetário Nacional (CMN) e a regulamentação editada pelo Banco Central do Brasil (BCB). Está correto o que se afirma em","opcoes":["III, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106782,"enunciado":"Em relação às garantias do Sistema Financeiro Nacional, assinale a afirmativa correta.","opcoes":["No caso de título de crédito, se o devedor pagar ao credor primitivo antes de ser notificado ou tiver conhecimento da cessão a outro credor, fica desobrigado de ter de pagar ao novo credor.","A fiança não pode ser de valor inferior ao da obrigação principal.","No caso de aval, é permitido que o título de crédito seja objeto de aval parcial.","A alienação fiduciária se aplica apenas a bens móveis.","O penhor mercantil se aplica a coisa móvel ou imóvel que possa ser alienada."],"correta":0,"explicacao":"Gabarito: <strong>No caso de título de crédito, se o devedor pagar ao credor primitivo antes de ser notificado ou tiver conhecimento da cessão a outro credor, fica desobrigado de ter de pagar ao novo credor.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106783,"enunciado":"Um cliente do Banestes quer fazer uma aplicação financeira, mas exige que a aplicação conte com proteção do Fundo Garantidor de Crédito (FGC). As opções a seguir apresentam aplicações que podem ser oferecidas a esse cliente, à exceção de uma. Assinale-a.","opcoes":["Depósito de poupança.","Recibo de Depósito Bancário (RDB).","Certificado de Depósito Bancário (CDB).","Fundos de Investimento.","Letras de câmbio."],"correta":3,"explicacao":"Gabarito: <strong>Fundos de Investimento.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106784,"enunciado":"Quanto à autorregulação bancária, analise os itens a seguir. I. A autorregulação bancária vigente no Brasil constitui-se de um conjunto de compromissos básicos de adesão obrigatória, podendo ser complementado por outro conjunto de compromissos adicionais de adesão voluntária. II. As sistemáticas de autorregulação bancária vigentes no Brasil têm eixos normativos de: relacionamento com o consumidor, prevenção a ilícitos e responsabilidade socioambiental. III. As regras de autorregulação bancária são supervisionadas pelo Banco Central do Brasil (BCB). Está correto o que se afirma em","opcoes":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":1,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106785,"enunciado":"Quanto a noções básicas sobre os crimes de lavagem ou ocultação de bens, direitos e valores, assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) O fato de um cliente do Banestes tentar fechar um câmbio de exportação no qual o preço do produto exportado está por um valor de 40% do preço internacional do produto constitui situação que precisa ser tratada para a prevenção à lavagem de dinheiro e ao financiamento do terrorismo (PLD/FT). ( ) O fato de ocorrerem saques em espécie da conta de um cliente do Banestes que recebeu diversos depósitos por transferência eletrônica de várias origens em curto período de tempo constitui situação que precisa ser tratada para a prevenção à lavagem de dinheiro e ao financiamento do terrorismo (PLD/FT). ( ) Um cliente brasileiro do Banestes que é diretor presidente de uma grande empresa privada precisa ser tratado como pessoa exposta politicamente (PEP) constante nas normas de prevenção à lavagem de dinheiro e ao financiamento do terrorismo (PLD/FT) editadas pelos órgãos reguladores e fiscalizadores. As afirmativas são, respectivamente,","opcoes":["F, F e F.","F, F e V.","V, F e F.","V, V e F.","V, V e V."],"correta":3,"explicacao":"Gabarito: <strong>V, V e F.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106786,"enunciado":"Em relação à prevenção da utilização do sistema financeiro para os atos ilícitos, em conformidade com a Lei nº 9.613/1998, analise as afirmativas a seguir. I. O Banestes, por ser considerado um banco de menor porte (segmento S3 da definição do Banco Central do Brasil), pode adotar políticas, procedimentos e controles internos para o cumprimento da obrigação de comunicação de atividades suspeitas proporcionalmente menores que os bancos maiores (S1 e S2). II. As operações com indícios de ilicitudes devem ser comunicadas pelo Banestes ao Conselho de Controle de Atividades Financeiras (Coaf), atual Unidade de Inteligência Financeira (UIF), e ao cliente do Banestes a que se refira a operação. III. Se o Banestes não cumprir com as obrigações relacionadas à lavagem ou à ocultação de bens, direitos e valores, poderá ter cassada ou suspensa sua autorização para funcionamento. Está correto o que se afirma em","opcoes":["II, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106787,"enunciado":"Tendo por base as previsões do Guia de Conduta Ética do Banestes para o relacionamento com o cliente e os usuários, assinale (V) para afirmativa verdadeira e (F) para a falsa. ( ) É vedado induzir os clientes ou usuários a erro, assegurar ou sugerir a existência de garantia de resultados futuros ou a isenção de risco. ( ) Deve-se evitar a transferência de contas de clientes por motivo de movimentação no quadro de gerentes entre agências. ( ) Caso o cliente do Banestes seja cidadão dos Estados Unidos da América, o Banestes terá de fornecer dados da conta desse cliente ao Fisco norte americano (IRS) em cumprimento às regras do FATCA (Foreign Account Tax Compliance Act). As afirmativas, são, respectivamente,","opcoes":["F, F e F.","F, F e V.","V, F e F.","V, V e F.","V, V e V."],"correta":4,"explicacao":"Gabarito: <strong>V, V e V.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106788,"enunciado":"Em relação à ruptura digital no SFN (Sistema Financeiro Nacional) promovida pelas Fintechs de crédito; pelas IPs (Instituições de Pagamento); pelo “Open Finance” (sistema financeiro aberto); e pelo PIX, assinale a afirmativa correta.","opcoes":["As Fintechs de crédito não necessitam de autorização do Banco Central do Brasil (BCB) para operarem.","Em relação às Fintechs de crédito, a Sociedade de Empréstimo entre Pessoas (SEP) pode fazer captação de recursos do público, desde que eles estejam inteira e exclusivamente vinculados à operação de empréstimo.","As IPs podem conceder empréstimos e financiamentos a seus clientes.","No “Open Finance”, é obrigatória a participação de todas as instituições autorizadas a funcionar pelo Banco Central do Brasil (BCB).","Empresas podem ser tarifadas no envio de pagamentos ou transferências via PIX, mas não podem ser tarifadas no recebimento de pagamentos ou transferências via PIX."],"correta":1,"explicacao":"Gabarito: <strong>Em relação às Fintechs de crédito, a Sociedade de Empréstimo entre Pessoas (SEP) pode fazer captação de recursos do público, desde que eles estejam inteira e exclusivamente vinculados à operação de empréstimo.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106789,"enunciado":"Em relação à ruptura digital no SFN (Sistema Financeiro Nacional) promovida pelas Fintechs de crédito; pelas IPs (Instituições de Pagamento); pelo “Open Finance” (sistema financeiro aberto); e pelo PIX, assinale a afirmativa correta.","opcoes":["Em relação às Fintechs de crédito, a Sociedade de Crédito Direto (SCD) pode prestar os serviços de análise de crédito para terceiros, cobrança de crédito de terceiros, mas não pode realizar operações de crédito com recursos próprios.","As IPs não podem gerir conta de pagamento.","No “Open Finance”, os clientes de produtos e serviços financeiros podem compartilhar suas informações entre diferentes instituições autorizadas pelo Banco Central do Brasil (BCB).","No “Open Finance”, a movimentação de contas bancárias de uma instituição só pode ser realizada a partir do aplicativo ou site dessa instituição.","É indispensável cadastrar uma chave para fazer ou receber um PIX."],"correta":2,"explicacao":"Gabarito: <strong>No “Open Finance”, os clientes de produtos e serviços financeiros podem compartilhar suas informações entre diferentes instituições autorizadas pelo Banco Central do Brasil (BCB).</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106790,"enunciado":"Em relação à ruptura digital no SFN (Sistema Financeiro Nacional) promovida pelo “Open Finance” (sistema financeiro aberto); e pelo PIX, assinale a afirmativa correta.","opcoes":["No “Open Finance”, o compartilhamento de informações depende da concordância da instituição detentora dessas informações.","No “Open Finance”, o compartilhamento de informações só pode ser interrompido ao final do prazo estabelecido para o compartilhamento.","O PIX funciona 24 horas por dia, sete dias por semana, exceto feriados.","O PIX é o pagamento instantâneo brasileiro criado pelo Banco Central do Brasil (BCB) em que os recursos são transferidos entre contas em poucos segundos.","No âmbito do PIX, aplicam-se aos microempreendedores individuais (MEI) e empresários individuais (EI) as mesmas regras de pessoa jurídica."],"correta":3,"explicacao":"Gabarito: <strong>O PIX é o pagamento instantâneo brasileiro criado pelo Banco Central do Brasil (BCB) em que os recursos são transferidos entre contas em poucos segundos.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106791,"enunciado":"Em relação ao que a Resolução CMN nº 4.949, de 30/09/2021, estabelece para o Banestes, assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) O Banestes deve adotar o previsto na Resolução nas fases de contratação e de pós-contratação de produtos e de serviços, estando desobrigado na fase de pré-contratação. ( ) A necessidade de o Banestes assegurar a identificação dos usuários finais beneficiários de pagamento ou transferência em demonstrativos e extratos de contas de depósitos não se aplica para contas de pagamento pré-pagas. ( ) O Banestes não pode recusar o recebimento de documentos mediante pagamento por meio de cheque. As afirmativas são, respectivamente,","opcoes":["F, F e F.","V, V e F","V, F e V","F, V e V","V, V e V."],"correta":0,"explicacao":"Gabarito: <strong>F, F e F.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106948,"enunciado":"Avalie se as afirmativas a seguir, acerca da apólice de seguros, estão corretas: I. É o documento que formaliza o contrato de seguros entre o segurado e o segurador. II. É constituída de capa ou frontispício. III. Registra as informações do segurado e da seguradora, o ramo e o objeto do seguro, a vigência do seguro, o prêmio do seguro, as importâncias seguradas etc. Está correto o que se afirma em","opcoes":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106949,"enunciado":"Observe as definições a seguir. I. Evento futuro e incerto, ou de data incerta, cuja ocorrência não depende exclusivamente da vontade das partes, e acarreta, geralmente, uma diminuição patrimonial para quem suporta seus efeitos. II. Designação genérica de qualquer interesse segurado, sejam coisas, bens, pessoas, responsabilidades, obrigações, direitos e garantias. Em seguros, elas se referem, respectivamente, a","opcoes":["direitos e prêmio.","prêmio e risco.","risco e objeto.","risco e prêmio.","objeto e direitos."],"correta":2,"explicacao":"Gabarito: <strong>risco e objeto.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106950,"enunciado":"Por meio de medidas de natureza legal ou contratual, pode haver restrições às coberturas de seguro para determinados riscos. Por esta razão, não há cobertura em seguros para","opcoes":["colisões causadas pelo segurado.","roubo ou furto qualificado.","danos a terceiros.","incêndio em imóveis alugados.","atos dolosos do segurado."],"correta":4,"explicacao":"Gabarito: <strong>atos dolosos do segurado.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106951,"enunciado":"Em seguros, frequentemente os segurados têm certa dúvida em relação ao enquadramento correto das coberturas de subtração de bens e de valores. Tal dúvida reside principalmente nas definições de furto e de roubo cobertos pelo seguro. Em relação ao tema, avalie se as afirmativas a seguir são falsas (F) ou verdadeiras (V). ( ) Furto é a subtração de qualquer coisa alheia móvel sem que haja violência ou grave ameaça contra a vítima. ( ) Roubo é a subtração de qualquer coisa alheia, com grave ameaça ou violência contra a vítima. ( ) Furto e roubo são crimes igualmente graves. As afirmativas são, respectivamente,","opcoes":["F – F – F.","F – F – V.","V – F – F.","V – V – F.","V – V – V."],"correta":3,"explicacao":"Gabarito: <strong>V – V – F.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106952,"enunciado":"SNSP é a sigla para o Sistema Nacional de Seguros Privados do Governo Federal. Ele é composto por entidades públicas e privadas que seguem uma hierarquia de atuação. Juntas, estas entidades trabalham com supervisão, fiscalização, regulação e participação na área de seguros privados. O Presidente do SNSP é o","opcoes":["Ministro da Fazenda.","Superintendente da SUSEP.","Presidente da CNSEG.","Superintendente da FENACOR.","Ministro do Desenvolvimento."],"correta":0,"explicacao":"Gabarito: <strong>Ministro da Fazenda.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106953,"enunciado":"O órgão responsável por fixar as diretrizes e normas da política de seguros privados é","opcoes":["a CNSEG.","a FENASEG.","o IBRACOR.","o CNSP.","a FUNENSEG."],"correta":3,"explicacao":"Gabarito: <strong>o CNSP.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106954,"enunciado":"Sinistro é uma ocorrência de um evento indesejável, que tenha cobertura no seguro contratado e esteja especificado na apólice. Todos os tipos de sinistros devem ter origem em um evento","opcoes":["não aleatório, voluntário ou previsto.","súbito, involuntário e imprevisto.","catastrófico, involuntário e previsível.","natural, súbito e voluntário.","aleatório, previsível e ocorrido."],"correta":1,"explicacao":"Gabarito: <strong>súbito, involuntário e imprevisto.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106955,"enunciado":"A regulação de sinistros tem como atores o perito, que é quem apura as causas dos eventos e as consequências ocorridas, e o regulador, que é quem verifica se estão os eventos cobertos pelo contrato de seguros. Por isso, os peritos devem informar ao regulador o que possivelmente causou o evento que deu origem ao sinistro, a dinâmica dos acontecimentos e o que foi danificado, além de indicar as possíveis responsabilidades, estabelecendo a correlação entre causa e efeitos. Nesse caso, dizemos que o perito busca estabelecer","opcoes":["o lapso temporal.","a implicação do efeito.","o nexo de casualidade.","o efeito de resposta.","a aleatoriedade circunstancial."],"correta":2,"explicacao":"Gabarito: <strong>o nexo de casualidade.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106956,"enunciado":"Uma apólice de seguros pode ser modificada, durante sua vigência, por meio de um documento expedido pela seguradora, pelo qual, formalmente, as partes (seguradora e segurado) acordam quanto à alteração de dados e modificam condições da apólice. Este documento é","opcoes":["a condição especial do seguro.","o certificado de seguro.","o bilhete de seguro.","a condição particular do seguro.","o endosso do seguro."],"correta":4,"explicacao":"Gabarito: <strong>o endosso do seguro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106957,"enunciado":"Um dos principais problemas do seguro é a chamada assimetria de informações entre o segurado, que teoricamente tem conhecimento dos riscos expostos, e o segurador, que depende de informações em quantidade e qualidade suficientes para precificar o seguro. Para minimizar essa assimetria, as seguradoras podem solicitar que os segurados prestem informações detalhadas durante o processo de cotação do seguro, inclusive preenchendo formulários específicos. Um formulário muito usado com esse objetivo é","opcoes":["a FAS – Ficha de Análise de Sinistros.","o QAR – Questionário de Avaliação de Riscos.","a FIP – Ficha de Informações da Proposta.","o FIR – Formulário de Informações de Riscos.","o RAR – Relato de Avaliação de Riscos."],"correta":1,"explicacao":"Gabarito: <strong>o QAR – Questionário de Avaliação de Riscos.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106958,"enunciado":"O segurado deve comunicar imediatamente à seguradora a ocorrência de um sinistro para que o processo de apuração de prejuízos, de regulação e a liquidação possam ocorrer no menor prazo possível, minimizando assim as perdas ocorridas e permitindo que o segurado possa repor o que foi perdido. O procedimento usado para a comunicação do sinistro é chamado, no mercado de seguros, de","opcoes":["notificação de sinistro.","averbação de sinistro.","declaração de ocorrência de sinistro.","aviso de sinistro.","informe de sinistro."],"correta":3,"explicacao":"Gabarito: <strong>aviso de sinistro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106959,"enunciado":"Um dos deveres do segurado é pagar o prêmio de seguro segundo as condições de parcelamento escolhidas no momento da contratação, expressa na proposta de seguro e na apólice. A inadimplência do pagamento de prêmio pode fazer com que o segurado","opcoes":["perca o direito à indenização em caso de sinistro.","seja obrigado a solicitar endosso da apólice, para continuar coberto.","se justifique formalmente quanto aos motivos do atraso.","perca o direito de ajustamento final do prêmio, no final da vigência do seguro, mesmo que venha a pagar em atraso.","seja relacionado na lista de maus pagadores, sendo impedido de contratar novos seguros."],"correta":0,"explicacao":"Gabarito: <strong>perca o direito à indenização em caso de sinistro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106960,"enunciado":"Para que um determinado evento de risco possa ser segurável há uma série de requisitos que buscam preservar o intuito do seguro e o equilíbrio que permite a precificação correta, preservando os interesses do mutualismo. Um dos requisitos importantes é que a sua ocorrência seja","opcoes":["limitada ao presente ou passado recente.","independente da vontade das partes.","improvável.","imensurável.","complexa."],"correta":1,"explicacao":"Gabarito: <strong>independente da vontade das partes.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106961,"enunciado":"Um dos pilares dos contratos de seguros é a boa-fé entre as partes. Há situações, entretanto, em que se percebe que o segurado pode ter más intenções ao contratar o seguro. Por exemplo, quando um segurado adquire um bem com recursos ilícitos e faz seguro com a intenção de receber indenização, fica configurada uma fraude de","opcoes":["conciliação de ativos.","lavagem de dinheiro.","ampliação da indenização de sinistro.","suborno de agentes privados.","corrupção."],"correta":1,"explicacao":"Gabarito: <strong>lavagem de dinheiro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106962,"enunciado":"Os contratos de seguro trazem um conjunto de cláusulas contratuais que são agrupadas e descritas nos seguintes conjuntos de condições contratuais: gerais, especiais e particulares. Em relação ao tema, analise as afirmativas a seguir. I. As condições gerais refletem o que está e não está coberto no seguro para todas as coberturas de seguro, inclusive as eventuais restrições legais que se aplicam a todas elas, além de várias outras disposições que regem o relacionamento entre as partes. II. As condições especiais são específicas para uma determinada cobertura ou modalidade contratada. III. As condições particulares são um conjunto de cláusulas que alteram as condições gerais ou particulares, modificando ou cancelando disposições existentes. Está correto o que se afirma em","opcoes":["I, apenas.","II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>I, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106963,"enunciado":"O seguro tem por princípio a contribuição de várias pessoas, expostas aos mesmos tipos de risco (massa de segurados), que pagam prêmios de seguro para a formação de um fundo comum, que será gerido pela seguradora, com compromisso de indenizar aqueles que tiverem perdas. Este princípio é chamado de","opcoes":["mutualismo.","complementarismo.","reintegração.","direito do segurado.","repartição conjugada."],"correta":0,"explicacao":"Gabarito: <strong>mutualismo.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106964,"enunciado":"Em matéria jornalística recente, um repórter disse que há quadrilhas especializadas em furtar faróis e lanternas de veículos de luxo, o que poderia não estar coberto pelo seguro, fazendo com que os segurados não viessem a receber o prêmio previsto nas apólices de seguros. Sabendo que pessoas leigas e até mesmo os segurados não necessariamente entendem alguns termos de seguro, cabe explicar que prêmio de seguro é","opcoes":["o que a seguradora paga ao ressegurador.","o que o segurado espera receber se ocorrer um sinistro.","o limite de responsabilidade do segurador.","aquilo que o segurado recebe quando sofre um sinistro.","aquilo que o segurado paga pela transferência do risco ao segurador."],"correta":4,"explicacao":"Gabarito: <strong>aquilo que o segurado paga pela transferência do risco ao segurador.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106965,"enunciado":"Podem existir contratações de seguros de forma individual ou coletiva. Em contratações coletivas pode existir a figura do estipulante, uma pessoa que, entre outras, exerce a função de","opcoes":["redigir as condições gerais do seguro em nome da seguradora e dos segurados.","definir o prêmio de seguro, as franquias e as participações dos segurados.","responder legalmente por fraudes cometidas pelos segurados.","representar os segurados perante a seguradora.","pagar as indenizações."],"correta":3,"explicacao":"Gabarito: <strong>representar os segurados perante a seguradora.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106966,"enunciado":"As franquias são impostas pelos seguradores aos segurados com o intuito de não incorrerem em pequenas perdas que poderiam gerar custos operacionais importantes pelo volume de ocorrências. Adicionalmente, as franquias são uma forma de induzir os segurados a","opcoes":["fazer reservas para cobrir seus possíveis prejuízos.","cumprir com o pagamento do prêmio.","gerenciar melhor seus riscos, a fim de evitar sinistros.","contratar seguros específicos para cobrir as franquias.","limitar a utilização operacional de seus bens."],"correta":2,"explicacao":"Gabarito: <strong>gerenciar melhor seus riscos, a fim de evitar sinistros.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106967,"enunciado":"A Tabela Fipe expressa preços médios de veículos anunciados pelos vendedores, no mercado nacional, servindo apenas como um parâmetro para negociações ou avaliações. As seguradoras utilizam a tabela FIPE para determinar as indenizações de seguros de automóveis, sendo para isso utilizado o valor médio de mercado no dia da ocorrência do sinistro. Nos demais ramos de seguros ocorre a mesma lógica, ou seja, a seguradora indeniza os bens sinistrados, salvo indicações específicas em contrário, pelo seu","opcoes":["valor em risco.","valor de novo.","valor histórico.","valor atual.","valor de face."],"correta":3,"explicacao":"Gabarito: <strong>valor atual.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106968,"enunciado":"Beatriz e Virgílio procuram uma corretora credenciada na Banestes Seguros e por meio telefônico solicitaram a contratação de seguro de vida para ambos. Após as tratativas entre corretora e solicitantes, a Banestes Seguros emitiu o bilhete de seguro. Diante da situação narrada, nos termos do Decreto-Lei nº 73/1966, assinale a afirmativa correta.","opcoes":["A solicitação verbal por meio telefônico realizada por Beatriz e Virgílio não é admitida, devendo a corretora exigir a solicitação por escrito, podendo ser utilizado o meio eletrônico.","A conduta da Banestes Seguros foi equivocada, pois a contratação de seguros por simples emissão de bilhete de seguro, depende de solicitação escrita dos interessados.","A emissão de bilhete de seguro na solicitação verbal feita por Beatriz e Virgílio é autorizada pelo Decreto-lei nº 73 de 1966, sendo que a boa-fé da Sociedade Seguradora, em sua aceitação, constitui presunção juris tantum (relativa).","Na emissão do bilhete de seguro, mediante solicitação verbal de Beatriz e Virgílio, é ilícito à Banestes Seguros arguir a existência de circunstância relativa ao objeto cujo conhecimento prévio influiria na sua aceitação.","O Decreto-lei nº 73 de 1966 permite expressamente a realização de mais de um seguro cobrindo o mesmo objeto mediante solicitação verbal do interessado, podendo ser emitido um único bilhete de seguro, mesmo na hipótese de o seguro não ser de pessoa."],"correta":2,"explicacao":"Gabarito: <strong>A emissão de bilhete de seguro na solicitação verbal feita por Beatriz e Virgílio é autorizada pelo Decreto-lei nº 73 de 1966, sendo que a boa-fé da Sociedade Seguradora, em sua aceitação, constitui presunção juris tantum (relativa).</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106969,"enunciado":"Riobalto, por meio de corretor credenciado, aceitou por escrito proposta de seguro de automóvel da Banestes Seguros. A respeito da situação narrada, nos termos do Decreto nº 60.459/67, assinale a afirmativa correta.","opcoes":["O início da cobertura do risco de Riobalto constará da apólice e coincidirá com a aceitação da proposta.","É vedado no seguro realizado por Riobalto a emissão de apólices de seguros com valor máximo determinado.","A emissão da apólice de Riobalto deverá ser feita até 30 (trinta) dias da aceitação da proposta.","Caso Riobalto não pague o prêmio no prazo fixado na proposta, a apólice vigorará pelo prazo máximo de sessenta dias.","A cobrança do prêmio poderá ser realizada por corretora devidamente credenciada na Banestes Seguros."],"correta":0,"explicacao":"Gabarito: <strong>O início da cobertura do risco de Riobalto constará da apólice e coincidirá com a aceitação da proposta.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106970,"enunciado":"Stela Mayer celebrou contrato de seguros de acidentes pessoais com a Banestes Seguros, contudo deixou de pagar o prêmio no prazo devido. A respeito da situação narrada, nos termos do Decreto nº 61.589/67, assinale a afirmativa correta.","opcoes":["Independentemente de previsão contratual, a ausência do pagamento do prêmio importa no cancelamento automático do contrato de seguro.","O não pagamento do prêmio sempre mantém o contrato em vigor pelo prazo ajustado, cabendo à Banestes Seguros ajuizar as ações judiciais cabíveis.","A ausência de pagamento conduz à vigência do contrato pelo prazo de noventa dias, independentemente de previsão contratual.","Para que haja o cancelamento do seguro, é obrigatória a inserção de cláusula de cancelamento do contrato de seguro na proposta e na apólice, independentemente de notificação, interpelação ou protesto, no caso de o prêmio não ser pago no prazo devido.","A inadimplência no pagamento do prazo nunca gera o cancelamento do contrato, gerando a incidência de multa contratual de vinte por cento e de juros de um por cento ao mês."],"correta":3,"explicacao":"Gabarito: <strong>Para que haja o cancelamento do seguro, é obrigatória a inserção de cláusula de cancelamento do contrato de seguro na proposta e na apólice, independentemente de notificação, interpelação ou protesto, no caso de o prêmio não ser pago no prazo devido.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106971,"enunciado":"A transportadora Hogwarts Transportes Rápidos S.A foi criada recentemente e começará a operar na próxima semana. Assim, ela está empenhada no cumprimento de diversas normas jurídicas que lhe são aplicáveis. A respeito da situação narrada, nos termos do Decreto nº 61.867/67, assinale a afirmativa correta.","opcoes":["Para que a transportadora Hogwarts realize transporte de carga, independentemente do valor, será necessário contratar seguro de responsabilidade civil em garantia das perdas e danos sobrevindos à carga que lhes tenha sido confiada para transporte, contra conhecimento ou nota de embarque.","Caso a transportadora Hogwarts venha a realizar transporte aéreo de passageiros, deverá contratar seguro que garanta, no mínimo, danos pessoais a passageiros de aeronaves comerciais, suas bagagens, acompanhadas ou não, nos limites estabelecidos pelo Código Brasileiro do Ar.","Na hipótese de que a transportadora Hogwarts venha a realizar transporte terrestre de passageiros, deverá, necessariamente, oferecer aos passageiros contrato de seguro que garanta, no mínimo, três vezes o valor da passagem em caso de sinistro.","No Brasil, o seguro de transporte de carga só é obrigatório no serviço internacional de exportação.","O seguro de transporte de passageiros, na atualidade, é facultativo, independentemente da modalidade do serviço."],"correta":1,"explicacao":"Gabarito: <strong>Caso a transportadora Hogwarts venha a realizar transporte aéreo de passageiros, deverá contratar seguro que garanta, no mínimo, danos pessoais a passageiros de aeronaves comerciais, suas bagagens, acompanhadas ou não, nos limites estabelecidos pelo Código Brasileiro do Ar.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106972,"enunciado":"Nastácia celebrou contrato de seguro de acidentes pessoais com a Banestes Seguros com a intervenção direta da corretora de seguros Parfion e Filippovana Corretores Associados. A respeito do tema Direito do Consumidor, assinale a afirmativa correta.","opcoes":["Como houve a intervenção direta da corretora de seguros, a Banestes Seguros não pode ser considerada fornecedora para fins de incidência do Código de Defesa do Consumidor.","Nos contratos de seguros de acidentes pessoais, o Código de Defesa do Consumidor não se aplica, em virtude de norma específica da Superintendência de Seguros Privados (SUSEP).","Na relação entre o segurado e a corretora de seguros, não se aplica o Código de Defesa do Consumidor.","O Código de Defesa do Consumidor não se aplica às prestações de serviço, valendo, apenas, para relações mercantis.","Nastácia, por ser destinatária final do contrato de seguro de acidentes pessoais, é considerada como consumidora para fins do Código de Defesa do Consumidor."],"correta":4,"explicacao":"Gabarito: <strong>Nastácia, por ser destinatária final do contrato de seguro de acidentes pessoais, é considerada como consumidora para fins do Código de Defesa do Consumidor.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106973,"enunciado":"Sofia e Capitolina, amigas, pretendem criar uma corretora de seguros especializada na área de saúde, com Bentinho trabalhando com elas na condição de preposto. A respeito do tema corretoras de seguro, nos termos do Decreto nº 60.459/67, assinale a afirmativa correta.","opcoes":["Sofia e Capitolina não poderão criar uma pessoa jurídica, pois a atividade de corretagem de seguros só pode ser exercida por profissional autônomo na condição de pessoa física.","Para que Sofia e Capitolina exerçam a profissão de corretor de seguros, será necessária a prévia habilitação e registro no Ministério da Fazenda.","Bentinho não poderá trabalhar como preposto de Sofia e Capitolina, pois o exercício da profissão de corretagem é personalíssima, não se admitindo a delegação por meio de preposto.","Entre outros requisitos, para o registro de Sofia e Capitolina, será necessária a apresentação de documentos comprovando terem habilitação técnico-profissional e não serem falidas.","Caso Sofia e Capitolina venham a ser corretoras, não respondem civilmente pelos danos causados aos segurados, pois se trata de responsabilidade exclusiva da sociedade seguradora."],"correta":3,"explicacao":"Gabarito: <strong>Entre outros requisitos, para o registro de Sofia e Capitolina, será necessária a apresentação de documentos comprovando terem habilitação técnico-profissional e não serem falidas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106974,"enunciado":"Katherina celebrou com a Banestes Seguros contrato de seguro de automóvel tendo cobertura por danos materiais e morais sofridos por terceiros. Três dias após a emissão da apólice, Katherina, dirigindo seu automóvel segurado, se envolve em uma colisão. Ocorre que o prêmio ainda não fora pago. A respeito da situação narrada, nos termos do Decreto nº 61.589/67, assinale a afirmativa correta.","opcoes":["Katherina deveria pagar o prêmio antes da emissão da apólice; assim, não está coberta no acidente narrado.","A obrigação do pagamento do prêmio pelo segurado será devida no prazo de 60 (sessenta) dias, contados da data da emissão da apólice.","Como o sinistro sofrido por Katherina ocorreu dentro do prazo de pagamento do prêmio sem que ele se ache efetuado, o direito à indenização não ficará prejudicado se o segurado cobrir o débito respectivo ainda naquele prazo.","A indenização do sinistro sofrido por Katherina pode ser exigida e paga, independe da comprovação do pagamento tempestivo do prêmio.","A legislação brasileira não admite o pagamento do prêmio fracionado, sendo ilegal qualquer cláusula na proposta que preveja o parcelamento."],"correta":2,"explicacao":"Gabarito: <strong>Como o sinistro sofrido por Katherina ocorreu dentro do prazo de pagamento do prêmio sem que ele se ache efetuado, o direito à indenização não ficará prejudicado se o segurado cobrir o débito respectivo ainda naquele prazo.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106975,"enunciado":"Uma determinada cooperativa agrícola exploradora da atividade cafeeira sofre um grande prejuízo na última safra em virtude de nova praga. A respeito do tema seguro obrigatório, e nos termos do Decreto nº 61.867/67, assinale a afirmativa correta.","opcoes":["O seguro rural obrigatório alcança os danos causados por praga sofridos por cooperativa.","Como o dano se deu em virtude de praga, a cooperativa não se encontra protegida.","O seguro rural obrigatório restringe-se à pecuária, não alcançando a atividade agrícola.","Para o recebimento do seguro, a cooperativa deverá ter mais de dez cooperados e demonstrar a imprevisibilidade do evento danoso.","A cooperativa não está segurada pelo seguro rural obrigatório, visto que somente as pessoas físicas são seguradas."],"correta":0,"explicacao":"Gabarito: <strong>O seguro rural obrigatório alcança os danos causados por praga sofridos por cooperativa.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106976,"enunciado":"Um renomado grupo econômico brasileiro pretende criar uma sociedade seguradora para atuação no setor de responsabilidade civil na construção civil com objetivo de instalar filiais em Miami, Estados Unidos da América, e em Lisboa, Portugal. A respeito da criação de seguradora, nos termos do Decreto nº 60.459/67, assinale a afirmativa correta.","opcoes":["Os subscritores de capital realizarão em dinheiro, no ato da subscrição, o mínimo de 10% (dez por cento) do valor nominal de suas ações, e o restante dentro de um ano.","O pedido de autorização para funcionamento da nova sociedade seguradora será encaminhado à apreciação do Conselho Nacional de Seguros Privados pela SUSEP.","O pedido de autorização feito pelos instituidores da nova sociedade seguradora será instruído com a prova da regularidade da constituição da sociedade do depósito em instituição financeira credenciada na SUSEP da parte já realizada do capital e exemplar do estatuto.","Caso a nova sociedade seguradora não obtenha autorização para funcionar, a importância depositada no Banco do Brasil S.A. será revertida para a Superintendência de Seguros Privados (SUSEP).","A nova sociedade seguradora poderá estabelecer filiais no exterior, desde que ocorra prévia autorização da Superintendência de Seguros Privados (SUSEP)."],"correta":1,"explicacao":"Gabarito: <strong>O pedido de autorização para funcionamento da nova sociedade seguradora será encaminhado à apreciação do Conselho Nacional de Seguros Privados pela SUSEP.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106978,"enunciado":"Um grande grupo empresarial brasileiro tem, entre outras, uma empresa de transporte de aeronaves comerciais e uma construtora de imóveis. Na última reunião do conselho de administração, surgiu dúvida a respeito da obrigatoriedade da celebração do contrato de seguro. A respeito do tema, nos termos do Decreto-lei nº 73/66, assinale a afirmativa correta.","opcoes":["Diferente da construção de imóveis, o seguro de responsabilidade civil de danos pessoais a passageiros de aeronaves comerciais é facultativo.","O seguro de garantia do cumprimento das obrigações do incorporador e construtor de imóveis é facultativo.","É obrigatório o seguro de responsabilidade civil do construtor de qualquer espécie de imóvel, contudo é facultativo o seguro de responsabilidade civil do proprietário de aeronaves e do transportador aéreo.","No Brasil, em razão da liberdade econômica, não há seguro obrigatório para as atividades empresariais de transporte de aeronaves comerciais e de construção de imóveis.","É obrigatório o seguro de garantia do pagamento a cargo de mutuário da construção civil, inclusive a obrigação imobiliária."],"correta":4,"explicacao":"Gabarito: <strong>É obrigatório o seguro de garantia do pagamento a cargo de mutuário da construção civil, inclusive a obrigação imobiliária.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106980,"enunciado":"Com relação à disciplina jurídica do contrato de seguro no Código Civil de 2002, analise as afirmativas a seguir. I. A diminuição do risco no curso do contrato, em qualquer monta, acarreta a redução do prêmio estipulado, sob pena de enriquecimento sem causa da seguradora. II. O segurador é obrigado a pagar em dinheiro o prejuízo resultante do risco assumido, salvo se convencionada a reposição da coisa. III. A recondução tácita do contrato, pelo mesmo prazo, poderá operar mais de uma vez, salvo expresso protesto de alguma das partes. Está correto o que se afirma em","opcoes":["I, apenas.","II, apenas.","III, apenas.","I e II, apenas.","II e III, apenas."],"correta":1,"explicacao":"Gabarito: <strong>II, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106981,"enunciado":"João Paulo, separado de fato de Tereza há 15 anos e em união estável com Maria há 5 anos, faleceu deixando dois filhos maiores e capazes. Após o óbito, Tereza e os filhos de João Paulo, dentre outras providências, entraram em contato com a Banestes Seguros, requerendo o pagamento do capital estipulado no seguro de vida de João Paulo. A Banestes Seguros informou que, 2 anos antes, João Paulo havia substituído os beneficiários do seguro de vida, indicando Maria como única beneficiária do seguro. Indignados, procuram assessoria técnico-jurídica, pois acreditam que Maria não pode ser beneficiária do seguro de vida de João Paulo. Sobre a situação hipotética narrada, assinale a afirmativa correta.","opcoes":["Nos termos da legislação civil vigente, Maria não pode ser beneficiária do seguro, pois João Paulo ainda era casado com Tereza.","Como Maria era a única beneficiária indicada e, não sendo válida essa indicação em razão de João Paulo ser casado, o capital estipulado deverá ser pago aos herdeiros, seguindo a ordem de vocação hereditária.","A indicação de Maria como beneficiária é válida, pois o ordenamento jurídico brasileiro considera válida a instituição do companheiro como beneficiário, se ao tempo do contrato o segurado já se encontrava separado de fato.","A substituição do beneficiário em seguro de vida, em regra, é válida, mas no caso é inválida por se tratar de indicação de concubina como beneficiária.","A indicação de Maria como beneficiária seria válida se João Paulo e Tereza fossem separados judicialmente, mas, no caso, é inválida, pois se encontravam separados de fato apenas."],"correta":2,"explicacao":"Gabarito: <strong>A indicação de Maria como beneficiária é válida, pois o ordenamento jurídico brasileiro considera válida a instituição do companheiro como beneficiário, se ao tempo do contrato o segurado já se encontrava separado de fato.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2106982,"enunciado":"Com relação à disciplina jurídica do contrato de seguro de dano no Código Civil de 2002, assinale (V) para afirmativa verdadeira e (F) para falsa. ( ) No seguro de dano, o risco do seguro compreenderá todos os prejuízos resultantes, salvo eventuais estragos ocasionados para evitar o sinistro. ( ) Na vigência de um contrato de seguro de dano, pode o segurado, livremente, celebrar novo contrato sobre o mesmo interesse e contra o mesmo risco junto a outro segurador. ( ) No seguro de dano, inclui-se na garantia o sinistro provocado por vício intrínseco da coisa segurada, independentemente de declaração do segurado a esse respeito. ( ) No seguro de dano, salvo disposição em contrário, admite-se a transferência do contrato a terceiro com a alienação ou a cessão do interesse segurado. As afirmativas são, respectivamente,","opcoes":["F, F, F e F.","F, V, F e V.","V, V, F e V.","V, F, V e V.","F, F, F e V."],"correta":4,"explicacao":"Gabarito: <strong>F, F, F e V.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107048,"enunciado":"Comercializar seguros não é simples, exige que quem o faz tenha pleno conhecimento do assunto, compreenda as necessidades de proteção dos clientes e possa indicar a ele quais seguros podem ser mais adequados para cobrir suas exposições a riscos. Trata-se, portanto, de uma comercialização","opcoes":["impulsiva.","indutiva.","consultiva.","colaborativa.","tradicional."],"correta":2,"explicacao":"Gabarito: <strong>consultiva.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107049,"enunciado":"Uma prática comercial ruim, mas que ocorre com frequência, é condicionar a contratação de um produto ou serviço financeiro qualquer à contratação de seguros, o que é definitivamente proibido por lei e não entrega o valor agregado projetado pelos produtos de seguro, fazendo com que, muitas vezes, os consumidores nem se lembrem de utilizá-los quando necessário. Essa prática, a ser evitada nas estratégias comerciais, é chamada de venda","opcoes":["lateral.","acessória.","incondicionada.","aleatória.","casada."],"correta":4,"explicacao":"Gabarito: <strong>casada.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107050,"enunciado":"Novatos no mercado de seguros talvez ainda não compreendam que, ao vender seguros, o pior argumento é o valor do prêmio, porque se trata de uma venda em que o conceito fundamental é a oferta de","opcoes":["ascensão social, por meio de serviços financeiros que promovam mudança de perfil de consumo.","bem-estar social, obtido por obtenção de financiamento a longo prazo.","tranquilidade, por meio da proteção de patrimônio, responsabilidades e vidas.","segurança, por meio da aquisição de produtos e serviços.","aumento de patrimônio, por meio de garantia de indenização."],"correta":2,"explicacao":"Gabarito: <strong>tranquilidade, por meio da proteção de patrimônio, responsabilidades e vidas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107051,"enunciado":"Ao indenizar um sinistro em que o seu segurado foi vítima de um terceiro, a seguradora pode agir judicialmente para pleitear ressarcimento dos prejuízos incorridos pela indenização paga a seu segurado. A isto denominamos o exercício","opcoes":["da sub-rogação de direitos.","do direito de concorrência de apólices.","do direito do consumidor.","de mediação contratual.","do direito da alienação dos bens."],"correta":0,"explicacao":"Gabarito: <strong>da sub-rogação de direitos.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107052,"enunciado":"Há situações em que o causador de um sinistro não é o segurado. Em outros casos, a vítima do sinistro pode também não ser o segurado. Essa pessoa culpada ou prejudicada em um acidente coberto pelo seguro, exceto o próprio segurado ou seus ascendentes, descendentes, cônjuge, irmãos e pessoas que com ele residam ou que dele dependam economicamente, em seguros, é chamada de","opcoes":["interveniente.","terceiro.","proponente.","agente.","segundo."],"correta":1,"explicacao":"Gabarito: <strong>terceiro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107053,"enunciado":"A venda de seguros complexos geralmente exige especialização, experiência técnica e comercial, porque requer a compreensão dos riscos expostos e dos valores envolvidos, além de nuances específicas dos ramos de seguro. Por isso, em seguros complexos, é sempre recomendável que a comercialização seja","opcoes":["parcial, realizada com auxílio do ressegurador.","direcionada, executada pelos profissionais mais antigos e experientes.","generalista, realizada por técnicos comerciais da corretora de seguros.","especializada, atenta aos detalhes técnicos, comerciais e operacionais.","direta, realizada pelos técnicos da seguradora."],"correta":3,"explicacao":"Gabarito: <strong>especializada, atenta aos detalhes técnicos, comerciais e operacionais.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107054,"enunciado":"A relação entre a seguradora e o consumidor de seguros também se enquadra no Código de Defesa do Consumidor, pois se trata de uma relação de consumo; a contratação dela decorrente exige que o consumidor compreenda em detalhes o que está contratando, as eventuais limitações, seus direitos e deveres, o que deve estar expresso na apólice/contrato de seguro. Esse aspecto é muito importante para definir","opcoes":["os limites de consumo que definem os direitos.","o que fazer em caso de sinistros que envolvam resseguro.","as franquias e as participações em caso de sinistro.","as relações de consumo protegidas entre as partes: segurados e seguradoras.","as formas possíveis de pagamento dos prêmios de seguro."],"correta":3,"explicacao":"Gabarito: <strong>as relações de consumo protegidas entre as partes: segurados e seguradoras.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107055,"enunciado":"Entre as principais obrigações das seguradoras para preservar o propósito do seguro estão o gerenciamento competente e tempestivo dos riscos que lhes são transferidos e confiados pelos segurados, mediante pagamento do prêmio e, em caso de sinistros, a promoção da regulação e liquidação deles, indenizando o que for devido, desde que","opcoes":["estejam cobertos pelas condições do contrato de seguros.","os prejuízos sejam de alguma forma passíveis de ressarcimento à seguradora.","o segurado seja brasileiro e maior de idade.","o proponente do seguro e o segurado sejam a mesma pessoa.","tenham ocorrido após 15 dias de vigência da apólice."],"correta":0,"explicacao":"Gabarito: <strong>estejam cobertos pelas condições do contrato de seguros.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107056,"enunciado":"A responsabilidade do segurador se limita aos riscos assumidos, expressos na apólice, que é o contrato de seguros. Tal limitação é necessária para","opcoes":["resguardar a estabilidade de resultados e a solvência do negócio de seguro.","impedir que as franquias penalizem excessivamente os segurados.","não permitir alteração do contrato.","evitar multas impetradas pela SUSEP.","evitar reclamações dos segurados."],"correta":0,"explicacao":"Gabarito: <strong>resguardar a estabilidade de resultados e a solvência do negócio de seguro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107057,"enunciado":"Nos seguros de danos, o propósito pode ser proteger um bem de uma variedade de eventos de riscos possíveis e indesejáveis e, na eventual ocorrência de um sinistro, remeter recursos ao segurado para cobrir o prejuízo material ocorrido (recursos para sua reposição). Esta lógica intrínseca significa que","opcoes":["é impossível não se indenizar o valor de novo do bem sinistrado.","o prêmio de seguro não pode ser excessivo a ponto de comprometer a indenização futura do bem.","os recursos citados são pagos em até 12 meses da ocorrência do dano.","o valor da indenização não deve ultrapassar o preço real (de mercado) do item segurado no momento do sinistro.","o valor do bem sinistrado deve ser o valor de mercado no estado de novo."],"correta":3,"explicacao":"Gabarito: <strong>o valor da indenização não deve ultrapassar o preço real (de mercado) do item segurado no momento do sinistro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107058,"enunciado":"O bom funcionamento das seguradoras requer que existam canais de atendimento estruturados e operacionais, capazes de atender às demandas por informação dos segurados. A Ouvidoria, um desses canais, tem a função principal de","opcoes":["reduzir a insuficiência de informações sobre os termos de seguro.","evitar reclamações.","orientar os segurados sobre as suas indenizações.","atuar na solução de eventuais conflitos na relação entre os consumidores e empresas.","disponibilizar um chat para facilitar o contato."],"correta":3,"explicacao":"Gabarito: <strong>atuar na solução de eventuais conflitos na relação entre os consumidores e empresas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107059,"enunciado":"As seguradoras usam variados mecanismos para pulverizar suas exposições aos riscos e se manterem solventes. Elas sabem que cada segurado paga prêmios de seguros, contribuindo com um valor muito menor do que aquele que poderá vir a receber como indenização ao longo do período de vigência do contrato se ocorrer um sinistro, o que cria uma espécie de fundo, administrado pelas seguradoras, justamente para garantir que todos os que necessitem sejam indenizados, respeitados os contratos firmados. A esse processo dá-se o nome de","opcoes":["prêmio individual.","risco coletivo.","seguro coletivo de pessoas.","mutualismo.","período indenitário."],"correta":3,"explicacao":"Gabarito: <strong>mutualismo.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107060,"enunciado":"No Brasil, segundo o estabelecido pelo CNSP, pela SUSEP e pelo Banco Central, as seguradoras são constituídas sob a forma de","opcoes":["Sociedades Fechadas.","Sociedades Anônimas.","Empresas Individuais.","Cooperativas de Crédito.","Empresas Limitadas."],"correta":1,"explicacao":"Gabarito: <strong>Sociedades Anônimas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107061,"enunciado":"O Conselho Nacional de Seguros Privados (CNSP) é órgão responsável por fixar","opcoes":["a quantidade máxima de seguradoras no país.","a estrutura de governança e os organogramas das seguradoras.","as diretrizes e normas da política de seguros privados.","a regulação ética dos níveis executivos superiores das seguradoras.","os prêmios mínimos e máximos dos seguros."],"correta":2,"explicacao":"Gabarito: <strong>as diretrizes e normas da política de seguros privados.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107062,"enunciado":"A base moral na qual se assenta o mercado de seguros é o princípio","opcoes":["da lógica matemática.","do risco.","da segmentação de coberturas.","da onerosidade.","da boa-fé mútua."],"correta":4,"explicacao":"Gabarito: <strong>da boa-fé mútua.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107063,"enunciado":"O documento que formaliza o interesse do proponente em contratar, alterar ou renovar o seguro é","opcoes":["o endosso de seguro.","a apólice de seguro.","a proposta de seguro.","a averbação de seguro.","o prêmio do seguro."],"correta":2,"explicacao":"Gabarito: <strong>a proposta de seguro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107064,"enunciado":"A Superintendência de Seguros Privados (Susep) é o órgão responsável pela regulação e supervisão dos mercados de seguro, previdência privada aberta, capitalização e resseguro, realizando","opcoes":["controle e fiscalização dos entes supervisionados.","precificação justa de seguros.","padronização e unificação das tarifas de seguros.","recomendações de critérios técnicos de subscrição de riscos.","resseguro direto e indireto."],"correta":0,"explicacao":"Gabarito: <strong>controle e fiscalização dos entes supervisionados.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107065,"enunciado":"As datas e os horários de início e término da vigência do seguro devem estar indicados e registrados no contrato de seguros. Na falta de indicação expressa de horário nos documentos, o horário de início e término de vigência do seguro será sempre ______ das datas para tal fim neles indicadas. A lacuna fica corretamente preenchida por","opcoes":["zero hora.","oito horas.","doze horas.","dezoito horas.","vinte e quatro horas."],"correta":4,"explicacao":"Gabarito: <strong>vinte e quatro horas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107066,"enunciado":"A aposentadoria é uma preocupação de todos os brasileiros. A previdência complementar possibilita ao trabalhador, facultativamente, acumular reservas para que, no futuro, possa desfrutar de uma complementação em sua aposentadoria. Ela pode complementar o RPPS – Regime Próprio de Previdência Social dos servidores públicos ou o RGPS, que atinge as demais camadas sociais e significa","opcoes":["Regime Geral de Previdência Social.","Regime Geral de Previdência Societária.","Regime Geral de Previdência do Servidor.","Regime Gerador de Previdência Social.","Regime Gerador de Previdência Societária."],"correta":0,"explicacao":"Gabarito: <strong>Regime Geral de Previdência Social.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107067,"enunciado":"Consumidores em geral não compreendem bem como funcionam os títulos de capitalização. Por exemplo, poucos sabem que há três prazos importantes a considerar na contratação. São eles os prazos de","opcoes":["emissão, aplicação e recorrência.","aplicação, vigência e resgate.","pagamento, recorrência e devolução.","aplicação, resgate e carência.","pagamento, vigência e carência."],"correta":4,"explicacao":"Gabarito: <strong>pagamento, vigência e carência.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107069,"enunciado":"Além das condições indispensáveis para que o risco seja segurável, há outras condições, para os riscos seguráveis, encontradas na maioria dos ramos de seguro. Essas condições são: ser possível, ser futuro, independer da vontade das partes, resultar um prejuízo de sua ocorrência e, ainda, ser","opcoes":["intencional.","gravoso.","certo.","especulativo.","mensurável."],"correta":4,"explicacao":"Gabarito: <strong>mensurável.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107070,"enunciado":"Um grupo de pessoas que, com interesses seguráveis comuns, concorre para a formação de uma massa econômica com a finalidade de suprir, em determinado momento, necessidades eventuais de algumas daquelas pessoas do grupo ou de parte do grupo é chamado de grupo","opcoes":["beneficiário.","segurável.","condominial.","associado.","mutual."],"correta":1,"explicacao":"Gabarito: <strong>segurável.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107071,"enunciado":"Quando a indenização do seguro ocorre com o mínimo de burocracia, dentro dos prazos previstos, com comunicação tempestiva e assertiva de todos os passos do processo de sinistro, dizemos que os serviços prestados pelas seguradoras de fato contribuem para","opcoes":["evitar conflitos e discussões sobre as franquias.","garantir o valor percebido pelo cliente e pela sociedade.","garantir que os clientes recebam a indenização que eles pleiteiam.","prevenir reclamações e eventual judicialização dos contratos.","estimular a cooperação mútua."],"correta":1,"explicacao":"Gabarito: <strong>garantir o valor percebido pelo cliente e pela sociedade.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107072,"enunciado":"É fundamental que o segurado faça declarações verdadeiras e completas, e não omita nada sobre as circunstâncias que envolvem o risco, objeto do seguro, principalmente sob pena de","opcoes":["só receber a indenização ao final da vigência do contrato.","não ter mais o seu seguro aceito no futuro.","perder o direito à indenização.","ser multado pelos resseguradores.","não ter direito a receber o prêmio de seguro."],"correta":2,"explicacao":"Gabarito: <strong>perder o direito à indenização.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107073,"enunciado":"Uma preocupação das empresas é com a perda de clientes. Por isso, além de prospectar novos clientes para repor as eventuais perdas e fazer de tudo para manter os clientes ativos, as empresas também fazem esforços para reativar clientes perdidos ao longo do tempo, o que significa não os deixar sem contato frequente. Entretanto, para que isso ocorra a contento, as empresas devem","opcoes":["fazer ações de marketing na mídia.","enviar felicitações em datas comemorativas.","manter atualizados os cadastros de clientes.","contratar empresas de ativação de clientes.","fazer promoções."],"correta":2,"explicacao":"Gabarito: <strong>manter atualizados os cadastros de clientes.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107074,"enunciado":"Um conhecido provérbio diz que tudo o que se faz bem é objeto de trabalho prévio e de agir de forma metodológica, com foco nos resultados. Um bom exemplo em vendas é entender como a interação com os clientes mudou ao longo do tempo, passando do contato presencial a outras opções, inclusive digitais, usadas atualmente. Em relação ao tema, avalie se, tanto no passado quanto hoje em dia, as boas práticas incluem: I. concentrar a atenção em clientes indecisos. II. dar mais atenção aos clientes com maior potencial de compra. III. ter um projeto bem estruturado de atendimento aos clientes. Está correto o que se afirma em","opcoes":["I, apenas.","II, apenas.","III, apenas.","I e II, apenas.","II e III, apenas."],"correta":2,"explicacao":"Gabarito: <strong>III, apenas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107075,"enunciado":"Nas empresas de referência do mercado, as ações comerciais são planejadas, coordenadas e controladas. Por exemplo, os bancos de dados de clientes têm registros dos contatos realizados, dos assuntos tratados, do histórico de transações etc. Estes dados são convertidos em informações que permitem um planejamento comercial voltado a cada cliente, o que facilita, sobretudo, a estruturação das estratégias de","opcoes":["oferta de benefícios.","contatos do call-center.","seleção de pessoas na área comercial.","produção de brindes.","marketing de relacionamento."],"correta":4,"explicacao":"Gabarito: <strong>marketing de relacionamento.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107076,"enunciado":"As empresas modernas tratam com muito cuidado de suas normas éticas e das normas de conduta de seus funcionários nos ambientes interno e externo, com especial atenção ao relacionamento com os pares e a sociedade e ao trato comercial, o que invariavelmente é registrado em códigos específicos, como os Códigos de Ética e de Conduta. Essas regras compõem o que chamamos de","opcoes":["atributos morais.","liberdade de expressão.","visão empresarial.","designação comercial.","etiqueta empresarial."],"correta":4,"explicacao":"Gabarito: <strong>etiqueta empresarial.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107080,"enunciado":"A gestão de carteiras de clientes exige análise, coerência e competência profissional, para que se perceba o que fazer com cada grupo de clientes, já que as demandas, as estratégias e as oportunidades de negócios podem ser bem diferentes. Uma ação que os gestores comerciais de sucesso fazem para ampliar os resultados das suas carteiras é","opcoes":["enviar aos clientes, várias vezes por ano, ofertas de descontos.","entender quem pode ser um cliente fiel ou infiel para dosar os esforços comerciais com cada um.","mostrar que os produtos têm valor agregado e preços competitivos.","segmentar a base de clientes, entendendo características comuns ou aproximadas (econômicas, sociais etc.)","estabelecer metas desafiadoras."],"correta":3,"explicacao":"Gabarito: <strong>segmentar a base de clientes, entendendo características comuns ou aproximadas (econômicas, sociais etc.)</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107081,"enunciado":"As técnicas de vendas de produtos financeiros podem ser definidas como um conjunto de metodologias e práticas aplicadas em todas as etapas do processo de vendas. Elas têm como objetivos potencializar as chances de vendas e aumentar o número de fechamentos; nesse processo, há também etapas posteriores, como as que visam a","opcoes":["reter e fidelizar os clientes.","converter clientes.","prospectar vendas.","nutrir vendas.","captar novos clientes."],"correta":0,"explicacao":"Gabarito: <strong>reter e fidelizar os clientes.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107173,"enunciado":"Considere a hipotética situação em que o Conselho Monetário Nacional, observando as diretrizes estabelecidas pelo Presidente da República: I. Expediu normas gerais de contabilidade e estatística a serem observadas pelas instituições financeiras. II. Disciplinou as atividades das Bolsas de Valores e dos corretores de fundos públicos. III. Determinou a percentagem máxima dos recursos que as instituições financeiras poderão emprestar a um mesmo cliente ou grupo de empresas. IV. Determinou que as matrizes das instituições financeiras registrem os cadastros das firmas que operam com suas agências há mais de um ano. V. Realizou operações de redesconto e empréstimo com instituições financeiras públicas e privadas, consoante remuneração, limites, prazos, garantias, formas de negociação e outras condições estabelecidas em regulamentação por ele editada. Considera-se que, à luz do disposto na Lei nº 4.595/1964, o Conselho Monetário Nacional agiu nos limites de sua competência nas seguintes hipóteses:","opcoes":["Apenas I, II e III.","Apenas I, II e IV.","Apenas II, III e V.","Apenas II, IV e V.","Apenas III, IV e V."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I, II e III.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2107176,"enunciado":"Considerando o disposto na Lei nº 6.385/76, que dispõe sobre o mercado de valores mobiliários e cria a Comissão de Valores Mobiliários, assinale a alternativa correta.","opcoes":["A Comissão de Valores Mobiliários será administrada por um Presidente e quatro Diretores, nomeados pelo Presidente da República, depois de aprovados pelo Senado Federal, dentre pessoas de ilibada reputação e reconhecida competência em matéria de mercado de capitais.","Os dirigentes da Comissão somente perderão o mandato em virtude de renúncia ou de condenação judicial transitada em julgado.","No caso de renúncia, morte ou perda de mandato do Presidente da Comissão, assumirá o diretor mais idoso ou mais antigo, nessa ordem, até nova nomeação, sem prejuízo de suas atribuições.","O mandato dos dirigentes da Comissão é de quatro anos, permitida uma recondução, devendo ser renovado a cada ano um terço dos membros do Colegiado.","A Comissão funcionará como órgão de deliberação colegiada, conforme regulamento fixado pelo Ministério da Economia."],"correta":0,"explicacao":"Gabarito: <strong>A Comissão de Valores Mobiliários será administrada por um Presidente e quatro Diretores, nomeados pelo Presidente da República, depois de aprovados pelo Senado Federal, dentre pessoas de ilibada reputação e reconhecida competência em matéria de mercado de capitais.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2118489,"enunciado":"De acordo com a Resolução CMN nº 4.963 de 25.11.2021, no segmento de renda fixa, as aplicações dos recursos dos regimes próprios de previdência social subordinam- -se a determinados limites. No entanto, as aplicações podem ser de 100% em","opcoes":["títulos de emissão do Tesouro Nacional, registrados no Sistema Especial de Liquidação e Custódia (Selic).","cotas de fundos de investimento classificados como renda fixa com sufixo “crédito privado”.","cotas de fundo de investimento de que trata o art. 3º da Lei nº 12.431, de 24 de junho de 2011.","diretamente em ativos financeiros de renda fixa de emissão com obrigação ou coobrigação de instituições financeiras bancárias.","cotas de classe sênior de fundos de investimento em direitos creditórios (FIDC)."],"correta":2,"explicacao":"Gabarito: <strong>cotas de fundo de investimento de que trata o art. 3º da Lei nº 12.431, de 24 de junho de 2011.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2171895,"enunciado":"A respeito do processo administrativo sancionador no mercado financeiro, assinale a opção correta de acordo com a Lei n.º 13.506/2017.","opcoes":["A apresentação de proposta de termo de compromisso por instituição financeira investigada pelo BACEN suspende o andamento do respectivo processo administrativo.","O termo de compromisso importará confissão quanto à matéria de fato e reconhecimento da ilicitude da conduta analisada, constituindo título executivo extrajudicial.","Para que o acordo administrativo em processo de supervisão seja celebrado, é necessário, entre outros requisitos, que o BACEN não disponha de provas suficientes para assegurar a condenação administrativa das pessoas tisicas ou jurídicas por ocasião da propositura do acordo.","Na hipótese de descumprimento do acordo administrativo em processo de supervisão, o BACEN deverá adotar as medidas judiciais necessárias para a execução das obrigações assumidas, sendo vedado o prosseguimento do processo administrativo.","O acordo administrativo em processo de supervisão celebrado pelo BACEN vincula a atuação do Ministério Público e dos demais órgãos públicos."],"correta":2,"explicacao":"Gabarito: <strong>Para que o acordo administrativo em processo de supervisão seja celebrado, é necessário, entre outros requisitos, que o BACEN não disponha de provas suficientes para assegurar a condenação administrativa das pessoas tisicas ou jurídicas por ocasião da propositura do acordo.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2179386,"enunciado":"No que se refere a comércio exterior, câmbio, tarifas, subsídios e cotas, assinale a opção correta.","opcoes":["A tarifa ad valorem é expressa em quantia de dinheiro por unidade física do produto importado, o que a difere da tarifa específica, que é expressa como uma porcentagem fixa do valor do produto importado.","Uma vantagem do sistema de câmbio flexível é o isolamento da política monetária dos condicionantes externos; com isso, o equilíbrio do balanço de pagamento dependerá exclusivamente das variações da taxa de câmbio.","Em país pequeno, a instituição de uma tarifa de importação gera benefícios líquidos para os consumidores e aumenta o ganho dos produtores domésticos e, por corolário, há incremento nas receitas do governo.","O subsídio é o pagamento aos exportadores, geralmente de certa proporção do valor dos bens exportados, podendo ser específico ou ad valorem, aumentando os preços no país exportador e sendo mais vantajoso economicamente ao país produtor, em relação à tarifa, pois melhora os termos de troca.","O sistema de cotas imposto sobre o volume ou o valor das importações é mais vantajoso para governo em relação ao sistema de tarifa, pois a renda passa a ser apropriada na forma de uma receita pública que pode financiar o déficit no balanço de pagamentos."],"correta":1,"explicacao":"Gabarito: <strong>Uma vantagem do sistema de câmbio flexível é o isolamento da política monetária dos condicionantes externos; com isso, o equilíbrio do balanço de pagamento dependerá exclusivamente das variações da taxa de câmbio.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2191057,"enunciado":"Em relação ao Banco Nacional de Desenvolvimento Econômico e Social (BNDES), analise as afirmações a seguir. I. O BNDES é empresa pública dotada de personalidade jurídica de direito público e patrimônio próprio. II. Ao contratar operações no exterior, o BNDES não poderá utilizar de garantia da União, lançando mão apenas de colaterais próprios. III. O BNDES executa a política de investimento do Governo Federal e tem por objetivo apoiar programas, projetos, obras e serviços que se relacionem com o desenvolvimento econômico e social do País. Está correto o que se afirma em","opcoes":["I, II e III.","I e III, apenas.","II e III, apenas.","I, apenas.","III, apenas."],"correta":4,"explicacao":"Gabarito: <strong>III, apenas.</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2232566,"enunciado":"Transferências financeiras sem intermediação bancária, a qualquer hora e lugar, de forma completamente virtual, é uma proposta atrativa, Porém, mesmo tendo passado quase duas décadas da criação do blockchain e do bitcoin, ainda há dúvidas a respeito da confiabilidade, transparência segurança das transações com moedas virtuais. As afirmativas a seguir identificam corretamente riscos associados às transações financeiras com moedas virtuais, em função de não serem emitidas nem garantidas por qualquer autoridade monetária, à exceção de uma. Assinale-a","opcoes":["Todo o risco fica com os detentores.","Não são lastreadas em ativo real de qualquer espécie.","Não tem garantia de conversão para moedas soberanas.","Não podem ser utilizadas para operações de câmbio não autorizadas.","Seu valor decorre exclusivamente da confiança conferida pelos indivíduos ao seu emissor."],"correta":3,"explicacao":"Gabarito: <strong>Não podem ser utilizadas para operações de câmbio não autorizadas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2232661,"enunciado":"As chamadas CBDCs são um tipo de criptomoeda cada vez mais discutida por governos de todo o mundo. Sua sigla significa moeda digital do Banco Central e sua implantação no Brasil está sendo pensada no âmbito do projeto Real Digital, em debate no Legislativo. Assinale a afirmativa que caracteriza corretamente as chamadas CBDCS.","opcoes":["As CBDCs usam blockchain e criptografia para registrar e validar transações, diferentemente dos criptoativos que utilizam outro tipo de tecnologia.","As CBDCs são a expressão digital da moeda soberana de cada país e atuam dentro dos perímetros regulatórios estabelecidos pelos bancos centrais, como os stablecoins.","As CBDCs são um tipo de moedas digitais criadas por uma equipe de desenvolvedores e administradas de maneira descentralizada pela própria comunidade de usuários","As CBDCs estão ancoradas a um lastro próprio, desvinculado da moeda emitida e garantida pela autoridade financeira nacional, associado ao dólar, ao euro ou a metais preciosos.","As CBDCs possuem uma autoridade central responsável por ocorrências e problemas, geralmente a autoridade monetária ligada a determinado país, a qual regula o estado das transações na rede."],"correta":1,"explicacao":"Gabarito: <strong>As CBDCs são a expressão digital da moeda soberana de cada país e atuam dentro dos perímetros regulatórios estabelecidos pelos bancos centrais, como os stablecoins.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2232662,"enunciado":"O Conselho de Controle de Atividades Financeiras (COAF) é o órgão do governo federal responsável por monitorar atividades financeiras suspeitas, de forma a produzir informações para prevenir e combater atos ilícitos como lavagem de dinheiro e ocultação de patrimônio, entre outros. Assinale a afirmativa que caracteriza corretamente uma atribuição do COAF.","opcoes":["Elaborar relatórios de inteligência financeira para subsidiar eventuais procedimentos investigativos das autoridades competentes.","Receber acesso direto a extratos bancários relativos a movimentações financeiras suspeitas de atos ilícitos realizados por clientes do banco.","Escolher discricionariamente as pessoas ou instituições sobre as quais se desenvolverão atividades de averiguação sobre operações financeiras.","Acessar bases de dados sigilosas, como a base fiscal da Receita Federal, para prevenir lavagem de dinheiro ou financiamento de terrorismo.","Investigar atos ilícitos mediante interrogatórios e bloqueio de contas, entre outras ferramentas que averiguam indícios de crime financeiro."],"correta":3,"explicacao":"Gabarito: <strong>Acessar bases de dados sigilosas, como a base fiscal da Receita Federal, para prevenir lavagem de dinheiro ou financiamento de terrorismo.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2232663,"enunciado":"Segundo pesquisa de 2021 do Instituto Brasileiro de Governança Corporativa, o tema da diversidade relacionado à raça e gênero é considerado central pelas organizações. Entretanto, apenas 42% das empresas possuem indicadores de diversidade e inclusão; 84,6% das organizações não incluem indicadores de diversidade e inclusão entre as métricas de remuneração variável de seus administradores; e 50% das áreas de RH nunca foi demandada pelos Conselhos para reportar ou desenvolver ações sobre diversidade ou inclusão. A formulação e a implementação de planos que busquem \"dar voz à diversidade\" nas organizações contempla necessariamente a eliminação de barreiras para a inclusão e a diversidade. As afirmativas a seguir descrevem corretamente tipos de barreiras que dificultam a incorporação da diversidade nas organizações à exceção de uma. Assinale-a.","opcoes":["Vieses de percepção, como estereótipos e preconceitos baseados em diferentes aspectos.","Atitudes negativas, como a apatia, a resistência à mudança e a tolerância à intolerância.","Restrições organizacionais, como medidas para conectar diversidade e inclusão com as estratégias de crescimento da empresa.","Conflitos culturais, como a interferência das crenças e valores pessoais no âmbito das relações de trabalho e nos fóruns de tomada de decisão.","Insuficiência de habilidades interculturais, como a incapacidade de valorizar a pluralidade como valor e potencial de fortalecimento da empresa."],"correta":4,"explicacao":"Gabarito: <strong>Insuficiência de habilidades interculturais, como a incapacidade de valorizar a pluralidade como valor e potencial de fortalecimento da empresa.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2232665,"enunciado":"Ao longo das últimas décadas, stakeholders em geral e, especificamente, sócios, acionistas, administradores, puderam observar os diversos benefícios gerados pela adoção de boas práticas na função da governança corporativa, como as listadas corretamente a seguir, à exceção de uma. Assinale-a.","opcoes":["A separação das competências.","A prevenção, detecção e resposta a desvios.","A mitigação de conflitos de interesses.","O aumento da transparência e da prestação de contas.","O fomento da equidade e da responsabilidade socioambiental."],"correta":2,"explicacao":"Gabarito: <strong>A mitigação de conflitos de interesses.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2234179,"enunciado":"A respeito dos terminais de autoatendimento bancário, assinale a afirmativa correta.","opcoes":["para os equipamentos providos de monitores sensíveis ao toque, é facultativa a entrada de dados e o acionamento de funções por meio do teclado numérico.","As informações em texto podem ser substituídas por imagens exibidas no vídeo.","Ao lado do conector do fone de ouvido deve estar localizada a chave para a ativação do som.","A sessão do usuário não pode ser finalizada quando o fone de ouvido for desconectado.","O monitor de vídeo deve ser automaticamente desativado ou congelado quando o fone de ouvido for conectado."],"correta":3,"explicacao":"Gabarito: <strong>A sessão do usuário não pode ser finalizada quando o fone de ouvido for desconectado.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240237,"enunciado":"Acerca do Sistema de Pagamentos Brasileiro, julgue o item que se segue.\n\n\n\n\nNo Sistema Especial de Liquidação e Custódia (SELIC), são realizadas as transações que envolvem os títulos de renda fixa privados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240238,"enunciado":"Acerca do Sistema de Pagamentos Brasileiro, julgue o item que se segue.\n\n\n\n\nA titularidade de conta reservas bancárias é obrigatória para os bancos comerciais, os bancos múltiplos com carteira comercial e as caixas econômicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240239,"enunciado":"Em relação aos órgãos normativos e de supervisão do SFN, julgue o próximo item.\n\n\n\n\nO BCB tem como uma de suas atribuições a fixação de metas para a inflação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240240,"enunciado":"Em relação aos órgãos normativos e de supervisão do SFN, julgue o próximo item.\n\n\n\n\nA apuração de fraudes ou manipulações destinadas a criar condições artificiais de demanda, oferta ou preço no mercado de capitais compete à CVM.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240241,"enunciado":"Em relação aos órgãos normativos e de supervisão do SFN, julgue o próximo item.\n\n\n\n\nO Conselho de Recursos do SFN é constituído, paritariamente, por oito conselheiros, possuidores de conhecimentos especializados em assuntos relativos aos mercados financeiros, de câmbio, de capitais, de consórcios e de crédito rural e industrial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240242,"enunciado":"No que se refere aos bancos comerciais, julgue o item subsecutivo. \n\n\n\n\nOs bancos comerciais podem captar recursos sob a modalidade de depósitos a prazo, com ou sem a emissão de certificados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240243,"enunciado":"Em relação à CAIXA, julgue o item abaixo.\n\n\n\n\nA CAIXA equipara-se aos bancos comerciais, sendo-lhe facultada a captação de depósitos de poupança, mas não a de depósitos à vista.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240244,"enunciado":"Em relação aos bancos de desenvolvimento e de investimento, julgue o item subsequente. \n\n\n\n\nÉ vedado aos bancos de investimento sem carteira de corretoras de títulos e valores mobiliários operarem em bolsas de mercadorias e de futuros, bem como em mercados de balcão organizados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240245,"enunciado":"Em relação aos bancos de desenvolvimento e de investimento, julgue o item subsequente. \n\n\n\n\nSe o empreendimento visar benefícios de interesse comum, os bancos de desenvolvimento poderão prestar assistência a programas e projetos desenvolvidos em estado limítrofe à sua área de atuação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240246,"enunciado":"Sujeitam-se à fiscalização do BCB, além das instituições financeiras, outros intermediários financeiros, tais como as sociedades de arrendamento mercantil, as sociedades corretoras de títulos e valores mobiliários e as sociedades distribuidoras de títulos e valores mobiliários. No que se refere a essas sociedades, julgue o item a seguir.\nCompete à CVM a supervisão dos fundos de investimento administrados pelas sociedades corretoras de títulos e valores mobiliários.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240247,"enunciado":"Sujeitam-se à fiscalização do BCB, além das instituições financeiras, outros intermediários financeiros, tais como as sociedades de arrendamento mercantil, as sociedades corretoras de títulos e valores mobiliários e as sociedades distribuidoras de títulos e valores mobiliários. No que se refere a essas sociedades, julgue o item a seguir.\nAs operações de arrendamento mercantil são atividades exclusivas das sociedades de arrendamento mercantil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2240248,"enunciado":"Acerca das bolsas de valores, julgue o item abaixo. \n\n\n\n\nNo Brasil, as bolsas de valores não podem constituir-se como associações civis; elas são, necessariamente, constituídas sob a forma de sociedades anônimas de capital aberto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2248008,"enunciado":"O Banco Central do Brasil (Bacen) tem por objetivo fundamental assegurar a estabilidade de preços e zelar pela estabilidade e pela eficiência do sistema financeiro, suavizar as flutuações do nível de atividade econômica e fomentar o pleno emprego. Acerca de seu papel em matéria de Direito Financeiro, à luz da Constituição da República de 1988, è correto afirmar que","opcoes":["é permitido ao Bacen conceder, direta ou indiretamente empréstimos a autarquias federais para desenvolvimento de programas de saúde, educação e assistência social;","o Bacen poderá comprar títulos de emissão do Tesouro Nacional, com o objetivo de regular a taxa de juros;","as disponibilidades de caixa da União serão depositadas no Bacen ou em instituições financeiras oficiais federais;","as disponibilidades de caixa dos Estados e do Distrito Federal serão obrigatoriamente depositadas no Bacen;","a competência da União para emitir moeda será exercida conjuntamente pelo Bacen e pela Secretaria do Tesouro Nacional."],"correta":4,"explicacao":"Gabarito: <strong>a competência da União para emitir moeda será exercida conjuntamente pelo Bacen e pela Secretaria do Tesouro Nacional.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2276407,"enunciado":"Em relação às fontes de financiamento de longo prazo, julgue o item a seguir. \n\nO leasing financeiro é uma operação que envolve a aquisição de um bem por uma empresa arrendadora, para cessão ao arrendatário, o qual usará esse bem por prazo determinado, pagando, em contrapartida, contraprestações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2276408,"enunciado":"Em relação às fontes de financiamento de longo prazo, julgue o item a seguir. \n\nNa subscrição do tipo stand-by, ocorre a subscrição e a integralização, por parte da instituição financeira, do total das novas ações emitidas por uma empresa, que assume amplamente o risco de sua colocação no mercado, ao público em geral e aos investidores institucionais, responsabilizando-se pelo pagamento à empresa emitente do valor total das ações lançadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2324928,"enunciado":"A Comissão de Valores Mobiliários (CVM) é uma entidade autárquica em regime especial, vinculada ao Ministério da Fazenda, com personalidade jurídica e patrimônio próprios, dotada de autoridade administrativa independente, ausência de subordinação hierárquica, mandato fixo e estabilidade de seus dirigentes, e autonomia financeira e orçamentária. Uma de suas competências é","opcoes":["administrar as reservas internacionais brasileiras.","executar a política monetária mediante utilização de títulos do Tesouro Nacional.","fiscalizar e inspecionar as companhias abertas e os fundos de investimento.","manter ativos de ouro e de moedas estrangeiras para atuação nos mercados de câmbio.","zelar pela liquidez e solvência das instituições financeiras nacionais."],"correta":2,"explicacao":"Gabarito: <strong>fiscalizar e inspecionar as companhias abertas e os fundos de investimento.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2386215,"enunciado":"As características a seguir estão relacionadas aos conceitos de moedas digitais fiduciárias e criptomoedas. I. Têm emissão e controle definidos por um órgão central ou governo, enquanto a contraparte é descentralizada. II. Preço oscila de acordo com oferta e procura, enquanto a contraparte tem regulação por um Banco Central. III. A única informação necessária para fazer uma transação é o endereço da carteira digital, enquanto a contraparte pode necessitar de comprovação de dados pessoais. Assinale a alternativa que apresenta apenas as características atribuídas às criptomoedas, referenciando as moedas digitais fiduciárias como contraparte.","opcoes":["I e II, apenas.","II, apenas.","I, II e III.","II e III, apenas.","III, apenas."],"correta":3,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2393675,"enunciado":"No regime de câmbio flutuante, o efeito da política monetária expansionista","opcoes":["aumentará a taxa de juros e não terá efeito sobre a renda real da economia.","somente aumentará a renda se BP for mais inclinada que LM.","aumentará a renda qualquer que seja a inclinação de BP ou LM.","não aumentará a renda mas diminuirá a taxa de juros","será pior no sentido de aumentar a renda comparada ao regime de câmbio fixo."],"correta":2,"explicacao":"Gabarito: <strong>aumentará a renda qualquer que seja a inclinação de BP ou LM.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2393678,"enunciado":"Entre as alternativas a seguir, uma delas foi parte integrante na implementação do Plano Real, qual seja:","opcoes":["adoção da URV.","adoção da URP.","adoção do chamado “gatilho salarial”.","criação da BTN.","congelamento de preços e salários."],"correta":0,"explicacao":"Gabarito: <strong>adoção da URV.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2397726,"enunciado":"O funcionamento dos bancos é regido por normas específicas que garantem a segurança das operações financeiras. Nesse contexto é CORRETO afirmar não ser operação típica de um banco comercial:","opcoes":["Empréstimos pessoais.","Registro de imóveis.","Abertura de contas.","Operações de câmbio."],"correta":1,"explicacao":"Gabarito: <strong>Registro de imóveis.</strong>.","banca":"UNIVIDA","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2444345,"enunciado":"Considerando as relações do Brasil com o resto do mundo e as principais variáveis que compõem os fluxos cambiais, assinale a opção correta.","opcoes":["É possível que haja superávit no balanço de pagamentos e perda de reservas internacionais.","Se há superávit no balanço de pagamentos, então as exportações líquidas são necessariamente positivas.","Se crescem as remessas de juros ao exterior, então há elevação do déficit na conta capital e financeira do balanço de pagamentos, ceteris paribus.","O aumento das reservas internacionais implica déficit no balanço de pagamentos.","Se há superávit no balanço de pagamentos, então há acúmulo de reservas internacionais."],"correta":4,"explicacao":"Gabarito: <strong>Se há superávit no balanço de pagamentos, então há acúmulo de reservas internacionais.</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2444349,"enunciado":"Julgue os seguintes itens, acerca do Acordo de Basileia. I O referido acordo busca tornar mais variada a gestão de balanço dos bancos, especificamente dos ativos, a partir da dispensa de um de requerimento mínimo de capital de risco. II O aludido acordo estabelece requisitos mínimos de capital que os bancos devem manter para garantir a estabilidade financeira e a capacidade de absorver perdas, evitando crises financeiras. III No mencionado acordo, a ponderação de risco dos ativos é determinada pela média das operações e por classificações fornecidas pelo mercado. IV Os acordos de capital de Basileia aplicam-se aos bancos de desenvolvimento, sendo, portanto, um marco relevante para a formulação de uma política de gestão de risco. Assinale a opção correta.","opcoes":["Nenhum item está certo.","Apenas o item I está certo.","Apenas o item II está certo.","Apenas o item III está certo.","Apenas o item IV está certo."],"correta":2,"explicacao":"Gabarito: <strong>Apenas o item II está certo.</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2444350,"enunciado":"O percentual dos depósitos captados pelas instituições financeiras que, conforme definição do Banco Central do Brasil (BACEN), deve ficar retido nas contas de reservas bancárias denomina-se","opcoes":["senhoriagem.","operação em mercado aberto.","compulsório.","regulamentação e controle de crédito.","redesconto."],"correta":2,"explicacao":"Gabarito: <strong>compulsório.</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2444351,"enunciado":"Assinale a opção correta a respeito das funções do BACEN.","opcoes":["É responsabilidade do BACEN manter a inflação dentro da meta, aumentando ou reduzindo o custo do dinheiro no mercado monetário por meio do controle da taxa de redesconto.","O BACEN executa a política de preços mínimos na agricultura, além de funcionar como típico banco comercial.","O BACEN atua como um banco para os bancos comerciais, influenciando o fluxo de dinheiro e de crédito na economia, exceto para concessão de empréstimos.","Além de implementar a política monetária do Brasil, o BACEN é responsável por imprimir e emitir a moeda circulante no país.","O BACEN é responsável pela política cambial e mantém a conta de reservas internacionais, que é o resultado do balanço de pagamentos internacionais."],"correta":4,"explicacao":"Gabarito: <strong>O BACEN é responsável pela política cambial e mantém a conta de reservas internacionais, que é o resultado do balanço de pagamentos internacionais.</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2444354,"enunciado":"No que se refere às garantias de empréstimos, assunto tratado no texto 2A4-I, é possível classificá-las em garantias reais e garantias fidejussórias. É exemplo de garantia fidejussória","opcoes":["o aval.","a caução de direitos creditórios.","o penhor.","a hipoteca.","a caução de títulos."],"correta":0,"explicacao":"Gabarito: <strong>o aval.</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2444356,"enunciado":"Com base na Resolução n.º 2.682/1999 do Banco Central do Brasil, que regulamenta a classificação das operações de crédito de acordo com o risco, bem como a constituição de provisões para operações de crédito duvidosas, julgue os próximos itens. I Em se tratando das operações com maior risco (nível H), 100% de seus valores devem ser provisionados para fazer face a perdas prováveis na sua realização. II Todas as operações, inclusive as de menor risco (nível AA), devem ter um percentual de seus valores provisionado para fazer face a perdas prováveis na sua realização. III Uma operação objeto de renegociação pode reduzir o percentual provisionado de seu valor, a depender do novo prazo total negociado para a operação. Assinale a opção correta.","opcoes":["Apenas o item I está certo.","Apenas o item II está certo.","Apenas os itens I e III estão certos.","Apenas os itens II e III estão certos.","Todos os itens estão certos."],"correta":0,"explicacao":"Gabarito: <strong>Apenas o item I está certo.</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2444366,"enunciado":"Considerando-se o conceito multidimensional de risco (de crédito, de mercado, de liquidez e operacional), é correto afirmar que o risco de mercado","opcoes":["depende do volume transacionado.","está relacionado à possível degradação da garantia de crédito.","depende do comportamento do preço do ativo diante das condições de mercado.","está relacionado a possíveis perdas como resultado de sistemas e(ou) controles inadequados, falhas de gerenciamento e erros humanos.","está relacionado a possíveis perdas quando um contrato não pode ser legalmente amparado."],"correta":2,"explicacao":"Gabarito: <strong>depende do comportamento do preço do ativo diante das condições de mercado.</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2469019,"enunciado":"A rápida incorporação de tecnologias pelo Setor Público também pode ser observada nas estruturas fazendárias, em especial para agilizar e simplificar a arrecadação de tributos. Sobre o tema, analise as assertivas a seguir: I. A operação realizada via PIX não apresenta, a princípio, nenhuma incompatibilidade com os controles utilizados na maioria das Administrações Municipais, mantendo a identificação do pagador e do recebedor. II. Para viabilizar o recebimento de tributos via PIX, há instituições financeiras que já desenvolveram sistemas de integração, vinculados ao PIX e voltados especificamente ao setor público, como é o caso do Banco do Brasil, que criou a “Arrecadação Integrada do Banco do Brasil”. III. A utilização do PIX para recebimento de tributos pode ser considerada boa prática às Administrações Municipais, já que reflete uma gestão mais eficiente dos recursos pela Administração Pública e uma melhor prestação de serviços ao cidadão, eventualmente com a redução dos custos de operação em relação a outros mecanismos de transferência, ainda que com perda da segurança e expressa ressalva na Lei de Responsabilidade Fiscal. IV. O PIX, novo sistema criado pela Caixa Econômica Federal, começou a funcionar em 16 de novembro de 2020, permitindo pagamentos e transferências por pessoas ou empresas 24 horas por dia, sete dias por semana, de maneira instantânea, em qualquer instituição financeira participante. Quais estão corretas?","opcoes":["Apenas I.","Apenas III.","Apenas IV.","Apenas I e II.","I, II, III e IV."],"correta":3,"explicacao":"Gabarito: <strong>Apenas I e II.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2476085,"enunciado":"Em relação às taxas de câmbio, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Uma taxa de câmbio fixa é determinada pelo mercado de câmbio, refletindo a oferta e a demanda por moeda estrangeira em um determinado país. ( ) Um regime de câmbio de flutuação suja é caracterizado por intervenções ocasionais do governo no mercado de câmbio para influenciar a taxa de câmbio em relação a outras moedas estrangeiras. ( ) A taxa de câmbio nominal é o preço relativo de duas moedas estrangeiras, expresso em termos de uma terceira moeda, geralmente o dólar americano. As afirmativas são, na ordem apresentada, respectivamente,","opcoes":["V – F – V.","F – F – V.","F – V – F.","F – V – V."],"correta":2,"explicacao":"Gabarito: <strong>F – V – F.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2510989,"enunciado":"Em 2024, por exemplo, a meta central é de um ‘déficit zero’, mas o governo pode registrar um déficit primário (sem contar os juros da dívida pública) de até 0,25% do PIB no próximo ano sem que a meta seja descumprida. (Portal G1, 30 de outubro de 2023.) Imagine que num país que enfrenta um período prolongado de déficit público, o Banco Central passa a adotar uma política monetária restritiva para evitar o descontrole inflacionário. A esse respeito, as afirmativas a seguir. I. A política monetária restritiva, aumentando as taxas de juros, pode efetivamente conter a inflação no curto prazo, mas corre o risco de aprofundar o déficit público ao aumentar o custo do serviço da dívida. II. Caso o banco central opte por uma política monetária expansiva para estimular o crescimento, pode-se esperar uma redução na taxa de inflação devido ao efeito positivo sobre o produto potencial da economia. III. Uma política monetária restritiva, ao desencorajar o investimento e o consumo através do aumento das taxas de juros, pode reduzir a demanda agregada a um ponto em que a inflação se estabilize, mesmo que temporariamente, ao custo de um crescimento econômico mais lento. É correto o que é afirmado em","opcoes":["I e II, apenas.","I e III, apenas.","II e III, apenas.","I apenas.","I, II e III."],"correta":1,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2511359,"enunciado":"Relacione os mecanismos listados a seguir com suas respectivas políticas econômicas, a saber, Política Monetária (PM) e Política Fiscal (PF). ( ) Envolve a administração tributária e contribui para melhorar a distribuição da renda. ( ) Por meio do aumento do gasto público é possível aumentar a renda e o PIB. ( ) Envolve a definição da taxa de juros e da oferta de crédito. ( ) O Banco Central é o protagonista de ações nesta área. Assinale a opção que indica a relação correta, na ordem apresentada.","opcoes":["PF – PF – PM – PM.","PF – PF – PF – PM.","PF – PM – PM – PM.","PF – PF – PM – PF.","PM – PF – PM – PM."],"correta":0,"explicacao":"Gabarito: <strong>PF – PF – PM – PM.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2513046,"enunciado":"Acerca dos crimes contra o sistema financeiro nacional, assinale a afirmativa correta.","opcoes":["Na fixação da pena de multa, o limite a que se refere o Código Penal pode ser estendido até o décuplo.","O crime de gestão fraudulenta de instituição financeira admite a modalidade culposa.","Não há distinção relevante entre gestão fraudulenta e temerária, eis que a legislação estabelece penas idênticas em abstrato.","O indivíduo que contrata, em instituição financeira oficial, financiamento vinculado à compra de máquina para sua fábrica e utiliza a quantia para viajar ao exterior pratica fato atípico, desde que quite as prestações devidas.","A responsabilidade penal dos administradores de instituição financeira é objetiva, haja vista seu poder genérico de comando exercido sobre a corporação."],"correta":0,"explicacao":"Gabarito: <strong>Na fixação da pena de multa, o limite a que se refere o Código Penal pode ser estendido até o décuplo.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2513048,"enunciado":"Acerca dos crimes contra o mercado de capitais previstos na Lei nº 6.385/76, assinale a afirmativa correta.","opcoes":["Desde que ainda não tenha sido divulgada publicamente, é isenta de pena a utilização de informação relevante capaz de propiciar vantagem em negociação de valores mobiliários.","A execução de operações simuladas destinadas a elevar, manter ou baixar a cotação ou o volume negociado de um valor mobiliário somente é punível se tiver o fim explícito de obter lucro para si.","Configura infração penal a prestação da assessoria para investimentos no mercado de valores mobiliários sem autorização da autoridade competente quando assim exigido por lei ou regulamento, exceto se a atividade é realizada gratuitamente.","As multas cominadas para os crimes de manipulação de mercado e de uso indevido de informação privilegiada deverão ser aplicadas em razão do dano provocado ou da vantagem ilícita auferida pelo agente.","O agente que repassa informação sigilosa relativa a fato relevante a que tenha tido acesso em razão de cargo ou posição que ocupe em entidade emissora de valores mobiliários comete o crime de violação de segredo profissional."],"correta":3,"explicacao":"Gabarito: <strong>As multas cominadas para os crimes de manipulação de mercado e de uso indevido de informação privilegiada deverão ser aplicadas em razão do dano provocado ou da vantagem ilícita auferida pelo agente.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2515169,"enunciado":"Julgue o item.\n\n\n\n\nEmbora a literatura mencione a existência de vários instrumentos de política monetária, a taxa Selic é utilizada pelo Banco Central como o principal para o controle da inflação. É calculada pela média das operações compromissadas de um dia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2516078,"enunciado":"De acordo com a Resolução CVM nº 182/2023, que dispõe sobre certificados de depósito emitidos no Brasil com lastro em ações, certificados de depósito de ações ou em valores mobiliários representativos de dívida emitidos no exterior (BDR), é correto afirmar que:","opcoes":["na modalidade não patrocinado, o programa de BDR pode ser instituído por três ou mais instituições depositárias;","em cada programa de BDR, os valores mobiliários que servem como lastro para os BDR devem pertencer a uma única espécie e classe;","na modalidade patrocinado, o programa de BDR deve ser instituído por duas instituições depositárias, contratadas pelo patrocinador;","um programa de BDR patrocinado pode vigorar simultaneamente a um programa não patrocinado de BDR com lastro em até dois valores mobiliários da mesma espécie;","o programa de BDR classificado no nível I é sempre na modalidade patrocinado, sendo uma de suas características a dispensa de registro do emissor na CVM, ressalvada a hipótese de BDR com lastro em valores mobiliários representativos de dívida emitidos por emissores brasileiros."],"correta":1,"explicacao":"Gabarito: <strong>em cada programa de BDR, os valores mobiliários que servem como lastro para os BDR devem pertencer a uma única espécie e classe;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2516083,"enunciado":"A oferta pública de Certificados de Recebíveis do Agronegócio (CRA) deve observar a regulamentação fixada pela CVM, no exercício da competência que lhe foi atribuída pela Lei nº 14.430/2022, para editar as normas sobre a emissão pública de Certificados de Recebíveis e outros valores mobiliários representativos de operações de securitização de tais direitos. Nesses termos, os CRAs ofertados ao público em geral devem:","opcoes":["ser constituídos por direitos creditórios cedidos por duas ou mais companhias abertas sob controle comum;","ser constituídos por créditos considerados como performados no momento da cessão ou subscrição pela companhia securitizadora;","possuir devedores ou coobrigados com exposição máxima de 10% do valor da emissão, ainda que o devedor ou coobrigado seja companhia aberta ou instituição financeira;","contar com retenção substancial de riscos e benefícios do cessionário ou de terceiros, salvo se o CRA estiver vinculado à dívida de responsabilidade de dois ou mais devedores;","ter como lastro direitos creditórios, originais ou cessionários, de credores pessoas físicas ou jurídicas, produtores rurais ou suas cooperativas, com destinação dos recursos, dada pelo devedor ou pelo cedente, exclusiva ao setor agropecuário."],"correta":1,"explicacao":"Gabarito: <strong>ser constituídos por créditos considerados como performados no momento da cessão ou subscrição pela companhia securitizadora;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2516084,"enunciado":"A operação de securitização tem por objeto a aquisição de direitos creditórios pelas companhias securitizadoras para lastrear a emissão de Certificados de Recebíveis (CRs) ou outros títulos e valores mobiliários perante investidores. Sobre a natureza dos CRs e os direitos creditórios que lhes servem de lastro, analise as afirmativas a seguir. I. Os Certificados de Recebíveis são valores mobiliários nominativos, sob forma escritural, de livre negociação, e constituem ordem de pagamento em dinheiro. II. A companhia securitizadora responde pela origem e pela autenticidade dos direitos creditórios vinculados ao Certificado de Recebíveis por ela emitido. III. Os direitos creditórios que lastreiam os Certificados de Recebíveis devem ser previamente identificados, atendendo aos critérios de seletividade previstos no termo de securitização, e devem ser adquiridos até a data de emissão dos Certificados de Recebíveis. Está correto o que se afirma em:","opcoes":["I, apenas;","II, apenas;","I e III, apenas;","II e III, apenas;","I, II e III."],"correta":1,"explicacao":"Gabarito: <strong>II, apenas;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2516085,"enunciado":"A CVM, ao regulamentar o dever de verificação da adequação dos produtos, serviços e operações ao perfil do cliente (suitability) por parte das pessoas habilitadas a atuar como integrantes do sistema de distribuição e dos consultores de valores mobiliários, veda qualquer recomendação de produtos, realização de operações ou prestação de quaisquer serviços sem verificação de sua adequação ao perfil do cliente. A verificação deve avaliar, cumulativamente, se: o produto, serviço ou operação é adequado aos objetivos de investimento do cliente; a situação financeira do cliente é compatível com o produto, serviço ou operação; o cliente possui o conhecimento necessário para compreender os riscos relacionados ao produto, serviço ou operação. Em relação ao cumprimento da adequação do produto, serviço ou operação aos objetivos de investimento do cliente, deve(m)-se analisar:","opcoes":["as finalidades do investimento;","a necessidade futura de recursos declarada pelo cliente;","o valor e os ativos que compõem o patrimônio do cliente;","os tipos de produtos, serviços e operações com os quais o cliente tem familiaridade;","a natureza, o volume e a frequência das operações já realizadas pelo cliente no mercado de valores mobiliários."],"correta":0,"explicacao":"Gabarito: <strong>as finalidades do investimento;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2516090,"enunciado":"Em relação ao entendimento da CVM sobre as normas aplicáveis aos criptoativos que forem valores mobiliários, consolidado no Parecer de Orientação nº 40, aprovado pelo Colegiado da autarquia em 11 de outubro de 2022, analise as afirmativas a seguir. I. O conceito de valor mobiliário tem natureza instrumental e objetiva delimitar o regime mobiliário e, consequentemente, a competência da CVM. Dessa forma, nas hipóteses em que determinado criptoativo é valor mobiliário, os emissores e demais agentes envolvidos estão obrigados a cumprir as regras estabelecidas para o mercado de valores mobiliários e poderão estar sujeitos à regulação da CVM. II. Ainda que os criptoativos não estejam expressamente incluídos entre os valores mobiliários citados nos incisos do Art. 2º da Lei nº 6.385/1976, os agentes de mercado devem analisar as características de cada criptoativo com o objetivo de determinar se é valor mobiliário, o que ocorre quando (i) o criptoativo é a representação digital de algum dos valores mobiliários previstos taxativamente nos incisos I a VIII do Art. 2º da Lei nº 6.385/1976 e/ou previstos na Lei nº 14.430/2022; ou (ii) o criptoativo se enquadra no conceito aberto de valor mobiliário do inciso IX do Art. 2º da Lei nº 6.385/1976, na medida em que seja contrato de investimento coletivo. III. No que diz respeito aos criptoativos que se enquadram nos requisitos previstos no inciso IX do Art. 2º da Lei nº 6.385/1976, a caracterização de determinado ativo como um contrato de investimento coletivo não depende de manifestação prévia da CVM. Por conseguinte, os contratos de investimento coletivo, ainda que invistam ou que assumam exposição em criptoativos que não sejam valores mobiliários, são valores mobiliários. Está correto o que se afirma em:","opcoes":["I, apenas;","II, apenas;","I e III, apenas;","II e III, apenas;","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2516091,"enunciado":"Consoante as normas da CVM para obtenção de registro e regimes de prestação de informações por emissores estrangeiros, é correto afirmar que:","opcoes":["o representante legal dos emissores estrangeiros é equiparado ao diretor de relações com investidores para todos os fins previstos na legislação e regulamentação do mercado de valores mobiliários;","a Superintendência de Relações com Empresas (SEP) deve suspender o registro de emissor de valores mobiliários estrangeiro caso ele descumpra, por período superior a seis meses, suas obrigações periódicas;","os emissores estrangeiros devem entregar as demonstrações financeiras à CVM na data em que forem colocadas à disposição do público, observado o limite máximo de três meses do encerramento do exercício social;","estão automaticamente dispensados do registro de emissor de valores mobiliários os emissores estrangeiros cujos valores mobiliários sejam lastro para programas de certificados de depósito de valores mobiliários – BDR Nível I, desde que sejam não patrocinados;","as demonstrações financeiras de emissores estrangeiros devem ser elaboradas em português, em moeda corrente nacional, de acordo com a Lei nº 6.404, de 1976, e com as normas da CVM, e devem ser auditadas por auditor independente registrado na CVM, tal qual os emissores nacionais."],"correta":0,"explicacao":"Gabarito: <strong>o representante legal dos emissores estrangeiros é equiparado ao diretor de relações com investidores para todos os fins previstos na legislação e regulamentação do mercado de valores mobiliários;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2516092,"enunciado":"A Comissão de Valores Mobiliários, após análise de conveniência e oportunidade, decidiu suspender, antes da tomada da decisão de primeira instância, o procedimento administrativo destinado à apuração de infração praticada por administrador de fundo de investimento, propondo ao investigado assinar termo de compromisso. Considerada essa situação hipotética, de acordo com a Lei nº 6.385/1976, é correto afirmar que:","opcoes":["o termo de compromisso deve ser homologado em juízo a fim de constituir título executivo judicial em favor da CVM para a execução forçada de suas obrigações em face do signatário;","o termo de compromisso deverá ser publicado no Diário Oficial eletrônico da União, após sua assinatura com discriminação do prazo para cumprimento das obrigações eventualmente assumidas;","o termo de compromisso importa confissão quanto à matéria de fato e o reconhecimento de ilicitude da conduta analisada, tendo como efeito a impossibilidade de aplicação de sanção pela CVM que não seja a de multa;","a CVM dará continuidade ao procedimento administrativo para a aplicação das penalidades cabíveis se o investigado assinar o termo de compromisso e não cumprir as obrigações nele fixadas no prazo;","o investigado, se assinar termo de compromisso, obriga-se a cessar a prática de atividades ou atos considerados ilícitos pela Comissão de Valores Mobiliários e a corrigir as irregularidades apontadas; porém, não indenizará os prejuízos, haja vista que tal conduta depende de decisão judicial condenatória."],"correta":3,"explicacao":"Gabarito: <strong>a CVM dará continuidade ao procedimento administrativo para a aplicação das penalidades cabíveis se o investigado assinar o termo de compromisso e não cumprir as obrigações nele fixadas no prazo;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2516096,"enunciado":"Em 2021, o Colegiado da CVM aprovou Resolução que dispõe sobre a prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa – PLD/FTP – no âmbito do mercado de valores mobiliários. Em relação aos aspectos (i) âmbito da Resolução, (ii) obrigações das pessoas jurídicas e (iii) obrigações dos órgãos da alta administração, é correto afirmar que:","opcoes":["os órgãos da alta administração, conforme especificado na política de PLD/FTP, são responsáveis pela aprovação e adequação da respectiva política, da avaliação interna de risco, assim como das regras, dos procedimentos e dos controles internos;","as pessoas jurídicas sujeitas às obrigações previstas na Resolução devem indicar um diretor estatutário, responsável pela implementação e manutenção da respectiva política de PLD/FTP, e sua nomeação ou substituição deve ser informada à CVM no prazo de cinco dias úteis, contados da sua nomeação ou substituição;","as pessoas jurídicas sujeitas às obrigações previstas na Resolução devem elaborar e implementar política de PLD/FTP, documentada, aprovada pelo órgão deliberativo máximo da pessoa jurídica e mantida atualizada, de prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa;","a Resolução disciplina a efetivação, no âmbito do mercado de valores mobiliários, das medidas visando à indisponibilidade de bens, direitos e valores em decorrência de resoluções do Conselho de Segurança das Nações Unidas e de demandas de cooperação jurídica internacional advindas de outras jurisdições, em conformidade com os tratados e atos internacionais vigentes;","as pessoas jurídicas sujeitas às obrigações previstas na Resolução devem comunicar, no prazo de 24 horas da conclusão da análise que caracterizou a atipicidade da operação, à Receita Federal do Brasil todas as situações e operações detectadas que possam constituir-se em sérios indícios de lavagem de dinheiro e financiamento do terrorismo ou da proliferação de armas de destruição em massa."],"correta":0,"explicacao":"Gabarito: <strong>os órgãos da alta administração, conforme especificado na política de PLD/FTP, são responsáveis pela aprovação e adequação da respectiva política, da avaliação interna de risco, assim como das regras, dos procedimentos e dos controles internos;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2534610,"enunciado":"No ecossistema do Bitcoin, o halving é um evento programado que ocorre a cada 210.000 blocos, reduzindo pela metade a recompensa por bloco que os mineradores recebem por validar transações e adicionar novos blocos à blockchain. Esse mecanismo tem um impacto significativo na economia do Bitcoin, influenciando a","opcoes":["velocidade de transação na rede, aumentando-a significativamente à medida que mais mineradores se juntam à rede em busca de recompensas maiores.","quantidade total de bitcoins em circulação, duplicando-a instantaneamente para incentivar a mineração.","taxa em que novos bitcoins são gerados, diminuindo-a e, consequentemente, aumentando a escassez de bitcoin ao longo do tempo.","segurança da rede Bitcoin, diminuindo-a ao reduzir o número de mineradores devido à menor rentabilidade.","capacidade de processamento necessário para a mineração de bitcoins, reduzindo-a pela metade e tornando a mineração acessível a mais pessoas."],"correta":2,"explicacao":"Gabarito: <strong>taxa em que novos bitcoins são gerados, diminuindo-a e, consequentemente, aumentando a escassez de bitcoin ao longo do tempo.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2534611,"enunciado":"Em sistemas de blockchain que interagem com o mundo real, uma questão fundamental surge quando contratos inteligentes necessitam de dados externos para executar suas funções. Essa questão representa um desafio significativo na integração confiável de informações fora da blockchain. O nome dado ao problema que descreve a dificuldade inerente em acessar informações verídicas e atualizadas do mundo externo, sem comprometer a segurança e a descentralização do sistema blockchain é","opcoes":["dupla despesa.","ataque de 51%.","oráculo.","volatilidade.","escalabilidade."],"correta":2,"explicacao":"Gabarito: <strong>oráculo.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2571554,"enunciado":"Relacione cada conceito de mercados financeiros apresentado a seguir com sua respectiva característica: 1. Índice de Mercado 2. Tipo de Ordem 3. Margem 4. Bolsa de Valores ( ) É essencial para operações que utilizam alavancagem, permitindo que os investidores controlem uma quantidade maior de ativos do que poderiam comprar diretamente, e pode variar conforme a volatilidade do ativo subjacente. ( ) Representa o desempenho de um conjunto específico de ativos financeiros, selecionados conforme determinados critérios, e são utilizados como benchmarks para fundos de investimento e gestores de carteira. ( ) Pode incluir restrições de preço que garantem que a execução não ocorra além do preço especificado, e é vital para a gestão de riscos em mercados voláteis. ( ) Ambiente regulado que facilita a captação de recursos pelas empresas, promovendo liquidez e transparência, além de oferecer serviços como clearing e settlement para garantir a execução e liquidação das transações. ( ) Envolve estratégias que consideram a dinâmica do mercado para otimizar as transações, utilizando tecnologia avançada para minimizar os custos e maximizar a eficiência. Assinale a opção que indica a relação correta, na ordem apresentada.","opcoes":["1 – 2 – 3 – 4 – 2.","2 – 1 – 3 – 4 – 3.","3 – 1 – 4 – 2 – 2.","3 – 1 – 2 – 4 – 2.","4 – 2 – 3 – 1 – 4."],"correta":3,"explicacao":"Gabarito: <strong>3 – 1 – 2 – 4 – 2.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2571557,"enunciado":"Sobre os instrumentos derivativos, especificamente opções e futuros, assinale a afirmativa incorreta.","opcoes":["Uma opção de compra (call) concede ao titular o direito, mas não a obrigação, de comprar um ativo subjacente a um preço predeterminado (preço de exercício) até ou na data de vencimento.","Uma opção de venda (put) concede ao titular o direito, mas não a obrigação, de vender um ativo subjacente a um preço predeterminado (preço de exercício) até ou na data de vencimento.","No mercado de futuros, as partes assumem a obrigação de comprar ou vender o ativo subjacente a um preço acordado na data de vencimento do contrato, sem a possibilidade de liquidação antes do vencimento.","O prêmio da opção é o preço que o comprador da opção paga ao vendedor para adquirir o direito conferido pela opção.","A avaliação de preço de um contrato de futuro pode ser feita utilizando o modelo de precificação de futuros, que considera o preço à vista do ativo subjacente ajustado pelo custo de carregamento até a data de vencimento do contrato."],"correta":2,"explicacao":"Gabarito: <strong>No mercado de futuros, as partes assumem a obrigação de comprar ou vender o ativo subjacente a um preço acordado na data de vencimento do contrato, sem a possibilidade de liquidação antes do vencimento.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2571564,"enunciado":"A política monetária é um dos principais instrumentos usados pelos bancos centrais para controlar a oferta de moeda e influenciar a economia de um país. No contexto da política monetária, os agregados monetários desempenham um papel fundamental. Assinale a opção que define corretamente um agregado monetário e apresenta sua importância na política monetária.","opcoes":["M0 - Representa a quantidade total de dinheiro em circulação na forma de papel-moeda e depósitos à vista, sendo o mais amplo dos agregados monetários.","M1 - Refere-se ao dinheiro físico em circulação, além dos depósitos à vista nos bancos comerciais, sendo considerado o agregado monetário mais líquido.","M2 - Inclui todos os componentes de M1, além dos depósitos de poupança, títulos públicos, e outros investimentos de longo prazo, oferecendo uma visão ampla da liquidez na economia.","M3 - Compõe-se de M1 mais depósitos a prazo, além de títulos do governo em poder do público, sendo um indicador importante da base monetária.","MB - Representa a soma de M1 e M2, além de ativos líquidos em instituições financeiras não bancárias, oferecendo uma medida mais abrangente da liquidez total na economia."],"correta":1,"explicacao":"Gabarito: <strong>M1 - Refere-se ao dinheiro físico em circulação, além dos depósitos à vista nos bancos comerciais, sendo considerado o agregado monetário mais líquido.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2571565,"enunciado":"Considerando os conceitos de criação e destruição de moeda e o multiplicador dos meios de pagamento, analise as afirmativas a seguir. I. A base monetária é composta pelo papel-moeda em poder do público mais as reservas bancárias. II. O multiplicador dos meios de pagamento é inversamente proporcional à taxa de reservas obrigatórias. III. Uma redução nas reservas internacionais do Banco Central resulta em expansão da base monetária. IV. Os depósitos à vista possuem liquidez absoluta, sendo integralmente mantidos como reservas pelos bancos comerciais. V. A política de redesconto é utilizada pelo Banco Central para influenciar a oferta de moeda através da alteração da taxa de juros de empréstimos aos bancos comerciais. Está correto apenas o que se afirma em","opcoes":["I, II e V.","II e IV.","I, III e V.","I, II, III e IV.","I, II, IV e V."],"correta":0,"explicacao":"Gabarito: <strong>I, II e V.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572447,"enunciado":"Considerando a operacionalização da política monetária executada pelo Banco Central do Brasil (BCB) e as principais medidas macroprudenciais, julgue o item subsequente. \n\n\n\n\nO BCB emite títulos para a execução da política monetária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572467,"enunciado":"Acerca dos títulos emitidos pelo Tesouro Nacional, julgue o item seguinte. \n\n\n\n\nO valor investido no título Tesouro Prefixado 2031 pode ser resgatado a qualquer data, com a garantia da taxa de juros contratada no dia da compra.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572468,"enunciado":"Acerca dos títulos emitidos pelo Tesouro Nacional, julgue o item seguinte. \n\n\n\n\nO rendimento dos títulos Tesouro IPCA corresponde a uma taxa prefixada de juros somada à variação do índice nacional de preços ao consumidor amplo (IPCA) no período.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572469,"enunciado":"No que se refere ao mercado de ações, julgue o item a seguir. \n\n\n\n\nO valor de mercado de uma ação coincide com o seu valor intrínseco, por corresponder às expectativas de fluxos de ganhos futuros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572470,"enunciado":"No que se refere ao mercado de ações, julgue o item a seguir. \n\n\n\n\nEnquanto ações ordinárias dão direito apenas a voto, as ações preferenciais dão direito à parte dos dividendos proporcional ao número de votos detidos pelo acionista.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572471,"enunciado":"Considerando que o preço de mercado de uma ação esteja em $ 195,00, julgue o próximo item, referente ao mercado de opções.\n\n\n\n\nNo referido contexto, o titular de opções de venda da referida ação poderá vendê-la por $ 200,00 e, com isso, terá ganho igual a $ 5,00, descontado o prêmio pago pelas opções.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572472,"enunciado":"A respeito de fundos de investimento e eficiência dos mercados, julgue o item subsecutivo.  \n\n\n\n\nEm geral, informações perfeitas e completas acerca de um mercado financeiro bastam para garantir a eficiência dele.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572473,"enunciado":"A respeito de fundos de investimento e eficiência dos mercados, julgue o item subsecutivo.  \n\n\n\n\nUm fundo com investimento de pelo menos uma parte de seu patrimônio em ativos atrelados à variação cambial é um fundo cambial, de acordo com a Comissão de Valores Mobiliários (CVM).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572474,"enunciado":"Na avaliação de investimentos no mercado financeiro, é importante considerar como o investidor avalia o retorno e o risco envolvidos em cada investimento. Com relação à teoria de carteiras, julgue o item subsequente. \n\n\n\n\nUm agente cujas preferências por riqueza sejam dadas pela função utilidade u(w) = ln w, em que ln indica o logaritmo natural e w, o montante de riqueza possuído pelo agente, é avesso ao risco.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572475,"enunciado":"Na avaliação de investimentos no mercado financeiro, é importante considerar como o investidor avalia o retorno e o risco envolvidos em cada investimento. Com relação à teoria de carteiras, julgue o item subsequente. \n\n\n\n\nNa análise de carteiras de investimentos, o risco sistemático é a parcela que não pode ser eliminada por meio da diversificação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2572497,"enunciado":"Julgue o item a seguir, relativos aos princípios gerais da contabilidade das instituições reguladas pelo BCB, instrumentos financeiros e a operações de crédito. \n\n\n\n\nOs empréstimos são operações de crédito realizadas sem destinação específica ou vínculo à comprovação da aplicação dos recursos, ao passo que os financiamentos são realizados com destinação específica, vinculados à comprovação da aplicação dos recursos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2609778,"enunciado":"Em relação à natureza jurídica da Comissão de Valores Mobiliários (CVM) e sua criação por lei, é correto afirmar que se trata de:","opcoes":["entidade autárquica em regime especial, instituída pela Lei nº 6.385/1976, com personalidade jurídica e patrimônio próprios, dotada de autoridade administrativa independente, ausência de subordinação hierárquica, mandato fixo e estabilidade de seus dirigentes, e autonomia financeira e orçamentária;","órgão integrante da administração pública direta da União, vinculado ao Ministério da Fazenda, instituída pela Lei nº 4.728/1965, dotada de autoridade administrativa independente, ausência de subordinação hierárquica, mandato de 5 anos de seus dirigentes, com uma recondução, e autonomia financeira e orçamentária;","entidade autárquica em regime especial, instituída pela Lei nº 6.404/1976, com personalidade jurídica e patrimônio próprios, dotada de autoridade administrativa independente, subordinação hierárquica ao Ministério da Fazenda, mandato variável de seus dirigentes, vedada a recondução, e autonomia orçamentária;","órgão integrante da administração pública direta da União, vinculado ao Ministério do Planejamento, instituída pela Lei nº 4.595/1964, com personalidade jurídica e patrimônio próprios, dotada de autoridade administrativa sujeita ao controle da CGU, ausência de subordinação hierárquica, mandato de 4 anos de seus dirigentes, e autonomia financeira;","entidade autárquica em regime especial, instituída pela Lei nº 5.772/1971, com personalidade jurídica e patrimônio próprios, dotada de autoridade administrativa subordinada ao Conselho Monetário Nacional, mandato fixo de seus dirigentes pelo prazo de dois anos, e autonomia financeira e orçamentária."],"correta":0,"explicacao":"Gabarito: <strong>entidade autárquica em regime especial, instituída pela Lei nº 6.385/1976, com personalidade jurídica e patrimônio próprios, dotada de autoridade administrativa independente, ausência de subordinação hierárquica, mandato fixo e estabilidade de seus dirigentes, e autonomia financeira e orçamentária;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2609783,"enunciado":"De acordo com a regulamentação da CVM para a atividade de classificação de risco de crédito, no âmbito do mercado de valores mobiliários, destinada à publicação, divulgação ou distribuição a terceiros, ainda que restrita a clientes, a agência de classificação de risco de crédito, para obtenção e manutenção do registro, deve atender aos requisitos a seguir, EXCETO:","opcoes":["ser domiciliada no Brasil;","constituir e manter recursos humanos e tecnológicos adequados ao seu porte e à sua área de atuação;","prever em seu objeto social a atividade de classificação de risco de crédito e estar regularmente constituída e registrada no Cadastro Nacional de Pessoas Jurídicas – CNPJ;","atribuir a responsabilidade pelas suas atividades e pelo cumprimento das normas estabelecidas pela CVM a um administrador que possua todos os poderes necessários para representar a agência;","atribuir a responsabilidade pela supervisão do cumprimento de regras, procedimentos e controles internos e das normas da CVM ao mesmo administrador com poderes para representar a agência, e com todos os poderes necessários para exercer sua função."],"correta":4,"explicacao":"Gabarito: <strong>atribuir a responsabilidade pela supervisão do cumprimento de regras, procedimentos e controles internos e das normas da CVM ao mesmo administrador com poderes para representar a agência, e com todos os poderes necessários para exercer sua função.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2631045,"enunciado":"Em 2023, os bancos associados à Federação Brasileira de Bancos (Febraban) iniciaram processo para descontinuar operações/transações via Documento de Ordem de Crédito (DOC), meio de pagamento presente na economia brasileira desde 1985. Considerando os fatores que motivaram o processo de extinção desse meio de pagamento, assinale a alternativa correta.","opcoes":["O processo de extinção do DOC é motivado pela elevação recente de seu custo de manutenção no sistema financeiro, decorrente do aumento do volume de transferências registradas por esse modal.","Apesar de serem gratuitas e não possuírem limite máximo de valor, as transferências via DOC estão em processo de descontinuação por causa das restrições de horário que essa modalidade apresenta.","A implementação do meio de pagamento instantâneo Pix, desenvolvido entre 2018 e 2020, está correlacionada à redução do volume de transações via DOC nos últimos anos, o que motivou sua descontinuação.","O interesse em descontinuar as transações via DOC está relacionado ao recente período de redução da taxa de juros básica (Selic) da economia brasileira, que reduz a viabilidade de operações por esse modal.","Enquanto as transações via DOC podem ser cobradas, outros meios de pagamento são necessariamente gratuitos, independentemente de sua origem, como é o caso do Pix e, portanto, são mais atrativos."],"correta":0,"explicacao":"Gabarito: <strong>O processo de extinção do DOC é motivado pela elevação recente de seu custo de manutenção no sistema financeiro, decorrente do aumento do volume de transferências registradas por esse modal.</strong>.","banca":"IADES","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2631046,"enunciado":"O Sistema Financeiro Nacional (SFN) é formado por um conjunto de entidades e instituições que promovem a intermediação financeira, isto é, o encontro entre credores e tomadores de recursos. É por meio do sistema financeiro que as pessoas, as empresas e o governo circulam a maior parte dos seus ativos, pagam suas dívidas e realizam seus investimentos. Disponível em: <https://www.bcb.gov.br/estabilidadefinanceira/sfn>. Acesso em: 25 jan. 2023, com adaptações. Com base nos seus conhecimentos acerca do SFN, assinale a alternativa que apresenta instituição pertencente ao Subsistema de Intermediação.","opcoes":["Superintendência de Seguros Privados","Comissão de Valores Mobiliários","Conselho Monetário Nacional","Banco Central do Brasil","Caixa Econômica Federal"],"correta":3,"explicacao":"Gabarito: <strong>Banco Central do Brasil</strong>.","banca":"IADES","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2645259,"enunciado":"O Banco Nacional de Desenvolvimento Econômico e Social (BNDES), diretamente ou por intermédio de empresas subsidiárias, agentes financeiros ou outras entidades, exercerá atividades bancárias e realizará operações, financeiras ou no mercado de capitais, de qualquer gênero, relacionadas com suas finalidades institucionais. Sobre o BNDES, assinale a alternativa correta.","opcoes":["Não poderá assumir obrigações ou responsabilidades, incluindo a realização de projetos de investimento e assunção de custos/resultados operacionais específicos, em condições diversas às de qualquer outra sociedade do setor privado que atue no mesmo mercado.","Entre suas atividades, cabe financiar programas de desenvolvimento econômico, com os recursos do Fundo de Amparo ao Trabalhador.","Poderá ter suas atividades, ainda que destoantes de seu objeto social, orientadas pela União de modo a contribuir para o interesse público que justificou a sua criação.","Exercitará suas atividades, visando a estimular o setor público, não estando autorizado a apoiar empreendimentos de interesse nacional a cargo do setor privado.","Trata-se de sociedade de economia mista dotada de personalidade jurídica de direito privado e patrimônio próprio."],"correta":1,"explicacao":"Gabarito: <strong>Entre suas atividades, cabe financiar programas de desenvolvimento econômico, com os recursos do Fundo de Amparo ao Trabalhador.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2645262,"enunciado":"Os Cinco C’s do Crédito são uma forma tradicional e subjetiva de captar informação para a avaliação de crédito na economia brasileira e em outras economias. Assinale a alternativa que NÃO corresponde a um dos conceitos que fazem parte dos Cinco C’s do crédito.","opcoes":["Conhecimento.","Caráter.","Colateral.","Condições.","Capital."],"correta":0,"explicacao":"Gabarito: <strong>Conhecimento.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2747754,"enunciado":"O Fundo Garantidor de Créditos gerencia o mecanismo de proteção contra instituições financeiras, proporcionando garantia limitada a:","opcoes":["Letras do tesouro nacional.","Depósitos à vista e a prazo.","Fundos de investimento.","Debêntures.","Depósitos judiciais."],"correta":3,"explicacao":"Gabarito: <strong>Debêntures.</strong>.","banca":"Centec","ano":2015,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2771559,"enunciado":"Segundo o Banco Central do Brasil, todo cliente pessoa natural que possuir conta de depósitos à vista ou de poupança tem direito aos seguintes serviços gratuitamente, exceto:","opcoes":["fornecimento de até 10 (dez) folhas de cheque, desde que o correntista reúna os requisitos necessários à sua utilização, de acordo com a regulamentação em vigor e as condições pactuadas.","compensação ilimitada de cheques.","até 1 (uma) transferência por meio de DOC ou TED.","realização de até 4 (quatro) saques em guichê de caixa, inclusive por meio de cheque ou de cheque avulso, ou em terminal de autoatendimento.","realização de até 2 (duas) transferências de recursos entre contas na própria instituição, em guichê de caixa, em terminal de autoatendimento ou pela internet."],"correta":2,"explicacao":"Gabarito: <strong>até 1 (uma) transferência por meio de DOC ou TED.</strong>.","banca":"Quadrix","ano":2016,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":2907266,"enunciado":"Sobre o Plano Gerador de Benefício Livre (PGBL), é correto afirmar que o participante:","opcoes":["Adquire cotas da bolsa de valores de curto prazo, mas há necessidade de periodicidade mínima.","Não opta pelo perfil da aplicação, embora seja esclarecido ao mesmo que os perfis estão classificados em conservador, moderado ou agressivo.","Adquire cotas de um fundo de investimento de longo prazo, mas não há periodicidade mínima de contribuição.","Adquire cotas de um fundo de investimento de longo prazo, mas há periodicidade mínima de contribuição.","Adquire cotas de um fundo de investimento de curto prazo, mas não há periodicidade mínima de contribuição."],"correta":4,"explicacao":"Gabarito: <strong>Adquire cotas de um fundo de investimento de curto prazo, mas não há periodicidade mínima de contribuição.</strong>.","banca":"Quadrix","ano":2013,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3079060,"enunciado":"Função da tesouraria que implica em um acompanhamento dos compromissos financeiros, garantindo que os pagamentos e recebimentos sejam feitos dentro do prazo:","opcoes":["Fluxo de caixa.","Conciliação bancária.","Contas a pagar e receber.","Projeção financeira."],"correta":2,"explicacao":"Gabarito: <strong>Contas a pagar e receber.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3146075,"enunciado":"No Brasil, a taxa de câmbio indica quantos reais são necessários para se adquirir uma unidade de moeda estrangeira (por exemplo, dólar americano). Considerando que, de dezembro de 2022 a dezembro de 2023, a taxa de câmbio do dólar americano caiu 8,5%, julgue o item seguinte, ignorando eventuais efeitos da inflação nos dois países (Brasil e EUA) e flutuações de oferta e procura dos bens e serviços importados.\n\nDe dezembro de 2022 a dezembro de 2023, houve valorização do real, o que barateou as importações de mercadorias dos EUA.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3146076,"enunciado":"Julgue o item subsequente, a respeito da taxa SELIC e de seu efeito nas taxas de juros do mercado brasileiro.  \n\nA taxa referencial de juros, conhecida como taxa SELIC, é definida pelo Comitê de Política Monetária (COPOM) a cada 45 dias.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3146077,"enunciado":"Julgue o item subsequente, a respeito da taxa SELIC e de seu efeito nas taxas de juros do mercado brasileiro.  \n\nA taxa SELIC determina o teto da taxa de juros real praticada pelos bancos comerciais e pelas financeiras em contratos de financiamento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3206273,"enunciado":"No que se refere à organização, à fiscalização e à supervisão da previdência complementar, julgue o próximo item.\n\n\n\n\nO órgão responsável pela fiscalização e supervisão das atividades das entidades fechadas de previdência complementar é a Superintendência Nacional de Previdência Complementar (PREVIC).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3206592,"enunciado":"Em relação a investimentos, julgue o item a seguir.\n\n\n\n\nDebêntures são títulos nominativos negociáveis representativos do valor de uma empresa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3206593,"enunciado":"Em relação a investimentos, julgue o item a seguir.\n\n\n\n\nCertificados de recebíveis imobiliários são títulos de renda fixa atrelados a operações imobiliárias futuras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3206594,"enunciado":"Em relação a investimentos, julgue o item a seguir.\n\n\n\n\nNotas promissórias são títulos de renda variável estimados em médio prazo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3206595,"enunciado":"Em relação a investimentos, julgue o item a seguir.\n\n\n\n\nBônus de subscrição são títulos nominativos atrelados a uma dívida disponível para negociação pública.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3206596,"enunciado":"Em relação a investimentos, julgue o item a seguir.\n\n\n\n\nSomente os acionistas principais — aqueles que detêm 20% ou mais das ações — fazem jus ao recebimento de dividendos, que se referem à parte dos lucros gerados por uma empresa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3213602,"enunciado":"Em relação ao sistema monetário, julgue o próximo item.\n\n\n\n\nConsidere que o Banco Central atue no mercado de câmbio à vista por meio da venda de dólares das reservas internacionais e, simultaneamente, faça uma operação de mercado aberto, no mesmo valor, comprando títulos da dívida pública em poder do público. Nessa hipótese, não haverá alteração da base monetária.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3213603,"enunciado":"Em relação ao sistema monetário, julgue o próximo item.\n\n\n\n\nEm uma economia com base monetária de $ 2.000, na qual 80% dos meios de pagamento são mantidos sob a forma de depósitos à vista em bancos comerciais, se os bancos mantiverem 25% desses depósitos sob a forma de reservas, consideradas tanto as obrigatórias quanto as voluntárias, a quantidade de moeda (M1) em circulação equivalerá a $ 5.000.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3213647,"enunciado":"Considerando aspectos contábeis concernentes às ações em tesouraria, julgue o item que se segue.\n\n\n\n\nA emissão de novas ações por uma empresa de capital aberto com ações em tesouraria aumentará o seu capital social apenas quando houver o cancelamento destas últimas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3213648,"enunciado":"Considerando aspectos contábeis concernentes às ações em tesouraria, julgue o item que se segue.\n\n\n\n\nA recompra das próprias ações não altera o valor do capital social registrado da empresa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3213649,"enunciado":"Considerando aspectos contábeis concernentes às ações em tesouraria, julgue o item que se segue.\n\n\n\n\nO pagamento de dividendos com distribuição de ações em tesouraria é considerado uma despesa operacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3213650,"enunciado":"Considerando aspectos contábeis concernentes às ações em tesouraria, julgue o item que se segue.\n\n\n\n\nO resultado positivo com a venda de ações em tesouraria é registrado diretamente em uma conta de reserva de capital.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3213651,"enunciado":"Considerando aspectos contábeis concernentes às ações em tesouraria, julgue o item que se segue.\n\n\n\n\nA reserva de lucros pode ser utilizada para comprar ações que ficarão em tesouraria.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257408,"enunciado":"Acerca de project finance, julgue o item subsecutivo.\n\n\n\n\n  \n\nRating é uma ferramenta que avalia no mercado financeiro o risco de crédito de empresas, de governos e até de produtos financeiros, como títulos de dívida.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257409,"enunciado":"Acerca de project finance, julgue o item subsecutivo.\n\n\n\n\nPenhor ou caução de ações da empresa de propósito específico são exemplos de tipos de contratos de financiamento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257410,"enunciado":"Acerca de project finance, julgue o item subsecutivo.\n\n\n\n\nO pagamento de empréstimos deve ser feito apenas com recursos do fluxo de caixa, tendo como garantia os ativos do projeto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257411,"enunciado":"Acerca de project finance, julgue o item subsecutivo.\n\n\n\n\n\nA estrutura de project finance caracteriza-se pela constituição de uma empresa de propósito específico, que terá tempo ilimitado de duração para a implantação do projeto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257412,"enunciado":"Acerca de project finance, julgue o item subsecutivo.\n\n\n\nContrato take-if-offered é aquele que obriga o comprador da produção ou dos serviços do projeto a recebê-los ou pagá-los apenas se o projeto for capaz de entregá-los.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257433,"enunciado":"Em relação aos órgãos do subsistema normativo do sistema financeiro nacional, julgue o item que se segue.\n\n \n\nUma das funções do Banco do Brasil é ser depositário das disponibilidades de caixa da União, na chamada Conta Única do Tesouro Nacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257434,"enunciado":"Em relação aos órgãos do subsistema normativo do sistema financeiro nacional, julgue o item que se segue.\n\n \n\n\n\n\nO Conselho Monetário Nacional define periodicamente, por meio de seu Comitê de Política Monetária (COPOM), o valor da taxa básica de juros da economia — taxa SELIC.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257435,"enunciado":"Em relação aos órgãos do subsistema normativo do sistema financeiro nacional, julgue o item que se segue.\n\n \n\nO controle do mercado de valores mobiliários é feito pela B3.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257436,"enunciado":"No que concerne ao mercado monetário e às suas operações, julgue o item seguinte.\n\n\n\n\nA CETIP realiza a custódia, o registro e o controle das operações envolvendo títulos privados, como debêntures e notas promissórias, bem como efetua a liquidação financeira de tais operações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257437,"enunciado":"No que concerne ao mercado monetário e às suas operações, julgue o item seguinte.\n\n\n\n\nAo comprar notas do Tesouro Nacional (NTN) do mercado, o Banco Central aumenta a oferta de moeda.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257438,"enunciado":"No início de determinado mês, a taxa de câmbio da moeda do país X em relação ao Brasil era R$ 5,00/X$. Ao fim do referido mês, a inflação no Brasil foi de 2%, enquanto a do país X foi de 5%.\n\n\n\n\nA partir da situação apresentada, julgue o item a seguir, relativo ao mercado cambial.  \n\n\n\n\nSe certo investidor comprar um contrato de swap cambial do Banco Central do Brasil (BCB), ele receberá do BCB, em caso de valorização da moeda do país X no respectivo período, um valor correspondente à variação cambial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257439,"enunciado":"No início de determinado mês, a taxa de câmbio da moeda do país X em relação ao Brasil era R$ 5,00/X$. Ao fim do referido mês, a inflação no Brasil foi de 2%, enquanto a do país X foi de 5%.\n\n\n\n\nA partir da situação apresentada, julgue o item a seguir, relativo ao mercado cambial.  \n\n\n\n\nSe a situação descrita permanecer como está, a taxa de câmbio que mantém a paridade cambial no fim do mês em questão deve ser 7% menor do que R$ 5,00/X$.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257440,"enunciado":"José adquiriu 100 ações de uma empresa, por R$ 23,00 cada uma. Como alternativa de hedge, ele também adquiriu opções de venda dessas mesmas ações pelo prêmio de R$ 0,40 por ação. O preço de exercício das opções é R$ 24,00 por ação. Na data de vencimento das opções, José observou que o preço à vista das suas ações estava em R$ 22,00 por ação.\n\n\n\n\nConsiderando a situação hipotética precedente, julgue o item subsequente, relativo ao funcionamento das opções no mercado futuro. \n\n\n\n\nIgnorados os impostos e as taxas envolvidos na operação, José terá, se optar por vender suas ações, um lucro líquido de R$ 160,00, ou de R$ 1,60 por ação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257441,"enunciado":"José adquiriu 100 ações de uma empresa, por R$ 23,00 cada uma. Como alternativa de hedge, ele também adquiriu opções de venda dessas mesmas ações pelo prêmio de R$ 0,40 por ação. O preço de exercício das opções é R$ 24,00 por ação. Na data de vencimento das opções, José observou que o preço à vista das suas ações estava em R$ 22,00 por ação.\n\n\n\n\nConsiderando a situação hipotética precedente, julgue o item subsequente, relativo ao funcionamento das opções no mercado futuro. \n\n\n\n\n\n\n\nO vendedor das opções tem a obrigação de comprar as ações de José, se este as quiser vender.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257442,"enunciado":"A respeito das instituições que operam no mercado financeiro e no mercado de capitais, julgue o item que se segue.\n\nTanto bancos de investimento quanto bancos de desenvolvimento podem prover recursos para o financiamento de atividades do setor privado, mas os bancos de desenvolvimento devem visar ao desenvolvimento econômico e social da região em que atuem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257443,"enunciado":"A respeito das instituições que operam no mercado financeiro e no mercado de capitais, julgue o item que se segue.\n\n\n\n\nApesar de as demais associações de poupança e empréstimo terem, formalmente, atuação apenas regional, a Associação de Poupança e Empréstimo (POUPEX) tem a peculiaridade de atuar em âmbito nacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3257444,"enunciado":"No que diz respeito a títulos emitidos pelo Tesouro Nacional, julgue o seguinte item. \n\n\n\n\nSe um investidor adquirir um título prefixado do Tesouro Nacional, ou seja, sem pagamentos semestrais de juros, ele poderá resgatar seu investimento a qualquer tempo e receberá, pelo período do investimento, rendimentos equivalentes à taxa contratada no dia da compra do título.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3279337,"enunciado":"Em relação aos modelos de negócio e às etapas de sua criação, julgue o item seguinte.\n\n\n\n\nA escolha do canal ou canais de comunicação com clientes está relacionada à forma como a empresa interage com seus clientes para entregar a proposta de valor, sendo necessária a criação de canal único de comunicação para o atendimento centralizado dos clientes, em face do novo modelo de negócio, ancorado na experiência omnichannel.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3279338,"enunciado":"Em relação aos modelos de negócio e às etapas de sua criação, julgue o item seguinte.\n\n\n\n\nA primeira etapa para um adequado modelo de negócio é a definição da estratégia: a partir de um leque de possibilidades, escolhe-se o modelo mais adequado à missão da empresa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3279339,"enunciado":"Em relação aos modelos de negócio e às etapas de sua criação, julgue o item seguinte.\n\n\n\n\nEntre os componentes do modelo de negócio está a proposta de valor, a partir da qual são combinados os elementos necessários ao atendimento das necessidades de determinado grupo de clientes, criando-se valor para esse segmento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3280351,"enunciado":"Julgue o próximo item, relativo a fontes de financiamento de negócios para inovação.\n\n\n\n\nAs ofertas públicas de crowdfunding de investimento estão sujeitas à regulamentação e à fiscalização da Comissão de Valores Mobiliários (CVM), e é obrigatório o registro da oferta e do emissor na CVM.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3285470,"enunciado":"J ingressou como sócio em determinada sociedade empresária possuindo cerca de dez por cento do capital votante. Após amplos debates, todos os sócios decidiram implantar normas para melhorar a prática de governança nas relações internas da sociedade. Nos termos do Código das melhores práticas de governança corporativa do Instituto Brasileiro de Governança Corporativa, a prática que mais promove o alinhamento de interesses entre todos os sócios corresponde a uma ação, um voto. Nesse sentido, devem ser rejeitadas estruturas que concentrem o poder político de modo desproporcional à participação do capital. Assim, o procedimento que promove o alinhamento de interesses é a prática de","opcoes":["voto plural","poison pills","golden shares","ações preferenciais","direito de voto proporcional"],"correta":4,"explicacao":"Gabarito: <strong>direito de voto proporcional</strong>.","banca":"CESGRANRIO","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3285472,"enunciado":"Um gerente do Banese foi convidado a ocupar cargo de destaque na estrutura do banco tendo em vista seu desempenho e dedicação ao trabalho, atingindo as metas determinadas e liderando equipes sem provocar resistências, logrando aprovação em todos os segmentos do negócio. Ao aceitar o convite, pleiteou à Diretoria a realização de treinamento nas modernas técnicas de administração com a finalidade de capacitar os colaboradores para enfrentar os novos desafios do mercado. Nos termos do Código das melhores práticas de governança corporativa do Instituto Brasileiro de Governança Corporativa, todos os agentes de governança da corporação devem desempenhar suas funções com diligência, independência e com vistas à geração de valor sustentável no longo prazo, assumindo a responsabilidade pelas consequências de seus atos e omissões e prestar contas de sua atuação de modo","opcoes":["técnico","padrão","extensivo","abrangente","compreensível"],"correta":4,"explicacao":"Gabarito: <strong>compreensível</strong>.","banca":"CESGRANRIO","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3346524,"enunciado":"Quanto ao processo de conciliação contábil e bancária, analise as assertivas abaixo: I. A conciliação bancária é a conferência dos registros contábeis a débito e crédito no razão com os respectivos lançamentos efetuados pela instituição financeira, através dos extratos bancários. II. Todas as divergências identificadas deverão constar em relatório para possibilitar a investigação e a correção de erros e ocorrências anormais. III. Cada conta contábil das demonstrações financeiras deve ser verificada e ter a composição de seu saldo validada. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3346526,"enunciado":"Há uma série de medidas que podem ser adotadas pelas organizações para a adequada gestão da Tesouraria, quais sejam: I. Reduzir as comissões bancárias e os custos de transação, através de economias de escala e uma racionalização das relações bancárias. II. Melhorar o ciclo de conversão do caixa, identificando os caminhos para reduzi-lo. III. Converter os possíveis excessos de fundos em ativos rentáveis, assegurando liquidez suficiente para as operações diárias. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3403761,"enunciado":"Como é chamada a movimentação bancária realizada quando o dinheiro é transferido de uma conta corrente ou do caixa, para uma conta de aplicação?","opcoes":["Saque.","Aplicação.","Depósito.","Resgate."],"correta":1,"explicacao":"Gabarito: <strong>Aplicação.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3417057,"enunciado":"No que se refere à previdência complementar aberta e aos planos com cobertura por sobrevivência, julgue o item subsequente. \n\n\n\n\nÉ possível a portabilidade dos recursos acumulados de um plano VGBL para um plano PGBL, ou vice-versa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3417058,"enunciado":"No que se refere à previdência complementar aberta e aos planos com cobertura por sobrevivência, julgue o item subsequente. \n\n\n\n\nAs entidades abertas de previdência complementar podem realizar contratação de plano coletivo com pessoa jurídica cujo objetivo principal seja estipular, em nome de terceiros, planos de benefícios coletivos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3417059,"enunciado":"No que se refere à previdência complementar aberta e aos planos com cobertura por sobrevivência, julgue o item subsequente. \n\n\n\n\nNos planos de benefícios de entidades abertas, a portabilidade não caracteriza resgate.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3417060,"enunciado":"No que se refere à previdência complementar aberta e aos planos com cobertura por sobrevivência, julgue o item subsequente. \n\n\n\n\nPGBL é um plano de previdência complementar, ao passo que VGBL é classificado como seguro de pessoa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3417061,"enunciado":"No que se refere à previdência complementar aberta e aos planos com cobertura por sobrevivência, julgue o item subsequente. \n\n\n\n\nNo plano VGBL, é garantida rentabilidade mínima, previamente acertada na contratação, durante a fase de acumulação dos recursos (período de diferimento).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3426347,"enunciado":"A estrutura do sistema financeiro nacional é composta por três segmentos: normativo, entidades supervisoras e operador. O Banco Central, a Superintendência de Seguros Privados e a Caixa Econômica Federal fazem parte dos seguintes segmentos, respectivamente:","opcoes":["supervisor, supervisor e operador.","supervisor, normativo e operador.","normativo, supervisor e supervisor.","supervisor, operador e operador.","normativo, supervisor e operador."],"correta":0,"explicacao":"Gabarito: <strong>supervisor, supervisor e operador.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3437112,"enunciado":"O principal princípio do open finance é","opcoes":["a mitigação do risco para novos empréstimos.","a obtenção de crédito mais barato.","o empoderamento do cliente sobre seus dados.","o compartilhamento das informações entre todos os bancos.","a utilização de uma aplicação para acessar diversos bancos."],"correta":2,"explicacao":"Gabarito: <strong>o empoderamento do cliente sobre seus dados.</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3437114,"enunciado":"Assinale a opção em que são citadas as quatro dimensões que devem ser consideradas no sistema bancário no que diz respeito às novas tecnologias.","opcoes":["acesso, uso, qualidade e destino","acesso, qualidade, destino e rapidez","uso, qualidade, destino e poder","acesso, uso, destino e rapidez","acesso, uso, qualidade e poder"],"correta":0,"explicacao":"Gabarito: <strong>acesso, uso, qualidade e destino</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3437115,"enunciado":"O termo beyond banking refere-se a","opcoes":["uma expansão internacional de uma instituição financeira brasileira.","um ecossistema no qual instituições financeiras oferecem produtos e serviços financeiros e não financeiros.","uma permissão para clientes brasileiros adquirirem produtos de instituições estrangeiras.","uma expansão de uma instituição estrangeira no Brasil.","uma estratégia de transferir para o celular atividades conduzidas em agências físicas."],"correta":1,"explicacao":"Gabarito: <strong>um ecossistema no qual instituições financeiras oferecem produtos e serviços financeiros e não financeiros.</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451649,"enunciado":"Um banco busca otimizar suas operações e aprimorar a experiência do cliente. Qual das alternativas a seguir melhor ilustra a aplicação integrada das análises descritiva, preditiva e prescritiva nesse contexto?","opcoes":["O banco analisa o histórico de transações dos clientes (análise preditiva), prevê quais clientes têm maior probabilidade de cancelar seus serviços (análise prescritiva) e oferece incentivos personalizados para retê-los (análise descritiva).","O banco analisa o histórico de transações dos clientes (análise preditiva), prevê quais clientes têm maior probabilidade de cancelar seus serviços (análise descritiva) e oferece incentivos personalizados para retê-los (análise prescritiva).","O banco analisa o histórico de transações dos clientes (análise prescritiva), prevê quais clientes têm maior probabilidade de cancelar seus serviços (análise descritiva) e oferece incentivos personalizados para retê-los (análise preditiva).","O banco analisa o histórico de transações dos clientes (análise descritiva), prevê quais clientes têm maior probabilidade de cancelar seus serviços (análise prescritiva) e oferece incentivos personalizados para retê-los (análise preditiva).","O banco analisa o histórico de transações dos clientes (análise descritiva), prevê quais clientes têm maior probabilidade de cancelar seus serviços (análise preditiva) e oferece incentivos personalizados para retê-los (análise prescritiva)."],"correta":4,"explicacao":"Gabarito: <strong>O banco analisa o histórico de transações dos clientes (análise descritiva), prevê quais clientes têm maior probabilidade de cancelar seus serviços (análise preditiva) e oferece incentivos personalizados para retê-los (análise prescritiva).</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451675,"enunciado":"Um empresário busca um empréstimo perante uma instituição financeira e recebe a informação de que será necessário apresentar uma fiança conferida por outra instituição financeira (ou seja, a concessão do empréstimo resta condicionada à fiança bancária). Com base na legislação do SFN, como a fiança bancária é classificada e regulamentada?","opcoes":["Garantia real sobre veículos, regulada pela SUSEP.","Obrigação pessoal de terceiro, regulada pelo Banco Central do Brasil.","Garantia pessoal com aval do Banco Central, aplicável apenas a PJs.","Garantia híbrida, exigindo penhor complementar.","Instrumento do mercado de capitais, supervisionado pela CVM."],"correta":1,"explicacao":"Gabarito: <strong>Obrigação pessoal de terceiro, regulada pelo Banco Central do Brasil.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451677,"enunciado":"A Lei Complementar nº. 179, de 2021, atribui ao Banco Central a missão prioritária de garantir a estabilidade econômica. Qual dessas funções é considerada a principal razão de existência do BCB, segundo tal diploma legal?","opcoes":["Fiscalizar cooperativas de crédito e bancos comerciais.","Controlar a inflação e preservar o poder de compra da moeda.","Emitir papel-moeda e gerenciar reservas internacionais.","Regular o mercado de câmbio e operações internacionais.","Supervisionar instituições de pagamento e fintechs."],"correta":1,"explicacao":"Gabarito: <strong>Controlar a inflação e preservar o poder de compra da moeda.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451678,"enunciado":"Em uma audiência pública, discutiu-se se o CMN é o único órgão normativo do SFN, no que toca aos mercados de crédito, câmbio, monetário e valores mobiliários. Um especialista mencionou que outros entes também emitem normas setoriais. Quais órgãos, além do CMN, possuem competência normativa no âmbito dos mercados de crédito, câmbio, monetário e valores mobiliários?","opcoes":["Apenas o Banco Central, para regular crédito e câmbio.","Ministério da Economia e Tesouro Nacional.","SUSEP e Previc, para seguros e previdência complementar.","Banco Central e CVM, conforme suas áreas de atuação.","Todos os órgãos vinculados ao Ministério da Fazenda."],"correta":3,"explicacao":"Gabarito: <strong>Banco Central e CVM, conforme suas áreas de atuação.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451679,"enunciado":"Um jornalista afirmou que o Copom se reúne mensalmente, como o FOMC do Fed americano. Considerando o calendário oficial do BCB, qual é a periodicidade correta das reuniões do Copom?","opcoes":["Mensal, sempre na primeira semana de cada mês.","Bimestral, com intervalos fixos de 60 dias.","Trimestral, alinhado ao calendário fiscal.","Oito vezes ao ano, em ciclos de aproximadamente 45 dias.","Semestral, exceto em cenários de crise."],"correta":3,"explicacao":"Gabarito: <strong>Oito vezes ao ano, em ciclos de aproximadamente 45 dias.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451694,"enunciado":"A política monetária é um dos principais instrumentos utilizados pelos Bancos Centrais para regular a economia de um país. Por meio do controle da oferta de moeda e das taxas de juros, busca-se equilibrar fatores como inflação, crescimento econômico e estabilidade financeira. No Brasil, essa função é desempenhada pelo Banco Central, que define a Taxa Selic como referência para os juros da economia. Considerando esse contexto, assinale a alternativa correta sobre a relação entre política monetária e taxas de juros:","opcoes":["Quando o Banco Central eleva a taxa de juros, o crédito se torna mais acessível e barato, estimulando o consumo e o crescimento da economia.","A política monetária expansionista caracteriza-se pela elevação da taxa de juros, com o objetivo de conter a inflação e reduzir o consumo.","A redução da taxa de juros tende a estimular o consumo e os investimentos, pois torna o crédito mais barato, incentivando a atividade econômica.","O Banco Central não influencia diretamente a inflação ou o crescimento econômico, pois a taxa de juros é determinada exclusivamente pelo mercado financeiro.","Quando os juros estão baixos, a tendência é que a população reduza os gastos e aumente a poupança, desacelerando a economia."],"correta":2,"explicacao":"Gabarito: <strong>A redução da taxa de juros tende a estimular o consumo e os investimentos, pois torna o crédito mais barato, incentivando a atividade econômica.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451696,"enunciado":"O mercado de ações é um dos principais ambientes para captação de recursos por empresas e para investidores que buscam rentabilidade a longo prazo. Ao comprar ações, um investidor se torna sócio da empresa e pode lucrar com a valorização dos papéis e com a distribuição de dividendos. Além das ações, existem diversos ativos de risco, como criptomoedas, fundos imobiliários e derivativos, que apresentam maior volatilidade e incerteza, mas também podem proporcionar retornos mais elevados. O desempenho desses ativos é influenciado por fatores como política monetária, crescimento econômico, resultados corporativos e eventos globais. Diante desse contexto, assinale a alternativa correta:","opcoes":["As ações são investimentos de renda fixa, pois pagam um retorno garantido independentemente das condições do mercado.","O mercado de ações é influenciado apenas pelos fundamentos das empresas, sendo imune a fatores externos, como política monetária e crises econômicas.","Investimentos em ativos de risco podem oferecer maior rentabilidade, mas estão sujeitos à volatilidade do mercado, podendo gerar perdas ou ganhos significativos.","As criptomoedas são regulamentadas da mesma forma que ações e títulos públicos, garantindo a mesma segurança e previsibilidade para os investidores.","O investimento em ações é indicado apenas para quem busca retornos de curto prazo, pois o mercado acionário sempre apresenta resultados previsíveis em poucos meses."],"correta":2,"explicacao":"Gabarito: <strong>Investimentos em ativos de risco podem oferecer maior rentabilidade, mas estão sujeitos à volatilidade do mercado, podendo gerar perdas ou ganhos significativos.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451697,"enunciado":"Nos últimos anos, as criptomoedas revolucionaram o setor financeiro, trazendo novos conceitos como descentralização, blockchain e finanças digitais. Diferente das moedas tradicionais (como o real ou o dólar), as criptomoedas não são emitidas por bancos centrais, mas sim registradas em redes descentralizadas, baseadas em tecnologia blockchain, garantindo segurança, transparência e imutabilidade das transações. Além disso, a inovação financeira impulsionada por esses ativos trouxe novas oportunidades, como contratos inteligentes, tokens digitais e finanças descentralizadas (DeFi), permitindo que usuários realizem transações sem a necessidade de intermediários, como bancos e corretoras. Entretanto, devido à sua alta volatilidade, regulação incerta e riscos tecnológicos, as criptomoedas ainda são vistas com cautela por parte de governos e investidores tradicionais. Diante desse contexto, assinale a alternativa correta:","opcoes":["As criptomoedas são reguladas de forma padronizada em todos os países, garantindo que todas as transações sejam rastreadas e controladas pelos bancos centrais.","A tecnologia blockchain, utilizada pelas criptomoedas, permite registrar transações de forma descentralizada e segura, reduzindo a necessidade de intermediários financeiros.","Criptomoedas, como o Bitcoin, têm seu valor determinado exclusivamente por governos e bancos centrais, da mesma forma que as moedas fiduciárias tradicionais.","As finanças descentralizadas (DeFi) são um conceito que exige a intermediação de bancos tradicionais para validar transações e garantir a liquidez do mercado.","Como as criptomoedas não possuem regulação em nenhum país, elas são sempre um investimento seguro e sem riscos de perda de valor ou ataques cibernéticos."],"correta":1,"explicacao":"Gabarito: <strong>A tecnologia blockchain, utilizada pelas criptomoedas, permite registrar transações de forma descentralizada e segura, reduzindo a necessidade de intermediários financeiros.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3451698,"enunciado":"Nos últimos anos, a pauta da sustentabilidade tem ganhado grande relevância no mundo dos investimentos, levando ao crescimento dos chamados investimentos ESG (Environmental, Social and Governance). O conceito de ESG (Ambiental, Social e Governança) representa um conjunto de práticas adotadas por empresas para minimizar impactos ambientais, promover responsabilidade social e garantir uma gestão corporativa ética e transparente. Investidores estão cada vez mais priorizando ativos alinhados a esses princípios, pois empresas sustentáveis tendem a ser mais resilientes a riscos e mais atrativas a longo prazo. Dessa forma, fundos e produtos financeiros baseados em ESG avaliam não apenas o desempenho financeiro, mas também fatores como emissões de carbono, diversidade no quadro de funcionários e transparência na gestão. No entanto, apesar do crescimento desse mercado, desafios como o greenwashing (práticas enganosas de sustentabilidade) ainda são um obstáculo para investidores. Diante desse contexto, assinale a alternativa correta:","opcoes":["O investimento ESG considera apenas critérios ambientais, como redução de emissão de carbono e uso de energias renováveis, ignorando aspectos sociais e de governança.","Empresas que adotam práticas ESG são automaticamente mais lucrativas, pois a sustentabilidade sempre gera retorno financeiro imediato.","O conceito ESG abrange critérios ambientais, sociais e de governança, incentivando investimentos em empresas comprometidas com práticas sustentáveis e éticas.","O mercado ESG é um modelo tradicional de investimento que não sofreu crescimento nos últimos anos e possui pouca relevância globalmente.","Greenwashing refere-se a uma estratégia legítima em que as empresas promovem práticas ESG autênticas e verificadas pelo mercado financeiro."],"correta":2,"explicacao":"Gabarito: <strong>O conceito ESG abrange critérios ambientais, sociais e de governança, incentivando investimentos em empresas comprometidas com práticas sustentáveis e éticas.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530129,"enunciado":"Em relação às operações de mercado de capitais, julgue o item seguinte. \n\n\n\n\n\n\n\nA Comissão de Valores Imobiliários é responsável direta pelo registro de investidores individuais no mercado de capitais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530130,"enunciado":"Em relação às operações de mercado de capitais, julgue o item seguinte. \n\n\n\n\nA recompra de ações pela empresa no mercado secundário pode ocorrer por decisão estratégica com vistas a programas de incentivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530131,"enunciado":"Em relação às operações de mercado de capitais, julgue o item seguinte. \n\n\n\n\nAções, debêntures, notas promissórias e cotas de fundos são consideradas valores mobiliários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530132,"enunciado":"Julgue o próximo item, relacionados ao Sistema de Investigação de Movimentações Bancárias (SIMBA). \n\n\n\n\n\n\n\nO SIMBA é utilizado por peritos e órgãos de controle para acessar dados bancários compartilhados com o Ministério Público e o Judiciário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530133,"enunciado":"Julgue o próximo item, relacionados ao Sistema de Investigação de Movimentações Bancárias (SIMBA). \n\n\n\n\nAs informações obtidas por meio do SIMBA dispensam autorização judicial, dada a natureza dos dados bancários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530134,"enunciado":"Em relação a aspectos relacionados à análise de movimentações bancárias no contexto pericial-contábil, identificação de padrões e prevenção de ilícitos financeiros, julgue o seguinte item.  \n\nO cadastro de clientes do SFN permite a identificação da existência de relacionamentos bancários, mas não revela saldos nem extratos das contas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530135,"enunciado":"Em relação a aspectos relacionados à análise de movimentações bancárias no contexto pericial-contábil, identificação de padrões e prevenção de ilícitos financeiros, julgue o seguinte item.  \n\nMovimentações bancárias que excedam a renda declarada indicam, por si só, evasão fiscal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530136,"enunciado":"Em relação a aspectos relacionados à análise de movimentações bancárias no contexto pericial-contábil, identificação de padrões e prevenção de ilícitos financeiros, julgue o seguinte item.  \n\nA responsabilização por lavagem de dinheiro exige, necessariamente, condenação prévia pelo crime antecedente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530137,"enunciado":"Em relação a aspectos relacionados à análise de movimentações bancárias no contexto pericial-contábil, identificação de padrões e prevenção de ilícitos financeiros, julgue o seguinte item.  \n\nO smurfing é uma técnica utilizada para disfarçar operações maiores por meio de múltiplas transações de pequeno valor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530138,"enunciado":"Em relação a aspectos relacionados à análise de movimentações bancárias no contexto pericial-contábil, identificação de padrões e prevenção de ilícitos financeiros, julgue o seguinte item.  \n\nO fato de uma pessoa movimentar valores superiores à sua renda declarada configura sonegação fiscal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530139,"enunciado":"Em relação a aspectos relacionados à análise de movimentações bancárias no contexto pericial-contábil, identificação de padrões e prevenção de ilícitos financeiros, julgue o seguinte item.  \n\nA ausência de justificativa para valores movimentados em espécie pode ser irrelevante se não houver indício de crime antecedente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530142,"enunciado":"Considerando a Resolução CMN n.º 4.963/2021, que dispõe sobre as aplicações dos recursos dos RPPS instituídos pela União, pelos estados, pelo Distrito Federal e pelos municípios, julgue o seguinte item. \n\nÉ vedada a aplicação dos recursos dos RPPS em empréstimos de qualquer natureza, inclusive nos consignados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530143,"enunciado":"Considerando a Resolução CMN n.º 4.963/2021, que dispõe sobre as aplicações dos recursos dos RPPS instituídos pela União, pelos estados, pelo Distrito Federal e pelos municípios, julgue o seguinte item. \n\nÉ possível a aplicação de até 100% dos recursos dos RPPS que constituam cotas de fundo de investimento em índice de mercado de renda fixa, negociáveis em bolsa de valores.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530144,"enunciado":"Considerando a Resolução CMN n.º 4.963/2021, que dispõe sobre as aplicações dos recursos dos RPPS instituídos pela União, pelos estados, pelo Distrito Federal e pelos municípios, julgue o seguinte item. \n\nOs recursos dos RPPS podem ser aplicados em investimentos estruturados desde que respeitados os limites previstos pela citada resolução, sendo, entretanto, vedada a aplicação desses recursos diretamente em certificados de operações estruturadas (COE).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3530145,"enunciado":"Considerando a Resolução CMN n.º 4.963/2021, que dispõe sobre as aplicações dos recursos dos RPPS instituídos pela União, pelos estados, pelo Distrito Federal e pelos municípios, julgue o seguinte item. \n\nÉ permitida a aplicação dos recursos dos RPPS em renda variável, fundos imobiliários e até em investimentos no exterior, desde que respeitados os limites previstos pela mencionada resolução.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3553634,"enunciado":"Uma das principais atividades das instituições financeiras é emprestar recursos para famílias, empresas e o governo. Para isso, os bancos não utilizam apenas capital próprio, mas também recursos captados junto ao público. Essa captação, do ponto de vista do investidor, representa:","opcoes":["Alternativas de investimento tradicionais, como depósitos a prazo e cadernetas de poupança.","Investimentos de alto risco, destinados exclusivamente a investidores qualificados.","Empréstimos tomados por investidores para financiamento de capital de giro.","Formas de captação restritas à emissão de debêntures e bônus por sociedades anônimas.","Aplicações diretas em ações emitidas por bancos, com garantia de rentabilidade fixa."],"correta":0,"explicacao":"Gabarito: <strong>Alternativas de investimento tradicionais, como depósitos a prazo e cadernetas de poupança.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3553640,"enunciado":"Quando os saldos do banco e da contabilidade não coincidem, é necessário identificar as causas da divergência. Assinale a alternativa que indica incorretamente uma das causas possíveis:","opcoes":["Valores lançados pela contabilidade e não creditados pelo banco.","Valores lançados pela contabilidade e não debitados pelo banco.","Valores creditados pelo banco e não lançados pela contabilidade.","Valores debitados pelo banco e não lançados pela contabilidade.","Valores lançados simultaneamente no banco e na contabilidade, mas com finalidades distintas."],"correta":4,"explicacao":"Gabarito: <strong>Valores lançados simultaneamente no banco e na contabilidade, mas com finalidades distintas.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3624710,"enunciado":"Em relação ao direito das obrigações, considerada a disciplina do Código Civil atinente a juros e a correlata jurisprudência do STJ, julgue o seguinte item. \n\n\n\n\nA metodologia de cálculo da taxa legal e sua forma de aplicação serão definidas pelo Conselho Monetário Nacional e divulgadas pelo Banco Central do Brasil, e, caso a taxa legal apresente resultado negativo, este será considerado igual a zero para efeito de cálculo dos juros no período de referência.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3698064,"enunciado":"O mês de agosto de 2023 no cenário econômico brasileiro ficou marcado por um avanço no desenvolvimento da versão eletrônica do Real, pois o Banco Central determinou que a nova moeda digital se chamará:","opcoes":["E-Real.","BCD.","Drex.","X-Real."],"correta":2,"explicacao":"Gabarito: <strong>Drex.</strong>.","banca":"IDESG","ano":2023,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3775274,"enunciado":"Ocorre criação de meios de pagamento quando","opcoes":["o Banco Central compra títulos públicos federais.","um banco privado compra títulos públicos de outro banco.","um título da dívida pública é negociado entre instituições financeiras.","o Banco Central vende títulos públicos federais.","uma empresa de economia mista vende ações na B3."],"correta":0,"explicacao":"Gabarito: <strong>o Banco Central compra títulos públicos federais.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3784324,"enunciado":"Uma empresa Ltda., buscando maior eficiência na gestão de caixa e no ciclo financeiro de suas vendas, substituiu gradualmente os boletos bancários e cartões de crédito pelo sistema de pagamento instantâneo (PIX) para liquidação das transações com clientes. Após a mudança, observou‑se uma melhoria significativa no fluxo de caixa operacional e na previsibilidade das entradas financeiras diárias. Com base nessa situação hipotética e nas normas do Banco Central do Brasil, assinale a opção que apresenta uma vantagem financeira direta proporcionada pela adoção do PIX no processo de recebimento.","opcoes":["Redução do risco de liquidez, em razão da liquidação imediata dos valores e da eliminação de prazos compensatórios.","Aumento do prazo médio de recebimento, permitindo maior controle sobre o giro de contas a receber.","Eliminação da necessidade de controle interno, uma vez que o sistema automatiza todos os registros de recebimento.","Descentralização da tesouraria, com criação de contas múltiplas para segregação de recursos e aplicações.","Retenção compulsória de tributos incidentes, conforme as normas de arrecadação automática previstas pelo BACEN."],"correta":0,"explicacao":"Gabarito: <strong>Redução do risco de liquidez, em razão da liquidação imediata dos valores e da eliminação de prazos compensatórios.</strong>.","banca":"Quadrix","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3809923,"enunciado":"No Sistema Financeiro Nacional (SFN), existe uma entidade encarregada de controlar a inflação no país e de zelar pela estabilidade do sistema e de suas instituições. Essa entidade é o Banco Central, que tem como uma de suas atribuições","opcoes":["definir a meta de inflação no país.","controlar o fluxo de capitais estrangeiros no Brasil.","autorizar as emissões de debêntures.","definir o superávit primário."],"correta":1,"explicacao":"Gabarito: <strong>controlar o fluxo de capitais estrangeiros no Brasil.</strong>.","banca":"IV - UFG","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3809925,"enunciado":"Entre as instituições que integram o Sistema Financeiro Nacional, destaca-se o Conselho Monetário Nacional, cuja função é definir a política da moeda e do crédito, com foco no desenvolvimento econômico e social do país. Assim, a atuação do Conselho Monetário Nacional tem como objetivo","opcoes":["propiciar o aperfeiçoamento das instituições e dos instrumentos financeiros, com vistas à maior eficiência do sistema de pagamentos e de mobilização de recursos e zelar pela liquidez e solvência das instituições financeiras.","praticar operações de câmbio, crédito e venda habitual de títulos da dívida pública federal, estadual ou municipal, ações, debêntures, letras hipotecárias e outros títulos de crédito ou mobiliários.","atuar no sentido de garantir o funcionamento regular do mercado cambial, a estabilidade relativa das taxas de câmbio e o equilíbrio no balanço de pagamentos, podendo, para esse fim, comprar e vender ouro e moeda estrangeira, bem como realizar operações de crédito no exterior.","emitir títulos de responsabilidade própria, de acordo com as condições estabelecidas pelo Congresso Nacional, para financiar a dívida pública do governo."],"correta":0,"explicacao":"Gabarito: <strong>propiciar o aperfeiçoamento das instituições e dos instrumentos financeiros, com vistas à maior eficiência do sistema de pagamentos e de mobilização de recursos e zelar pela liquidez e solvência das instituições financeiras.</strong>.","banca":"IV - UFG","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3810327,"enunciado":"Um investidor, avesso ao risco, busca uma alternativa financeira que garanta segurança do capital investido, com rendimento padronizado por norma legal, isenção de custos de resgate e liquidez com possibilidade de saque a qualquer momento. Qual possibilidade de investimento atende aos requisitos desse investidor?","opcoes":["Caderneta de poupança.","Fundos de investimento de renda fixa.","Planos de previdência privada.","Certificado de capitalização."],"correta":0,"explicacao":"Gabarito: <strong>Caderneta de poupança.</strong>.","banca":"IV - UFG","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3810332,"enunciado":"No Brasil, instituições como os Bancos de Desenvolvimento e as Agências de Fomento atuam na concessão de crédito voltado ao desenvolvimento econômico regional. Essas entidades estão vinculadas especificamente ao","opcoes":["sistema financeiro nacional.","tesouro nacional.","sistema nacional de fomento.","sistema de seguros privados."],"correta":2,"explicacao":"Gabarito: <strong>sistema nacional de fomento.</strong>.","banca":"IV - UFG","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3810333,"enunciado":"Durante o expediente, o escriturário auxilia na conferência de numerário e no controle de cheques recebidos. Essa atividade corresponde ao setor de","opcoes":["tesouraria.","arquivologia.","planejamento estratégico.","orçamento empresarial."],"correta":0,"explicacao":"Gabarito: <strong>tesouraria.</strong>.","banca":"IV - UFG","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3810334,"enunciado":"O escriturário precisa apresentar ao gerente o desempenho da agência, utilizando tabelas e gráficos para demonstrar evolução de depósitos. Essa tarefa corresponde","opcoes":["à tesouraria.","à elaboração de relatórios gerenciais.","ao controle de numerário.","ao arquivamento de documentos."],"correta":1,"explicacao":"Gabarito: <strong>à elaboração de relatórios gerenciais.</strong>.","banca":"IV - UFG","ano":2025,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3834846,"enunciado":"O Sistema de Pagamentos Brasileiro é composto por dois segmentos: Infraestruturas do Mercado Financeiro (IMF) e Arranjos de Pagamento. Participa(m) como entidade(s) normativa(s) de ambos os segmentos:","opcoes":["apenas o Conselho Monetário Nacional (CMN).","apenas o Banco Central do Brasil (BC).","o Conselho Monetário Nacional (CMN) e a Comissão de Valores Monetários (CVM).","o Conselho Monetário Nacional (CMN) e o Banco Central do Brasil (BC).","o Banco Central do Brasil (BC) e a Comissão de Valores Monetários (CVM)."],"correta":3,"explicacao":"Gabarito: <strong>o Conselho Monetário Nacional (CMN) e o Banco Central do Brasil (BC).</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3834850,"enunciado":"Um investidor do mercado financeiro com perfil conserva­dor tende a preferir aplicar seus recursos em","opcoes":["ações de alta liquidez.","ações de baixa liquidez.","CDB, independentemente do seu emissor.","debêntures.","títulos públicos."],"correta":4,"explicacao":"Gabarito: <strong>títulos públicos.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3834856,"enunciado":"Empréstimos Bancários distinguem-se de Financiamentos porque","opcoes":["os empréstimos bancários são concedidos apenas para prazos de até um ano, enquanto os financiamentos têm prazos superiores a um ano.","nos empréstimos bancários somente se permite a cobrança de juros com taxas pré-fixadas, enquanto que os financiamentos são negociados somente com taxas pós-fixadas.","os empréstimos bancários devem ser devolvidos às instituições financeiras em uma única parcela, ao passo que financiamentos são amortizados através de parcelas mensais e sucessivas.","nos empréstimos bancários não há determinação da finalidade para a qual foram concedidos, enquanto que os financiamentos estão vinculados a um bem ou propósito específico.","os empréstimos bancários são concedidos apenas por instituições financeiras privadas, ao contrário dos financiamentos, cuja concessão é exclusividade de instituições financeiras públicas."],"correta":3,"explicacao":"Gabarito: <strong>nos empréstimos bancários não há determinação da finalidade para a qual foram concedidos, enquanto que os financiamentos estão vinculados a um bem ou propósito específico.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3834857,"enunciado":"Atualmente, podem ser utilizados(as) como garantias de empréstimos bancários com garantia","opcoes":["apenas veículos quitados e imóveis quitados.","apenas veículos, quitados ou não, e imóveis, quitados ou não.","veículos quitados, imóveis somente quitados e aplicações no Tesouro Direto.","veículos quitados ou não, imóveis somente quitados e aplicações no Tesouro Direto.","veículos quitados, imóveis, quitados ou não, e aplicações no Tesouro Direto."],"correta":4,"explicacao":"Gabarito: <strong>veículos quitados, imóveis, quitados ou não, e aplicações no Tesouro Direto.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3834858,"enunciado":"A aquisição de um veículo no valor de R$ 150.000,00 em 36 parcelas mensais de R$ 5.400,00 com alienação fiduciária é caracterizada como","opcoes":["financiamento sem garantia.","empréstimo sem garantia.","financiamento com garantia.","empréstimo com garantia.","empréstimo consignado."],"correta":2,"explicacao":"Gabarito: <strong>financiamento com garantia.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3834859,"enunciado":"O órgão da mais elevada hierarquia do Sistema Financeiro Nacional, encarregado da formulação da política monetária nacional e da regulamentação das diretrizes de todo o sistema financeiro nacional entre suas principais atribuições, é o","opcoes":["Banco Central.","Conselho Monetário Nacional (CMN).","Comissão de Valores Mobiliários (CVM).","Ministério da Fazenda.","Ministério do Planejamento."],"correta":1,"explicacao":"Gabarito: <strong>Conselho Monetário Nacional (CMN).</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3884645,"enunciado":"O Sistema Financeiro Nacional apresenta estrutura envolvendo diferentes autoridades e agentes, cabendo","opcoes":["a presença de entidades de autorregulação, como a AMBIMA - Associação Brasileira das Entidades dos Mercados Financeiro e de Capitais.","à Comissão de Valores Mobiliários decretar a liquidação das sociedades distribuidoras de títulos e valores mobiliários que atuam no mercado de capitais, para saneamento.","a disponibilização, pelas instituições de pagamento, de serviços de contas eletrônicas e de operações de crédito.","ao Banco Central do Brasil garantir a estabilidade do poder de compra da moeda, o que é coordenado por meio do Comitê de Estabilidade Financeira.","às agências de fomento o financiamento de capital fixo e de giro associado a projetos na região do país onde tenham sede."],"correta":0,"explicacao":"Gabarito: <strong>a presença de entidades de autorregulação, como a AMBIMA - Associação Brasileira das Entidades dos Mercados Financeiro e de Capitais.</strong>.","banca":"FCC","ano":2024,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3885905,"enunciado":"Em novembro de 2025, o Banco Central anunciou a liquidação extrajudicial de uma instituição financeira brasileira. A medida foi tomada após constatação de problemas graves de solvência e gestão, o que levou à falência da instituição. Qual foi o banco que entrou em processo de liquidação em novembro de 2025?","opcoes":["Banco Master.","Banco Inter.","Banco Safra.","Banco Soft Bank."],"correta":1,"explicacao":"Gabarito: <strong>Banco Inter.</strong>.","banca":"Instituto UniFil","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3899810,"enunciado":"Sobre a atuação do Banco Central na economia, assinale a opção correta.","opcoes":["Quando o Banco Central aumenta os meios de pagamentos através da compra de títulos em operações no mercado aberto, implica no aumento do preço e na redução da taxa de juros desses títulos.","Ao tomar empréstimos externos e aumentar suas reservas internacionais, o Banco Central está criando moeda.","Quando o Banco Central vende títulos públicos no mercado aberto, ou reduz a alíquota dos compulsórios, ele aumenta a quantidade de moeda na economia.","Criado pela Lei 4.595, de 1964, o Banco Central é uma autarquia responsável por emitir moeda, controlar o crédito e garantir a estabilidade da economia. A citada lei estabelece que cabe ao Banco Central determinar o recolhimento de até cem por cento do total dos depósitos à vista das instituições financeiras, não podendo adotar percentagens diferentes em função das regiões geoeconômicas."],"correta":0,"explicacao":"Gabarito: <strong>Quando o Banco Central aumenta os meios de pagamentos através da compra de títulos em operações no mercado aberto, implica no aumento do preço e na redução da taxa de juros desses títulos.</strong>.","banca":"FCPC","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3906763,"enunciado":"Uma instituição financeira de grande porte está revisando sua estrutura de mensuração e stress testing para risco de mercado e risco de taxa de juros na carteira bancária (IRRBB). Para tanto, a equipe técnica propõe que a instituição I mensure, no módulo de risco de mercado, a exposição apenas das posições ativas classificadas no trading book, excluindo passivos, derivativos e posições cambiais mantidas no banking book, pois a equipe técnica entende que “risco de mercado está associado somente a ativos” e que as demais posições seriam tratadas no risco de crédito ou de liquidez. II utilize, no âmbito do IRRBB, derivativos de taxa de juros (swaps e opções) como instrumentos de hedge da exposição estrutural do banking book, incorporando-os aos modelos de mensuração sob cenários de choques paralelos e não paralelos na curva de juros, bem como em exercícios de teste de estresse reverso. III implemente um programa de reverse stress testing focado em risco de mercado e IRRBB, partindo de situações como “cenário em que o banco viola limites internos de perda econômica em EVE (economic value of equity) ou de queda de NII (net interest income)”, e trabalhando retrospectivamente as combinações de choques de taxas de juros, de spreads, de liquidez e de basis que poderiam produzir tais resultados. Considerando a situação hipotética precedente e as boas práticas de gestão de riscos, assinale a opção correta.","opcoes":["Apenas a proposta I está alinhada às boas práticas de gestão de riscos, pois o foco em posições ativas do trading book é o núcleo do risco de mercado, enquanto derivativos e IRRBB devem ser tratados separadamente como risco de modelo.","A proposta I está correta, pois limita a complexidade do modelo; a proposta II está equivocada, já que derivativos não devem ser utilizados no gerenciamento do IRRBB em função da volatilidade que introduzem; e a proposta III é desnecessária, pois o teste de estresse reverso não é contemplado nos padrões de Basileia.","As propostas II e III estão alinhadas às boas práticas internacionais de gestão de riscos; já a proposta I é incompatível com o escopo de risco de mercado, pois exclui posições passivas, derivativos e certas posições do banking book sujeitas a variações de mercado.","As três propostas estão incorretas, pois o IRRBB não admite o uso de derivativos como hedge, além de o reverse stress testing ser um instrumento aplicável apenas a risco de crédito.","As três propostas estão corretas, pois o foco da gestão de risco bancária está nos riscos de mercado no trading book, ficando IRRBB e derivativos fora do escopo prudencial."],"correta":2,"explicacao":"Gabarito: <strong>As propostas II e III estão alinhadas às boas práticas internacionais de gestão de riscos; já a proposta I é incompatível com o escopo de risco de mercado, pois exclui posições passivas, derivativos e certas posições do banking book sujeitas a variações de mercado.</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3922022,"enunciado":"O Certificado de Depósito Bancário (CDB) distingue-se do Recibo de Depósito Bancário (RDB) principalmente porque","opcoes":["o RDB é negociado exclusivamente por bancos de investimento.","apenas ao CDB é assegurada a proteção do Fundo Garantidor de Créditos (FGC).","o CDB pode ser emitido apenas por bancos múltiplos.","o RDB é intransferível e seu resgate ocorre apenas no vencimento, normalmente.","o RDB pode ser emitido somente com taxas pós-fixadas."],"correta":3,"explicacao":"Gabarito: <strong>o RDB é intransferível e seu resgate ocorre apenas no vencimento, normalmente.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3922024,"enunciado":"A B3-Brasil, Bolsa, Balcão é a maior bolsa de valores brasileira e nela ocorrem as operações com ações no ______________ que corresponde a transações públicas entre investidores. Dele fazem parte os seguintes mercados: ___________ no qual são negociadas ações cuja transferência de titularidade ocorre rapidamente; ________________ em que são transacionados direitos para comprar ou vender ações a um preço de exercício pré- -determinado até uma data estipulada e ____________ em que ações podem ser compradas ou vendidas a preços pré-determinados mediante contratos entre as partes com prazo normalmente de 30, 60, 90 ou 120 dias. Assinale a alternativa que completa, correta e respectivamente, as lacunas.","opcoes":["mercado primário … mercado à vista … mercado de opções … mercado a termo","mercado secundário … mercado à vista … mercado de opções … mercado a termo","mercado secundário … mercado à vista … mercado a termo … mercado de opções","mercado primário … mercado presente … mercado futuro … mercado de opções","mercado secundário … mercado presente … mercado a termo … mercado de opções"],"correta":1,"explicacao":"Gabarito: <strong>mercado secundário … mercado à vista … mercado de opções … mercado a termo</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3922025,"enunciado":"Os fundos de investimento são classificados em diversas dimensões e numa delas são divididos entre abertos e fechados. A distinção entre eles é que os abertos:","opcoes":["não têm limite de cotas e por isso podem admitir novos participantes.","têm suas cotas negociadas em bolsa de valores.","têm objetivos estabelecidos e por isso podem cobrar taxa de performance.","podem ter títulos públicos e privados na composição de suas carteiras.","podem ter títulos de renda fixa e de renda variável na composição de suas carteiras."],"correta":0,"explicacao":"Gabarito: <strong>não têm limite de cotas e por isso podem admitir novos participantes.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3939239,"enunciado":"A cédula de crédito bancário (CCB) é um título de crédito que alterou o modo com o qual as instituições financeiras formalizavam empréstimos e financiamentos. Conforme a Lei no 10.931, de 2 de agosto de 2004, que institui esse título, a CCB","opcoes":["deverá apresentar garantia real ou fidejussória, devendo ser constituídas cedularmente.","será transferível mediante endosso em preto ou em branco, mesmo que o endossatário não seja instituição financeira.","poderá ser emitida em moeda estrangeira, desde que a obrigação esteja sujeita à lei estrangeira e exclusivamente ao foro brasileiro.","é uma ordem de pagamento em dinheiro, decorrente de operação de crédito, emitida em favor de instituição financeira.","poderá ser emitida em favor de instituição domiciliada no exterior, desde que a obrigação esteja sujeita exclusivamente à lei e ao foro brasileiros."],"correta":4,"explicacao":"Gabarito: <strong>poderá ser emitida em favor de instituição domiciliada no exterior, desde que a obrigação esteja sujeita exclusivamente à lei e ao foro brasileiros.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3965859,"enunciado":"Considere o texto e proposições a seguir: \"De acordo com a ISO 31000:2018, o risco é definido como o efeito das incertezas nos objetivos da organização. […] Os riscos podem ser divididos em riscos de origem financeira […] e riscos organizacionais […] e têm diferentes dimensões de impacto, como impacto financeiro, reputacional (ou de imagem) e de negócios.\" BANCO CENTRAL DO BRASIL. Gestão Integrada de Riscos. Brasília: Banco Central do Brasil, 2024. Disponível em: . Acesso em: 9 jan. 2026. I. A gestão dos riscos financeiros concentra-se nos ativos e nos passivos que compõem o balanço patrimonial da instituição, considerando as dimensões de risco de mercado, de crédito e de liquidez. II. A identificação e a mensuração dos riscos financeiros conduzem à adoção de estratégias de mitigação, não se admitindo a aceitação do risco como forma de tratamento. III. Os Planos de Mitigação de Riscos (PMRs) formalizam as ações necessárias para mitigar, evitar ou transferir riscos cuja priorização, resultante da metodologia de identificação e de avaliação, indique a necessidade de tratamento. IV. O monitoramento dos riscos permite o acompanhamento diário das exposições a riscos financeiros e operacionais, bem como o relato tempestivo de quebras de limites de operação e das medidas adotadas para sua solução, subsidiando a elaboração de relatórios destinados às áreas de negócio e ao Comitê de Governança, Riscos e Controles (GRC). Considerando as práticas de gestão de riscos financeiros adotadas no âmbito institucional, estão corretas as proposições","opcoes":["I, III e IV, apenas.","I, II e III, apenas.","II e IV, apenas.","I e II, apenas.","III e IV, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, III e IV, apenas.</strong>.","banca":"FADESP","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":3968126,"enunciado":"Entre as linhas de financiamento para fomentar o desenvolvimento econômico de diferentes setores, aquela voltada especificamente para produtores envolvidos em atividades de produção ou comercialização agropecuária, podendo financiar a aquisição de insumos, a compra de máquinas, a colheita e o transporte da produção, é denominada","opcoes":["consórcio.","crédito rural.","título de capitalização.","crédito direto ao consumidor."],"correta":1,"explicacao":"Gabarito: <strong>crédito rural.</strong>.","banca":"IV - UFG","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":4044041,"enunciado":"O caso do “Banco Master”, reiteradamente noticiado pela imprensa, refere-se a:","opcoes":["Fraudes no sistema bancário e financeiro","Fraudes no Banco do Nordeste","Desvio de emendas parlamentares","Alucinação de algoritmos para induzir a população a fazer investimentos do Banco"],"correta":0,"explicacao":"Gabarito: <strong>Fraudes no sistema bancário e financeiro</strong>.","banca":"ESDN","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":4186115,"enunciado":"O Banco Central do Brasil (Bacen) constitui a principal autoridade monetária do país, desempenhando papel fundamental na formulação e execução de políticas voltadas à estabilidade econômica e financeira nacional. Sua estrutura administrativa é composta por uma Diretoria Colegiada, integrada pelo presidente e por diretores indicados pelo Presidente da República e aprovados pelo Senado Federal. Com base nessas informações e em seus conhecimentos sobre o Sistema Financeiro Nacional, assinale a alternativa que NÃO CORRESPONDE à competência do Bacen.","opcoes":["O Banco Central controla a quantidade de dinheiro em circulação na economia.","Fiscaliza e supervisiona os bancos, cooperativas de crédito e outras instituições financeiras.","Administra as reservas internacionais, e a execução da política cambial por meio do mercado de câmbio.","Atua como “banco dos bancos” ao receber depósitos compulsórios das instituições financeiras","Uma das ações mais importante do Bacen é fomentar setores estratégicos para o crescimento econômico."],"correta":0,"explicacao":"Gabarito: <strong>O Banco Central controla a quantidade de dinheiro em circulação na economia.</strong>.","banca":"DEPSEC","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":4201372,"enunciado":"A respeito de órgãos de regulação e fiscalização, julgue o item a seguir. \n\n\n\n\nO CMN e o BACEN são entidades responsáveis pela execução da política monetária nacional, e, diferentemente do primeiro, o segundo exerce apenas função consultiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":4202912,"enunciado":"De acordo com as disposições legais, as instituições financeiras devem depositar um percentual de seus depósitos à vista no Banco Central do Brasil. Assinale a opção em que é corretamente apresentado o instrumento de política monetária praticado quando do cumprimento dessa obrigação.","opcoes":["depósito de reservas de moeda estrangeira","compra e venda de títulos públicos federais","fiscalização de instituições financeiras","recolhimento compulsório","redesconto"],"correta":3,"explicacao":"Gabarito: <strong>recolhimento compulsório</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"temas_relacionados":["conhecimentos_bancarios_geral"]},{"id":4241141,"enunciado":"As cooperativas de crédito estão autorizadas a realizar operações de captação por meio de depósitos à vista e a prazo somente de associados, de empréstimos, repasses e refinanciamentos de outras entidades financeiras, e de doações.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["conhecimentos_bancarios_geral"]}];
